import type { BankQuestion } from "@/lib/bank";

/** Seating Arrangement and Puzzles (Reasoning): 227 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"reason-seating-puzzles-1","question":"Five friends A, B, C, D and E sit in a row facing north. A sits at the extreme left end, B sits to the immediate right of A, C sits exactly in the middle, and E sits to the immediate left of D. Who sits at the extreme right end?","options":["D","C","B","E"],"answer":0,"explanation":"A takes seat 1, B seat 2 and C seat 3; E must be just left of D, so E is 4 and D is 5. Arrangement (left to right): A, B, C, E, D.","difficulty":"easy","source":"SBI Clerk · IBPS Clerk · RRB NTPC","questionHi":"पाँच मित्र A, B, C, D और E उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं। A सबसे बाएँ छोर पर बैठा है, B, A के ठीक दाएँ बैठा है, C ठीक बीच में बैठा है, और E, D के ठीक बाएँ बैठा है। सबसे दाएँ छोर पर कौन बैठा है?","optionsHi":["D","C","B","E"],"explanationHi":"A सीट 1 पर, B सीट 2 पर और C सीट 3 पर बैठा है; E, D के ठीक बाएँ होना चाहिए, इसलिए E सीट 4 पर और D सीट 5 पर है। व्यवस्था (बाएँ से दाएँ): A, B, C, E, D।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-2","question":"Seven children sit in a row facing north. Ravi is third from the left end and Mohan is second from the right end. How many children sit between Ravi and Mohan?","options":["3","1","2","4"],"answer":2,"explanation":"Ravi is at seat 3; second from the right of 7 seats is seat 6. Seats 4 and 5 lie between them, so 2 children.","difficulty":"easy","source":"SBI Clerk · IBPS Clerk · RRB NTPC","questionHi":"सात बच्चे उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं। रवि बाएँ छोर से तीसरे स्थान पर है और मोहन दाएँ छोर से दूसरे स्थान पर है। रवि और मोहन के बीच कितने बच्चे बैठे हैं?","optionsHi":["3","1","2","4"],"explanationHi":"रवि सीट 3 पर है; 7 सीटों में दाएँ से दूसरी सीट सीट 6 है। उनके बीच सीट 4 और 5 हैं, इसलिए 2 बच्चे।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-3","question":"Four friends P, Q, R and S sit around a square table facing the centre. Q sits to the immediate left of P and R sits opposite P. Who sits to the immediate right of P?","options":["S","R","Cannot be determined","Q"],"answer":0,"explanation":"For people facing the centre, left is clockwise. Clockwise from P: Q, then R (opposite P), then S, so S is the anticlockwise neighbour, i.e. P’s immediate right.","difficulty":"easy","source":"SBI Clerk · IBPS Clerk · RRB NTPC","questionHi":"चार मित्र P, Q, R और S केंद्र की ओर मुख करके एक वर्गाकार मेज़ के चारों ओर बैठे हैं। Q, P के ठीक बाएँ बैठा है और R, P के सामने बैठा है। P के ठीक दाएँ कौन बैठा है?","optionsHi":["S","R","निर्धारित नहीं किया जा सकता","Q"],"explanationHi":"केंद्र की ओर मुख करने वालों के लिए बायाँ पक्ष दक्षिणावर्त (घड़ी की दिशा में) होता है। P से दक्षिणावर्त: Q, फिर R (P के सामने), फिर S, इसलिए S वामावर्त पड़ोसी है, यानी P के ठीक दाएँ।","subtopic":"square-rectangular"},
  {"id":"reason-seating-puzzles-4","question":"Five persons A, B, C, D and E live on the five floors of a building, floor 1 being the lowest and floor 5 the top. A lives on the top floor and B immediately below A. C lives on floor 1 and D lives above E. Who lives on floor 3?","options":["D","B","C","E"],"answer":0,"explanation":"A is on 5, B on 4 and C on 1; D and E share floors 2 and 3, and D is above E, so D is on 3 and E on 2.","difficulty":"easy","source":"SBI Clerk · IBPS Clerk · RRB NTPC","questionHi":"पाँच व्यक्ति A, B, C, D और E एक इमारत की पाँच मंज़िलों पर रहते हैं, मंज़िल 1 सबसे नीचे और मंज़िल 5 सबसे ऊपर है। A सबसे ऊपरी मंज़िल पर रहता है और B, A के ठीक नीचे रहता है। C मंज़िल 1 पर रहता है और D, E के ऊपर रहता है। मंज़िल 3 पर कौन रहता है?","optionsHi":["D","B","C","E"],"explanationHi":"A मंज़िल 5 पर, B मंज़िल 4 पर और C मंज़िल 1 पर है; D और E मंज़िल 2 और 3 पर हैं, और D, E के ऊपर है, इसलिए D मंज़िल 3 पर और E मंज़िल 2 पर है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-5","question":"Six persons P, Q, R, S, T and U sit in a row facing north. R sits at the extreme left end, S sits to the immediate right of R, and exactly two persons sit between R and T. Q sits to the immediate right of T, and P is not an immediate neighbour of T. Who sits second to the left of Q?","options":["T","P","S","U"],"answer":3,"explanation":"R = 1, S = 2, T = 4, Q = 5. P cannot be 3 (next to T), so P = 6 and U = 3. Arrangement: R, S, U, T, Q, P; second to the left of Q (5) is seat 3, U.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह व्यक्ति P, Q, R, S, T और U उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं। R सबसे बाएँ छोर पर बैठा है, S, R के ठीक दाएँ बैठा है, और R तथा T के बीच ठीक दो व्यक्ति बैठे हैं। Q, T के ठीक दाएँ बैठा है, और P, T का निकटतम पड़ोसी नहीं है। Q के बाएँ से दूसरे स्थान पर कौन बैठा है?","optionsHi":["T","P","S","U"],"explanationHi":"R = 1, S = 2, T = 4, Q = 5। P सीट 3 पर नहीं हो सकता (T के बगल में), इसलिए P = 6 और U = 3। व्यवस्था: R, S, U, T, Q, P; Q (5) के बाएँ से दूसरी सीट 3 है, यानी U।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-6","question":"Six persons A, B, C, D, E and F sit around a circular table facing the centre. A sits opposite D. B sits to the immediate left of A. E sits second to the right of B. C is not an immediate neighbour of B. Who sits to the immediate right of D?","options":["E","B","F","C"],"answer":2,"explanation":"Facing the centre, left is clockwise. Clockwise from A: B, F, D, C, E (E is two places anticlockwise of B; C avoids B so takes the seat between D and E). D’s right (anticlockwise) is F.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह व्यक्ति A, B, C, D, E और F केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। A, D के सामने बैठा है। B, A के ठीक बाएँ बैठा है। E, B के दाएँ से दूसरे स्थान पर बैठा है। C, B का निकटतम पड़ोसी नहीं है। D के ठीक दाएँ कौन बैठा है?","optionsHi":["E","B","F","C"],"explanationHi":"केंद्र की ओर मुख करने पर बायाँ पक्ष दक्षिणावर्त होता है। A से दक्षिणावर्त: B, F, D, C, E (E, B से दो स्थान वामावर्त है; C, B के बगल में नहीं आ सकता, इसलिए D और E के बीच की सीट लेता है)। D का दायाँ (वामावर्त) F है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-7","question":"Seven persons J, K, L, M, N, O and P live on floors 1 (lowest) to 7 of a building, one per floor. L lives on the top floor and M on the lowest floor. J lives on an odd-numbered floor above floor 3, and exactly one person lives between J and K, with K below J. O lives immediately above M, and N lives above P. Who lives immediately below J?","options":["O","K","P","N"],"answer":2,"explanation":"J can be 5 or 7, but L has 7, so J = 5 and K = 3. M = 1, O = 2; N and P take 6 and 4 with N higher. Floors 1→7: M, O, K, P, J, N, L, so P is just below J.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"सात व्यक्ति J, K, L, M, N, O और P एक इमारत की मंज़िल 1 (सबसे नीचे) से 7 तक रहते हैं, प्रत्येक मंज़िल पर एक व्यक्ति। L सबसे ऊपरी मंज़िल पर और M सबसे निचली मंज़िल पर रहता है। J मंज़िल 3 से ऊपर की एक विषम संख्या वाली मंज़िल पर रहता है, और J तथा K के बीच ठीक एक व्यक्ति रहता है, K, J से नीचे है। O, M के ठीक ऊपर रहता है, और N, P के ऊपर रहता है। J के ठीक नीचे कौन रहता है?","optionsHi":["O","K","P","N"],"explanationHi":"J मंज़िल 5 या 7 हो सकता है, पर 7 पर L है, इसलिए J = 5 और K = 3। M = 1, O = 2; N और P मंज़िल 6 और 4 लेते हैं, जिनमें N ऊपर है। मंज़िल 1→7: M, O, K, P, J, N, L, इसलिए P, J के ठीक नीचे है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-8","question":"Five boxes A, B, C, D and E are stacked one above another, position 1 being the bottom. Box C is at the top. Exactly two boxes are kept between C and A. B is kept immediately above A, and D is not at the bottom. How many boxes are kept between B and E?","options":["3","0","1","2"],"answer":2,"explanation":"C = 5, so A = 2 and B = 3. D cannot be 1, so D = 4 and E = 1. Stack (bottom to top): E, A, B, D, C; only A lies between B and E.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"पाँच डिब्बे A, B, C, D और E एक के ऊपर एक रखे गए हैं, स्थिति 1 सबसे नीचे है। डिब्बा C सबसे ऊपर है। C और A के बीच ठीक दो डिब्बे रखे हैं। B, A के ठीक ऊपर रखा है, और D सबसे नीचे नहीं है। B और E के बीच कितने डिब्बे रखे हैं?","optionsHi":["3","0","1","2"],"explanationHi":"C = 5, इसलिए A = 2 और B = 3। D, 1 पर नहीं हो सकता, इसलिए D = 4 और E = 1। ढेर (नीचे से ऊपर): E, A, B, D, C; B और E के बीच केवल A है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-9","question":"Five persons sit in a row facing south. B sits at one end and A sits to the immediate right of B. C sits second to the right of A. E does not sit at an end, and D sits at the remaining seat. Who sits to the immediate left of C?","options":["D","A","E","B"],"answer":2,"explanation":"Facing south, a person’s right is the viewer’s west. Seats west to east: D, C, E, A, B (B at the east end, A just west of B, C two seats further west). C’s left is the seat to its east, E; D is the trap answer for people who treat them as facing north.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"पाँच व्यक्ति दक्षिण की ओर मुख करके एक पंक्ति में बैठे हैं। B एक छोर पर बैठा है और A, B के ठीक दाएँ बैठा है। C, A के दाएँ से दूसरे स्थान पर बैठा है। E किसी छोर पर नहीं बैठा है, और D शेष सीट पर बैठा है। C के ठीक बाएँ कौन बैठा है?","optionsHi":["D","A","E","B"],"explanationHi":"दक्षिण की ओर मुख करने पर व्यक्ति का दायाँ पक्ष देखने वाले का पश्चिम होता है। सीटें पश्चिम से पूर्व: D, C, E, A, B (B पूर्वी छोर पर, A, B के ठीक पश्चिम में, C दो सीट और पश्चिम में)। C का बायाँ पक्ष उसके पूर्व की सीट है, यानी E; D उन लोगों के लिए जाल का उत्तर है जो उन्हें उत्तर की ओर मुख वाला मान लेते हैं।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-10","question":"Eight persons sit equally spaced around a circular table facing the centre. A sits third to the left of B, and C sits opposite A. What is the position of C with respect to B?","options":["Immediate right","Second to the right","Immediate left","Third to the left"],"answer":0,"explanation":"Number the seats clockwise with B at 0; facing the centre, left is clockwise, so A is at 3 and C (opposite A) at 7, which is one seat anticlockwise of B, i.e. B’s immediate right.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। A, B के बाएँ से तीसरे स्थान पर बैठा है, और C, A के सामने बैठा है। B के सापेक्ष C की स्थिति क्या है?","optionsHi":["ठीक दाएँ","दाएँ से दूसरा","ठीक बाएँ","बाएँ से तीसरा"],"explanationHi":"सीटों को दक्षिणावर्त क्रमांकित कीजिए जिसमें B = 0 है; केंद्र की ओर मुख करने पर बायाँ पक्ष दक्षिणावर्त है, इसलिए A सीट 3 पर और C (A के सामने) सीट 7 पर है, जो B से एक सीट वामावर्त है, यानी B के ठीक दाएँ।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-11","question":"Seven persons sit in a row facing north. D sits exactly in the middle, B sits third to the right of D, and F sits to the immediate left of D. How many persons sit to the right of F?","options":["5","2","4","3"],"answer":2,"explanation":"D = 4, B = 7, F = 3. Seats 4 to 7 lie to F’s right, so 4 persons.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk · RRB NTPC","questionHi":"सात व्यक्ति उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं। D ठीक बीच में बैठा है, B, D के दाएँ से तीसरे स्थान पर बैठा है, और F, D के ठीक बाएँ बैठा है। F के दाएँ कितने व्यक्ति बैठे हैं?","optionsHi":["5","2","4","3"],"explanationHi":"D = 4, B = 7, F = 3। F के दाएँ सीट 4 से 7 तक हैं, इसलिए 4 व्यक्ति।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-12","question":"Six persons P, Q, R, S, T and U sit around a circle facing away from the centre. Q sits to the immediate left of P, S sits to the immediate right of P, R sits opposite Q, and U sits between R and T. Who sits to the immediate right of R?","options":["U","Q","T","S"],"answer":0,"explanation":"Facing outward, left is anticlockwise and right is clockwise. Clockwise from P: S, R, U, T, Q (Q anticlockwise of P, R opposite Q, U between R and T). R’s right (clockwise) is U.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह व्यक्ति P, Q, R, S, T और U केंद्र से बाहर की ओर मुख करके एक वृत्त में बैठे हैं। Q, P के ठीक बाएँ बैठा है, S, P के ठीक दाएँ बैठा है, R, Q के सामने बैठा है, और U, R तथा T के बीच बैठा है। R के ठीक दाएँ कौन बैठा है?","optionsHi":["U","Q","T","S"],"explanationHi":"बाहर की ओर मुख करने पर बायाँ पक्ष वामावर्त और दायाँ पक्ष दक्षिणावर्त होता है। P से दक्षिणावर्त: S, R, U, T, Q (Q, P से वामावर्त, R, Q के सामने, U, R और T के बीच)। R का दायाँ (दक्षिणावर्त) U है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-13","question":"Eight persons A to H sit in a row facing north. A sits fourth from the left end and three persons sit between A and D. C sits second to the left of D, and H is an immediate neighbour of both A and C. F sits to the immediate left of D. G sits at an extreme end, and B is not an immediate neighbour of A. Who sits exactly midway between B and C?","options":["H","A","G","E"],"answer":1,"explanation":"A = 4, D = 8, C = 6, H = 5, F = 7. G takes the free end seat 1; B cannot be 3 (next to A), so B = 2 and E = 3. Row: G, B, E, A, H, C, F, D; midway between B (2) and C (6) is seat 4, A.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति A से H तक उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं। A बाएँ छोर से चौथे स्थान पर बैठा है और A तथा D के बीच तीन व्यक्ति बैठे हैं। C, D के बाएँ से दूसरे स्थान पर बैठा है, और H, A तथा C दोनों का निकटतम पड़ोसी है। F, D के ठीक बाएँ बैठा है। G किसी एक छोर पर बैठा है, और B, A का निकटतम पड़ोसी नहीं है। B और C के ठीक बीच में कौन बैठा है?","optionsHi":["H","A","G","E"],"explanationHi":"A = 4, D = 8, C = 6, H = 5, F = 7। G खाली छोर वाली सीट 1 लेता है; B सीट 3 पर नहीं हो सकता (A के बगल में), इसलिए B = 2 और E = 3। पंक्ति: G, B, E, A, H, C, F, D; B (2) और C (6) के ठीक बीच सीट 4 है, यानी A।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-14","question":"Eight persons A to H sit around a circular table facing the centre. A sits opposite E, and B sits second to the left of A. F sits to the immediate right of B. C is not an immediate neighbour of A or E. D sits third to the right of C, and G sits to the immediate left of E. Who sits second to the right of G?","options":["D","C","B","H"],"answer":0,"explanation":"Seats clockwise from A = 0 (left is clockwise): B = 2, F = 1, E = 4; C must avoid 1, 3, 5, 7, so C = 6; D = 6 − 3 = 3; G = 5; H = 7. Clockwise: A, F, B, D, E, G, C, H. Two seats anticlockwise of G is D.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति A से H तक केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। A, E के सामने बैठा है, और B, A के बाएँ से दूसरे स्थान पर बैठा है। F, B के ठीक दाएँ बैठा है। C, A या E का निकटतम पड़ोसी नहीं है। D, C के दाएँ से तीसरे स्थान पर बैठा है, और G, E के ठीक बाएँ बैठा है। G के दाएँ से दूसरे स्थान पर कौन बैठा है?","optionsHi":["D","C","B","H"],"explanationHi":"A = 0 मानकर दक्षिणावर्त सीटें (बायाँ पक्ष दक्षिणावर्त है): B = 2, F = 1, E = 4; C को 1, 3, 5, 7 से बचना है, इसलिए C = 6; D = 6 − 3 = 3; G = 5; H = 7। दक्षिणावर्त: A, F, B, D, E, G, C, H। G से दो सीट वामावर्त D है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-15","question":"Six persons P, Q, R, S, T and U live on floors 1 (lowest) to 6, one per floor. P lives immediately above U, who lives on an even-numbered floor. Exactly two persons live between U and T, and T lives on a floor below Q. S lives on the top floor, and R lives immediately below U. Who lives immediately above Q?","options":["U","P","T","R"],"answer":3,"explanation":"If U = 2, then P = 3, T = 5 and Q would need floor 6, which S occupies, so U = 4, P = 5, T = 1, R = 3 and Q = 2. Floors 1→6: T, Q, R, U, P, S; R is directly above Q.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह व्यक्ति P, Q, R, S, T और U मंज़िल 1 (सबसे नीचे) से 6 तक रहते हैं, प्रत्येक मंज़िल पर एक व्यक्ति। P, U के ठीक ऊपर रहता है, जो एक सम संख्या वाली मंज़िल पर रहता है। U और T के बीच ठीक दो व्यक्ति रहते हैं, और T, Q से नीचे की मंज़िल पर रहता है। S सबसे ऊपरी मंज़िल पर रहता है, और R, U के ठीक नीचे रहता है। Q के ठीक ऊपर कौन रहता है?","optionsHi":["U","P","T","R"],"explanationHi":"यदि U = 2, तो P = 3, T = 5 और Q को मंज़िल 6 चाहिए, जिस पर S है, इसलिए U = 4, P = 5, T = 1, R = 3 और Q = 2। मंज़िल 1→6: T, Q, R, U, P, S; R, Q के ठीक ऊपर है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-16","question":"Six persons sit in a row, seats numbered 1 to 6 from west to east; some face north and some face south. A sits in seat 1 facing north, and every two neighbours face opposite directions. E sits at an end. C sits to the immediate right of E. B sits second to the left of C, and D does not sit next to A. Who sits to the immediate left of D?","options":["E","F","B","C"],"answer":3,"explanation":"Alternate facing gives odd seats north, even seats south. E = 6 (south), so its right is west: C = 5 (north); C’s left is west, so B = 3; D avoids seat 2, so D = 4 and F = 2. D faces south, so its left is east: seat 5, C (B is the north-facing trap).","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह व्यक्ति एक पंक्ति में बैठे हैं, सीटें पश्चिम से पूर्व की ओर 1 से 6 तक क्रमांकित हैं; कुछ का मुख उत्तर की ओर और कुछ का दक्षिण की ओर है। A सीट 1 पर उत्तर की ओर मुख करके बैठा है, और हर दो पड़ोसियों के मुख विपरीत दिशाओं में हैं। E किसी एक छोर पर बैठा है। C, E के ठीक दाएँ बैठा है। B, C के बाएँ से दूसरे स्थान पर बैठा है, और D, A के बगल में नहीं बैठा है। D के ठीक बाएँ कौन बैठा है?","optionsHi":["E","F","B","C"],"explanationHi":"एकांतर मुख होने से विषम सीटें उत्तर की ओर और सम सीटें दक्षिण की ओर मुख वाली हैं। E = 6 (दक्षिण की ओर मुख), इसलिए उसका दायाँ पश्चिम है: C = 5 (उत्तर की ओर मुख); C का बायाँ पश्चिम है, इसलिए B = 3; D सीट 2 से बचता है, इसलिए D = 4 और F = 2। D का मुख दक्षिण की ओर है, इसलिए उसका बायाँ पूर्व है: सीट 5, यानी C (B जाल का उत्तर है)।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-17","question":"Eight persons A to H sit around a square table: four sit at the corners facing the centre and four sit at the middle of the sides facing outside. A sits at a corner. E sits second to the right of A, and B sits to the immediate left of E. C sits third to the left of B, and G sits opposite B. D is an immediate neighbour of C, and F sits at a corner. Who sits to the immediate right of D?","options":["E","C","B","G"],"answer":0,"explanation":"Seats clockwise 0–7 with A = 0 (corners even). Corner sitters face in (left = clockwise), side sitters face out (left = anticlockwise). E = 6, B = 7, C = 7 − 3 = 4, G = 3, D = 5, F = 2, H = 1. Clockwise: A, H, F, G, C, D, E, B. D faces outside, so its right is clockwise: E.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति A से H तक एक वर्गाकार मेज़ के चारों ओर बैठे हैं: चार कोनों पर केंद्र की ओर मुख करके और चार भुजाओं के मध्य में बाहर की ओर मुख करके बैठे हैं। A किसी कोने पर बैठा है। E, A के दाएँ से दूसरे स्थान पर बैठा है, और B, E के ठीक बाएँ बैठा है। C, B के बाएँ से तीसरे स्थान पर बैठा है, और G, B के सामने बैठा है। D, C का निकटतम पड़ोसी है, और F किसी कोने पर बैठा है। D के ठीक दाएँ कौन बैठा है?","optionsHi":["E","C","B","G"],"explanationHi":"A = 0 मानकर दक्षिणावर्त सीटें 0–7 (कोने सम संख्या वाली सीटें हैं)। कोनों पर बैठे लोग अंदर की ओर मुख करते हैं (बायाँ = दक्षिणावर्त), भुजा के मध्य वाले बाहर की ओर मुख करते हैं (बायाँ = वामावर्त)। E = 6, B = 7, C = 7 − 3 = 4, G = 3, D = 5, F = 2, H = 1। दक्षिणावर्त: A, H, F, G, C, D, E, B। D का मुख बाहर की ओर है, इसलिए उसका दायाँ दक्षिणावर्त है: E।","subtopic":"square-rectangular"},
  {"id":"reason-seating-puzzles-18","question":"Six boxes P, Q, R, S, T and U are stacked one above another, position 1 being the bottom. R is third from the top, and exactly one box is kept between R and S. T is kept immediately below S. Q is above U and both are below R. U is kept immediately below P. How many boxes are kept between Q and T?","options":["4","1","2","3"],"answer":1,"explanation":"R = 4, so S = 2 or 6; S = 2 leaves no room for Q and U below R, so S = 6, T = 5, and U = 1, P = 2, Q = 3. Bottom to top: U, P, Q, R, T, S; only R lies between Q and T, i.e. 1.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह डिब्बे P, Q, R, S, T और U एक के ऊपर एक रखे गए हैं, स्थिति 1 सबसे नीचे है। R ऊपर से तीसरे स्थान पर है, और R तथा S के बीच ठीक एक डिब्बा रखा है। T, S के ठीक नीचे रखा है। Q, U के ऊपर है और दोनों R के नीचे हैं। U, P के ठीक नीचे रखा है। Q और T के बीच कितने डिब्बे रखे हैं?","optionsHi":["4","1","2","3"],"explanationHi":"R = 4, इसलिए S = 2 या 6; S = 2 होने पर R के नीचे Q और U के लिए जगह नहीं बचती, इसलिए S = 6, T = 5, और U = 1, P = 2, Q = 3। नीचे से ऊपर: U, P, Q, R, T, S; Q और T के बीच केवल R है, यानी 1।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-19","question":"A, B, C and D sit in row 1 facing south; P, Q, R and S sit in row 2 facing north, so each person faces one person of the other row. B sits at an end of row 1 and faces Q. S sits to the immediate left of Q. A sits to the immediate right of D. R sits at an end of row 2, and P faces A. Who faces the person sitting to the immediate left of A?","options":["P","Q","R","S"],"answer":3,"explanation":"Number both rows 1–4 west to east. Q faces north, so its left is west; Q cannot be at the west end, so Q = 4, S = 3, R = 1, P = 2. A faces P, so A = 2; A faces south, so its right is west and D = 3; C = 1, B = 4. A’s left is east, seat 3 (D), who faces S.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"A, B, C और D पंक्ति 1 में दक्षिण की ओर मुख करके बैठे हैं; P, Q, R और S पंक्ति 2 में उत्तर की ओर मुख करके बैठे हैं, इसलिए प्रत्येक व्यक्ति दूसरी पंक्ति के एक व्यक्ति के सामने है। B पंक्ति 1 के एक छोर पर बैठा है और Q के सामने है। S, Q के ठीक बाएँ बैठा है। A, D के ठीक दाएँ बैठा है। R पंक्ति 2 के एक छोर पर बैठा है, और P, A के सामने है। A के ठीक बाएँ बैठे व्यक्ति के सामने कौन बैठा है?","optionsHi":["P","Q","R","S"],"explanationHi":"दोनों पंक्तियों की सीटों को पश्चिम से पूर्व 1–4 क्रमांकित कीजिए। Q का मुख उत्तर की ओर है, इसलिए उसका बायाँ पश्चिम है; Q पश्चिमी छोर पर नहीं हो सकता, इसलिए Q = 4, S = 3, R = 1, P = 2। A, P के सामने है, इसलिए A = 2; A का मुख दक्षिण की ओर है, इसलिए उसका दायाँ पश्चिम है और D = 3; C = 1, B = 4। A का बायाँ पूर्व है, सीट 3 (D), जो S के सामने है।","subtopic":"double-row"},
  {"id":"reason-seating-puzzles-20","question":"Six persons P, Q, R, S, T and U sit around a circle; some face the centre and some face outside. P faces the centre and Q sits to the immediate left of P. R sits opposite P and faces the centre. Q faces outside and S sits to the immediate right of Q. T sits to the immediate left of R. If S faces the centre, who sits second to the left of S?","options":["R","P","T","U"],"answer":2,"explanation":"Seats clockwise with P = 0: Q = 1 (P’s left, clockwise), R = 3, S = 2 (Q faces out, so its right is clockwise), T = 4 (R faces in, left clockwise), U = 5. Clockwise: P, Q, S, R, T, U. S faces in, so two places clockwise from S is T.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह व्यक्ति P, Q, R, S, T और U एक वृत्त में बैठे हैं; कुछ का मुख केंद्र की ओर और कुछ का बाहर की ओर है। P का मुख केंद्र की ओर है और Q, P के ठीक बाएँ बैठा है। R, P के सामने बैठा है और उसका मुख केंद्र की ओर है। Q का मुख बाहर की ओर है और S, Q के ठीक दाएँ बैठा है। T, R के ठीक बाएँ बैठा है। यदि S का मुख केंद्र की ओर है, तो S के बाएँ से दूसरे स्थान पर कौन बैठा है?","optionsHi":["R","P","T","U"],"explanationHi":"P = 0 मानकर दक्षिणावर्त सीटें: Q = 1 (P का बायाँ, दक्षिणावर्त), R = 3, S = 2 (Q का मुख बाहर की ओर है, इसलिए उसका दायाँ दक्षिणावर्त है), T = 4 (R का मुख अंदर की ओर है, बायाँ दक्षिणावर्त), U = 5। दक्षिणावर्त: P, Q, S, R, T, U। S का मुख अंदर की ओर है, इसलिए S से दक्षिणावर्त दो स्थान आगे T है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-21","question":"Seven persons J, K, L, M, N, O and P attend a seminar on different days of one week, Monday to Sunday. J attends on Wednesday. Only one person attends between J and L, and L attends after J. N attends immediately after L. K attends before M, and both attend before J. P does not attend on Thursday. Who attends exactly midway between M and N?","options":["O","J","L","P"],"answer":0,"explanation":"J = Wednesday, L = Friday, N = Saturday; K and M fill Monday and Tuesday in that order. P avoids Thursday, so P = Sunday and O = Thursday. M is Tuesday and N Saturday, so the midpoint is Thursday, O.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"सात व्यक्ति J, K, L, M, N, O और P एक सप्ताह के अलग-अलग दिनों, सोमवार से रविवार तक, एक संगोष्ठी में भाग लेते हैं। J बुधवार को भाग लेता है। J और L के बीच केवल एक व्यक्ति भाग लेता है, और L, J के बाद भाग लेता है। N, L के ठीक बाद भाग लेता है। K, M से पहले भाग लेता है, और दोनों J से पहले भाग लेते हैं। P गुरुवार को भाग नहीं लेता है। M और N के ठीक बीच में कौन भाग लेता है?","optionsHi":["O","J","L","P"],"explanationHi":"J = बुधवार, L = शुक्रवार, N = शनिवार; K और M सोमवार और मंगलवार को इसी क्रम में आते हैं। P गुरुवार से बचता है, इसलिए P = रविवार और O = गुरुवार। M मंगलवार को और N शनिवार को है, इसलिए मध्य बिंदु गुरुवार है, यानी O।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-22","question":"Seven persons A to G sit in a row facing north. E sits third from the right end. As many persons sit to the left of E as to the right of B. C sits to the immediate right of B. Two persons sit between C and F. G sits at an extreme end and to the left of D, and D is an immediate neighbour of E. Who sits second to the right of C?","options":["F","E","D","A"],"answer":2,"explanation":"E = 5 with 4 people to its left, so B has 4 to its right: B = 3, C = 4, F = 1 or 7. G must be at seat 1 to have D on its right, so F = 7; D next to E gives D = 6 and A = 2. Row: G, A, B, C, E, D, F; second to the right of C is D.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"सात व्यक्ति A से G तक उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं। E दाएँ छोर से तीसरे स्थान पर बैठा है। E के बाएँ उतने ही व्यक्ति बैठे हैं जितने B के दाएँ बैठे हैं। C, B के ठीक दाएँ बैठा है। C और F के बीच दो व्यक्ति बैठे हैं। G किसी एक छोर पर और D के बाएँ बैठा है, और D, E का निकटतम पड़ोसी है। C के दाएँ से दूसरे स्थान पर कौन बैठा है?","optionsHi":["F","E","D","A"],"explanationHi":"E = 5 और उसके बाएँ 4 व्यक्ति हैं, इसलिए B के दाएँ 4 व्यक्ति हैं: B = 3, C = 4, F = 1 या 7। G को D के दाएँ रखने के लिए G सीट 1 पर होना चाहिए, इसलिए F = 7; D, E के बगल में है तो D = 6 और A = 2। पंक्ति: G, A, B, C, E, D, F; C के दाएँ से दूसरा D है।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-23","question":"Seven persons A to G sit around a circular table facing the centre (no two sit opposite each other). B sits third to the left of A, and C sits second to the right of B. D is an immediate neighbour of A but not of C. E sits to the immediate left of B, and F is not an immediate neighbour of D. Who sits exactly between E and D?","options":["F","B","G","A"],"answer":2,"explanation":"Seats clockwise 0–6 with A = 0 (left = clockwise): B = 3, C = 1, D = 6, E = 4; F avoids 5 (next to D), so F = 2 and G = 5. Clockwise: A, C, F, B, E, G, D; G sits between E and D.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"सात व्यक्ति A से G तक केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर बैठे हैं (कोई भी दो एक-दूसरे के सामने नहीं बैठे हैं)। B, A के बाएँ से तीसरे स्थान पर बैठा है, और C, B के दाएँ से दूसरे स्थान पर बैठा है। D, A का निकटतम पड़ोसी है पर C का नहीं है। E, B के ठीक बाएँ बैठा है, और F, D का निकटतम पड़ोसी नहीं है। E और D के ठीक बीच में कौन बैठा है?","optionsHi":["F","B","G","A"],"explanationHi":"A = 0 मानकर दक्षिणावर्त सीटें 0–6 (बायाँ = दक्षिणावर्त): B = 3, C = 1, D = 6, E = 4; F सीट 5 से बचता है (D के बगल में), इसलिए F = 2 और G = 5। दक्षिणावर्त: A, C, F, B, E, G, D; G, E और D के बीच बैठा है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-24","question":"Five friends P, Q, R, S and T sit in a row facing north, each owning a car of a different colour: red, blue, green, white and black. R sits in the middle. The green car’s owner sits at the extreme right end and Q sits to his immediate left. T sits at an extreme end and owns the red car. P is not an immediate neighbour of R. The blue car’s owner sits to the immediate right of S, and Q does not own the white car. Who owns the white car?","options":["Q","R","T","S"],"answer":3,"explanation":"R = 3, Q = 4; P and T must be at the ends and T (red) cannot be the green owner at seat 5, so T = 1, P = 5 (green), S = 2. R, right of S, owns blue; Q is not white, so Q has black and S white. Row: T-red, S-white, R-blue, Q-black, P-green.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"पाँच मित्र P, Q, R, S और T उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं, और प्रत्येक के पास अलग रंग की कार है: लाल, नीली, हरी, सफेद और काली। R बीच में बैठा है। हरी कार का मालिक सबसे दाएँ छोर पर बैठा है और Q उसके ठीक बाएँ बैठा है। T किसी एक छोर पर बैठा है और उसके पास लाल कार है। P, R का निकटतम पड़ोसी नहीं है। नीली कार का मालिक S के ठीक दाएँ बैठा है, और Q के पास सफेद कार नहीं है। सफेद कार का मालिक कौन है?","optionsHi":["Q","R","T","S"],"explanationHi":"R = 3, Q = 4; P और T छोरों पर होने चाहिए और T (लाल) सीट 5 पर हरी कार का मालिक नहीं हो सकता, इसलिए T = 1, P = 5 (हरी), S = 2। S के दाएँ R के पास नीली कार है; Q के पास सफेद नहीं है, इसलिए Q के पास काली और S के पास सफेद है। पंक्ति: T-लाल, S-सफेद, R-नीली, Q-काली, P-हरी।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-25","question":"Some persons sit in a row facing north. A sits fourth from the left end, and exactly two persons sit between A and B, with B to the right of A. B is eighth from the right end. D sits third from the right end and C sits exactly midway between A and D. How many persons sit between B and the person who sits second to the right of C?","options":["2","1","4","3"],"answer":0,"explanation":"A = 4, B = 7, and 7 + 8 − 1 = 14 persons in all. D = 14 − 3 + 1 = 12, so C = (4 + 12)/2 = 8 and the person second to C’s right is at 10. Between seats 7 and 10 sit 8 and 9: 2 persons.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"कुछ व्यक्ति उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं। A बाएँ छोर से चौथे स्थान पर बैठा है, और A तथा B के बीच ठीक दो व्यक्ति बैठे हैं, B, A के दाएँ है। B दाएँ छोर से आठवें स्थान पर है। D दाएँ छोर से तीसरे स्थान पर बैठा है और C, A तथा D के ठीक बीच में बैठा है। B और C के दाएँ से दूसरे स्थान पर बैठे व्यक्ति के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["2","1","4","3"],"explanationHi":"A = 4, B = 7, और कुल व्यक्ति 7 + 8 − 1 = 14 हैं। D = 14 − 3 + 1 = 12, इसलिए C = (4 + 12)/2 = 8 और C के दाएँ से दूसरा व्यक्ति 10 पर है। सीट 7 और 10 के बीच 8 और 9 बैठे हैं: 2 व्यक्ति।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-26","question":"Eight persons J, K, L, M, N, O, P and Q sit around a circular table facing the centre. M sits third to the right of J. Only one person sits between M and Q when counted clockwise from M. K sits opposite Q and L sits to the immediate left of K. N is not an immediate neighbour of J, and P sits to the immediate right of N. How many of these statements are true? I. O sits to the immediate right of Q. II. N sits second to the left of J. III. L sits opposite J. IV. M is an immediate neighbour of both L and O.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"Clockwise from J = 0: J, P, N, K, L, M, O, Q. O is to Q's immediate right, N is second to J's left, L (seat 4) is opposite J (seat 0), and M sits between L and O. All four are true.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति J, K, L, M, N, O, P और Q केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। M, J के दाएँ से तीसरे स्थान पर बैठा है। M से दक्षिणावर्त गिनने पर M और Q के बीच केवल एक व्यक्ति बैठा है। K, Q के सामने बैठा है और L, K के ठीक बाएँ बैठा है। N, J का निकटतम पड़ोसी नहीं है, और P, N के ठीक दाएँ बैठा है। इनमें से कितने कथन सत्य हैं? I. O, Q के ठीक दाएँ बैठा है। II. N, J के बाएँ से दूसरे स्थान पर बैठा है। III. L, J के सामने बैठा है। IV. M, L और O दोनों का निकटतम पड़ोसी है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"J = 0 से दक्षिणावर्त: J, P, N, K, L, M, O, Q। O, Q के ठीक दाएँ है, N, J के बाएँ से दूसरे स्थान पर है, L (सीट 4), J (सीट 0) के सामने है, और M, L तथा O के बीच बैठा है। चारों कथन सत्य हैं।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-27","question":"Eight persons A to H live on floors 1 (lowest) to 8, one per floor. D lives on an odd-numbered floor above floor 4, and three persons live between D and G. B lives immediately above G. Only one person lives between B and A, and A lives above B. C lives on the lowest floor and E lives immediately above C. F lives above H. How many of these statements are true? I. Two persons live between H and E. II. F lives immediately above D. III. B lives exactly midway between G and A. IV. G lives immediately below H.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"D = 5 would give G = 1, clashing with C, so D = 7, G = 3, B = 4, A = 6, C = 1, E = 2, and F, H take 8 and 5. Floors 1→8: C, E, G, B, H, A, D, F. I (floors 3, 4 between) and II are true; III is false (midway of 3 and 6 is 4.5) and IV is false.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति A से H तक मंज़िल 1 (सबसे नीचे) से 8 तक रहते हैं, प्रत्येक मंज़िल पर एक व्यक्ति। D मंज़िल 4 से ऊपर की एक विषम संख्या वाली मंज़िल पर रहता है, और D तथा G के बीच तीन व्यक्ति रहते हैं। B, G के ठीक ऊपर रहता है। B और A के बीच केवल एक व्यक्ति रहता है, और A, B के ऊपर रहता है। C सबसे निचली मंज़िल पर रहता है और E, C के ठीक ऊपर रहता है। F, H के ऊपर रहता है। इनमें से कितने कथन सत्य हैं? I. H और E के बीच दो व्यक्ति रहते हैं। II. F, D के ठीक ऊपर रहता है। III. B, G और A के ठीक बीच में रहता है। IV. G, H के ठीक नीचे रहता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"D = 5 होने पर G = 1 आता, जो C से टकराता है, इसलिए D = 7, G = 3, B = 4, A = 6, C = 1, E = 2, और F, H मंज़िल 8 और 5 लेते हैं। मंज़िल 1→8: C, E, G, B, H, A, D, F। I (मंज़िल 3, 4 बीच में) और II सत्य हैं; III असत्य है (3 और 6 का मध्य 4.5 है) और IV असत्य है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-28","question":"Eight persons P, Q, R, K, T, U, V and W sit in a row, seats numbered 1 to 8 from west to east; some face north and some face south. P sits in seat 4 facing north, and R sits second to the right of P. U sits to the immediate left of R, and U and R face opposite directions. K sits at an end facing south, and V sits third to the right of K and faces north. T sits at the west end facing north. W faces south and Q sits to the immediate right of W. Who sits to the immediate left of the person who sits second to the left of U?","options":["T","R","W","P"],"answer":3,"explanation":"R = 6. K must be at seat 8 (south-facing, its right is west) so V = 5; U cannot be 5, so U = 7, meaning R faces south and U north. T = 1; W faces south, its right is west, so Q = 2 and W = 3. U faces north: second to its left is V (5); V faces north, so its immediate left is P (4).","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति P, Q, R, K, T, U, V और W एक पंक्ति में बैठे हैं, सीटें पश्चिम से पूर्व की ओर 1 से 8 तक क्रमांकित हैं; कुछ का मुख उत्तर की ओर और कुछ का दक्षिण की ओर है। P सीट 4 पर उत्तर की ओर मुख करके बैठा है, और R, P के दाएँ से दूसरे स्थान पर बैठा है। U, R के ठीक बाएँ बैठा है, और U तथा R के मुख विपरीत दिशाओं में हैं। K किसी एक छोर पर दक्षिण की ओर मुख करके बैठा है, और V, K के दाएँ से तीसरे स्थान पर बैठा है और उसका मुख उत्तर की ओर है। T पश्चिमी छोर पर उत्तर की ओर मुख करके बैठा है। W का मुख दक्षिण की ओर है और Q, W के ठीक दाएँ बैठा है। U के बाएँ से दूसरे स्थान पर बैठे व्यक्ति के ठीक बाएँ कौन बैठा है?","optionsHi":["T","R","W","P"],"explanationHi":"R = 6। K को सीट 8 पर होना चाहिए (दक्षिण की ओर मुख, उसका दायाँ पश्चिम है), इसलिए V = 5; U सीट 5 पर नहीं हो सकता, इसलिए U = 7, यानी R का मुख दक्षिण की ओर और U का उत्तर की ओर है। T = 1; W का मुख दक्षिण की ओर है, उसका दायाँ पश्चिम है, इसलिए Q = 2 और W = 3। U का मुख उत्तर की ओर है: उसके बाएँ से दूसरा V (5) है; V का मुख उत्तर की ओर है, इसलिए उसके ठीक बाएँ P (4) है।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-29","question":"Eight persons A to H sit around a square table: four sit at the corners facing outside and four at the middle of the sides facing the centre. G sits at a corner. C sits third to the left of G, and A sits opposite C. E sits second to the right of A, and B sits to the immediate right of E. H is not an immediate neighbour of C. D sits at a corner, and F sits to the immediate left of D. Who sits second to the right of F?","options":["C","A","H","D"],"answer":1,"explanation":"Seats clockwise 0–7 with G = 0 (corners even, facing out: left = anticlockwise; sides facing in: left = clockwise). C = 5, A = 1, E = 7, B = 6. D = 2 would put F on A, so D = 4, F = 3, H = 2. Clockwise: G, A, H, F, D, C, B, E. F faces the centre, so its right is anticlockwise: two seats gives A.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति A से H तक एक वर्गाकार मेज़ के चारों ओर बैठे हैं: चार कोनों पर बाहर की ओर मुख करके और चार भुजाओं के मध्य में केंद्र की ओर मुख करके बैठे हैं। G किसी कोने पर बैठा है। C, G के बाएँ से तीसरे स्थान पर बैठा है, और A, C के सामने बैठा है। E, A के दाएँ से दूसरे स्थान पर बैठा है, और B, E के ठीक दाएँ बैठा है। H, C का निकटतम पड़ोसी नहीं है। D किसी कोने पर बैठा है, और F, D के ठीक बाएँ बैठा है। F के दाएँ से दूसरे स्थान पर कौन बैठा है?","optionsHi":["C","A","H","D"],"explanationHi":"G = 0 मानकर दक्षिणावर्त सीटें 0–7 (कोने सम संख्या वाली सीटें हैं, बाहर की ओर मुख: बायाँ = वामावर्त; भुजा के मध्य वाले अंदर की ओर मुख: बायाँ = दक्षिणावर्त)। C = 5, A = 1, E = 7, B = 6। D = 2 होने पर F, A की जगह आ जाता, इसलिए D = 4, F = 3, H = 2। दक्षिणावर्त: G, A, H, F, D, C, B, E। F का मुख केंद्र की ओर है, इसलिए उसका दायाँ वामावर्त है: दो सीट पर A मिलता है।","subtopic":"square-rectangular"},
  {"id":"reason-seating-puzzles-30","question":"A building has four floors (1 at the bottom to 4 at the top), each with two flats: Flat A on the west and Flat B on the east, with each Flat A directly above the Flat A below it. Eight persons live one per flat. P lives in Flat A of an odd-numbered floor, and T lives in the flat immediately east of P. Q lives on floor 1 in the same type of flat as T, and S lives to the west of Q. N lives directly above Q and M directly above T. O lives directly below P. Which pair lives on the same floor?","options":["R and M","P and M","S and N","O and T"],"answer":0,"explanation":"If P were on floor 1, T and Q would both need flat 1B, so P = 3A, T = 3B, Q = 1B, S = 1A, N = 2B, M = 4B, O = 2A and R = 4A. Floor 4: R, M; floor 3: P, T; floor 2: O, N; floor 1: S, Q.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"एक इमारत में चार मंज़िलें हैं (1 सबसे नीचे से 4 सबसे ऊपर तक), प्रत्येक पर दो फ्लैट हैं: फ्लैट A पश्चिम में और फ्लैट B पूर्व में, और प्रत्येक फ्लैट A अपने नीचे वाले फ्लैट A के ठीक ऊपर है। आठ व्यक्ति रहते हैं, प्रत्येक फ्लैट में एक। P एक विषम संख्या वाली मंज़िल के फ्लैट A में रहता है, और T, P के ठीक पूर्व वाले फ्लैट में रहता है। Q मंज़िल 1 पर उसी प्रकार के फ्लैट में रहता है जिसमें T रहता है, और S, Q के पश्चिम में रहता है। N, Q के ठीक ऊपर और M, T के ठीक ऊपर रहता है। O, P के ठीक नीचे रहता है। कौन-सा जोड़ा एक ही मंज़िल पर रहता है?","optionsHi":["R और M","P और M","S और N","O और T"],"explanationHi":"यदि P मंज़िल 1 पर होता, तो T और Q दोनों को फ्लैट 1B चाहिए होता, इसलिए P = 3A, T = 3B, Q = 1B, S = 1A, N = 2B, M = 4B, O = 2A और R = 4A। मंज़िल 4: R, M; मंज़िल 3: P, T; मंज़िल 2: O, N; मंज़िल 1: S, Q।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-31","question":"Six persons A to F go on trips in six months, January to June, one per month, each to a different city: Pune, Goa, Agra, Ooty, Leh and Kochi. Agra is visited in a 31-day month after February, and C travels in the month immediately after the Agra traveller, in a 30-day month. D goes to Leh after C. B travels in June. A travels immediately after E, and F goes to Agra. Goa is visited in the month with fewer than 30 days, Pune is visited before Goa, and B does not go to Ooty. Who goes to Ooty, and in which month?","options":["F, March","C, June","C, April","B, June"],"answer":2,"explanation":"Agra is March or May; May would put C in June and leave no month for D after C, so Agra = March (F), C = April, D = May (Leh), B = June, E = January, A = February. Goa = February (A), Pune = January (E), and B takes Kochi, leaving Ooty for C in April.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह व्यक्ति A से F तक जनवरी से जून के छह महीनों में यात्राएँ करते हैं, प्रत्येक महीने में एक, और प्रत्येक अलग शहर जाता है: पुणे, गोवा, आगरा, ऊटी, लेह और कोच्चि। आगरा फरवरी के बाद के 31 दिन वाले महीने में जाया जाता है, और C आगरा जाने वाले के ठीक अगले महीने में यात्रा करता है, जो 30 दिन का महीना है। D, C के बाद लेह जाता है। B जून में यात्रा करता है। A, E के ठीक बाद यात्रा करता है, और F आगरा जाता है। गोवा उस महीने में जाया जाता है जिसमें 30 दिन से कम होते हैं, पुणे गोवा से पहले जाया जाता है, और B ऊटी नहीं जाता। ऊटी कौन जाता है, और किस महीने में?","optionsHi":["F, मार्च","C, जून","C, अप्रैल","B, जून"],"explanationHi":"आगरा मार्च या मई है; मई होने पर C जून में आता और C के बाद D के लिए कोई महीना नहीं बचता, इसलिए आगरा = मार्च (F), C = अप्रैल, D = मई (लेह), B = जून, E = जनवरी, A = फरवरी। गोवा = फरवरी (A), पुणे = जनवरी (E), और B कोच्चि लेता है, जिससे ऊटी अप्रैल में C के लिए बचता है।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-32","question":"Eight persons A to H sit around a circle; four face the centre and four face outside. A faces the centre. D sits second to the left of A, and both immediate neighbours of A face outside. F sits opposite A and faces the same direction as A. B sits to the immediate right of F and faces outside. C sits third to the right of B. D faces outside and H sits to the immediate left of D. C faces the centre and E sits to the immediate right of C. How many of these statements are true? I. G sits to the immediate left of A. II. E faces the centre. III. H sits opposite C. IV. Exactly two persons sit between D and F counted clockwise from D.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Seats clockwise from A = 0: D = 2, F = 4, B = 3, C = 6 (B faces out, right = clockwise), H = 1, E = 5, G = 7. Facing centre: A, F, C and so E; facing out: H, D, B, G. Only II is true: A’s left is H, H is opposite E, and only B sits between D and F clockwise.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति A से H तक एक वृत्त में बैठे हैं; चार का मुख केंद्र की ओर और चार का बाहर की ओर है। A का मुख केंद्र की ओर है। D, A के बाएँ से दूसरे स्थान पर बैठा है, और A के दोनों निकटतम पड़ोसियों का मुख बाहर की ओर है। F, A के सामने बैठा है और उसका मुख A की ही दिशा में है। B, F के ठीक दाएँ बैठा है और उसका मुख बाहर की ओर है। C, B के दाएँ से तीसरे स्थान पर बैठा है। D का मुख बाहर की ओर है और H, D के ठीक बाएँ बैठा है। C का मुख केंद्र की ओर है और E, C के ठीक दाएँ बैठा है। इनमें से कितने कथन सत्य हैं? I. G, A के ठीक बाएँ बैठा है। II. E का मुख केंद्र की ओर है। III. H, C के सामने बैठा है। IV. D से दक्षिणावर्त गिनने पर D और F के बीच ठीक दो व्यक्ति बैठे हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"A = 0 से दक्षिणावर्त सीटें: D = 2, F = 4, B = 3, C = 6 (B का मुख बाहर की ओर है, दायाँ = दक्षिणावर्त), H = 1, E = 5, G = 7। केंद्र की ओर मुख: A, F, C और इसलिए E; बाहर की ओर मुख: H, D, B, G। केवल II सत्य है: A का बायाँ H है, H, E के सामने है, और दक्षिणावर्त D और F के बीच केवल B बैठा है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-33","question":"Seven boxes P, Q, R, S, T, U and V are stacked one above another, position 1 being the bottom. V is exactly in the middle of the stack, and two boxes are kept between V and R. Q is kept above R. Only one box is kept between R and S, and U is kept immediately above R. P is kept below T, Q is not kept immediately above V, and T is kept immediately below Q. How many of these statements are true? I. P is kept immediately above V. II. Three boxes are kept between U and P. III. U is at the bottom. IV. P is second from the top.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Bottom to top: R, U, S, V, P, T, Q. Only I is true (P is just above V). II is false (only S and V lie between U and P), III is false (R, not U, is at the bottom) and IV is false (T, not P, is second from the top).","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"सात डिब्बे P, Q, R, S, T, U और V एक के ऊपर एक रखे गए हैं, स्थिति 1 सबसे नीचे है। V ढेर के ठीक बीच में है, और V तथा R के बीच दो डिब्बे रखे हैं। Q, R के ऊपर रखा है। R और S के बीच केवल एक डिब्बा रखा है, और U, R के ठीक ऊपर रखा है। P, T के नीचे रखा है, Q, V के ठीक ऊपर नहीं रखा है, और T, Q के ठीक नीचे रखा है। इनमें से कितने कथन सत्य हैं? I. P, V के ठीक ऊपर रखा है। II. U और P के बीच तीन डिब्बे रखे हैं। III. U सबसे नीचे है। IV. P ऊपर से दूसरे स्थान पर है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"नीचे से ऊपर: R, U, S, V, P, T, Q। केवल I सत्य है (P, V के ठीक ऊपर है)। II असत्य है (U और P के बीच केवल S और V हैं), III असत्य है (सबसे नीचे U नहीं, R है) और IV असत्य है (ऊपर से दूसरे स्थान पर P नहीं, T है)।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-34","question":"Seven persons J, K, L, M, O, P and N sit in a row facing north. K sits third from an end, and only two persons sit between K and N, with N to the right of K. As many persons sit to the right of N as to the left of J. M sits at an extreme end and is not an immediate neighbour of J. P sits to the immediate left of O. If all seven are re-seated in alphabetical order from left to right, how many of them keep their original seats?","options":["None","Three","One","Two"],"answer":0,"explanation":"K = 5 would put N at 8, so K = 3 and N = 6; one person is right of N, so J = 2. M must be at 7, P = 4, O = 5 and L = 1. Original: L, J, K, P, O, N, M; alphabetical: J, K, L, M, N, O, P. No seat holds the same person.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"सात व्यक्ति J, K, L, M, O, P और N उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं। K किसी एक छोर से तीसरे स्थान पर बैठा है, और K तथा N के बीच केवल दो व्यक्ति बैठे हैं, N, K के दाएँ है। N के दाएँ उतने ही व्यक्ति बैठे हैं जितने J के बाएँ बैठे हैं। M किसी एक छोर पर बैठा है और J का निकटतम पड़ोसी नहीं है। P, O के ठीक बाएँ बैठा है। यदि सातों को बाएँ से दाएँ वर्णमाला क्रम में फिर से बिठाया जाए, तो उनमें से कितने अपनी मूल सीट पर बने रहेंगे?","optionsHi":["कोई नहीं","तीन","एक","दो"],"explanationHi":"K = 5 होने पर N = 8 आता, इसलिए K = 3 और N = 6; N के दाएँ एक व्यक्ति है, इसलिए J = 2। M को 7 पर होना चाहिए, P = 4, O = 5 और L = 1। मूल क्रम: L, J, K, P, O, N, M; वर्णमाला क्रम: J, K, L, M, N, O, P। किसी सीट पर वही व्यक्ति नहीं रहता।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-35","question":"Six persons A to F sit around a circular table facing the centre, each liking a different fruit: apple, banana, cherry, grape, mango and orange. A likes mango. F likes grape and sits opposite A. C sits second to the right of A, and E sits to the immediate left of C. B is not an immediate neighbour of A, and D sits to the immediate right of B. The cherry lover sits to the immediate left of the grape lover. D likes neither apple nor orange. The orange lover sits to the immediate right of A. Which combination is correct?","options":["B – apple – sits opposite D","E – apple – sits opposite B","C – orange – sits opposite D","D – banana – sits opposite C"],"answer":3,"explanation":"Seats clockwise from A = 0 (left = clockwise): F = 3, C = 4, E = 5, B = 2, D = 1. Cherry is clockwise of F, so C; orange is anticlockwise of A, so E; D takes banana and B apple. Clockwise: A-mango, D-banana, B-apple, F-grape, C-cherry, E-orange; D (1) is opposite C (4).","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह व्यक्ति A से F तक केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर बैठे हैं, और प्रत्येक को अलग फल पसंद है: सेब, केला, चेरी, अंगूर, आम और संतरा। A को आम पसंद है। F को अंगूर पसंद है और वह A के सामने बैठा है। C, A के दाएँ से दूसरे स्थान पर बैठा है, और E, C के ठीक बाएँ बैठा है। B, A का निकटतम पड़ोसी नहीं है, और D, B के ठीक दाएँ बैठा है। चेरी पसंद करने वाला अंगूर पसंद करने वाले के ठीक बाएँ बैठा है। D को न सेब पसंद है न संतरा। संतरा पसंद करने वाला A के ठीक दाएँ बैठा है। कौन-सा संयोजन सही है?","optionsHi":["B – सेब – D के सामने बैठा है","E – सेब – B के सामने बैठा है","C – संतरा – D के सामने बैठा है","D – केला – C के सामने बैठा है"],"explanationHi":"A = 0 से दक्षिणावर्त सीटें (बायाँ = दक्षिणावर्त): F = 3, C = 4, E = 5, B = 2, D = 1। चेरी वाला F के दक्षिणावर्त है, यानी C; संतरे वाला A के वामावर्त है, यानी E; D को केला और B को सेब मिलता है। दक्षिणावर्त: A-आम, D-केला, B-सेब, F-अंगूर, C-चेरी, E-संतरा; D (1), C (4) के सामने है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-36","question":"Some persons sit around a circular table facing the centre. P is fifth to the left of Q and also seventh to the right of Q. R sits third to the right of P. How many persons sit between R and Q when counted in the direction of R’s left?","options":["1","10","9","8"],"answer":2,"explanation":"5 + 7 = 12 persons. Seats clockwise with Q = 0 (left = clockwise): P = 5, R = 5 − 3 = 2. Moving clockwise (R’s left) from 2 to Q at 0 passes seats 3 to 11: 9 persons; 1 is the count the other way.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"कुछ व्यक्ति केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। P, Q के बाएँ से पाँचवें स्थान पर है और Q के दाएँ से सातवें स्थान पर भी है। R, P के दाएँ से तीसरे स्थान पर बैठा है। R के बाएँ की दिशा में गिनने पर R और Q के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["1","10","9","8"],"explanationHi":"5 + 7 = 12 व्यक्ति हैं। Q = 0 मानकर दक्षिणावर्त सीटें (बायाँ = दक्षिणावर्त): P = 5, R = 5 − 3 = 2। 2 से Q (0) की ओर दक्षिणावर्त (R के बाएँ) चलने पर सीट 3 से 11 पार होती हैं: 9 व्यक्ति; 1 दूसरी दिशा की गिनती है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-37","question":"Seven persons A to G live on floors 1 (lowest) to 7, one per floor. G lives on an even-numbered floor above floor 3, and C lives two floors below G. E lives immediately above A. Four persons live between A and F, and F lives above A. B does not live above D. How many of these statements are true? I. D lives immediately below G. II. Exactly two persons live between E and G. III. B lives immediately below A. IV. F lives exactly three floors above C.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"G = 4 would put C on 2 and leave no valid A–F pair, so G = 6, C = 4; A = 2, F = 7 (A = 1 needs F = 6), E = 3; B and D take 1 and 5 with B lower. Floors 1→7: B, A, E, C, D, G, F. All four statements are true.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"सात व्यक्ति A से G तक मंज़िल 1 (सबसे नीचे) से 7 तक रहते हैं, प्रत्येक मंज़िल पर एक व्यक्ति। G मंज़िल 3 से ऊपर की एक सम संख्या वाली मंज़िल पर रहता है, और C, G से दो मंज़िल नीचे रहता है। E, A के ठीक ऊपर रहता है। A और F के बीच चार व्यक्ति रहते हैं, और F, A के ऊपर रहता है। B, D से ऊपर नहीं रहता। इनमें से कितने कथन सत्य हैं? I. D, G के ठीक नीचे रहता है। II. E और G के बीच ठीक दो व्यक्ति रहते हैं। III. B, A के ठीक नीचे रहता है। IV. F, C से ठीक तीन मंज़िल ऊपर रहता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"G = 4 होने पर C = 2 आता और A–F की कोई वैध जोड़ी नहीं बचती, इसलिए G = 6, C = 4; A = 2, F = 7 (A = 1 के लिए F = 6 चाहिए), E = 3; B और D मंज़िल 1 और 5 लेते हैं जिनमें B नीचे है। मंज़िल 1→7: B, A, E, C, D, G, F। चारों कथन सत्य हैं।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-38","question":"Six persons A to F sit in a row facing north, each liking a different subject: Hindi, English, Maths, Physics, History and Biology. D sits at an extreme end, and only two persons sit between D and E. B sits to the immediate right of E. The Maths lover sits to the immediate left of E, and F sits to the immediate left of the Maths lover. C sits at an extreme end and likes Physics. The History lover sits at an extreme end. The English lover sits second to the right of the Maths lover, and F does not like Biology. Who sits second to the left of the Biology lover, and what does that person like?","options":["F – Hindi","A – Maths","F – Biology","D – History"],"answer":0,"explanation":"D = 6 would force F onto C’s seat, so D = 1, E = 4, B = 5, C = 6, Maths = seat 3 (A), F = 2. D likes History, B English (seat 5), F Hindi, E Biology. Row: D-History, F-Hindi, A-Maths, E-Biology, B-English, C-Physics; second left of E is F.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह व्यक्ति A से F तक उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं, और प्रत्येक को अलग विषय पसंद है: हिंदी, अंग्रेज़ी, गणित, भौतिकी, इतिहास और जीव विज्ञान। D किसी एक छोर पर बैठा है, और D तथा E के बीच केवल दो व्यक्ति बैठे हैं। B, E के ठीक दाएँ बैठा है। गणित पसंद करने वाला E के ठीक बाएँ बैठा है, और F गणित पसंद करने वाले के ठीक बाएँ बैठा है। C किसी एक छोर पर बैठा है और उसे भौतिकी पसंद है। इतिहास पसंद करने वाला किसी एक छोर पर बैठा है। अंग्रेज़ी पसंद करने वाला गणित पसंद करने वाले के दाएँ से दूसरे स्थान पर बैठा है, और F को जीव विज्ञान पसंद नहीं है। जीव विज्ञान पसंद करने वाले के बाएँ से दूसरे स्थान पर कौन बैठा है, और उसे क्या पसंद है?","optionsHi":["F – हिंदी","A – गणित","F – जीव विज्ञान","D – इतिहास"],"explanationHi":"D = 6 होने पर F, C की सीट पर आ जाता, इसलिए D = 1, E = 4, B = 5, C = 6, गणित = सीट 3 (A), F = 2। D को इतिहास, B को अंग्रेज़ी (सीट 5), F को हिंदी, E को जीव विज्ञान पसंद है। पंक्ति: D-इतिहास, F-हिंदी, A-गणित, E-जीव विज्ञान, B-अंग्रेज़ी, C-भौतिकी; E के बाएँ से दूसरा F है।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-39","question":"Six persons L, M, R, O, P and Q sit in a row, seats numbered 1 to 6 from west to east; some face north and some face south. L sits at the west end facing north. O sits third to the right of L. P faces south, sits to the immediate left of O, and faces the same direction as O. Q sits at an end and faces the same direction as L. R sits to the immediate left of M, who faces north. R faces the direction opposite to both of its neighbours. How many persons face north, and who sits to the immediate right of P?","options":["Two; O","Four; Q","Three; Q","Three; O"],"answer":3,"explanation":"O = 4 and faces south like P, so O’s left is east: P = 5. Q = 6 facing north. M faces north, so R (on M’s left, i.e. west) = 2 and M = 3. R’s neighbours L and M face north, so R faces south. North: L, M, Q (three). P faces south, so its right is west: O.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह व्यक्ति L, M, R, O, P और Q एक पंक्ति में बैठे हैं, सीटें पश्चिम से पूर्व की ओर 1 से 6 तक क्रमांकित हैं; कुछ का मुख उत्तर की ओर और कुछ का दक्षिण की ओर है। L पश्चिमी छोर पर उत्तर की ओर मुख करके बैठा है। O, L के दाएँ से तीसरे स्थान पर बैठा है। P का मुख दक्षिण की ओर है, वह O के ठीक बाएँ बैठा है, और उसका मुख O की ही दिशा में है। Q किसी एक छोर पर बैठा है और उसका मुख L की ही दिशा में है। R, M के ठीक बाएँ बैठा है, जिसका मुख उत्तर की ओर है। R का मुख अपने दोनों पड़ोसियों की विपरीत दिशा में है। कितने व्यक्तियों का मुख उत्तर की ओर है, और P के ठीक दाएँ कौन बैठा है?","optionsHi":["दो; O","चार; Q","तीन; Q","तीन; O"],"explanationHi":"O = 4 और उसका मुख P की तरह दक्षिण की ओर है, इसलिए O का बायाँ पूर्व है: P = 5। Q = 6 उत्तर की ओर मुख करके। M का मुख उत्तर की ओर है, इसलिए R (M के बाएँ, यानी पश्चिम में) = 2 और M = 3। R के पड़ोसी L और M का मुख उत्तर की ओर है, इसलिए R का मुख दक्षिण की ओर है। उत्तर की ओर: L, M, Q (तीन)। P का मुख दक्षिण की ओर है, इसलिए उसका दायाँ पश्चिम है: O।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-40","question":"Five persons V, W, X, Y and Z live on floors 1 (lowest) to 5, one per floor, each liking a different colour: red, blue, green, yellow and white. Y lives on the lowest floor and W immediately above Y. V lives on an even-numbered floor and X lives above V. The person on the top floor likes green. The blue lover lives exactly midway between Y and the green lover. V likes neither red nor yellow, and W does not like yellow. Which combination is correct?","options":["X – white – floor 5","W – red – floor 2","Z – blue – floor 4","V – yellow – floor 4"],"answer":1,"explanation":"Y = 1, W = 2, so V = 4 and X = 5 (green); Z = 3, which is midway between 1 and 5, so Z likes blue. V gets white, W red and Y yellow. Floors 1→5: Y-yellow, W-red, Z-blue, V-white, X-green.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"पाँच व्यक्ति V, W, X, Y और Z मंज़िल 1 (सबसे नीचे) से 5 तक रहते हैं, प्रत्येक मंज़िल पर एक व्यक्ति, और प्रत्येक को अलग रंग पसंद है: लाल, नीला, हरा, पीला और सफेद। Y सबसे निचली मंज़िल पर और W, Y के ठीक ऊपर रहता है। V एक सम संख्या वाली मंज़िल पर रहता है और X, V के ऊपर रहता है। सबसे ऊपरी मंज़िल वाले को हरा रंग पसंद है। नीला पसंद करने वाला Y और हरा पसंद करने वाले के ठीक बीच की मंज़िल पर रहता है। V को न लाल पसंद है न पीला, और W को पीला पसंद नहीं है। कौन-सा संयोजन सही है?","optionsHi":["X – सफेद – मंज़िल 5","W – लाल – मंज़िल 2","Z – नीला – मंज़िल 4","V – पीला – मंज़िल 4"],"explanationHi":"Y = 1, W = 2, इसलिए V = 4 और X = 5 (हरा); Z = 3, जो 1 और 5 के ठीक बीच में है, इसलिए Z को नीला पसंद है। V को सफेद, W को लाल और Y को पीला मिलता है। मंज़िल 1→5: Y-पीला, W-लाल, Z-नीला, V-सफेद, X-हरा।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-41","question":"Six persons P, Q, R, S, T and U sit in a row facing north. Q sits at the extreme right end. T sits third to the left of Q, and P sits to the immediate left of T. U sits to the immediate left of Q, and S does not sit at either end. Who sits between T and U?","options":["R","P","S","U"],"answer":2,"explanation":"Q = 6, T = 3, P = 2, U = 5. S cannot be at an end, so S = 4 and R = 1. Row (left to right): R, P, T, S, U, Q; S sits between T and U.","difficulty":"easy","source":"SBI Clerk · IBPS Clerk · RRB NTPC","questionHi":"छह व्यक्ति P, Q, R, S, T और U उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं। Q सबसे दाएँ छोर पर बैठा है। T, Q के बाएँ से तीसरे स्थान पर बैठा है, और P, T के ठीक बाएँ बैठा है। U, Q के ठीक बाएँ बैठा है, और S किसी भी छोर पर नहीं बैठा है। T और U के बीच कौन बैठा है?","optionsHi":["R","P","S","U"],"explanationHi":"Q = 6, T = 3, P = 2, U = 5। S किसी छोर पर नहीं हो सकता, इसलिए S = 4 और R = 1। पंक्ति (बाएँ से दाएँ): R, P, T, S, U, Q; S, T और U के बीच बैठा है।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-42","question":"Six friends A, B, C, D, E and F sit around a circular table facing the centre. A sits opposite D. B sits to the immediate left of A, and C sits opposite B. E sits to the immediate right of D. Who sits to the immediate right of A?","options":["E","C","B","F"],"answer":3,"explanation":"Facing the centre, left is clockwise. Clockwise from A: B, E, D, C, F. A's right is its anticlockwise neighbour, F.","difficulty":"easy","source":"SBI Clerk · IBPS Clerk · RRB NTPC","questionHi":"छह मित्र A, B, C, D, E और F केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। A, D के सामने बैठा है। B, A के ठीक बाएँ बैठा है, और C, B के सामने बैठा है। E, D के ठीक दाएँ बैठा है। A के ठीक दाएँ कौन बैठा है?","optionsHi":["E","C","B","F"],"explanationHi":"केंद्र की ओर मुख करने पर बायाँ पक्ष दक्षिणावर्त होता है। A से दक्षिणावर्त: B, E, D, C, F। A का दायाँ उसका वामावर्त पड़ोसी, यानी F है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-43","question":"Five persons A, B, C, D and E have meetings on five days, Monday to Friday, one per day. C's meeting is on Wednesday and A's is on the day just after C's. E's meeting is on Monday, and B's is not on Friday. Whose meeting is on Friday?","options":["D","B","A","C"],"answer":0,"explanation":"E Monday, C Wednesday, A Thursday. B cannot take Friday, so B takes Tuesday and D Friday.","difficulty":"easy","source":"SBI Clerk · IBPS Clerk · RRB NTPC","questionHi":"पाँच व्यक्ति A, B, C, D और E की बैठकें सोमवार से शुक्रवार तक पाँच दिनों में होती हैं, प्रतिदिन एक। C की बैठक बुधवार को है और A की बैठक C के ठीक अगले दिन है। E की बैठक सोमवार को है, और B की बैठक शुक्रवार को नहीं है। शुक्रवार को किसकी बैठक है?","optionsHi":["D","B","A","C"],"explanationHi":"E सोमवार, C बुधवार, A गुरुवार। B शुक्रवार नहीं ले सकता, इसलिए B मंगलवार लेता है और D शुक्रवार।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-44","question":"Six persons A to F sit around a rectangular table facing the centre: one person at each shorter end and two along each longer side. A and D sit at the two shorter ends. B sits to the immediate left of A, and C sits directly opposite B across the table. F sits to the immediate left of D. Who sits directly opposite F?","options":["B","E","C","A"],"answer":1,"explanation":"Going clockwise (the left of a centre-facing person) from A: B, E, D, F, C. B and E share one long side, F and C the other; B faces C, so E faces F.","difficulty":"easy","source":"SBI Clerk · IBPS Clerk · RRB NTPC","questionHi":"छह व्यक्ति A से F तक केंद्र की ओर मुख करके एक आयताकार मेज़ के चारों ओर बैठे हैं: प्रत्येक छोटे सिरे पर एक व्यक्ति और प्रत्येक लंबी भुजा पर दो व्यक्ति। A और D दोनों छोटे सिरों पर बैठे हैं। B, A के ठीक बाएँ बैठा है, और C मेज़ के आर-पार B के ठीक सामने बैठा है। F, D के ठीक बाएँ बैठा है। F के ठीक सामने कौन बैठा है?","optionsHi":["B","E","C","A"],"explanationHi":"A से दक्षिणावर्त (केंद्र की ओर मुख करने वाले का बायाँ) चलने पर: B, E, D, F, C। B और E एक लंबी भुजा पर हैं, F और C दूसरी पर; B, C के सामने है, इसलिए E, F के सामने है।","subtopic":"square-rectangular"},
  {"id":"reason-seating-puzzles-45","question":"A, B and C sit in one row facing south, and P, Q and R sit in a parallel row facing north, so each person faces one person of the other row. B sits in the middle of the first row and faces P. A sits to the immediate right of B, and Q sits to the immediate right of P. Who faces C?","options":["P","R","Q","A"],"answer":2,"explanation":"Number seats 1–3 west to east. B = 2, P = 2. A faces south, so its right is west: A = 1, C = 3. Q faces north, so its right is east: Q = 3, R = 1. C (3) faces Q.","difficulty":"easy","source":"SBI Clerk · IBPS Clerk · RRB NTPC","questionHi":"A, B और C दक्षिण की ओर मुख करके एक पंक्ति में बैठे हैं, और P, Q और R उत्तर की ओर मुख करके एक समानांतर पंक्ति में बैठे हैं, इसलिए प्रत्येक व्यक्ति दूसरी पंक्ति के एक व्यक्ति के सामने है। B पहली पंक्ति के बीच में बैठा है और P के सामने है। A, B के ठीक दाएँ बैठा है, और Q, P के ठीक दाएँ बैठा है। C के सामने कौन है?","optionsHi":["P","R","Q","A"],"explanationHi":"सीटों को पश्चिम से पूर्व 1–3 क्रमांकित कीजिए। B = 2, P = 2। A का मुख दक्षिण की ओर है, इसलिए उसका दायाँ पश्चिम है: A = 1, C = 3। Q का मुख उत्तर की ओर है, इसलिए उसका दायाँ पूर्व है: Q = 3, R = 1। C (3), Q के सामने है।","subtopic":"double-row"},
  {"id":"reason-seating-puzzles-46","question":"Eight seats in a row are numbered 1 to 8 from left to right, and six persons A to F sit on six of them facing north; two seats are vacant. A sits on seat 3 and seat 8 is vacant. Exactly one person sits between A and B, with B to the right of A, and the seat to the immediate right of B is vacant. C sits on seat 1 and D sits to the immediate right of C. E sits somewhere to the right of F. How many persons sit between C and E?","options":["3","4","5","2"],"answer":1,"explanation":"B = 5 (seat 4 is occupied) and seat 6 is vacant. C = 1, D = 2. E and F take seats 4 and 7, with E to the right: F = 4, E = 7. Between seats 1 and 7 sit D, A, F and B (seat 6 is empty): 4 persons.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"एक पंक्ति में आठ सीटें बाएँ से दाएँ 1 से 8 तक क्रमांकित हैं, और छह व्यक्ति A से F उनमें से छह सीटों पर उत्तर की ओर मुख करके बैठे हैं; दो सीटें खाली हैं। A सीट 3 पर बैठा है और सीट 8 खाली है। A और B के बीच ठीक एक व्यक्ति बैठा है, B, A के दाएँ है, और B के ठीक दाएँ की सीट खाली है। C सीट 1 पर बैठा है और D, C के ठीक दाएँ बैठा है। E, F के दाएँ किसी स्थान पर बैठा है। C और E के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["3","4","5","2"],"explanationHi":"B = 5 (सीट 4 भरी हुई है) और सीट 6 खाली है। C = 1, D = 2। E और F सीट 4 और 7 लेते हैं, E दाएँ है: F = 4, E = 7। सीट 1 और 7 के बीच D, A, F और B बैठे हैं (सीट 6 खाली है): 4 व्यक्ति।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-47","question":"Eight persons A to H sit around a circular table facing the centre. C sits second to the right of A, and E sits opposite C. G sits to the immediate left of E, and D sits opposite G. B and H sit next to each other, H to the immediate right of B, and neither of them is an immediate neighbour of A. Who sits to the immediate left of A?","options":["G","D","H","F"],"answer":3,"explanation":"Seats clockwise from A = 0 (left = clockwise): C = 6, E = 2, G = 3, D = 7. Of seats 1, 4 and 5, B and H avoid A's side, so they take 4 and 5 with H anticlockwise of B: B = 5, H = 4, F = 1. A's left (clockwise) is F.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति A से H तक केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। C, A के दाएँ से दूसरे स्थान पर बैठा है, और E, C के सामने बैठा है। G, E के ठीक बाएँ बैठा है, और D, G के सामने बैठा है। B और H एक-दूसरे के बगल में बैठे हैं, H, B के ठीक दाएँ है, और इनमें से कोई भी A का निकटतम पड़ोसी नहीं है। A के ठीक बाएँ कौन बैठा है?","optionsHi":["G","D","H","F"],"explanationHi":"A = 0 से दक्षिणावर्त सीटें (बायाँ = दक्षिणावर्त): C = 6, E = 2, G = 3, D = 7। सीट 1, 4 और 5 में से B और H, A की ओर वाली सीटों से बचते हैं, इसलिए वे 4 और 5 लेते हैं जिनमें H, B के वामावर्त है: B = 5, H = 4, F = 1। A का बायाँ (दक्षिणावर्त) F है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-48","question":"Seven persons P, Q, R, S, T, U and V live on floors 1 (lowest) to 7, one per floor. S lives on floor 4, and exactly two persons live between S and V, with V above S. Q lives immediately below S. R lives on an odd-numbered floor below Q. P lives on an even-numbered floor above Q, and U lives above T. Who lives immediately above U?","options":["P","V","S","T"],"answer":0,"explanation":"V = 7, Q = 3, R = 1, and P (even, above 3, floor 4 taken) = 6. T and U take 2 and 5 with U higher: T = 2, U = 5. P on floor 6 is just above U.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"सात व्यक्ति P, Q, R, S, T, U और V मंज़िल 1 (सबसे नीचे) से 7 तक रहते हैं, प्रत्येक मंज़िल पर एक व्यक्ति। S मंज़िल 4 पर रहता है, और S तथा V के बीच ठीक दो व्यक्ति रहते हैं, V, S के ऊपर है। Q, S के ठीक नीचे रहता है। R, Q से नीचे की एक विषम संख्या वाली मंज़िल पर रहता है। P, Q से ऊपर की एक सम संख्या वाली मंज़िल पर रहता है, और U, T के ऊपर रहता है। U के ठीक ऊपर कौन रहता है?","optionsHi":["P","V","S","T"],"explanationHi":"V = 7, Q = 3, R = 1, और P (सम, 3 से ऊपर, मंज़िल 4 भरी हुई) = 6। T और U मंज़िल 2 और 5 लेते हैं जिनमें U ऊपर है: T = 2, U = 5। मंज़िल 6 पर P, U के ठीक ऊपर है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-49","question":"Seven persons A to G have appointments on the seven days of a week, Monday to Sunday, one per day. D's appointment is on Thursday, and exactly two persons have appointments between D and B, B after D. G's appointment is the day before D's. Exactly one person's appointment falls between A's and G's, A before G. E's appointment is after D's but before B's, and not on Saturday. C's appointment is not on the day immediately after A's. Whose appointment is on Saturday?","options":["F","E","C","A"],"answer":2,"explanation":"D Thursday, B Sunday, G Wednesday, A Monday, E Friday. Tuesday and Saturday remain; C cannot be on Tuesday (the day after A), so C is on Saturday and F on Tuesday.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"सात व्यक्ति A से G तक की नियुक्तियाँ (अपॉइंटमेंट) एक सप्ताह के सातों दिनों, सोमवार से रविवार तक, प्रतिदिन एक हैं। D की नियुक्ति गुरुवार को है, और D तथा B की नियुक्तियों के बीच ठीक दो व्यक्तियों की नियुक्तियाँ हैं, B, D के बाद है। G की नियुक्ति D की नियुक्ति से एक दिन पहले है। A और G की नियुक्तियों के बीच ठीक एक व्यक्ति की नियुक्ति है, A, G से पहले है। E की नियुक्ति D के बाद पर B से पहले है, और शनिवार को नहीं है। C की नियुक्ति A की नियुक्ति के ठीक अगले दिन नहीं है। शनिवार को किसकी नियुक्ति है?","optionsHi":["F","E","C","A"],"explanationHi":"D गुरुवार, B रविवार, G बुधवार, A सोमवार, E शुक्रवार। मंगलवार और शनिवार बचते हैं; C मंगलवार को नहीं हो सकता (A के अगले दिन), इसलिए C शनिवार को और F मंगलवार को है।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-50","question":"Two parallel rows have five seats each, numbered 1 to 5 from west to east. A, B, C, D and E sit in row 1 facing south; P, Q, R, S and T sit in row 2 facing north, so each person faces one person of the other row. C sits in the middle of row 1, and A sits second to the right of C. R faces A. Q sits third to the right of R, and B faces Q. P sits at an end of row 2. E sits to the immediate left of B, and S sits to the immediate right of R. Who faces D?","options":["T","S","P","R"],"answer":1,"explanation":"Row 1 faces south, so right = west: C = 3, A = 1, R = 1. Row 2 faces north, so right = east: Q = 4, B = 4, P = 5. E is left (east) of B: E = 5, D = 2. S is right (east) of R: S = 2, T = 3. D faces S.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"दो समानांतर पंक्तियों में पाँच-पाँच सीटें हैं, जो पश्चिम से पूर्व की ओर 1 से 5 तक क्रमांकित हैं। A, B, C, D और E पंक्ति 1 में दक्षिण की ओर मुख करके बैठे हैं; P, Q, R, S और T पंक्ति 2 में उत्तर की ओर मुख करके बैठे हैं, इसलिए प्रत्येक व्यक्ति दूसरी पंक्ति के एक व्यक्ति के सामने है। C पंक्ति 1 के बीच में बैठा है, और A, C के दाएँ से दूसरे स्थान पर बैठा है। R, A के सामने है। Q, R के दाएँ से तीसरे स्थान पर बैठा है, और B, Q के सामने है। P पंक्ति 2 के एक छोर पर बैठा है। E, B के ठीक बाएँ बैठा है, और S, R के ठीक दाएँ बैठा है। D के सामने कौन है?","optionsHi":["T","S","P","R"],"explanationHi":"पंक्ति 1 का मुख दक्षिण की ओर है, इसलिए दायाँ = पश्चिम: C = 3, A = 1, R = 1। पंक्ति 2 का मुख उत्तर की ओर है, इसलिए दायाँ = पूर्व: Q = 4, B = 4, P = 5। E, B के बाएँ (पूर्व) है: E = 5, D = 2। S, R के दाएँ (पूर्व) है: S = 2, T = 3। D, S के सामने है।","subtopic":"double-row"},
  {"id":"reason-seating-puzzles-51","question":"Six boxes P, Q, R, S, T and U are stacked one above another, position 1 being the bottom. T is fourth from the bottom, and exactly one box is kept between T and Q, Q below T. U is immediately above T. S is neither at the top nor at the bottom, and R is kept above P. How many boxes are kept between R and S?","options":["1","3","0","2"],"answer":3,"explanation":"T = 4, Q = 2, U = 5. Of positions 1, 3 and 6, S takes 3; R above P gives P = 1, R = 6. Between 6 and 3 lie T and U: 2 boxes.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह डिब्बे P, Q, R, S, T और U एक के ऊपर एक रखे गए हैं, स्थिति 1 सबसे नीचे है। T नीचे से चौथे स्थान पर है, और T तथा Q के बीच ठीक एक डिब्बा रखा है, Q, T के नीचे है। U, T के ठीक ऊपर है। S न सबसे ऊपर है न सबसे नीचे, और R, P के ऊपर रखा है। R और S के बीच कितने डिब्बे रखे हैं?","optionsHi":["1","3","0","2"],"explanationHi":"T = 4, Q = 2, U = 5। स्थिति 1, 3 और 6 में से S, 3 लेता है; R, P के ऊपर होने से P = 1, R = 6। 6 और 3 के बीच T और U हैं: 2 डिब्बे।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-52","question":"Six persons A to F sit around a circle facing away from the centre. B sits second to the left of A, and D sits opposite B. C sits to the immediate right of D. E is not an immediate neighbour of A. Who sits opposite F?","options":["C","E","D","B"],"answer":0,"explanation":"Facing outside, left is anticlockwise. Seats clockwise from A = 0: B = 4, D = 1, C = 2 (right = clockwise). E avoids seats 1 and 5, so E = 3 and F = 5. Opposite seat 5 is seat 2, C.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह व्यक्ति A से F तक केंद्र से बाहर की ओर मुख करके एक वृत्त में बैठे हैं। B, A के बाएँ से दूसरे स्थान पर बैठा है, और D, B के सामने बैठा है। C, D के ठीक दाएँ बैठा है। E, A का निकटतम पड़ोसी नहीं है। F के सामने कौन बैठा है?","optionsHi":["C","E","D","B"],"explanationHi":"बाहर की ओर मुख करने पर बायाँ पक्ष वामावर्त होता है। A = 0 से दक्षिणावर्त सीटें: B = 4, D = 1, C = 2 (दायाँ = दक्षिणावर्त)। E सीट 1 और 5 से बचता है, इसलिए E = 3 और F = 5। सीट 5 के सामने सीट 2 है, यानी C।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-53","question":"Five persons P, Q, R, S and T were born in 1982, 1986, 1988, 1995 and 1999, one in each year. Q was born in a leap year, and R is 7 years younger than Q. S is older than Q but is not the eldest. P's age in 2024 is an odd number. Taking ages in 2024, what is the sum of the ages of S and R?","options":["63","71","67","65"],"answer":2,"explanation":"Only 1988 is a leap year, so Q = 1988 and R = 1995. S older than Q but not eldest = 1986. Of 1982 (42) and 1999 (25), P has the odd age: P = 1999, T = 1982. S 38 + R 29 = 67.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"पाँच व्यक्ति P, Q, R, S और T का जन्म 1982, 1986, 1988, 1995 और 1999 में हुआ, प्रत्येक का एक वर्ष में। Q का जन्म एक अधिवर्ष (लीप वर्ष) में हुआ, और R, Q से 7 वर्ष छोटा है। S, Q से बड़ा है पर सबसे बड़ा नहीं है। 2024 में P की आयु एक विषम संख्या है। 2024 में आयु लेते हुए, S और R की आयु का योग क्या है?","optionsHi":["63","71","67","65"],"explanationHi":"केवल 1988 अधिवर्ष है, इसलिए Q = 1988 और R = 1995। S, Q से बड़ा पर सबसे बड़ा नहीं = 1986। 1982 (42) और 1999 (25) में से P की आयु विषम है: P = 1999, T = 1982। S की 38 + R की 29 = 67।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-54","question":"Seven persons J, K, L, M, N, O and P sit in a row facing south. K sits at the west end, and M sits third to the left of K. N sits to the immediate right of M, and O sits second to the left of N. P sits at the east end, and J sits to the immediate right of P. Who sits to the immediate left of L?","options":["M","N","K","O"],"answer":1,"explanation":"Facing south, left is east and right is west. Seats 1–7 west to east: K = 1, M = 4, N = 3, O = 5, P = 7, J = 6, L = 2. L's immediate left is seat 3, N.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"सात व्यक्ति J, K, L, M, N, O और P दक्षिण की ओर मुख करके एक पंक्ति में बैठे हैं। K पश्चिमी छोर पर बैठा है, और M, K के बाएँ से तीसरे स्थान पर बैठा है। N, M के ठीक दाएँ बैठा है, और O, N के बाएँ से दूसरे स्थान पर बैठा है। P पूर्वी छोर पर बैठा है, और J, P के ठीक दाएँ बैठा है। L के ठीक बाएँ कौन बैठा है?","optionsHi":["M","N","K","O"],"explanationHi":"दक्षिण की ओर मुख करने पर बायाँ पक्ष पूर्व और दायाँ पक्ष पश्चिम होता है। पश्चिम से पूर्व सीटें 1–7: K = 1, M = 4, N = 3, O = 5, P = 7, J = 6, L = 2। L का ठीक बायाँ सीट 3 है, यानी N।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-55","question":"Eight persons A to H sit around a circular table facing the centre. A sits opposite B. C sits second to the left of A, and D sits opposite C. H is an immediate neighbour of both B and C. E is not an immediate neighbour of D, and F sits to the immediate right of A. Who sits third to the left of the person who sits to the immediate right of D?","options":["E","F","H","A"],"answer":3,"explanation":"Seats clockwise from A = 0: B = 4, C = 2, D = 6, H = 3, F = 7; E avoids 5 and 7, so E = 1 and G = 5. Clockwise: A, E, C, H, B, G, D, F. D's right (anticlockwise) is G at 5; third to the left of G is seat 0, A.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति A से H तक केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। A, B के सामने बैठा है। C, A के बाएँ से दूसरे स्थान पर बैठा है, और D, C के सामने बैठा है। H, B और C दोनों का निकटतम पड़ोसी है। E, D का निकटतम पड़ोसी नहीं है, और F, A के ठीक दाएँ बैठा है। D के ठीक दाएँ बैठे व्यक्ति के बाएँ से तीसरे स्थान पर कौन बैठा है?","optionsHi":["E","F","H","A"],"explanationHi":"A = 0 से दक्षिणावर्त सीटें: B = 4, C = 2, D = 6, H = 3, F = 7; E सीट 5 और 7 से बचता है, इसलिए E = 1 और G = 5। दक्षिणावर्त: A, E, C, H, B, G, D, F। D का दायाँ (वामावर्त) सीट 5 पर G है; G के बाएँ से तीसरी सीट 0 है, यानी A।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-56","question":"Eight persons A to H live on floors 1 (lowest) to 8, one per floor. C lives on an even-numbered floor above floor 5. Exactly two persons live between C and F, and F lives on an odd-numbered floor. A lives immediately above F. E lives on floor 1. B lives immediately below G. D lives below H but not immediately above E. How many persons live between H and G?","options":["2","3","4","1"],"answer":1,"explanation":"Case C = 6: F = 3, A = 4, so B–G take 7–8 and D, H take 2 and 5 with D = 2, just above E: rejected. Case C = 8: F = 5, A = 6; B–G must be 2–3 (if 3–4, D would be 2), so D = 4, H = 7. Floors 1→8: E, B, G, D, F, A, H, C. Between H (7) and G (3): D, F, A = 3.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति A से H तक मंज़िल 1 (सबसे नीचे) से 8 तक रहते हैं, प्रत्येक मंज़िल पर एक व्यक्ति। C मंज़िल 5 से ऊपर की एक सम संख्या वाली मंज़िल पर रहता है। C और F के बीच ठीक दो व्यक्ति रहते हैं, और F एक विषम संख्या वाली मंज़िल पर रहता है। A, F के ठीक ऊपर रहता है। E मंज़िल 1 पर रहता है। B, G के ठीक नीचे रहता है। D, H से नीचे रहता है पर E के ठीक ऊपर नहीं रहता। H और G के बीच कितने व्यक्ति रहते हैं?","optionsHi":["2","3","4","1"],"explanationHi":"स्थिति C = 6: F = 3, A = 4, इसलिए B–G मंज़िल 7–8 लेते हैं और D, H मंज़िल 2 और 5 लेते हैं जिसमें D = 2, E के ठीक ऊपर आता है: अस्वीकृत। स्थिति C = 8: F = 5, A = 6; B–G को 2–3 पर होना चाहिए (3–4 पर होने से D = 2 आता), इसलिए D = 4, H = 7। मंज़िल 1→8: E, B, G, D, F, A, H, C। H (7) और G (3) के बीच: D, F, A = 3।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-57","question":"Eight persons P, Q, R, S, T, U, V and W each have a programme on the 12th or the 25th of March, May, July or September of one year; no two programmes share a date. R's programme is on the 25th of a month with 31 days. Exactly two programmes fall between R's and V's, and V's programme is in a month with 30 days. T's programme is immediately before R's. Q's programme is in the same month as V's. W's programme is on the 12th, but not in March. U's programme is after S's, and P's is not in March. Whose programme is on 25 March?","options":["U","S","P","T"],"answer":0,"explanation":"Order: Mar 12, Mar 25, May 12, May 25, Jul 12, Jul 25, Sep 12, Sep 25. V is in September, three places from R (25 Mar/May/Jul), so R = 25 May, V = 12 Sep. T = 12 May, Q = 25 Sep, W = 12 Jul, P = 25 Jul. S and U take March with U later: S = 12 Mar, U = 25 Mar.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति P, Q, R, S, T, U, V और W में से प्रत्येक का कार्यक्रम एक वर्ष के मार्च, मई, जुलाई या सितंबर की 12 या 25 तारीख को है; किसी दो कार्यक्रमों की तारीख एक नहीं है। R का कार्यक्रम 31 दिन वाले महीने की 25 तारीख को है। R और V के कार्यक्रमों के बीच ठीक दो कार्यक्रम आते हैं, और V का कार्यक्रम 30 दिन वाले महीने में है। T का कार्यक्रम R के कार्यक्रम से ठीक पहले है। Q का कार्यक्रम V के कार्यक्रम वाले महीने में ही है। W का कार्यक्रम 12 तारीख को है, पर मार्च में नहीं है। U का कार्यक्रम S के बाद है, और P का कार्यक्रम मार्च में नहीं है। 25 मार्च को किसका कार्यक्रम है?","optionsHi":["U","S","P","T"],"explanationHi":"क्रम: 12 मार्च, 25 मार्च, 12 मई, 25 मई, 12 जुलाई, 25 जुलाई, 12 सितंबर, 25 सितंबर। V सितंबर में है, R (25 मार्च/मई/जुलाई) से तीन स्थान आगे, इसलिए R = 25 मई, V = 12 सितंबर। T = 12 मई, Q = 25 सितंबर, W = 12 जुलाई, P = 25 जुलाई। S और U मार्च लेते हैं जिसमें U बाद में है: S = 12 मार्च, U = 25 मार्च।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-58","question":"Eight persons A to H sit in a row facing north. B sits third from the right end, and exactly two persons sit between B and E. G sits second to the left of E. As many persons sit between G and E as between B and D, and D does not sit at an end. C sits to the immediate right of B. F is not an immediate neighbour of G, H is not an immediate neighbour of D, and A sits somewhere to the left of H. Who sits third to the right of the person who sits to the immediate right of A?","options":["D","F","B","C"],"answer":2,"explanation":"B = 6, E = 3, G = 1. One person sits between G and E, so D = 4 (8 is an end); C = 7. Seats 2, 5, 8 remain: H cannot be 5 (next to D) or 2 (A must be to its left), so H = 8; F cannot be 2, so F = 5, A = 2. Row: G, A, E, D, F, B, C, H. A's right is E (3); third to the right of E is seat 6, B.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति A से H तक उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं। B दाएँ छोर से तीसरे स्थान पर बैठा है, और B तथा E के बीच ठीक दो व्यक्ति बैठे हैं। G, E के बाएँ से दूसरे स्थान पर बैठा है। G और E के बीच उतने ही व्यक्ति बैठे हैं जितने B और D के बीच बैठे हैं, और D किसी छोर पर नहीं बैठा है। C, B के ठीक दाएँ बैठा है। F, G का निकटतम पड़ोसी नहीं है, H, D का निकटतम पड़ोसी नहीं है, और A, H के बाएँ किसी स्थान पर बैठा है। A के ठीक दाएँ बैठे व्यक्ति के दाएँ से तीसरे स्थान पर कौन बैठा है?","optionsHi":["D","F","B","C"],"explanationHi":"B = 6, E = 3, G = 1। G और E के बीच एक व्यक्ति बैठा है, इसलिए D = 4 (8 एक छोर है); C = 7। सीट 2, 5, 8 बचती हैं: H, 5 (D के बगल में) या 2 (A को उसके बाएँ होना है) पर नहीं हो सकता, इसलिए H = 8; F, 2 पर नहीं हो सकता, इसलिए F = 5, A = 2। पंक्ति: G, A, E, D, F, B, C, H। A का दायाँ E (3) है; E के दाएँ से तीसरी सीट 6 है, यानी B।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-59","question":"Six persons P, Q, R, S, T and U sit around a circle; some face the centre and some face outside. P faces the centre, and Q sits to the immediate left of P. S sits opposite P and faces the same direction as Q. T sits second to the right of Q. U sits to the immediate left of S. Exactly three persons face the centre. Who sits to the immediate right of R?","options":["U","P","T","S"],"answer":3,"explanation":"Seats clockwise from P = 0: Q = 1, S = 3. If Q faced outside, its right would be clockwise and T would fall on S's seat, so Q faces the centre and T = 5. S faces the centre too, so U (its left, clockwise) = 4 and R = 2. P, Q and S face the centre, so R, T and U face outside. R's right is therefore clockwise: seat 3, S.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह व्यक्ति P, Q, R, S, T और U एक वृत्त में बैठे हैं; कुछ का मुख केंद्र की ओर और कुछ का बाहर की ओर है। P का मुख केंद्र की ओर है, और Q, P के ठीक बाएँ बैठा है। S, P के सामने बैठा है और उसका मुख Q की ही दिशा में है। T, Q के दाएँ से दूसरे स्थान पर बैठा है। U, S के ठीक बाएँ बैठा है। ठीक तीन व्यक्तियों का मुख केंद्र की ओर है। R के ठीक दाएँ कौन बैठा है?","optionsHi":["U","P","T","S"],"explanationHi":"P = 0 से दक्षिणावर्त सीटें: Q = 1, S = 3। यदि Q का मुख बाहर की ओर होता, तो उसका दायाँ दक्षिणावर्त होता और T, S की सीट पर आ जाता, इसलिए Q का मुख केंद्र की ओर है और T = 5। S का मुख भी केंद्र की ओर है, इसलिए U (उसका बायाँ, दक्षिणावर्त) = 4 और R = 2। P, Q और S का मुख केंद्र की ओर है, इसलिए R, T और U का मुख बाहर की ओर है। अतः R का दायाँ दक्षिणावर्त है: सीट 3, यानी S।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-60","question":"Seven persons A to G work in an office at seven levels; from the highest: CEO, MD, GM, AGM, Manager, Executive and Clerk, one person per level. D is senior to only three persons. Exactly two persons rank between D and B, and B is junior to F. G is D's immediate senior. E is senior to G but is not the CEO. C is junior to A, and A is not the CEO. How many persons are senior to A?","options":["3","5","2","4"],"answer":3,"explanation":"D is AGM (4th). B is 1st or 7th; being junior to F, B is Clerk. G is GM and E is MD. CEO, Manager and Executive remain for A, C and F; A is not CEO and C is junior to A, so A = Manager, C = Executive, F = CEO. Senior to A: F, E, G, D = 4.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"सात व्यक्ति A से G तक एक कार्यालय में सात स्तरों पर काम करते हैं; सबसे ऊपर से: CEO, MD, GM, AGM, मैनेजर, एग्ज़ीक्यूटिव और क्लर्क, प्रत्येक स्तर पर एक व्यक्ति। D केवल तीन व्यक्तियों से वरिष्ठ है। D और B के बीच ठीक दो व्यक्ति आते हैं, और B, F से कनिष्ठ है। G, D का ठीक वरिष्ठ है। E, G से वरिष्ठ है पर CEO नहीं है। C, A से कनिष्ठ है, और A, CEO नहीं है। A से कितने व्यक्ति वरिष्ठ हैं?","optionsHi":["3","5","2","4"],"explanationHi":"D, AGM (चौथा) है। B पहला या सातवाँ है; F से कनिष्ठ होने के कारण B क्लर्क है। G, GM है और E, MD है। CEO, मैनेजर और एग्ज़ीक्यूटिव A, C और F के लिए बचते हैं; A, CEO नहीं है और C, A से कनिष्ठ है, इसलिए A = मैनेजर, C = एग्ज़ीक्यूटिव, F = CEO। A से वरिष्ठ: F, E, G, D = 4।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-61","question":"Six persons P, Q, R, S, T and U were born in 1976, 1981, 1985, 1990, 1996 and 2001, one in each year. S was born in a leap year, and the difference between the ages of S and U is 11 years. Q is older than U. T's age in 2024 is a multiple of 17. R is younger than T. P is not the eldest. Taking ages in 2024, what is the sum of the ages of P and T?","options":["77","82","73","71"],"answer":0,"explanation":"Leap years: 1976 and 1996; only 1996 has a year 11 apart (1985), so S = 1996, U = 1985. Ages in 2024 are 48, 43, 39, 34, 28, 23; only 34 is a multiple of 17, so T = 1990. R younger than T = 2001. Q older than U and P not eldest: Q = 1976, P = 1981. 43 + 34 = 77.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह व्यक्ति P, Q, R, S, T और U का जन्म 1976, 1981, 1985, 1990, 1996 और 2001 में हुआ, प्रत्येक का एक वर्ष में। S का जन्म एक अधिवर्ष (लीप वर्ष) में हुआ, और S तथा U की आयु का अंतर 11 वर्ष है। Q, U से बड़ा है। 2024 में T की आयु 17 का गुणज है। R, T से छोटा है। P सबसे बड़ा नहीं है। 2024 में आयु लेते हुए, P और T की आयु का योग क्या है?","optionsHi":["77","82","73","71"],"explanationHi":"अधिवर्ष: 1976 और 1996; इनमें से केवल 1996 के 11 वर्ष के अंतर पर एक वर्ष (1985) है, इसलिए S = 1996, U = 1985। 2024 में आयु 48, 43, 39, 34, 28, 23 हैं; केवल 34, 17 का गुणज है, इसलिए T = 1990। R, T से छोटा = 2001। Q, U से बड़ा और P सबसे बड़ा नहीं: Q = 1976, P = 1981। 43 + 34 = 77।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-62","question":"Five persons J, K, L, M and N live on floors 1 (lowest) to 5, one per floor, and each likes a different colour: red, blue, green, white and black. The person who likes green lives on floor 3, and K lives immediately above that person. Exactly one person lives between K and the person who likes red. J lives on an odd-numbered floor and does not like green. L likes white and does not live on the top floor. M lives above N. J does not like black. Who likes black, and on which floor does that person live?","options":["J, floor 5","K, floor 4","N, floor 2","M, floor 3"],"answer":1,"explanation":"Green = 3, K = 4, red = 2. L (white) cannot be on 2, 3, 4 or 5, so L = 1. J (odd, not green) = 5. M above N: M = 3 (green), N = 2 (red). J is not black, so J likes blue and K black, on floor 4.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"पाँच व्यक्ति J, K, L, M और N मंज़िल 1 (सबसे नीचे) से 5 तक रहते हैं, प्रत्येक मंज़िल पर एक व्यक्ति, और प्रत्येक को अलग रंग पसंद है: लाल, नीला, हरा, सफेद और काला। हरा पसंद करने वाला मंज़िल 3 पर रहता है, और K उस व्यक्ति के ठीक ऊपर रहता है। K और लाल पसंद करने वाले के बीच ठीक एक व्यक्ति रहता है। J एक विषम संख्या वाली मंज़िल पर रहता है और उसे हरा पसंद नहीं है। L को सफेद पसंद है और वह सबसे ऊपरी मंज़िल पर नहीं रहता। M, N के ऊपर रहता है। J को काला पसंद नहीं है। काला किसे पसंद है, और वह किस मंज़िल पर रहता है?","optionsHi":["J, मंज़िल 5","K, मंज़िल 4","N, मंज़िल 2","M, मंज़िल 3"],"explanationHi":"हरा = 3, K = 4, लाल = 2। L (सफेद) 2, 3, 4 या 5 पर नहीं हो सकता, इसलिए L = 1। J (विषम, हरा नहीं) = 5। M, N के ऊपर: M = 3 (हरा), N = 2 (लाल)। J को काला पसंद नहीं है, इसलिए J को नीला और K को काला पसंद है, जो मंज़िल 4 पर रहता है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-63","question":"Seven persons A to G sit around a circular table facing the centre. D sits second to the right of A. Only two persons sit between D and F, and F is an immediate neighbour of A. B sits third to the left of F. G sits to the immediate left of D. E sits to the immediate left of C. How many persons sit between B and F when counted clockwise from B?","options":["2","4","3","1"],"answer":2,"explanation":"Seats clockwise from A = 0 (left = clockwise): D = 5. Seats with two persons between them and D are 1 and 2; F next to A gives F = 1. B = 4, G = 6; C and E take 2 and 3 with E clockwise of C. Clockwise: A, F, C, E, B, D, G. From B clockwise: D, G, A, then F, so 3.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"सात व्यक्ति A से G तक केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। D, A के दाएँ से दूसरे स्थान पर बैठा है। D और F के बीच केवल दो व्यक्ति बैठे हैं, और F, A का निकटतम पड़ोसी है। B, F के बाएँ से तीसरे स्थान पर बैठा है। G, D के ठीक बाएँ बैठा है। E, C के ठीक बाएँ बैठा है। B से दक्षिणावर्त गिनने पर B और F के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["2","4","3","1"],"explanationHi":"A = 0 से दक्षिणावर्त सीटें (बायाँ = दक्षिणावर्त): D = 5। D से जिन सीटों के बीच दो व्यक्ति हों वे 1 और 2 हैं; F, A के बगल में है तो F = 1। B = 4, G = 6; C और E सीट 2 और 3 लेते हैं जिनमें E, C के दक्षिणावर्त है। दक्षिणावर्त: A, F, C, E, B, D, G। B से दक्षिणावर्त: D, G, A, फिर F, इसलिए 3।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-64","question":"Six persons A to F attend a workshop with six sessions held on Monday, Wednesday and Friday of one week, with a morning and an evening session each day; one person per session. C attends on Wednesday. Exactly one session falls between C's and E's, and E attends an evening session. F attends the session immediately after E's. B does not attend on Friday, and D attends after A. Who attends the Friday morning session?","options":["D","B","F","A"],"answer":3,"explanation":"Order: Mon-M, Mon-E, Wed-M, Wed-E, Fri-M, Fri-E. If C were Wed-M, the sessions two away would be mornings, so C = Wed-E and E = Mon-E or Fri-E; F follows E, so E = Mon-E, F = Wed-M. B = Mon-M, and A before D gives A = Fri-M, D = Fri-E.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"छह व्यक्ति A से F तक एक कार्यशाला में भाग लेते हैं, जिसके छह सत्र एक सप्ताह के सोमवार, बुधवार और शुक्रवार को होते हैं, प्रतिदिन एक सुबह का और एक शाम का सत्र; प्रत्येक सत्र में एक व्यक्ति। C बुधवार को भाग लेता है। C और E के सत्रों के बीच ठीक एक सत्र आता है, और E शाम के सत्र में भाग लेता है। F, E के सत्र के ठीक बाद वाले सत्र में भाग लेता है। B शुक्रवार को भाग नहीं लेता, और D, A के बाद भाग लेता है। शुक्रवार के सुबह के सत्र में कौन भाग लेता है?","optionsHi":["D","B","F","A"],"explanationHi":"क्रम: सोम-सुबह, सोम-शाम, बुध-सुबह, बुध-शाम, शुक्र-सुबह, शुक्र-शाम। यदि C बुध-सुबह में होता, तो दो सत्र दूर वाले सत्र सुबह के होते, इसलिए C = बुध-शाम और E = सोम-शाम या शुक्र-शाम; F, E के बाद आता है, इसलिए E = सोम-शाम, F = बुध-सुबह। B = सोम-सुबह, और A के D से पहले होने से A = शुक्र-सुबह, D = शुक्र-शाम।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-65","question":"Seven boxes A to G are stacked one above another, position 1 being the bottom. C is immediately above F. Exactly two boxes are kept between F and B. B is at an odd-numbered position above position 3. D is at the top. As many boxes are kept between B and D as between E and C. G is kept above A. Which box is exactly in the middle of the stack?","options":["B","A","C","G"],"answer":1,"explanation":"D = 7, so B = 5, F = 2, C = 3. One box lies between B and D, so one lies between E and C: E = 1. A and G take 4 and 6 with G higher: A = 4, the middle.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"सात डिब्बे A से G तक एक के ऊपर एक रखे गए हैं, स्थिति 1 सबसे नीचे है। C, F के ठीक ऊपर है। F और B के बीच ठीक दो डिब्बे रखे हैं। B स्थिति 3 से ऊपर की एक विषम संख्या वाली स्थिति पर है। D सबसे ऊपर है। B और D के बीच उतने ही डिब्बे रखे हैं जितने E और C के बीच रखे हैं। G, A के ऊपर रखा है। ढेर के ठीक बीच में कौन-सा डिब्बा है?","optionsHi":["B","A","C","G"],"explanationHi":"D = 7, इसलिए B = 5, F = 2, C = 3। B और D के बीच एक डिब्बा है, इसलिए E और C के बीच भी एक है: E = 1। A और G स्थिति 4 और 6 लेते हैं जिनमें G ऊपर है: A = 4, यानी बीच में।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-66","question":"Some persons sit in a row facing north. P sits sixth from the left end, and Q sits third to the right of P. Exactly four persons sit between Q and the right end. R sits third to the left of P. S sits to the immediate left of the person who sits exactly midway between R and Q. What is S's position from the right end?","options":["9th","11th","8th","10th"],"answer":3,"explanation":"P = 6, Q = 9, so the row has 9 + 4 + 1 = 14 persons. R = 3; midway between 3 and 9 is seat 6 (P), so S = 5. From the right: 14 − 5 + 1 = 10th.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"कुछ व्यक्ति उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं। P बाएँ छोर से छठे स्थान पर बैठा है, और Q, P के दाएँ से तीसरे स्थान पर बैठा है। Q और दाएँ छोर के बीच ठीक चार व्यक्ति बैठे हैं। R, P के बाएँ से तीसरे स्थान पर बैठा है। S, उस व्यक्ति के ठीक बाएँ बैठा है जो R और Q के ठीक बीच में बैठा है। दाएँ छोर से S की स्थिति क्या है?","optionsHi":["9वाँ","11वाँ","8वाँ","10वाँ"],"explanationHi":"P = 6, Q = 9, इसलिए पंक्ति में 9 + 4 + 1 = 14 व्यक्ति हैं। R = 3; 3 और 9 के ठीक बीच सीट 6 (P) है, इसलिए S = 5। दाएँ से: 14 − 5 + 1 = 10वाँ।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-67","question":"Eight persons A to H sit around a circular table facing away from the centre. B sits third to the right of A, and D sits opposite B. E sits second to the left of D. C sits to the immediate right of A. F is an immediate neighbour of B. H sits to the immediate left of E. Who sits third to the left of F?","options":["D","G","E","H"],"answer":0,"explanation":"Facing outside, right is clockwise. Seats clockwise from A = 0: B = 3, D = 7, E = 5, C = 1, H = 4; F next to B takes 2 and G = 6. Clockwise: A, C, F, B, H, E, G, D. Third to the left (anticlockwise) of F: C, A, then D.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आठ व्यक्ति A से H तक केंद्र से बाहर की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। B, A के दाएँ से तीसरे स्थान पर बैठा है, और D, B के सामने बैठा है। E, D के बाएँ से दूसरे स्थान पर बैठा है। C, A के ठीक दाएँ बैठा है। F, B का निकटतम पड़ोसी है। H, E के ठीक बाएँ बैठा है। F के बाएँ से तीसरे स्थान पर कौन बैठा है?","optionsHi":["D","G","E","H"],"explanationHi":"बाहर की ओर मुख करने पर दायाँ पक्ष दक्षिणावर्त होता है। A = 0 से दक्षिणावर्त सीटें: B = 3, D = 7, E = 5, C = 1, H = 4; B के बगल में F सीट 2 लेता है और G = 6। दक्षिणावर्त: A, C, F, B, H, E, G, D। F के बाएँ (वामावर्त) से तीसरा: C, A, फिर D।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-68","question":"Eight persons A to H sit around a circular table; four face the centre and four face outside. A faces the centre, and C sits third to the left of A. E sits opposite A and faces the same direction as C. B sits second to the right of E. G sits to the immediate left of B and faces outside. D is an immediate neighbour of A and faces outside. F sits second to the left of C. H faces the same direction as A. The two immediate neighbours of C face opposite directions. How many of these statements are true? I. B faces outside. II. F sits third to the right of A. III. H sits to the immediate left of F. IV. D sits opposite E.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Seats clockwise from A = 0: C = 3, E = 4. If C and E faced outside, B = 6, F = 1, D = 7, G = 5, H = 2 and at most A, F, H could face the centre, not four. So C and E face the centre: B = 2, F = 5; G left of B must be 1, so B faces outside; D = 7, H = 6. Centre: A, C, E, H; outside: G, B, F, D. I and II are true; F's left is E, so III is false, and D is opposite C, so IV is false.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"आठ व्यक्ति A से H तक एक वृत्ताकार मेज़ के चारों ओर बैठे हैं; चार का मुख केंद्र की ओर और चार का बाहर की ओर है। A का मुख केंद्र की ओर है, और C, A के बाएँ से तीसरे स्थान पर बैठा है। E, A के सामने बैठा है और उसका मुख C की ही दिशा में है। B, E के दाएँ से दूसरे स्थान पर बैठा है। G, B के ठीक बाएँ बैठा है और उसका मुख बाहर की ओर है। D, A का निकटतम पड़ोसी है और उसका मुख बाहर की ओर है। F, C के बाएँ से दूसरे स्थान पर बैठा है। H का मुख A की ही दिशा में है। C के दोनों निकटतम पड़ोसियों के मुख विपरीत दिशाओं में हैं। इनमें से कितने कथन सत्य हैं? I. B का मुख बाहर की ओर है। II. F, A के दाएँ से तीसरे स्थान पर बैठा है। III. H, F के ठीक बाएँ बैठा है। IV. D, E के सामने बैठा है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"A = 0 से दक्षिणावर्त सीटें: C = 3, E = 4। यदि C और E का मुख बाहर की ओर होता, तो B = 6, F = 1, D = 7, G = 5, H = 2 आते और अधिकतम A, F, H का मुख केंद्र की ओर हो सकता, चार का नहीं। इसलिए C और E का मुख केंद्र की ओर है: B = 2, F = 5; G, B के बाएँ यानी 1 पर होना चाहिए, इसलिए B का मुख बाहर की ओर है; D = 7, H = 6। केंद्र की ओर: A, C, E, H; बाहर की ओर: G, B, F, D। I और II सत्य हैं; F का बायाँ E है, इसलिए III असत्य है, और D, C के सामने है, इसलिए IV असत्य है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-69","question":"A building has four floors, numbered 1 (bottom) to 4, with a west flat and an east flat on each floor; each flat is directly above the flat on the same side of the floor below. Eight persons A to H live there, one per flat. D lives in an east flat on an odd-numbered floor above floor 1. A lives directly below D. G lives on the same floor as A, and H lives directly above G. C and E live on the same floor, C in the west flat. F lives in an east flat on a floor above A's. How many of these statements are true? I. B lives directly above H. II. E lives in the east flat of floor 1. III. G lives directly above C. IV. F and A live on the same floor.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"D = 3-East, A = 2-East, G = 2-West, H = 3-West. F (east, above floor 2) = 4-East. C and E need a floor with both flats free: floor 1, C west, E east. B = 4-West. I, II and III are true; F is on floor 4 and A on floor 2, so IV is false.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक इमारत में चार मंज़िलें हैं, जो 1 (सबसे नीचे) से 4 तक क्रमांकित हैं, और प्रत्येक मंज़िल पर एक पश्चिमी फ्लैट और एक पूर्वी फ्लैट है; प्रत्येक फ्लैट अपने नीचे की मंज़िल की उसी ओर वाले फ्लैट के ठीक ऊपर है। आठ व्यक्ति A से H तक वहाँ रहते हैं, प्रत्येक फ्लैट में एक। D मंज़िल 1 से ऊपर की एक विषम संख्या वाली मंज़िल के पूर्वी फ्लैट में रहता है। A, D के ठीक नीचे रहता है। G, A की ही मंज़िल पर रहता है, और H, G के ठीक ऊपर रहता है। C और E एक ही मंज़िल पर रहते हैं, C पश्चिमी फ्लैट में। F, A की मंज़िल से ऊपर की एक मंज़िल के पूर्वी फ्लैट में रहता है। इनमें से कितने कथन सत्य हैं? I. B, H के ठीक ऊपर रहता है। II. E मंज़िल 1 के पूर्वी फ्लैट में रहता है। III. G, C के ठीक ऊपर रहता है। IV. F और A एक ही मंज़िल पर रहते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"D = 3-पूर्व, A = 2-पूर्व, G = 2-पश्चिम, H = 3-पश्चिम। F (पूर्व, मंज़िल 2 से ऊपर) = 4-पूर्व। C और E को ऐसी मंज़िल चाहिए जिसके दोनों फ्लैट खाली हों: मंज़िल 1, C पश्चिम, E पूर्व। B = 4-पश्चिम। I, II और III सत्य हैं; F मंज़िल 4 पर और A मंज़िल 2 पर है, इसलिए IV असत्य है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-70","question":"Six persons P, Q, R, S, T and U have meetings on six dates: the 8th and 19th of March, June and September of one year, one per date. Each likes a different fruit: apple, banana, grape, kiwi, mango and papaya. S's meeting is on the 19th of a month with 30 days. Exactly two meetings fall between S's and that of the kiwi-lover, whose meeting is in March. Q meets immediately before S and likes apple. U meets in the same month as the kiwi-lover but does not like kiwi. The mango-lover meets immediately after the grape-lover. T meets after R, and P does not meet in September. S does not like grape, and U does not like papaya. Who likes papaya, and when is that person's meeting?","options":["U – 19 March","R – 8 September","S – 19 June","T – 19 September"],"answer":2,"explanation":"Order: 8 Mar, 19 Mar, 8 Jun, 19 Jun, 8 Sep, 19 Sep. Kiwi three places from S and in March gives S = 19 Jun, kiwi = 8 Mar. Q = 8 Jun (apple), U = 19 Mar, P = 8 Mar (kiwi), R = 8 Sep, T = 19 Sep. Grape–mango must be S–R or R–T; S is not grape, so R grape, T mango. U is not papaya, so U banana and S papaya.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"छह व्यक्ति P, Q, R, S, T और U की बैठकें एक वर्ष के मार्च, जून और सितंबर की 8 और 19 तारीख को छह तारीखों पर होती हैं, प्रत्येक तारीख पर एक। प्रत्येक को अलग फल पसंद है: सेब, केला, अंगूर, कीवी, आम और पपीता। S की बैठक 30 दिन वाले महीने की 19 तारीख को है। S की और कीवी पसंद करने वाले की बैठकों के बीच ठीक दो बैठकें होती हैं, और कीवी पसंद करने वाले की बैठक मार्च में है। Q की बैठक S से ठीक पहले है और उसे सेब पसंद है। U की बैठक कीवी पसंद करने वाले के ही महीने में है पर उसे कीवी पसंद नहीं है। आम पसंद करने वाले की बैठक अंगूर पसंद करने वाले के ठीक बाद है। T की बैठक R के बाद है, और P की बैठक सितंबर में नहीं है। S को अंगूर पसंद नहीं है, और U को पपीता पसंद नहीं है। पपीता किसे पसंद है, और उसकी बैठक कब है?","optionsHi":["U – 19 मार्च","R – 8 सितंबर","S – 19 जून","T – 19 सितंबर"],"explanationHi":"क्रम: 8 मार्च, 19 मार्च, 8 जून, 19 जून, 8 सितंबर, 19 सितंबर। कीवी वाला S से तीन स्थान दूर और मार्च में है, इसलिए S = 19 जून, कीवी = 8 मार्च। Q = 8 जून (सेब), U = 19 मार्च, P = 8 मार्च (कीवी), R = 8 सितंबर, T = 19 सितंबर। अंगूर–आम की जोड़ी S–R या R–T है; S को अंगूर नहीं है, इसलिए R को अंगूर और T को आम। U को पपीता नहीं है, इसलिए U को केला और S को पपीता।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-71","question":"Eight seats in a row are numbered 1 to 8 from west to east, and J, K, L, M, N, O, P and Q sit on them; some face north and some face south. K sits at the west end facing north. M sits third to the right of K and faces south. P sits second to the left of M and faces the same direction as K. Exactly one person sits between P and Q, and Q faces opposite to P. N sits to the immediate right of Q. L is an immediate neighbour of K. O sits to the immediate left of M. Both immediate neighbours of M face the same direction as M. N faces north, and L faces opposite to N. How many persons face north, and who sits third to the left of L?","options":["Four; J","Three; O","Three; M","Two; O"],"answer":1,"explanation":"K = 1 faces north, so M = 4. M faces south (left = east): P = 6, O = 5. Q is 4 or 8, so Q = 8, facing south (right = west): N = 7. L = 2, J = 3. J and O face south like M; N faces north and L south. North-facing: K, P, N = three. L faces south, so third to its left (east) is seat 5, O.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक पंक्ति में आठ सीटें पश्चिम से पूर्व की ओर 1 से 8 तक क्रमांकित हैं, और J, K, L, M, N, O, P और Q उन पर बैठे हैं; कुछ का मुख उत्तर की ओर और कुछ का दक्षिण की ओर है। K पश्चिमी छोर पर उत्तर की ओर मुख करके बैठा है। M, K के दाएँ से तीसरे स्थान पर बैठा है और उसका मुख दक्षिण की ओर है। P, M के बाएँ से दूसरे स्थान पर बैठा है और उसका मुख K की ही दिशा में है। P और Q के बीच ठीक एक व्यक्ति बैठा है, और Q का मुख P के विपरीत है। N, Q के ठीक दाएँ बैठा है। L, K का निकटतम पड़ोसी है। O, M के ठीक बाएँ बैठा है। M के दोनों निकटतम पड़ोसियों का मुख M की ही दिशा में है। N का मुख उत्तर की ओर है, और L का मुख N के विपरीत है। कितने व्यक्तियों का मुख उत्तर की ओर है, और L के बाएँ से तीसरे स्थान पर कौन बैठा है?","optionsHi":["चार; J","तीन; O","तीन; M","दो; O"],"explanationHi":"K = 1 का मुख उत्तर की ओर है, इसलिए M = 4। M का मुख दक्षिण की ओर है (बायाँ = पूर्व): P = 6, O = 5। Q, 4 या 8 पर है, इसलिए Q = 8, उसका मुख दक्षिण की ओर है (दायाँ = पश्चिम): N = 7। L = 2, J = 3। J और O का मुख M की तरह दक्षिण की ओर है; N का मुख उत्तर की ओर और L का दक्षिण की ओर है। उत्तर की ओर मुख वाले: K, P, N = तीन। L का मुख दक्षिण की ओर है, इसलिए उसके बाएँ (पूर्व) से तीसरी सीट 5 है, यानी O।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-72","question":"Two parallel rows have five seats each, numbered 1 to 5 from west to east. A, B, C, D and E sit in row 1 facing south, and P, Q, R, S and T sit in row 2 facing north, so each person faces one person of the other row. B sits second from the east end. Q faces the person who sits to the immediate right of B. S sits second to the left of Q, and D faces S. E sits neither at an end nor next to D. A sits at an end, and T faces A. R sits to the immediate left of T. Who faces the person who sits second to the right of A?","options":["R","P","S","Q"],"answer":3,"explanation":"B = 4; B faces south, so its right is west: seat 3, so Q = 3. Q faces north, so its left is west: S = 1, D = 1. E (not an end, not next to D) = 3; A = 5, C = 2. T = 5, R = 4 (left of T is west), P = 2. Second to the right (west) of A is seat 3, E, who faces Q.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"दो समानांतर पंक्तियों में पाँच-पाँच सीटें हैं, जो पश्चिम से पूर्व की ओर 1 से 5 तक क्रमांकित हैं। A, B, C, D और E पंक्ति 1 में दक्षिण की ओर मुख करके बैठे हैं, और P, Q, R, S और T पंक्ति 2 में उत्तर की ओर मुख करके बैठे हैं, इसलिए प्रत्येक व्यक्ति दूसरी पंक्ति के एक व्यक्ति के सामने है। B पूर्वी छोर से दूसरे स्थान पर बैठा है। Q, B के ठीक दाएँ बैठे व्यक्ति के सामने है। S, Q के बाएँ से दूसरे स्थान पर बैठा है, और D, S के सामने है। E न किसी छोर पर बैठा है और न D के बगल में। A किसी छोर पर बैठा है, और T, A के सामने है। R, T के ठीक बाएँ बैठा है। A के दाएँ से दूसरे स्थान पर बैठे व्यक्ति के सामने कौन है?","optionsHi":["R","P","S","Q"],"explanationHi":"B = 4; B का मुख दक्षिण की ओर है, इसलिए उसका दायाँ पश्चिम है: सीट 3, इसलिए Q = 3। Q का मुख उत्तर की ओर है, इसलिए उसका बायाँ पश्चिम है: S = 1, D = 1। E (न छोर पर, न D के बगल में) = 3; A = 5, C = 2। T = 5, R = 4 (T का बायाँ पश्चिम है), P = 2। A के दाएँ (पश्चिम) से दूसरी सीट 3 है, यानी E, जो Q के सामने है।","subtopic":"double-row"},
  {"id":"reason-seating-puzzles-73","question":"Eight persons A to H sit around a rectangular table facing the centre: one person at each shorter end and three along each longer side, each person on a long side directly facing one person on the other. A sits at one end and C at the other end. D sits second to the right of A, and F sits directly opposite D. G sits to the immediate left of D, and B sits directly opposite G. E sits to the immediate right of C. Who sits directly opposite the person who sits to the immediate right of D?","options":["E","B","H","F"],"answer":0,"explanation":"Label seats clockwise from A = 0: 1, 2, 3 on one side, C at 4, then 5, 6, 7; seat 1 faces 7, 2 faces 6, 3 faces 5. D = 6 (right = anticlockwise), F = 2, G = 7, B = 1, E = 3 and H = 5. D's right is H (5), who faces E (3).","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"आठ व्यक्ति A से H तक केंद्र की ओर मुख करके एक आयताकार मेज़ के चारों ओर बैठे हैं: प्रत्येक छोटे सिरे पर एक व्यक्ति और प्रत्येक लंबी भुजा पर तीन व्यक्ति, लंबी भुजा पर बैठा प्रत्येक व्यक्ति दूसरी भुजा के एक व्यक्ति के ठीक सामने है। A एक सिरे पर और C दूसरे सिरे पर बैठा है। D, A के दाएँ से दूसरे स्थान पर बैठा है, और F, D के ठीक सामने बैठा है। G, D के ठीक बाएँ बैठा है, और B, G के ठीक सामने बैठा है। E, C के ठीक दाएँ बैठा है। D के ठीक दाएँ बैठे व्यक्ति के ठीक सामने कौन बैठा है?","optionsHi":["E","B","H","F"],"explanationHi":"A = 0 से दक्षिणावर्त सीटों को चिह्नित कीजिए: एक भुजा पर 1, 2, 3, C सीट 4 पर, फिर 5, 6, 7; सीट 1 सीट 7 के सामने है, 2 सामने 6 के, 3 सामने 5 के। D = 6 (दायाँ = वामावर्त), F = 2, G = 7, B = 1, E = 3 और H = 5। D का दायाँ H (5) है, जो E (3) के सामने है।","subtopic":"square-rectangular"},
  {"id":"reason-seating-puzzles-74","question":"Seven persons J, K, L, M, N, O and P were born in 1968, 1973, 1979, 1984, 1988, 1995 and 2000, one in each year. M was born in a leap year after 1980, and the difference between the ages of M and O is 11 years. J is younger than M, and J's age in 2024 is a multiple of 4. P is younger than J. O's age in 2024 is a prime number. L's age in 2024 is a multiple of 9. K is younger than N. Taking ages in 2024, how many persons are older than J, and what is the sum of the ages of K and O?","options":["Three; 80","Four; 76","Five; 85","Four; 80"],"answer":3,"explanation":"Of the leap years 1984, 1988 and 2000, only 1984 has years 11 apart (1973, 1995): M = 1984. J younger than M with age divisible by 4: 1988 (36) or 2000 (24); P is younger, so J = 1988. O's age is 51 (not prime) or 29 (prime), so O = 1995, P = 2000. Of 56, 51, 45, only 45 is a multiple of 9: L = 1979; K = 1973, N = 1968. Older than J: N, K, L, M = four; 51 + 29 = 80.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"सात व्यक्ति J, K, L, M, N, O और P का जन्म 1968, 1973, 1979, 1984, 1988, 1995 और 2000 में हुआ, प्रत्येक का एक वर्ष में। M का जन्म 1980 के बाद के एक अधिवर्ष (लीप वर्ष) में हुआ, और M तथा O की आयु का अंतर 11 वर्ष है। J, M से छोटा है, और 2024 में J की आयु 4 का गुणज है। P, J से छोटा है। 2024 में O की आयु एक अभाज्य संख्या है। 2024 में L की आयु 9 का गुणज है। K, N से छोटा है। 2024 में आयु लेते हुए, J से कितने व्यक्ति बड़े हैं, और K तथा O की आयु का योग क्या है?","optionsHi":["तीन; 80","चार; 76","पाँच; 85","चार; 80"],"explanationHi":"अधिवर्षों 1984, 1988 और 2000 में से केवल 1984 के 11 वर्ष के अंतर पर वर्ष (1973, 1995) हैं: M = 1984। J, M से छोटा और उसकी आयु 4 से विभाज्य: 1988 (36) या 2000 (24); P उससे छोटा है, इसलिए J = 1988। O की आयु 51 (अभाज्य नहीं) या 29 (अभाज्य) है, इसलिए O = 1995, P = 2000। 56, 51, 45 में से केवल 45, 9 का गुणज है: L = 1979; K = 1973, N = 1968। J से बड़े: N, K, L, M = चार; 51 + 29 = 80।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-75","question":"Seven persons A to G live on floors 1 (lowest) to 7, one per floor, each from a different city: Agra, Bhopal, Chennai, Delhi, Indore, Jaipur and Kochi. The person from Kochi lives on an odd-numbered floor below floor 4, and exactly two persons live between that person and G. A lives immediately above the person from Kochi. The person from Delhi lives on the top floor, and E lives immediately below that person. D lives on an odd-numbered floor below G. B is from Jaipur and lives below C. F is from Indore, does not live on floor 1 and lives below B. Neither A nor G is from Agra, and the person from Chennai lives below the person from Bhopal. How many of these statements are true? I. E is from Agra. II. The person from Indore lives immediately above A. III. G lives exactly in the middle of the building. IV. Two persons live between D and G.","options":["Only one","Only three","Only two","All four"],"answer":3,"explanation":"Floors 1–7: D (Kochi), A (Chennai), F (Indore), G (Bhopal), B (Jaipur), E (Agra), C (Delhi). E is from Agra, F lives just above A, G is on floor 4 (the middle), and A and F live between D and G. All four are true.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"सात व्यक्ति A से G तक मंज़िल 1 (सबसे नीचे) से 7 तक रहते हैं, प्रत्येक मंज़िल पर एक व्यक्ति, और प्रत्येक अलग शहर का है: आगरा, भोपाल, चेन्नई, दिल्ली, इंदौर, जयपुर और कोच्चि। कोच्चि का व्यक्ति मंज़िल 4 से नीचे की एक विषम संख्या वाली मंज़िल पर रहता है, और उस व्यक्ति तथा G के बीच ठीक दो व्यक्ति रहते हैं। A, कोच्चि के व्यक्ति के ठीक ऊपर रहता है। दिल्ली का व्यक्ति सबसे ऊपरी मंज़िल पर रहता है, और E उस व्यक्ति के ठीक नीचे रहता है। D, G से नीचे की एक विषम संख्या वाली मंज़िल पर रहता है। B जयपुर का है और C से नीचे रहता है। F इंदौर का है, मंज़िल 1 पर नहीं रहता और B से नीचे रहता है। न A और न G आगरा का है, और चेन्नई का व्यक्ति भोपाल के व्यक्ति से नीचे रहता है। इनमें से कितने कथन सत्य हैं? I. E आगरा का है। II. इंदौर का व्यक्ति A के ठीक ऊपर रहता है। III. G इमारत के ठीक बीच में रहता है। IV. D और G के बीच दो व्यक्ति रहते हैं।","optionsHi":["केवल एक","केवल तीन","केवल दो","चारों"],"explanationHi":"मंज़िल 1–7: D (कोच्चि), A (चेन्नई), F (इंदौर), G (भोपाल), B (जयपुर), E (आगरा), C (दिल्ली)। E आगरा का है, F, A के ठीक ऊपर रहता है, G मंज़िल 4 (बीच में) पर है, और D तथा G के बीच A और F रहते हैं। चारों सत्य हैं।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-76","question":"Eight persons A to H sit around a circular table facing the centre. E sits third to the left of B. Only one person sits between E and H, and H is not an immediate neighbour of B. A sits opposite H. C sits to the immediate right of E. G is not an immediate neighbour of H. F sits second to the left of C. Three of the following four pairs are alike in the way the second person sits relative to the first. Which pair does not belong to the group?","options":["B, C","A, E","E, H","F, B"],"answer":3,"explanation":"Seats clockwise from B = 0: E = 3; H is 1 or 5 and not next to B, so H = 5; A = 1; C = 2; G avoids 4 and 6, so G = 7; F = 4, D = 6. Clockwise: B, A, C, E, F, H, D, G. In B–C, A–E and E–H the second person sits second to the left of the first; B sits fourth from F.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"आठ व्यक्ति A से H तक केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। E, B के बाएँ से तीसरे स्थान पर बैठा है। E और H के बीच केवल एक व्यक्ति बैठा है, और H, B का निकटतम पड़ोसी नहीं है। A, H के सामने बैठा है। C, E के ठीक दाएँ बैठा है। G, H का निकटतम पड़ोसी नहीं है। F, C के बाएँ से दूसरे स्थान पर बैठा है। निम्नलिखित चार जोड़ों में से तीन इस प्रकार समान हैं कि पहले व्यक्ति के सापेक्ष दूसरा व्यक्ति एक ही तरह बैठा है। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["B, C","A, E","E, H","F, B"],"explanationHi":"B = 0 से दक्षिणावर्त सीटें: E = 3; H, 1 या 5 पर है और B के बगल में नहीं है, इसलिए H = 5; A = 1; C = 2; G, 4 और 6 से बचता है, इसलिए G = 7; F = 4, D = 6। दक्षिणावर्त: B, A, C, E, F, H, D, G। B–C, A–E और E–H में दूसरा व्यक्ति पहले के बाएँ से दूसरे स्थान पर बैठा है; B, F के (बाएँ से) चौथे स्थान पर बैठा है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-77","question":"Six boxes P, Q, R, S, T and U are stacked one above another, position 1 being the bottom, and each is a different colour: red, blue, green, yellow, white and black. R is fourth from the top. Exactly one box is kept between R and the green box, which is not at the bottom. P is immediately below S. The blue box is immediately below R. The red box is at the top and the white box at the bottom. Q is kept below T. U is above R and is not green. R is not yellow. S is neither blue nor at the top. Which box is yellow, and how many boxes are kept between it and the white box?","options":["P; two","U; two","P; three","Q; one"],"answer":0,"explanation":"R = 3, green = 5, blue = 2, red = 6, white = 1; R is not yellow, so R is black and position 4 is yellow. S cannot be at 2 (blue) or 6, so P–S = 4–5. U above R takes 6; Q below T gives Q = 1, T = 2. P is yellow at 4, with T and R (two boxes) between it and the white box.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"छह डिब्बे P, Q, R, S, T और U एक के ऊपर एक रखे गए हैं, स्थिति 1 सबसे नीचे है, और प्रत्येक अलग रंग का है: लाल, नीला, हरा, पीला, सफेद और काला। R ऊपर से चौथे स्थान पर है। R और हरे डिब्बे के बीच ठीक एक डिब्बा रखा है, और हरा डिब्बा सबसे नीचे नहीं है। P, S के ठीक नीचे है। नीला डिब्बा R के ठीक नीचे है। लाल डिब्बा सबसे ऊपर और सफेद डिब्बा सबसे नीचे है। Q, T के नीचे रखा है। U, R के ऊपर है और हरा नहीं है। R पीला नहीं है। S न नीला है न सबसे ऊपर है। कौन-सा डिब्बा पीला है, और उसके तथा सफेद डिब्बे के बीच कितने डिब्बे रखे हैं?","optionsHi":["P; दो","U; दो","P; तीन","Q; एक"],"explanationHi":"R = 3, हरा = 5, नीला = 2, लाल = 6, सफेद = 1; R पीला नहीं है, इसलिए R काला है और स्थिति 4 पीला है। S, 2 (नीला) या 6 पर नहीं हो सकता, इसलिए P–S = 4–5। R के ऊपर U, 6 लेता है; T के नीचे Q होने से Q = 1, T = 2। P, 4 पर पीला है, और उसके तथा सफेद डिब्बे के बीच T और R (दो डिब्बे) हैं।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-78","question":"Seven persons A to G sit in a row facing north, and each likes a different sport: cricket, hockey, tennis, chess, golf, polo and squash. The chess-lover sits third from the left end, and D sits second to the right of the chess-lover. Exactly two persons sit between D and the golf-lover. B likes hockey and sits to the immediate left of D. The tennis-lover sits to the immediate right of D. F likes squash and sits next to the golf-lover. A sits at an end and does not like polo. G likes neither chess nor golf. E sits to the right of C. Who likes polo, and who sits second to the left of the tennis-lover?","options":["A; B","D; E","D; B","G; C"],"answer":2,"explanation":"Chess = 3, D = 5, golf = 2, B = 4, tennis = 6. F (squash) next to golf cannot be 3, so F = 1 and A = 7. Cricket and polo remain for D and A; A is not polo, so D likes polo. G avoids 2 and 3, so G = 6 (tennis), C = 2, E = 3. Second to the left of G is seat 4, B.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"सात व्यक्ति A से G तक उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं, और प्रत्येक को अलग खेल पसंद है: क्रिकेट, हॉकी, टेनिस, शतरंज, गोल्फ, पोलो और स्क्वैश। शतरंज पसंद करने वाला बाएँ छोर से तीसरे स्थान पर बैठा है, और D शतरंज पसंद करने वाले के दाएँ से दूसरे स्थान पर बैठा है। D और गोल्फ पसंद करने वाले के बीच ठीक दो व्यक्ति बैठे हैं। B को हॉकी पसंद है और वह D के ठीक बाएँ बैठा है। टेनिस पसंद करने वाला D के ठीक दाएँ बैठा है। F को स्क्वैश पसंद है और वह गोल्फ पसंद करने वाले के बगल में बैठा है। A किसी छोर पर बैठा है और उसे पोलो पसंद नहीं है। G को न शतरंज पसंद है न गोल्फ। E, C के दाएँ बैठा है। पोलो किसे पसंद है, और टेनिस पसंद करने वाले के बाएँ से दूसरे स्थान पर कौन बैठा है?","optionsHi":["A; B","D; E","D; B","G; C"],"explanationHi":"शतरंज = 3, D = 5, गोल्फ = 2, B = 4, टेनिस = 6। F (स्क्वैश) गोल्फ के बगल में है और 3 पर नहीं हो सकता, इसलिए F = 1 और A = 7। क्रिकेट और पोलो D और A के लिए बचते हैं; A को पोलो नहीं है, इसलिए D को पोलो पसंद है। G, 2 और 3 से बचता है, इसलिए G = 6 (टेनिस), C = 2, E = 3। G के बाएँ से दूसरी सीट 4 है, यानी B।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-79","question":"A building has three floors, numbered 1 (bottom) to 3, each with three flats in a line: flat 1 (west), flat 2 (middle) and flat 3 (east); each flat is directly above the flat with the same number below. Nine persons A to I live there, one per flat. E lives in the middle flat of floor 2, and A lives directly above E. G lives in the east flat of E's floor, and B lives directly below G. H lives in a west flat but not on A's floor, and I lives directly below H. C and D live on the same floor, D in a west flat. F lives on floor 1. Who lives directly above G, and who lives in the middle flat of floor 1?","options":["A; I","C; F","D; F","C; B"],"answer":1,"explanation":"E = 2-middle, A = 3-middle, G = 2-east, B = 1-east. H needs a flat below it and is not on floor 3, so H = 2-west, I = 1-west, and F takes 1-middle. C and D share floor 3: D = 3-west, C = 3-east, directly above G.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक इमारत में तीन मंज़िलें हैं, जो 1 (सबसे नीचे) से 3 तक क्रमांकित हैं, और प्रत्येक पर एक पंक्ति में तीन फ्लैट हैं: फ्लैट 1 (पश्चिम), फ्लैट 2 (बीच का) और फ्लैट 3 (पूर्व); प्रत्येक फ्लैट अपने नीचे उसी संख्या वाले फ्लैट के ठीक ऊपर है। नौ व्यक्ति A से I तक वहाँ रहते हैं, प्रत्येक फ्लैट में एक। E मंज़िल 2 के बीच वाले फ्लैट में रहता है, और A, E के ठीक ऊपर रहता है। G, E की मंज़िल के पूर्वी फ्लैट में रहता है, और B, G के ठीक नीचे रहता है। H पश्चिमी फ्लैट में रहता है पर A की मंज़िल पर नहीं, और I, H के ठीक नीचे रहता है। C और D एक ही मंज़िल पर रहते हैं, D पश्चिमी फ्लैट में। F मंज़िल 1 पर रहता है। G के ठीक ऊपर कौन रहता है, और मंज़िल 1 के बीच वाले फ्लैट में कौन रहता है?","optionsHi":["A; I","C; F","D; F","C; B"],"explanationHi":"E = 2-बीच, A = 3-बीच, G = 2-पूर्व, B = 1-पूर्व। H के नीचे एक फ्लैट होना चाहिए और वह मंज़िल 3 पर नहीं है, इसलिए H = 2-पश्चिम, I = 1-पश्चिम, और F, 1-बीच लेता है। C और D मंज़िल 3 पर रहते हैं: D = 3-पश्चिम, C = 3-पूर्व, जो G के ठीक ऊपर है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-80","question":"Eight persons J, K, L, M, N, O, P and Q sit around a circular table facing the centre. J and L sit opposite each other. N sits second to the left of L, and P sits third to the right of N. K is an immediate neighbour of J but not of N. Q sits to the immediate right of N. O is not an immediate neighbour of N. If J and P interchange their seats, who will then sit second to the right of P?","options":["M","Q","N","K"],"answer":2,"explanation":"Seats clockwise from J = 0: L = 4, N = 6, P = 3; K is next to J but not N, so K = 1; Q = 5; O avoids 7, so O = 2 and M = 7. Clockwise: J, K, O, P, L, Q, N, M. After the swap P is at seat 0; second to its right (anticlockwise) is seat 6, N.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"आठ व्यक्ति J, K, L, M, N, O, P और Q केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। J और L एक-दूसरे के सामने बैठे हैं। N, L के बाएँ से दूसरे स्थान पर बैठा है, और P, N के दाएँ से तीसरे स्थान पर बैठा है। K, J का निकटतम पड़ोसी है पर N का नहीं है। Q, N के ठीक दाएँ बैठा है। O, N का निकटतम पड़ोसी नहीं है। यदि J और P अपनी सीटें आपस में बदल लें, तो P के दाएँ से दूसरे स्थान पर कौन बैठेगा?","optionsHi":["M","Q","N","K"],"explanationHi":"J = 0 से दक्षिणावर्त सीटें: L = 4, N = 6, P = 3; K, J के बगल में है पर N के नहीं, इसलिए K = 1; Q = 5; O, 7 से बचता है, इसलिए O = 2 और M = 7। दक्षिणावर्त: J, K, O, P, L, Q, N, M। अदला-बदली के बाद P सीट 0 पर है; उसके दाएँ (वामावर्त) से दूसरी सीट 6 है, यानी N।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-81","question":"Nine seats in a row are numbered 1 to 9 from left to right, and six persons A to F sit on six of them facing north; three seats are vacant. D sits at the extreme right end. B sits second to the left of D, and the seat between them is vacant. A sits fourth to the left of B. Exactly one of the two seats next to A is vacant. E sits to the immediate right of A. C sits at the extreme left end. F is not an immediate neighbour of E. How many persons and how many vacant seats are there between C and B?","options":["Three persons and two vacant seats","Four persons and one vacant seat","Three persons and one vacant seat","Two persons and three vacant seats"],"answer":0,"explanation":"D = 9, B = 7, seat 8 vacant, A = 3, E = 4, so seat 2 is the vacant neighbour of A; C = 1. F takes 5 or 6 and is not next to E, so F = 6 and seat 5 is vacant. Between seats 1 and 7: vacant 2, A, E, vacant 5, F — three persons and two vacant seats.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक पंक्ति में नौ सीटें बाएँ से दाएँ 1 से 9 तक क्रमांकित हैं, और छह व्यक्ति A से F उनमें से छह सीटों पर उत्तर की ओर मुख करके बैठे हैं; तीन सीटें खाली हैं। D सबसे दाएँ छोर पर बैठा है। B, D के बाएँ से दूसरे स्थान पर बैठा है, और उन दोनों के बीच की सीट खाली है। A, B के बाएँ से चौथे स्थान पर बैठा है। A के बगल की दो सीटों में से ठीक एक खाली है। E, A के ठीक दाएँ बैठा है। C सबसे बाएँ छोर पर बैठा है। F, E का निकटतम पड़ोसी नहीं है। C और B के बीच कितने व्यक्ति और कितनी खाली सीटें हैं?","optionsHi":["तीन व्यक्ति और दो खाली सीटें","चार व्यक्ति और एक खाली सीट","तीन व्यक्ति और एक खाली सीट","दो व्यक्ति और तीन खाली सीटें"],"explanationHi":"D = 9, B = 7, सीट 8 खाली है, A = 3, E = 4, इसलिए सीट 2, A की खाली बगल वाली सीट है; C = 1। F, 5 या 6 लेता है और E के बगल में नहीं है, इसलिए F = 6 और सीट 5 खाली है। सीट 1 और 7 के बीच: खाली 2, A, E, खाली 5, F: तीन व्यक्ति और दो खाली सीटें।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-82","question":"Six persons P, Q, R, S, T and U were born in different months of the same year: January, March, April, June, September and November, one in each. R was born in a month with 30 days, and exactly two of them were born between R and T. T was born in a month with 31 days, and Q was born in the very next month of this list after T. S was born in a month with 30 days, but not in the month just after Q's in the list. P was born after S, and U was not born in November. Who was born in April, and how many persons were born between U and P?","options":["Q; three","U; three","R; one","U; two"],"answer":3,"explanation":"T is January or March and R is three places later: (Jan, Jun) or (Mar, Sep). If T = Mar, Q = Apr and S (30 days, not June) = Nov, leaving no month after S for P, so T = Jan, Q = Mar, R = Jun. S cannot be April, and P is after S, so S = Sep, P = Nov, U = Apr. Between U (Apr) and P (Nov): R and S, two.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"छह व्यक्ति P, Q, R, S, T और U का जन्म एक ही वर्ष के अलग-अलग महीनों में हुआ: जनवरी, मार्च, अप्रैल, जून, सितंबर और नवंबर, प्रत्येक का एक में। R का जन्म 30 दिन वाले महीने में हुआ, और R तथा T के बीच उनमें से ठीक दो का जन्म हुआ। T का जन्म 31 दिन वाले महीने में हुआ, और Q का जन्म इस सूची में T के ठीक अगले महीने में हुआ। S का जन्म 30 दिन वाले महीने में हुआ, पर सूची में Q के ठीक बाद वाले महीने में नहीं। P का जन्म S के बाद हुआ, और U का जन्म नवंबर में नहीं हुआ। अप्रैल में किसका जन्म हुआ, और U तथा P के बीच कितने व्यक्तियों का जन्म हुआ?","optionsHi":["Q; तीन","U; तीन","R; एक","U; दो"],"explanationHi":"T जनवरी या मार्च है और R तीन स्थान बाद है: (जनवरी, जून) या (मार्च, सितंबर)। यदि T = मार्च, तो Q = अप्रैल और S (30 दिन, जून नहीं) = नवंबर, जिससे S के बाद P के लिए कोई महीना नहीं बचता, इसलिए T = जनवरी, Q = मार्च, R = जून। S अप्रैल नहीं हो सकता, और P, S के बाद है, इसलिए S = सितंबर, P = नवंबर, U = अप्रैल। U (अप्रैल) और P (नवंबर) के बीच: R और S, यानी दो।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-83","question":"Six persons A to F sit around a circular table facing the centre, and each has a different profession: doctor, engineer, lawyer, pilot, teacher and writer. The doctor sits opposite A, and B sits to the immediate left of the doctor. The lawyer sits second to the left of B. C is the pilot and sits opposite B. D is not the doctor and sits next to A. The teacher sits to the immediate right of the engineer. E is the writer. Who is the teacher, and who sits opposite the engineer?","options":["D; E","B; E","B; F","F; C"],"answer":1,"explanation":"Seats clockwise from A = 0: doctor = 3, B = 4, lawyer = seat 0, so A is the lawyer. C (pilot) = 1. D next to A = 5. E (writer) cannot take the doctor's seat, so E = 2, F = 3 (doctor). The teacher sits anticlockwise of the engineer, so D = engineer, B = teacher. Opposite D (5) is seat 2, E.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"छह व्यक्ति A से F तक केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर बैठे हैं, और प्रत्येक का पेशा अलग है: डॉक्टर, इंजीनियर, वकील, पायलट, शिक्षक और लेखक। डॉक्टर A के सामने बैठा है, और B डॉक्टर के ठीक बाएँ बैठा है। वकील B के बाएँ से दूसरे स्थान पर बैठा है। C पायलट है और B के सामने बैठा है। D डॉक्टर नहीं है और A के बगल में बैठा है। शिक्षक इंजीनियर के ठीक दाएँ बैठा है। E लेखक है। शिक्षक कौन है, और इंजीनियर के सामने कौन बैठा है?","optionsHi":["D; E","B; E","B; F","F; C"],"explanationHi":"A = 0 से दक्षिणावर्त सीटें: डॉक्टर = 3, B = 4, वकील = सीट 0, इसलिए A वकील है। C (पायलट) = 1। D, A के बगल में = 5। E (लेखक) डॉक्टर की सीट नहीं ले सकता, इसलिए E = 2, F = 3 (डॉक्टर)। शिक्षक इंजीनियर के वामावर्त बैठा है, इसलिए D = इंजीनियर, B = शिक्षक। D (5) के सामने सीट 2 है, यानी E।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-84","question":"Eight persons A to H sit around a square table: four sit at the corners facing the centre and four sit at the middle of the sides facing outside. A sits at a corner. E sits third to the left of A. B sits second to the right of E. G sits opposite E, and C sits to the immediate left of G. H is not an immediate neighbour of A. D sits at a corner next to B. How many of these statements are true? I. F faces outside. II. H sits second to the left of E. III. C sits opposite F. IV. D sits to the immediate right of E.","options":["Only one","Only three","Only two","All four"],"answer":2,"explanation":"Seats clockwise from A = 0; even seats are corners (facing in), odd seats middles (facing out). E = 3, facing out, so its right is clockwise: B = 5. G = 7, its left is anticlockwise: C = 6. D (corner next to B) = 4, H (not next to A) = 2, F = 1. I and IV are true; E's second left is F, not H, and C is opposite H, not F.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"आठ व्यक्ति A से H तक एक वर्गाकार मेज़ के चारों ओर बैठे हैं: चार कोनों पर केंद्र की ओर मुख करके और चार भुजाओं के मध्य में बाहर की ओर मुख करके बैठे हैं। A किसी कोने पर बैठा है। E, A के बाएँ से तीसरे स्थान पर बैठा है। B, E के दाएँ से दूसरे स्थान पर बैठा है। G, E के सामने बैठा है, और C, G के ठीक बाएँ बैठा है। H, A का निकटतम पड़ोसी नहीं है। D, B के बगल वाले कोने पर बैठा है। इनमें से कितने कथन सत्य हैं? I. F का मुख बाहर की ओर है। II. H, E के बाएँ से दूसरे स्थान पर बैठा है। III. C, F के सामने बैठा है। IV. D, E के ठीक दाएँ बैठा है।","optionsHi":["केवल एक","केवल तीन","केवल दो","चारों"],"explanationHi":"A = 0 से दक्षिणावर्त सीटें; सम सीटें कोने हैं (अंदर की ओर मुख), विषम सीटें भुजाओं के मध्य हैं (बाहर की ओर मुख)। E = 3, उसका मुख बाहर की ओर है, इसलिए उसका दायाँ दक्षिणावर्त है: B = 5। G = 7, उसका बायाँ वामावर्त है: C = 6। D (B के बगल वाला कोना) = 4, H (A के बगल में नहीं) = 2, F = 1। I और IV सत्य हैं; E के बाएँ से दूसरा F है, H नहीं, और C, H के सामने है, F के नहीं।","subtopic":"square-rectangular"},
  {"id":"reason-seating-puzzles-85","question":"Six persons A to F sit in a row facing north, and their ages are 21, 24, 27, 30, 33 and 36 years, all different. The person aged 30 sits third from the left end, and B sits second to the right of that person. The eldest sits at an end, and exactly one person sits between the eldest and E. E is 6 years younger than B. A sits to the immediate left of E. F sits at an end, is not the eldest and is older than B. C is younger than D and sits to the left of D. What is the sum of the ages of the two persons at the ends, and who is the youngest?","options":["69; E","69; C","66; E","63; A"],"answer":0,"explanation":"The 30-year-old is at 3 and B at 5. If the eldest sat at 1, E would be the 30-year-old at 3 and B would have to be 36, impossible. So the eldest is at 6, E = 4, A = 3 (30). F (not eldest) = 1; C = 2, D = 6 (36). E = B − 6: B 27, E 21 or B 33, E 27; F is older than B, so B = 27, E = 21, F = 33, C = 24. Ends: 33 + 36 = 69; youngest E.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"छह व्यक्ति A से F तक उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं, और उनकी आयु 21, 24, 27, 30, 33 और 36 वर्ष है, सभी अलग-अलग। 30 वर्ष की आयु वाला व्यक्ति बाएँ छोर से तीसरे स्थान पर बैठा है, और B उस व्यक्ति के दाएँ से दूसरे स्थान पर बैठा है। सबसे बड़ा व्यक्ति किसी छोर पर बैठा है, और सबसे बड़े तथा E के बीच ठीक एक व्यक्ति बैठा है। E, B से 6 वर्ष छोटा है। A, E के ठीक बाएँ बैठा है। F किसी छोर पर बैठा है, सबसे बड़ा नहीं है और B से बड़ा है। C, D से छोटा है और D के बाएँ बैठा है। दोनों छोरों पर बैठे व्यक्तियों की आयु का योग क्या है, और सबसे छोटा कौन है?","optionsHi":["69; E","69; C","66; E","63; A"],"explanationHi":"30 वर्ष वाला सीट 3 पर और B सीट 5 पर है। यदि सबसे बड़ा सीट 1 पर बैठता, तो E सीट 3 पर 30 वर्ष का होता और B को 36 का होना पड़ता, जो असंभव है। इसलिए सबसे बड़ा सीट 6 पर है, E = 4, A = 3 (30)। F (सबसे बड़ा नहीं) = 1; C = 2, D = 6 (36)। E = B − 6: B 27, E 21 या B 33, E 27; F, B से बड़ा है, इसलिए B = 27, E = 21, F = 33, C = 24। छोर: 33 + 36 = 69; सबसे छोटा E।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-86","question":"Study the information and answer the question. Five persons A, B, C, D and E sit in a straight row facing north. B is not an immediate neighbour of D. A sits to the immediate right of B. D sits fourth to the left of E. Question: Who sits second to the right of B?","options":["E","C","A","D"],"answer":0,"explanation":"Final arrangement: From left to right: D, C, B, A, E. E sits second to the right of B.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। पाँच व्यक्ति A, B, C, D और E उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं। B, D का निकटतम पड़ोसी नहीं है। A, B के ठीक दाएँ बैठा है। D, E के बाएँ से चौथे स्थान पर बैठा है। प्रश्न: B के दाएँ से दूसरे स्थान पर कौन बैठा है?","optionsHi":["E","C","A","D"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: D, C, B, A, E। B के दाएँ से दूसरे स्थान पर E बैठा है।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-87","question":"Study the information and answer the question. Five persons A, B, C, D and E sit in a straight row facing north. B is not an immediate neighbour of D. A sits to the immediate right of B. D sits fourth to the left of E. Question: Which pair sits at the two extreme ends of the row?","options":["B and D","D and E","C and A","A and E"],"answer":1,"explanation":"Final arrangement: From left to right: D, C, B, A, E. The ends are occupied by D and E.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। पाँच व्यक्ति A, B, C, D और E उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं। B, D का निकटतम पड़ोसी नहीं है। A, B के ठीक दाएँ बैठा है। D, E के बाएँ से चौथे स्थान पर बैठा है। प्रश्न: पंक्ति के दोनों छोरों पर कौन-सा जोड़ा बैठा है?","optionsHi":["B और D","D और E","C और A","A और E"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: D, C, B, A, E। छोरों पर D और E हैं।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-88","question":"Study the information and answer the question. Five persons Aman, Bela, Chirag, Divya and Esha live on the 5 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 5. Chirag lives on floor 3. Aman lives somewhere below Chirag. Chirag lives somewhere above Divya. Only three persons live between Aman and Bela. Question: On which floor does Bela live?","options":["2","3","4","5"],"answer":3,"explanation":"Final arrangement: From floor 5 down to 1: Bela, Esha, Chirag, Divya, Aman. Bela lives on floor 5.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। पाँच व्यक्ति अमन, बेला, चिराग, दिव्या और ईशा एक इमारत की 5 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 5 है। चिराग मंज़िल 3 पर रहता है। अमन चिराग से कहीं नीचे रहता है। चिराग दिव्या से कहीं ऊपर रहता है। अमन और बेला के बीच केवल तीन व्यक्ति रहते हैं। प्रश्न: बेला किस मंज़िल पर रहती है?","optionsHi":["2","3","4","5"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 5 से 1 तक: बेला, ईशा, चिराग, दिव्या, अमन। बेला मंज़िल 5 पर रहती है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-89","question":"Study the information and answer the question. Five persons Aman, Bela, Chirag, Divya and Esha live on the 5 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 5. Chirag lives on floor 3. Aman lives somewhere below Chirag. Chirag lives somewhere above Divya. Only three persons live between Aman and Bela. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["Aman – Divya","Chirag – Esha","Bela – Chirag","Esha – Bela"],"answer":2,"explanation":"Final arrangement: From floor 5 down to 1: Bela, Esha, Chirag, Divya, Aman. In Aman – Divya, Chirag – Esha, Esha – Bela, the second person lives immediately above the first; Bela – Chirag does not follow this pattern.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। पाँच व्यक्ति अमन, बेला, चिराग, दिव्या और ईशा एक इमारत की 5 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 5 है। चिराग मंज़िल 3 पर रहता है। अमन चिराग से कहीं नीचे रहता है। चिराग दिव्या से कहीं ऊपर रहता है। अमन और बेला के बीच केवल तीन व्यक्ति रहते हैं। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["अमन – दिव्या","चिराग – ईशा","बेला – चिराग","ईशा – बेला"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 5 से 1 तक: बेला, ईशा, चिराग, दिव्या, अमन। अमन – दिव्या, चिराग – ईशा, ईशा – बेला में दूसरा व्यक्ति पहले के ठीक ऊपर रहता है; बेला – चिराग इस पैटर्न का पालन नहीं करता।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-90","question":"Study the information and answer the question. Six persons P, Q, R, S, T and U sit around a circular table, equally spaced and facing the centre. S is not an immediate neighbour of R. Q sits second to the right of R. P sits to the immediate right of T. Question: Who sits third to the right of P?","options":["Q","U","R","S"],"answer":0,"explanation":"Final arrangement: Going clockwise from P: P, T, S, Q, U, R. Q sits third to the right of P.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति P, Q, R, S, T और U केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। S, R का निकटतम पड़ोसी नहीं है। Q, R के दाएँ से दूसरे स्थान पर बैठा है। P, T के ठीक दाएँ बैठा है। प्रश्न: P के दाएँ से तीसरे स्थान पर कौन बैठा है?","optionsHi":["Q","U","R","S"],"explanationHi":"अंतिम व्यवस्था: P से दक्षिणावर्त चलने पर: P, T, S, Q, U, R। Q, P के दाएँ से तीसरे स्थान पर बैठा है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-91","question":"Study the information and answer the question. Six persons P, Q, R, S, T and U sit around a circular table, equally spaced and facing the centre. S is not an immediate neighbour of R. Q sits second to the right of R. P sits to the immediate right of T. Question: Who sits opposite S?","options":["P","R","T","U"],"answer":1,"explanation":"Final arrangement: Going clockwise from P: P, T, S, Q, U, R. R is directly opposite S.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति P, Q, R, S, T और U केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। S, R का निकटतम पड़ोसी नहीं है। Q, R के दाएँ से दूसरे स्थान पर बैठा है। P, T के ठीक दाएँ बैठा है। प्रश्न: S के सामने कौन बैठा है?","optionsHi":["P","R","T","U"],"explanationHi":"अंतिम व्यवस्था: P से दक्षिणावर्त चलने पर: P, T, S, Q, U, R। R ठीक S के सामने है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-92","question":"Study the information and answer the question. Five boxes K, L, M, N and O are kept one above another in a single stack; position 1 is at the bottom and position 5 at the top. M is kept at an even-numbered position. O is kept somewhere above M. L is kept somewhere above O. N is 3rd from the top. Question: How many boxes are kept between K and N?","options":["0","1","2","3"],"answer":1,"explanation":"Final arrangement: From position 5 down to 1: L, O, N, M, K. Between K and N is M, i.e. 1.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। पाँच डिब्बे K, L, M, N और O एक ही ढेर में एक के ऊपर एक रखे गए हैं; स्थिति 1 सबसे नीचे और स्थिति 5 सबसे ऊपर है। M सम संख्या वाली स्थिति पर रखा है। O, M से कहीं ऊपर रखा है। L, O से कहीं ऊपर रखा है। N ऊपर से तीसरे स्थान पर है। प्रश्न: K और N के बीच कितने डिब्बे रखे हैं?","optionsHi":["0","1","2","3"],"explanationHi":"अंतिम व्यवस्था: स्थिति 5 से 1 तक: L, O, N, M, K। K और N के बीच M है, यानी 1।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-93","question":"Study the information and answer the question. Five boxes K, L, M, N and O are kept one above another in a single stack; position 1 is at the bottom and position 5 at the top. M is kept at an even-numbered position. O is kept somewhere above M. L is kept somewhere above O. N is 3rd from the top. Question: At which position is box O kept?","options":["2","3","4","5"],"answer":2,"explanation":"Final arrangement: From position 5 down to 1: L, O, N, M, K. O is at position 4.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। पाँच डिब्बे K, L, M, N और O एक ही ढेर में एक के ऊपर एक रखे गए हैं; स्थिति 1 सबसे नीचे और स्थिति 5 सबसे ऊपर है। M सम संख्या वाली स्थिति पर रखा है। O, M से कहीं ऊपर रखा है। L, O से कहीं ऊपर रखा है। N ऊपर से तीसरे स्थान पर है। प्रश्न: डिब्बा O किस स्थिति पर रखा है?","optionsHi":["2","3","4","5"],"explanationHi":"अंतिम व्यवस्था: स्थिति 5 से 1 तक: L, O, N, M, K। O स्थिति 4 पर है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-94","question":"Study the information and answer the question. Five persons Kiran, Lalit, Meena, Naveen and Ojas visit a trade fair in 5 different months of the same year (January, February, March, April, May), one person per month, in that order of months. Naveen goes in a month that has 28 days. Ojas goes in some month after Meena. Meena goes in the month immediately before Kiran. Question: In which month does Lalit visit the fair?","options":["March","April","February","January"],"answer":3,"explanation":"Final arrangement: January: Lalit, February: Naveen, March: Meena, April: Kiran, May: Ojas. Lalit goes in January.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। पाँच व्यक्ति किरण, ललित, मीना, नवीन और ओजस एक ही वर्ष के 5 अलग-अलग महीनों (जनवरी, फरवरी, मार्च, अप्रैल, मई) में एक व्यापार मेले में जाते हैं, प्रत्येक महीने में एक व्यक्ति, महीनों के इसी क्रम में। नवीन उस महीने में जाता है जिसमें 28 दिन होते हैं। ओजस मीना के बाद किसी महीने में जाता है। मीना किरण के ठीक पहले वाले महीने में जाती है। प्रश्न: ललित मेले में किस महीने में जाता है?","optionsHi":["मार्च","अप्रैल","फरवरी","जनवरी"],"explanationHi":"अंतिम व्यवस्था: जनवरी: ललित, फरवरी: नवीन, मार्च: मीना, अप्रैल: किरण, मई: ओजस। ललित जनवरी में जाता है।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-95","question":"Study the information and answer the question. Six persons Kiran, Lalit, Meena, Naveen, Ojas and Pooja sit in a straight row facing north. Lalit sits at an extreme end of the row. Meena sits to the immediate right of Lalit. Pooja is an immediate neighbour of Ojas. Naveen sits third to the right of Pooja. Question: Which pair sits at the two extreme ends of the row?","options":["Lalit and Naveen","Kiran and Naveen","Ojas and Meena","Meena and Lalit"],"answer":0,"explanation":"Final arrangement: From left to right: Lalit, Meena, Pooja, Ojas, Kiran, Naveen. The ends are occupied by Lalit and Naveen.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति किरण, ललित, मीना, नवीन, ओजस और पूजा उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं। ललित पंक्ति के एक छोर पर बैठा है। मीना ललित के ठीक दाएँ बैठी है। पूजा ओजस की निकटतम पड़ोसी है। नवीन पूजा के दाएँ से तीसरे स्थान पर बैठा है। प्रश्न: पंक्ति के दोनों छोरों पर कौन-सा जोड़ा बैठा है?","optionsHi":["ललित और नवीन","किरण और नवीन","ओजस और मीना","मीना और ललित"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: ललित, मीना, पूजा, ओजस, किरण, नवीन। छोरों पर ललित और नवीन हैं।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-96","question":"Study the information and answer the question. Six persons Kiran, Lalit, Meena, Naveen, Ojas and Pooja sit in a straight row facing north. Lalit sits at an extreme end of the row. Meena sits to the immediate right of Lalit. Pooja is an immediate neighbour of Ojas. Naveen sits third to the right of Pooja. Question: Who sits third to the right of Lalit?","options":["Meena","Kiran","Ojas","Pooja"],"answer":2,"explanation":"Final arrangement: From left to right: Lalit, Meena, Pooja, Ojas, Kiran, Naveen. Ojas sits third to the right of Lalit.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति किरण, ललित, मीना, नवीन, ओजस और पूजा उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं। ललित पंक्ति के एक छोर पर बैठा है। मीना ललित के ठीक दाएँ बैठी है। पूजा ओजस की निकटतम पड़ोसी है। नवीन पूजा के दाएँ से तीसरे स्थान पर बैठा है। प्रश्न: ललित के दाएँ से तीसरे स्थान पर कौन बैठा है?","optionsHi":["मीना","किरण","ओजस","पूजा"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: ललित, मीना, पूजा, ओजस, किरण, नवीन। ओजस ललित के दाएँ से तीसरे स्थान पर बैठा है।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-97","question":"Study the information and answer the question. Six persons Tanya, Uday, Varun, Wasim, Yamini and Zoya sit around a circular table, equally spaced and facing the centre. Zoya sits to the immediate left of Varun. Uday sits second to the left of Zoya. Yamini sits second to the left of Wasim. Question: Who sits second to the left of Tanya?","options":["Wasim","Yamini","Uday","Zoya"],"answer":3,"explanation":"Final arrangement: Going clockwise from Tanya: Tanya, Varun, Zoya, Wasim, Uday, Yamini. Zoya sits second to the left of Tanya.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति तान्या, उदय, वरुण, वसीम, यामिनी और ज़ोया केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। ज़ोया वरुण के ठीक बाएँ बैठी है। उदय ज़ोया के बाएँ से दूसरे स्थान पर बैठा है। यामिनी वसीम के बाएँ से दूसरे स्थान पर बैठी है। प्रश्न: तान्या के बाएँ से दूसरे स्थान पर कौन बैठा है?","optionsHi":["वसीम","यामिनी","उदय","ज़ोया"],"explanationHi":"अंतिम व्यवस्था: तान्या से दक्षिणावर्त चलने पर: तान्या, वरुण, ज़ोया, वसीम, उदय, यामिनी। ज़ोया तान्या के बाएँ से दूसरे स्थान पर बैठी है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-98","question":"Study the information and answer the question. Six persons Tanya, Uday, Varun, Wasim, Yamini and Zoya sit around a circular table, equally spaced and facing the centre. Zoya sits to the immediate left of Varun. Uday sits second to the left of Zoya. Yamini sits second to the left of Wasim. Question: Who sits opposite Yamini?","options":["Zoya","Varun","Uday","Wasim"],"answer":0,"explanation":"Final arrangement: Going clockwise from Tanya: Tanya, Varun, Zoya, Wasim, Uday, Yamini. Zoya is directly opposite Yamini.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति तान्या, उदय, वरुण, वसीम, यामिनी और ज़ोया केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। ज़ोया वरुण के ठीक बाएँ बैठी है। उदय ज़ोया के बाएँ से दूसरे स्थान पर बैठा है। यामिनी वसीम के बाएँ से दूसरे स्थान पर बैठी है। प्रश्न: यामिनी के सामने कौन बैठा है?","optionsHi":["ज़ोया","वरुण","उदय","वसीम"],"explanationHi":"अंतिम व्यवस्था: तान्या से दक्षिणावर्त चलने पर: तान्या, वरुण, ज़ोया, वसीम, उदय, यामिनी। ज़ोया ठीक यामिनी के सामने है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-99","question":"Study the information and answer the question. Six persons J, K, L, M, N and O live on the 6 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 6. J lives on an odd-numbered floor. J lives somewhere above N. L lives on the lowest floor. O lives somewhere below M. Only two persons live between O and K. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["N – O","K – M","M – J","L – N"],"answer":1,"explanation":"Final arrangement: From floor 6 down to 1: K, J, M, O, N, L. In M – J, N – O, L – N, the second person lives immediately above the first; K – M does not follow this pattern.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति J, K, L, M, N और O एक इमारत की 6 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 6 है। J एक विषम संख्या वाली मंज़िल पर रहता है। J, N से कहीं ऊपर रहता है। L सबसे निचली मंज़िल पर रहता है। O, M से कहीं नीचे रहता है। O और K के बीच केवल दो व्यक्ति रहते हैं। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["N – O","K – M","M – J","L – N"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 6 से 1 तक: K, J, M, O, N, L। M – J, N – O, L – N में दूसरा व्यक्ति पहले के ठीक ऊपर रहता है; K – M इस पैटर्न का पालन नहीं करता।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-100","question":"Study the information and answer the question. Six persons J, K, L, M, N and O live on the 6 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 6. J lives on an odd-numbered floor. J lives somewhere above N. L lives on the lowest floor. O lives somewhere below M. Only two persons live between O and K. Question: Who lives immediately above J?","options":["N","L","K","M"],"answer":2,"explanation":"Final arrangement: From floor 6 down to 1: K, J, M, O, N, L. K lives immediately above J.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति J, K, L, M, N और O एक इमारत की 6 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 6 है। J एक विषम संख्या वाली मंज़िल पर रहता है। J, N से कहीं ऊपर रहता है। L सबसे निचली मंज़िल पर रहता है। O, M से कहीं नीचे रहता है। O और K के बीच केवल दो व्यक्ति रहते हैं। प्रश्न: J के ठीक ऊपर कौन रहता है?","optionsHi":["N","L","K","M"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 6 से 1 तक: K, J, M, O, N, L। K, J के ठीक ऊपर रहता है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-101","question":"Study the information and answer the question. Six boxes P, Q, R, S, T and U are kept one above another in a single stack; position 1 is at the bottom and position 6 at the top. T is kept at an even-numbered position. T is kept neither at the top nor at the bottom. T is kept immediately above S. T is kept somewhere above R. P is kept three positions below U. Question: How many boxes are kept between T and P?","options":["0","1","2","3"],"answer":1,"explanation":"Final arrangement from position 6 down to 1: Q, U, T, S, P, R. T is at 4 and P at 2, so only S lies between them, i.e. 1.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह डिब्बे P, Q, R, S, T और U एक ही ढेर में एक के ऊपर एक रखे गए हैं; स्थिति 1 सबसे नीचे और स्थिति 6 सबसे ऊपर है। T सम संख्या वाली स्थिति पर रखा है। T न सबसे ऊपर रखा है न सबसे नीचे। T, S के ठीक ऊपर रखा है। T, R से कहीं ऊपर रखा है। P, U से तीन स्थिति नीचे रखा है। प्रश्न: T और P के बीच कितने डिब्बे रखे हैं?","optionsHi":["0","1","2","3"],"explanationHi":"अंतिम व्यवस्था स्थिति 6 से 1 तक: Q, U, T, S, P, R। T स्थिति 4 पर और P स्थिति 2 पर है, इसलिए उनके बीच केवल S है, यानी 1।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-102","question":"Study the information and answer the question. Six boxes P, Q, R, S, T and U are kept one above another in a single stack; position 1 is at the bottom and position 6 at the top. T is kept at an even-numbered position. T is kept neither at the top nor at the bottom. T is kept immediately above S. T is kept somewhere above R. P is kept three positions below U. Question: Which box is kept two positions above R?","options":["S","Q","T","U"],"answer":0,"explanation":"Final arrangement: From position 6 down to 1: Q, U, T, S, P, R. S is kept two positions above R.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह डिब्बे P, Q, R, S, T और U एक ही ढेर में एक के ऊपर एक रखे गए हैं; स्थिति 1 सबसे नीचे और स्थिति 6 सबसे ऊपर है। T सम संख्या वाली स्थिति पर रखा है। T न सबसे ऊपर रखा है न सबसे नीचे। T, S के ठीक ऊपर रखा है। T, R से कहीं ऊपर रखा है। P, U से तीन स्थिति नीचे रखा है। प्रश्न: R से दो स्थिति ऊपर कौन-सा डिब्बा रखा है?","optionsHi":["S","Q","T","U"],"explanationHi":"अंतिम व्यवस्था: स्थिति 6 से 1 तक: Q, U, T, S, P, R। S, R से दो स्थिति ऊपर रखा है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-103","question":"Study the information and answer the question. Six persons Aman, Bela, Chirag, Divya, Esha and Farhan visit a trade fair in 6 different months of the same year (January, February, March, April, May, June), one person per month, in that order of months. Farhan goes in some month before Aman. Exactly one person goes between Aman and Chirag. Farhan goes exactly two months after Esha. Only one person goes between Bela and Chirag. Divya goes neither first nor last. Question: Who goes two months before Divya?","options":["Bela","Farhan","Aman","Chirag"],"answer":1,"explanation":"Final arrangement: January: Esha, February: Bela, March: Farhan, April: Chirag, May: Divya, June: Aman. Farhan goes two months before Divya.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति अमन, बेला, चिराग, दिव्या, ईशा और फ़रहान एक ही वर्ष के 6 अलग-अलग महीनों (जनवरी, फरवरी, मार्च, अप्रैल, मई, जून) में एक व्यापार मेले में जाते हैं, प्रत्येक महीने में एक व्यक्ति, महीनों के इसी क्रम में। फ़रहान अमन से पहले किसी महीने में जाता है। अमन और चिराग के बीच ठीक एक व्यक्ति जाता है। फ़रहान ईशा के ठीक दो महीने बाद जाता है। बेला और चिराग के बीच केवल एक व्यक्ति जाता है। दिव्या न पहले जाती है न अंत में। प्रश्न: दिव्या से दो महीने पहले कौन जाता है?","optionsHi":["बेला","फ़रहान","अमन","चिराग"],"explanationHi":"अंतिम व्यवस्था: जनवरी: ईशा, फरवरी: बेला, मार्च: फ़रहान, अप्रैल: चिराग, मई: दिव्या, जून: अमन। फ़रहान दिव्या से दो महीने पहले जाता है।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-104","question":"Study the information and answer the question. Six persons Aman, Bela, Chirag, Divya, Esha and Farhan visit a trade fair in 6 different months of the same year (January, February, March, April, May, June), one person per month, in that order of months. Farhan goes in some month before Aman. Exactly one person goes between Aman and Chirag. Farhan goes exactly two months after Esha. Only one person goes between Bela and Chirag. Divya goes neither first nor last. Question: How many persons visit the fair between Divya and Esha?","options":["1","2","3","4"],"answer":2,"explanation":"Final arrangement: January: Esha, February: Bela, March: Farhan, April: Chirag, May: Divya, June: Aman. Between Divya and Esha are Bela, Farhan, Chirag, i.e. 3.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति अमन, बेला, चिराग, दिव्या, ईशा और फ़रहान एक ही वर्ष के 6 अलग-अलग महीनों (जनवरी, फरवरी, मार्च, अप्रैल, मई, जून) में एक व्यापार मेले में जाते हैं, प्रत्येक महीने में एक व्यक्ति, महीनों के इसी क्रम में। फ़रहान अमन से पहले किसी महीने में जाता है। अमन और चिराग के बीच ठीक एक व्यक्ति जाता है। फ़रहान ईशा के ठीक दो महीने बाद जाता है। बेला और चिराग के बीच केवल एक व्यक्ति जाता है। दिव्या न पहले जाती है न अंत में। प्रश्न: दिव्या और ईशा के बीच कितने व्यक्ति मेले में जाते हैं?","optionsHi":["1","2","3","4"],"explanationHi":"अंतिम व्यवस्था: जनवरी: ईशा, फरवरी: बेला, मार्च: फ़रहान, अप्रैल: चिराग, मई: दिव्या, जून: अमन। दिव्या और ईशा के बीच बेला, फ़रहान, चिराग हैं, यानी 3।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-105","question":"Study the information and answer the question. Six persons A, B, C, D, E and F sit around a circular table, equally spaced and facing away from the centre. D sits to the immediate left of F. D is not an immediate neighbour of B. D sits second to the left of C. E sits to the immediate right of C. Question: How many persons sit between B and C, counted along the shorter side of the table?","options":["1","2","3","4"],"answer":0,"explanation":"Final arrangement: Going clockwise from A: A, D, F, C, E, B. Between B and C is E, i.e. 1.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति A, B, C, D, E और F केंद्र से बाहर की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। D, F के ठीक बाएँ बैठा है। D, B का निकटतम पड़ोसी नहीं है। D, C के बाएँ से दूसरे स्थान पर बैठा है। E, C के ठीक दाएँ बैठा है। प्रश्न: मेज़ की छोटी ओर से गिनने पर B और C के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["1","2","3","4"],"explanationHi":"अंतिम व्यवस्था: A से दक्षिणावर्त चलने पर: A, D, F, C, E, B। B और C के बीच E है, यानी 1।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-106","question":"Study the information and answer the question. Six persons A, B, C, D, E and F sit around a circular table, equally spaced and facing away from the centre. D sits to the immediate left of F. D is not an immediate neighbour of B. D sits second to the left of C. E sits to the immediate right of C. Question: Who sits opposite D?","options":["F","A","B","E"],"answer":3,"explanation":"Final arrangement: Going clockwise from A: A, D, F, C, E, B. E is directly opposite D.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति A, B, C, D, E और F केंद्र से बाहर की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। D, F के ठीक बाएँ बैठा है। D, B का निकटतम पड़ोसी नहीं है। D, C के बाएँ से दूसरे स्थान पर बैठा है। E, C के ठीक दाएँ बैठा है। प्रश्न: D के सामने कौन बैठा है?","optionsHi":["F","A","B","E"],"explanationHi":"अंतिम व्यवस्था: A से दक्षिणावर्त चलने पर: A, D, F, C, E, B। E ठीक D के सामने है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-107","question":"Study the information and answer the question. Seven persons J, K, L, M, N, O and P sit in a straight row facing north. P sits at an extreme end of the row. K sits to the immediate right of P. M sits to the immediate right of K. M sits to the immediate left of N. J sits second to the right of O. Question: How many persons sit between M and J?","options":["2","3","4","5"],"answer":1,"explanation":"Final arrangement: From left to right: P, K, M, N, O, L, J. Between M and J are N, O, L, i.e. 3.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति J, K, L, M, N, O और P उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं। P पंक्ति के एक छोर पर बैठा है। K, P के ठीक दाएँ बैठा है। M, K के ठीक दाएँ बैठा है। M, N के ठीक बाएँ बैठा है। J, O के दाएँ से दूसरे स्थान पर बैठा है। प्रश्न: M और J के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["2","3","4","5"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: P, K, M, N, O, L, J। M और J के बीच N, O, L हैं, यानी 3।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-108","question":"Study the information and answer the question. Seven persons J, K, L, M, N, O and P sit in a straight row facing north. P sits at an extreme end of the row. K sits to the immediate right of P. M sits to the immediate right of K. M sits to the immediate left of N. J sits second to the right of O. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["M – O","N – L","O – P","P – M"],"answer":2,"explanation":"Final arrangement: From left to right: P, K, M, N, O, L, J. In M – O, N – L, P – M, the second person sits second to the right of the first; O – P does not follow this pattern.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति J, K, L, M, N, O और P उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं। P पंक्ति के एक छोर पर बैठा है। K, P के ठीक दाएँ बैठा है। M, K के ठीक दाएँ बैठा है। M, N के ठीक बाएँ बैठा है। J, O के दाएँ से दूसरे स्थान पर बैठा है। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["M – O","N – L","O – P","P – M"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: P, K, M, N, O, L, J। M – O, N – L, P – M में दूसरा व्यक्ति पहले के दाएँ से दूसरे स्थान पर बैठा है; O – P इस पैटर्न का पालन नहीं करता।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-109","question":"Study the information and answer the question. Seven persons Tanya, Uday, Varun, Wasim, Yamini, Zoya and Arjun live on the 7 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 7. Tanya lives on an odd-numbered floor. Tanya lives immediately below Varun. Wasim lives on floor 2. Yamini lives neither at the top nor at the bottom. Uday lives immediately below Arjun. Question: On which floor does Tanya live?","options":["3","4","5","6"],"answer":0,"explanation":"Final arrangement: From floor 7 down to 1: Arjun, Uday, Yamini, Varun, Tanya, Wasim, Zoya. Tanya lives on floor 3.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति तान्या, उदय, वरुण, वसीम, यामिनी, ज़ोया और अर्जुन एक इमारत की 7 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 7 है। तान्या एक विषम संख्या वाली मंज़िल पर रहती है। तान्या वरुण के ठीक नीचे रहती है। वसीम मंज़िल 2 पर रहता है। यामिनी न सबसे ऊपर रहती है न सबसे नीचे। उदय अर्जुन के ठीक नीचे रहता है। प्रश्न: तान्या किस मंज़िल पर रहती है?","optionsHi":["3","4","5","6"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 7 से 1 तक: अर्जुन, उदय, यामिनी, वरुण, तान्या, वसीम, ज़ोया। तान्या मंज़िल 3 पर रहती है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-110","question":"Study the information and answer the question. Seven persons Tanya, Uday, Varun, Wasim, Yamini, Zoya and Arjun live on the 7 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 7. Tanya lives on an odd-numbered floor. Tanya lives immediately below Varun. Wasim lives on floor 2. Yamini lives neither at the top nor at the bottom. Uday lives immediately below Arjun. Question: Who lives immediately below Tanya?","options":["Uday","Zoya","Varun","Wasim"],"answer":3,"explanation":"Final arrangement: From floor 7 down to 1: Arjun, Uday, Yamini, Varun, Tanya, Wasim, Zoya. Wasim lives immediately below Tanya.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति तान्या, उदय, वरुण, वसीम, यामिनी, ज़ोया और अर्जुन एक इमारत की 7 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 7 है। तान्या एक विषम संख्या वाली मंज़िल पर रहती है। तान्या वरुण के ठीक नीचे रहती है। वसीम मंज़िल 2 पर रहता है। यामिनी न सबसे ऊपर रहती है न सबसे नीचे। उदय अर्जुन के ठीक नीचे रहता है। प्रश्न: तान्या के ठीक नीचे कौन रहता है?","optionsHi":["उदय","ज़ोया","वरुण","वसीम"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 7 से 1 तक: अर्जुन, उदय, यामिनी, वरुण, तान्या, वसीम, ज़ोया। वसीम तान्या के ठीक नीचे रहता है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-111","question":"Study the information and answer the question. Eight persons A, B, C, D, E, F, G and H sit in a straight row facing north. B sits fourth to the right of G. G sits to the immediate left of E. E sits second to the left of F. B sits second to the left of H. D sits second to the left of A. Question: Who sits to the immediate left of H?","options":["B","D","A","G"],"answer":1,"explanation":"Final arrangement: From left to right: G, E, C, F, B, D, H, A. D sits to the immediate left of H.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति A, B, C, D, E, F, G और H उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं। B, G के दाएँ से चौथे स्थान पर बैठा है। G, E के ठीक बाएँ बैठा है। E, F के बाएँ से दूसरे स्थान पर बैठा है। B, H के बाएँ से दूसरे स्थान पर बैठा है। D, A के बाएँ से दूसरे स्थान पर बैठा है। प्रश्न: H के ठीक बाएँ कौन बैठा है?","optionsHi":["B","D","A","G"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: G, E, C, F, B, D, H, A। D, H के ठीक बाएँ बैठा है।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-112","question":"Study the information and answer the question. Eight persons A, B, C, D, E, F, G and H sit in a straight row facing north. B sits fourth to the right of G. G sits to the immediate left of E. E sits second to the left of F. B sits second to the left of H. D sits second to the left of A. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["D – A","C – B","H – F","B – H"],"answer":2,"explanation":"Final arrangement: From left to right: G, E, C, F, B, D, H, A. In B – H, D – A, C – B, the second person sits second to the right of the first; H – F does not follow this pattern.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति A, B, C, D, E, F, G और H उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं। B, G के दाएँ से चौथे स्थान पर बैठा है। G, E के ठीक बाएँ बैठा है। E, F के बाएँ से दूसरे स्थान पर बैठा है। B, H के बाएँ से दूसरे स्थान पर बैठा है। D, A के बाएँ से दूसरे स्थान पर बैठा है। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["D – A","C – B","H – F","B – H"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: G, E, C, F, B, D, H, A। B – H, D – A, C – B में दूसरा व्यक्ति पहले के दाएँ से दूसरे स्थान पर बैठा है; H – F इस पैटर्न का पालन नहीं करता।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-113","question":"Study the information and answer the question. Eight persons A, B, C, D, E, F, G and H sit in a straight row facing north. B sits fourth to the right of G. G sits to the immediate left of E. E sits second to the left of F. B sits second to the left of H. D sits second to the left of A. Question: Which pair sits at the two extreme ends of the row?","options":["E and H","A and B","A and H","G and A"],"answer":3,"explanation":"Final arrangement: From left to right: G, E, C, F, B, D, H, A. The ends are occupied by G and A.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति A, B, C, D, E, F, G और H उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं। B, G के दाएँ से चौथे स्थान पर बैठा है। G, E के ठीक बाएँ बैठा है। E, F के बाएँ से दूसरे स्थान पर बैठा है। B, H के बाएँ से दूसरे स्थान पर बैठा है। D, A के बाएँ से दूसरे स्थान पर बैठा है। प्रश्न: पंक्ति के दोनों छोरों पर कौन-सा जोड़ा बैठा है?","optionsHi":["E और H","A और B","A और H","G और A"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: G, E, C, F, B, D, H, A। छोरों पर G और A हैं।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-114","question":"Study the information and answer the question. Eight persons P, Q, R, S, T, U, V and W sit around a circular table, equally spaced and facing the centre. U sits to the immediate right of R. R sits second to the left of T. Q sits to the immediate right of T. W sits second to the left of S. W sits to the immediate right of P. Question: Who sits third to the left of S?","options":["P","U","V","T"],"answer":0,"explanation":"Final arrangement: Going clockwise from P: P, Q, T, U, R, S, V, W. P sits third to the left of S.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति P, Q, R, S, T, U, V और W केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। U, R के ठीक दाएँ बैठा है। R, T के बाएँ से दूसरे स्थान पर बैठा है। Q, T के ठीक दाएँ बैठा है। W, S के बाएँ से दूसरे स्थान पर बैठा है। W, P के ठीक दाएँ बैठा है। प्रश्न: S के बाएँ से तीसरे स्थान पर कौन बैठा है?","optionsHi":["P","U","V","T"],"explanationHi":"अंतिम व्यवस्था: P से दक्षिणावर्त चलने पर: P, Q, T, U, R, S, V, W। P, S के बाएँ से तीसरे स्थान पर बैठा है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-115","question":"Study the information and answer the question. Eight persons P, Q, R, S, T, U, V and W sit around a circular table, equally spaced and facing the centre. U sits to the immediate right of R. R sits second to the left of T. Q sits to the immediate right of T. W sits second to the left of S. W sits to the immediate right of P. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["T – P","R – W","W – S","P – V"],"answer":1,"explanation":"Final arrangement: Going clockwise from P: P, Q, T, U, R, S, V, W. In W – S, T – P, P – V, the second person sits second to the right of the first; R – W does not follow this pattern.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति P, Q, R, S, T, U, V और W केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। U, R के ठीक दाएँ बैठा है। R, T के बाएँ से दूसरे स्थान पर बैठा है। Q, T के ठीक दाएँ बैठा है। W, S के बाएँ से दूसरे स्थान पर बैठा है। W, P के ठीक दाएँ बैठा है। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["T – P","R – W","W – S","P – V"],"explanationHi":"अंतिम व्यवस्था: P से दक्षिणावर्त चलने पर: P, Q, T, U, R, S, V, W। W – S, T – P, P – V में दूसरा व्यक्ति पहले के दाएँ से दूसरे स्थान पर बैठा है; R – W इस पैटर्न का पालन नहीं करता।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-116","question":"Study the information and answer the question. Eight persons P, Q, R, S, T, U, V and W sit around a circular table, equally spaced and facing the centre. U sits to the immediate right of R. R sits second to the left of T. Q sits to the immediate right of T. W sits second to the left of S. W sits to the immediate right of P. Question: How many persons sit between U and V, counted along the shorter side of the table?","options":["0","1","2","3"],"answer":2,"explanation":"Final arrangement: Going clockwise from P: P, Q, T, U, R, S, V, W. Between U and V are R, S, i.e. 2.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति P, Q, R, S, T, U, V और W केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। U, R के ठीक दाएँ बैठा है। R, T के बाएँ से दूसरे स्थान पर बैठा है। Q, T के ठीक दाएँ बैठा है। W, S के बाएँ से दूसरे स्थान पर बैठा है। W, P के ठीक दाएँ बैठा है। प्रश्न: मेज़ की छोटी ओर से गिनने पर U और V के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["0","1","2","3"],"explanationHi":"अंतिम व्यवस्था: P से दक्षिणावर्त चलने पर: P, Q, T, U, R, S, V, W। U और V के बीच R, S हैं, यानी 2।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-117","question":"Study the information and answer the question. Eight persons Aman, Bela, Chirag, Divya, Esha, Farhan, Gauri and Harsh live on the 8 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 8. Divya lives neither at the top nor at the bottom. Divya lives somewhere above Farhan. Farhan lives three floors above Chirag. Bela lives four floors above Chirag. Esha lives four floors below Aman. Exactly two persons live between Esha and Gauri. Question: How many persons live between Bela and Gauri?","options":["1","2","3","4"],"answer":3,"explanation":"Final arrangement: From floor 8 down to 1: Aman, Divya, Bela, Farhan, Esha, Harsh, Chirag, Gauri. Between Bela and Gauri are Chirag, Harsh, Esha, Farhan, i.e. 4.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति अमन, बेला, चिराग, दिव्या, ईशा, फ़रहान, गौरी और हर्ष एक इमारत की 8 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 8 है। दिव्या न सबसे ऊपर रहती है न सबसे नीचे। दिव्या फ़रहान से कहीं ऊपर रहती है। फ़रहान चिराग से तीन मंज़िल ऊपर रहता है। बेला चिराग से चार मंज़िल ऊपर रहती है। ईशा अमन से चार मंज़िल नीचे रहती है। ईशा और गौरी के बीच ठीक दो व्यक्ति रहते हैं। प्रश्न: बेला और गौरी के बीच कितने व्यक्ति रहते हैं?","optionsHi":["1","2","3","4"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 8 से 1 तक: अमन, दिव्या, बेला, फ़रहान, ईशा, हर्ष, चिराग, गौरी। बेला और गौरी के बीच चिराग, हर्ष, ईशा, फ़रहान हैं, यानी 4।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-118","question":"Study the information and answer the question. Eight persons Aman, Bela, Chirag, Divya, Esha, Farhan, Gauri and Harsh live on the 8 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 8. Divya lives neither at the top nor at the bottom. Divya lives somewhere above Farhan. Farhan lives three floors above Chirag. Bela lives four floors above Chirag. Esha lives four floors below Aman. Exactly two persons live between Esha and Gauri. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["Aman – Esha","Farhan – Bela","Gauri – Chirag","Esha – Farhan"],"answer":0,"explanation":"Final arrangement: From floor 8 down to 1: Aman, Divya, Bela, Farhan, Esha, Harsh, Chirag, Gauri. In Farhan – Bela, Gauri – Chirag, Esha – Farhan, the second person lives immediately above the first; Aman – Esha does not follow this pattern.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति अमन, बेला, चिराग, दिव्या, ईशा, फ़रहान, गौरी और हर्ष एक इमारत की 8 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 8 है। दिव्या न सबसे ऊपर रहती है न सबसे नीचे। दिव्या फ़रहान से कहीं ऊपर रहती है। फ़रहान चिराग से तीन मंज़िल ऊपर रहता है। बेला चिराग से चार मंज़िल ऊपर रहती है। ईशा अमन से चार मंज़िल नीचे रहती है। ईशा और गौरी के बीच ठीक दो व्यक्ति रहते हैं। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["अमन – ईशा","फ़रहान – बेला","गौरी – चिराग","ईशा – फ़रहान"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 8 से 1 तक: अमन, दिव्या, बेला, फ़रहान, ईशा, हर्ष, चिराग, गौरी। फ़रहान – बेला, गौरी – चिराग, ईशा – फ़रहान में दूसरा व्यक्ति पहले के ठीक ऊपर रहता है; अमन – ईशा इस पैटर्न का पालन नहीं करता।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-119","question":"Study the information and answer the question. Eight persons Aman, Bela, Chirag, Divya, Esha, Farhan, Gauri and Harsh live on the 8 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 8. Divya lives neither at the top nor at the bottom. Divya lives somewhere above Farhan. Farhan lives three floors above Chirag. Bela lives four floors above Chirag. Esha lives four floors below Aman. Exactly two persons live between Esha and Gauri. Question: Who lives two floors below Farhan?","options":["Divya","Harsh","Aman","Bela"],"answer":1,"explanation":"Final arrangement: From floor 8 down to 1: Aman, Divya, Bela, Farhan, Esha, Harsh, Chirag, Gauri. Harsh lives two floors below Farhan.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति अमन, बेला, चिराग, दिव्या, ईशा, फ़रहान, गौरी और हर्ष एक इमारत की 8 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 8 है। दिव्या न सबसे ऊपर रहती है न सबसे नीचे। दिव्या फ़रहान से कहीं ऊपर रहती है। फ़रहान चिराग से तीन मंज़िल ऊपर रहता है। बेला चिराग से चार मंज़िल ऊपर रहती है। ईशा अमन से चार मंज़िल नीचे रहती है। ईशा और गौरी के बीच ठीक दो व्यक्ति रहते हैं। प्रश्न: फ़रहान से दो मंज़िल नीचे कौन रहता है?","optionsHi":["दिव्या","हर्ष","अमन","बेला"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 8 से 1 तक: अमन, दिव्या, बेला, फ़रहान, ईशा, हर्ष, चिराग, गौरी। हर्ष फ़रहान से दो मंज़िल नीचे रहता है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-120","question":"Study the information and answer the question. Seven boxes K, L, M, N, O, P and Q are kept one above another in a single stack; position 1 is at the bottom and position 7 at the top. K is kept at position 4. L is kept somewhere below K. O is kept somewhere below L. P is kept immediately above K. Exactly two boxes are kept between P and Q. N is kept at the top. Question: Which box is kept two positions above Q?","options":["N","M","K","O"],"answer":2,"explanation":"Final arrangement: From position 7 down to 1: N, M, P, K, L, Q, O. K is kept two positions above Q.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात डिब्बे K, L, M, N, O, P और Q एक ही ढेर में एक के ऊपर एक रखे गए हैं; स्थिति 1 सबसे नीचे और स्थिति 7 सबसे ऊपर है। K स्थिति 4 पर रखा है। L, K से कहीं नीचे रखा है। O, L से कहीं नीचे रखा है। P, K के ठीक ऊपर रखा है। P और Q के बीच ठीक दो डिब्बे रखे हैं। N सबसे ऊपर रखा है। प्रश्न: Q से दो स्थिति ऊपर कौन-सा डिब्बा रखा है?","optionsHi":["N","M","K","O"],"explanationHi":"अंतिम व्यवस्था: स्थिति 7 से 1 तक: N, M, P, K, L, Q, O। K, Q से दो स्थिति ऊपर रखा है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-121","question":"Study the information and answer the question. Seven boxes K, L, M, N, O, P and Q are kept one above another in a single stack; position 1 is at the bottom and position 7 at the top. K is kept at position 4. L is kept somewhere below K. O is kept somewhere below L. P is kept immediately above K. Exactly two boxes are kept between P and Q. N is kept at the top. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["K – P","M – N","L – K","N – O"],"answer":3,"explanation":"Final arrangement: From position 7 down to 1: N, M, P, K, L, Q, O. In L – K, M – N, K – P, the second box is kept immediately above the first; N – O does not follow this pattern.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात डिब्बे K, L, M, N, O, P और Q एक ही ढेर में एक के ऊपर एक रखे गए हैं; स्थिति 1 सबसे नीचे और स्थिति 7 सबसे ऊपर है। K स्थिति 4 पर रखा है। L, K से कहीं नीचे रखा है। O, L से कहीं नीचे रखा है। P, K के ठीक ऊपर रखा है। P और Q के बीच ठीक दो डिब्बे रखे हैं। N सबसे ऊपर रखा है। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["K – P","M – N","L – K","N – O"],"explanationHi":"अंतिम व्यवस्था: स्थिति 7 से 1 तक: N, M, P, K, L, Q, O। L – K, M – N, K – P में दूसरा डिब्बा पहले के ठीक ऊपर रखा है; N – O इस पैटर्न का पालन नहीं करता।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-122","question":"Study the information and answer the question. Eight persons Kiran, Lalit, Meena, Naveen, Ojas, Pooja, Rohit and Sana sit around a circular table, equally spaced and facing away from the centre. Meena sits second to the right of Pooja. Pooja sits third to the left of Ojas. Lalit sits opposite Ojas. Kiran sits to the immediate left of Lalit. Rohit sits third to the right of Naveen. Question: Who sits opposite Meena?","options":["Kiran","Ojas","Sana","Naveen"],"answer":0,"explanation":"Final arrangement: Going clockwise from Kiran: Kiran, Lalit, Pooja, Naveen, Meena, Ojas, Rohit, Sana. Kiran is directly opposite Meena.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति किरण, ललित, मीना, नवीन, ओजस, पूजा, रोहित और सना केंद्र से बाहर की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। मीना पूजा के दाएँ से दूसरे स्थान पर बैठी है। पूजा ओजस के बाएँ से तीसरे स्थान पर बैठी है। ललित ओजस के सामने बैठा है। किरण ललित के ठीक बाएँ बैठी है। रोहित नवीन के दाएँ से तीसरे स्थान पर बैठा है। प्रश्न: मीना के सामने कौन बैठा है?","optionsHi":["किरण","ओजस","सना","नवीन"],"explanationHi":"अंतिम व्यवस्था: किरण से दक्षिणावर्त चलने पर: किरण, ललित, पूजा, नवीन, मीना, ओजस, रोहित, सना। किरण ठीक मीना के सामने है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-123","question":"Study the information and answer the question. Eight persons Kiran, Lalit, Meena, Naveen, Ojas, Pooja, Rohit and Sana sit around a circular table, equally spaced and facing away from the centre. Meena sits second to the right of Pooja. Pooja sits third to the left of Ojas. Lalit sits opposite Ojas. Kiran sits to the immediate left of Lalit. Rohit sits third to the right of Naveen. Question: Who sits to the immediate right of Pooja?","options":["Ojas","Naveen","Sana","Lalit"],"answer":1,"explanation":"Final arrangement: Going clockwise from Kiran: Kiran, Lalit, Pooja, Naveen, Meena, Ojas, Rohit, Sana. Naveen sits to the immediate right of Pooja.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति किरण, ललित, मीना, नवीन, ओजस, पूजा, रोहित और सना केंद्र से बाहर की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। मीना पूजा के दाएँ से दूसरे स्थान पर बैठी है। पूजा ओजस के बाएँ से तीसरे स्थान पर बैठी है। ललित ओजस के सामने बैठा है। किरण ललित के ठीक बाएँ बैठी है। रोहित नवीन के दाएँ से तीसरे स्थान पर बैठा है। प्रश्न: पूजा के ठीक दाएँ कौन बैठा है?","optionsHi":["ओजस","नवीन","सना","ललित"],"explanationHi":"अंतिम व्यवस्था: किरण से दक्षिणावर्त चलने पर: किरण, ललित, पूजा, नवीन, मीना, ओजस, रोहित, सना। नवीन पूजा के ठीक दाएँ बैठा है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-124","question":"Study the information and answer the question. Eight persons Kiran, Lalit, Meena, Naveen, Ojas, Pooja, Rohit and Sana sit around a circular table, equally spaced and facing away from the centre. Meena sits second to the right of Pooja. Pooja sits third to the left of Ojas. Lalit sits opposite Ojas. Kiran sits to the immediate left of Lalit. Rohit sits third to the right of Naveen. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["Kiran – Pooja","Pooja – Meena","Ojas – Rohit","Sana – Lalit"],"answer":2,"explanation":"Final arrangement: Going clockwise from Kiran: Kiran, Lalit, Pooja, Naveen, Meena, Ojas, Rohit, Sana. In Kiran – Pooja, Sana – Lalit, Pooja – Meena, the second person sits second to the right of the first; Ojas – Rohit does not follow this pattern.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति किरण, ललित, मीना, नवीन, ओजस, पूजा, रोहित और सना केंद्र से बाहर की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। मीना पूजा के दाएँ से दूसरे स्थान पर बैठी है। पूजा ओजस के बाएँ से तीसरे स्थान पर बैठी है। ललित ओजस के सामने बैठा है। किरण ललित के ठीक बाएँ बैठी है। रोहित नवीन के दाएँ से तीसरे स्थान पर बैठा है। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["किरण – पूजा","पूजा – मीना","ओजस – रोहित","सना – ललित"],"explanationHi":"अंतिम व्यवस्था: किरण से दक्षिणावर्त चलने पर: किरण, ललित, पूजा, नवीन, मीना, ओजस, रोहित, सना। किरण – पूजा, सना – ललित, पूजा – मीना में दूसरा व्यक्ति पहले के दाएँ से दूसरे स्थान पर बैठा है; ओजस – रोहित इस पैटर्न का पालन नहीं करता।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-125","question":"Study the information and answer the question. Seven persons J, K, L, M, N, O and P visit a trade fair in 7 different months of the same year (April, May, June, July, August, September, October), one person per month, in that order of months. N goes in some month after O. O goes neither first nor last. O goes in the month immediately before M. J goes neither first nor last. J goes exactly two months before P. J goes exactly three months before L. Question: In which month does J visit the fair?","options":["May","June","April","July"],"answer":3,"explanation":"Final arrangement: April: K, May: O, June: M, July: J, August: N, September: P, October: L. J goes in July.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति J, K, L, M, N, O और P एक ही वर्ष के 7 अलग-अलग महीनों (अप्रैल, मई, जून, जुलाई, अगस्त, सितंबर, अक्टूबर) में एक व्यापार मेले में जाते हैं, प्रत्येक महीने में एक व्यक्ति, महीनों के इसी क्रम में। N, O के बाद किसी महीने में जाता है। O न पहले जाता है न अंत में। O, M के ठीक पहले वाले महीने में जाता है। J न पहले जाता है न अंत में। J, P से ठीक दो महीने पहले जाता है। J, L से ठीक तीन महीने पहले जाता है। प्रश्न: J मेले में किस महीने में जाता है?","optionsHi":["मई","जून","अप्रैल","जुलाई"],"explanationHi":"अंतिम व्यवस्था: अप्रैल: K, मई: O, जून: M, जुलाई: J, अगस्त: N, सितंबर: P, अक्टूबर: L। J जुलाई में जाता है।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-126","question":"Study the information and answer the question. Seven persons J, K, L, M, N, O and P visit a trade fair in 7 different months of the same year (April, May, June, July, August, September, October), one person per month, in that order of months. N goes in some month after O. O goes neither first nor last. O goes in the month immediately before M. J goes neither first nor last. J goes exactly two months before P. J goes exactly three months before L. Question: How many persons visit the fair between O and L?","options":["2","3","4","5"],"answer":2,"explanation":"Final arrangement: April: K, May: O, June: M, July: J, August: N, September: P, October: L. Between O and L are M, J, N, P, i.e. 4.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति J, K, L, M, N, O और P एक ही वर्ष के 7 अलग-अलग महीनों (अप्रैल, मई, जून, जुलाई, अगस्त, सितंबर, अक्टूबर) में एक व्यापार मेले में जाते हैं, प्रत्येक महीने में एक व्यक्ति, महीनों के इसी क्रम में। N, O के बाद किसी महीने में जाता है। O न पहले जाता है न अंत में। O, M के ठीक पहले वाले महीने में जाता है। J न पहले जाता है न अंत में। J, P से ठीक दो महीने पहले जाता है। J, L से ठीक तीन महीने पहले जाता है। प्रश्न: O और L के बीच कितने व्यक्ति मेले में जाते हैं?","optionsHi":["2","3","4","5"],"explanationHi":"अंतिम व्यवस्था: अप्रैल: K, मई: O, जून: M, जुलाई: J, अगस्त: N, सितंबर: P, अक्टूबर: L। O और L के बीच M, J, N, P हैं, यानी 4।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-127","question":"Study the information and answer the question. Six persons Tanya, Uday, Varun, Wasim, Yamini and Zoya sit in a straight row facing north; each likes a different fruit (Apple, Banana, Guava, Mango, Orange and Papaya). The person who likes Papaya sits at an extreme end of the row. Zoya sits to the immediate left of Varun. Varun is not an immediate neighbour of Yamini. Uday sits fourth to the left of Yamini. Uday does not like Banana. As many persons sit to the left of Varun as to the right of the person who likes Apple. The person who likes Orange sits third to the right of Tanya. As many persons sit to the left of the person who likes Guava as to the right of Tanya. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["Yamini – Uday","Varun – Yamini","Tanya – Zoya","Uday – Varun"],"answer":0,"explanation":"Final arrangement: From left to right: Tanya (Papaya), Uday (Mango), Zoya (Apple), Varun (Orange), Wasim (Banana), Yamini (Guava). In Varun – Yamini, Uday – Varun, Tanya – Zoya, the second person sits second to the right of the first; Yamini – Uday does not follow this pattern.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति तान्या, उदय, वरुण, वसीम, यामिनी और ज़ोया उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं; प्रत्येक को अलग फल पसंद है (सेब, केला, अमरूद, आम, संतरा और पपीता)। पपीता पसंद करने वाला पंक्ति के एक छोर पर बैठा है। ज़ोया वरुण के ठीक बाएँ बैठी है। वरुण यामिनी का निकटतम पड़ोसी नहीं है। उदय यामिनी के बाएँ से चौथे स्थान पर बैठा है। उदय को केला पसंद नहीं है। वरुण के बाएँ उतने ही व्यक्ति बैठे हैं जितने सेब पसंद करने वाले के दाएँ बैठे हैं। संतरा पसंद करने वाला तान्या के दाएँ से तीसरे स्थान पर बैठा है। अमरूद पसंद करने वाले के बाएँ उतने ही व्यक्ति बैठे हैं जितने तान्या के दाएँ बैठे हैं। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["यामिनी – उदय","वरुण – यामिनी","तान्या – ज़ोया","उदय – वरुण"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: तान्या (पपीता), उदय (आम), ज़ोया (सेब), वरुण (संतरा), वसीम (केला), यामिनी (अमरूद)। वरुण – यामिनी, उदय – वरुण, तान्या – ज़ोया में दूसरा व्यक्ति पहले के दाएँ से दूसरे स्थान पर बैठा है; यामिनी – उदय इस पैटर्न का पालन नहीं करता।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-128","question":"Study the information and answer the question. Six persons Tanya, Uday, Varun, Wasim, Yamini and Zoya sit in a straight row facing north; each likes a different fruit (Apple, Banana, Guava, Mango, Orange and Papaya). The person who likes Papaya sits at an extreme end of the row. Zoya sits to the immediate left of Varun. Varun is not an immediate neighbour of Yamini. Uday sits fourth to the left of Yamini. Uday does not like Banana. As many persons sit to the left of Varun as to the right of the person who likes Apple. The person who likes Orange sits third to the right of Tanya. As many persons sit to the left of the person who likes Guava as to the right of Tanya. Question: How many persons sit between Wasim and Zoya?","options":["0","1","2","3"],"answer":1,"explanation":"Final arrangement: From left to right: Tanya (Papaya), Uday (Mango), Zoya (Apple), Varun (Orange), Wasim (Banana), Yamini (Guava). Between Wasim and Zoya is Varun, i.e. 1.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति तान्या, उदय, वरुण, वसीम, यामिनी और ज़ोया उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं; प्रत्येक को अलग फल पसंद है (सेब, केला, अमरूद, आम, संतरा और पपीता)। पपीता पसंद करने वाला पंक्ति के एक छोर पर बैठा है। ज़ोया वरुण के ठीक बाएँ बैठी है। वरुण यामिनी का निकटतम पड़ोसी नहीं है। उदय यामिनी के बाएँ से चौथे स्थान पर बैठा है। उदय को केला पसंद नहीं है। वरुण के बाएँ उतने ही व्यक्ति बैठे हैं जितने सेब पसंद करने वाले के दाएँ बैठे हैं। संतरा पसंद करने वाला तान्या के दाएँ से तीसरे स्थान पर बैठा है। अमरूद पसंद करने वाले के बाएँ उतने ही व्यक्ति बैठे हैं जितने तान्या के दाएँ बैठे हैं। प्रश्न: वसीम और ज़ोया के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["0","1","2","3"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: तान्या (पपीता), उदय (आम), ज़ोया (सेब), वरुण (संतरा), वसीम (केला), यामिनी (अमरूद)। वसीम और ज़ोया के बीच वरुण है, यानी 1।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-129","question":"Study the information and answer the question. Six persons Tanya, Uday, Varun, Wasim, Yamini and Zoya sit in a straight row facing north; each likes a different fruit (Apple, Banana, Guava, Mango, Orange and Papaya). The person who likes Papaya sits at an extreme end of the row. Zoya sits to the immediate left of Varun. Varun is not an immediate neighbour of Yamini. Uday sits fourth to the left of Yamini. Uday does not like Banana. As many persons sit to the left of Varun as to the right of the person who likes Apple. The person who likes Orange sits third to the right of Tanya. As many persons sit to the left of the person who likes Guava as to the right of Tanya. Question: Who sits to the immediate right of Wasim?","options":["Zoya","Varun","Uday","Yamini"],"answer":3,"explanation":"Final arrangement: From left to right: Tanya (Papaya), Uday (Mango), Zoya (Apple), Varun (Orange), Wasim (Banana), Yamini (Guava). Yamini sits to the immediate right of Wasim.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति तान्या, उदय, वरुण, वसीम, यामिनी और ज़ोया उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं; प्रत्येक को अलग फल पसंद है (सेब, केला, अमरूद, आम, संतरा और पपीता)। पपीता पसंद करने वाला पंक्ति के एक छोर पर बैठा है। ज़ोया वरुण के ठीक बाएँ बैठी है। वरुण यामिनी का निकटतम पड़ोसी नहीं है। उदय यामिनी के बाएँ से चौथे स्थान पर बैठा है। उदय को केला पसंद नहीं है। वरुण के बाएँ उतने ही व्यक्ति बैठे हैं जितने सेब पसंद करने वाले के दाएँ बैठे हैं। संतरा पसंद करने वाला तान्या के दाएँ से तीसरे स्थान पर बैठा है। अमरूद पसंद करने वाले के बाएँ उतने ही व्यक्ति बैठे हैं जितने तान्या के दाएँ बैठे हैं। प्रश्न: वसीम के ठीक दाएँ कौन बैठा है?","optionsHi":["ज़ोया","वरुण","उदय","यामिनी"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: तान्या (पपीता), उदय (आम), ज़ोया (सेब), वरुण (संतरा), वसीम (केला), यामिनी (अमरूद)। यामिनी वसीम के ठीक दाएँ बैठी है।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-130","question":"Study the information and answer the question. Six persons P, Q, R, S, T and U live on the 6 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 6; each is from a different city (Agra, Bhopal, Chennai, Delhi, Indore and Jaipur). T lives on floor 3. U lives somewhere above T. U lives somewhere below the person from Agra. As many persons live above the person from Agra as below S. Exactly three persons live between S and U. P lives immediately below the person from Jaipur. The person from Bhopal lives two floors below the person from Delhi. The person from Chennai lives two floors below R. Question: Who lives immediately above T?","options":["P","R","Q","U"],"answer":0,"explanation":"Final arrangement: From floor 6 down to 1: R (Agra), U (Jaipur), P (Chennai), T (Delhi), Q (Indore), S (Bhopal). P lives immediately above T.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति P, Q, R, S, T और U एक इमारत की 6 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 6 है; प्रत्येक अलग शहर का है (आगरा, भोपाल, चेन्नई, दिल्ली, इंदौर और जयपुर)। T मंज़िल 3 पर रहता है। U, T से कहीं ऊपर रहता है। U, आगरा के व्यक्ति से कहीं नीचे रहता है। आगरा के व्यक्ति के ऊपर उतने ही व्यक्ति रहते हैं जितने S के नीचे रहते हैं। S और U के बीच ठीक तीन व्यक्ति रहते हैं। P, जयपुर के व्यक्ति के ठीक नीचे रहता है। भोपाल का व्यक्ति दिल्ली के व्यक्ति से दो मंज़िल नीचे रहता है। चेन्नई का व्यक्ति R से दो मंज़िल नीचे रहता है। प्रश्न: T के ठीक ऊपर कौन रहता है?","optionsHi":["P","R","Q","U"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 6 से 1 तक: R (आगरा), U (जयपुर), P (चेन्नई), T (दिल्ली), Q (इंदौर), S (भोपाल)। P, T के ठीक ऊपर रहता है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-131","question":"Study the information and answer the question. Six persons P, Q, R, S, T and U live on the 6 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 6; each is from a different city (Agra, Bhopal, Chennai, Delhi, Indore and Jaipur). T lives on floor 3. U lives somewhere above T. U lives somewhere below the person from Agra. As many persons live above the person from Agra as below S. Exactly three persons live between S and U. P lives immediately below the person from Jaipur. The person from Bhopal lives two floors below the person from Delhi. The person from Chennai lives two floors below R. Question: How many persons live between S and P?","options":["1","2","3","4"],"answer":1,"explanation":"Final arrangement: From floor 6 down to 1: R (Agra), U (Jaipur), P (Chennai), T (Delhi), Q (Indore), S (Bhopal). Between S and P are Q, T, i.e. 2.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति P, Q, R, S, T और U एक इमारत की 6 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 6 है; प्रत्येक अलग शहर का है (आगरा, भोपाल, चेन्नई, दिल्ली, इंदौर और जयपुर)। T मंज़िल 3 पर रहता है। U, T से कहीं ऊपर रहता है। U, आगरा के व्यक्ति से कहीं नीचे रहता है। आगरा के व्यक्ति के ऊपर उतने ही व्यक्ति रहते हैं जितने S के नीचे रहते हैं। S और U के बीच ठीक तीन व्यक्ति रहते हैं। P, जयपुर के व्यक्ति के ठीक नीचे रहता है। भोपाल का व्यक्ति दिल्ली के व्यक्ति से दो मंज़िल नीचे रहता है। चेन्नई का व्यक्ति R से दो मंज़िल नीचे रहता है। प्रश्न: S और P के बीच कितने व्यक्ति रहते हैं?","optionsHi":["1","2","3","4"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 6 से 1 तक: R (आगरा), U (जयपुर), P (चेन्नई), T (दिल्ली), Q (इंदौर), S (भोपाल)। S और P के बीच Q, T हैं, यानी 2।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-132","question":"Study the information and answer the question. Six persons P, Q, R, S, T and U live on the 6 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 6; each is from a different city (Agra, Bhopal, Chennai, Delhi, Indore and Jaipur). T lives on floor 3. U lives somewhere above T. U lives somewhere below the person from Agra. As many persons live above the person from Agra as below S. Exactly three persons live between S and U. P lives immediately below the person from Jaipur. The person from Bhopal lives two floors below the person from Delhi. The person from Chennai lives two floors below R. Question: On which floor does P live?","options":["2","3","4","5"],"answer":2,"explanation":"Final arrangement: From floor 6 down to 1: R (Agra), U (Jaipur), P (Chennai), T (Delhi), Q (Indore), S (Bhopal). P lives on floor 4.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति P, Q, R, S, T और U एक इमारत की 6 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 6 है; प्रत्येक अलग शहर का है (आगरा, भोपाल, चेन्नई, दिल्ली, इंदौर और जयपुर)। T मंज़िल 3 पर रहता है। U, T से कहीं ऊपर रहता है। U, आगरा के व्यक्ति से कहीं नीचे रहता है। आगरा के व्यक्ति के ऊपर उतने ही व्यक्ति रहते हैं जितने S के नीचे रहते हैं। S और U के बीच ठीक तीन व्यक्ति रहते हैं। P, जयपुर के व्यक्ति के ठीक नीचे रहता है। भोपाल का व्यक्ति दिल्ली के व्यक्ति से दो मंज़िल नीचे रहता है। चेन्नई का व्यक्ति R से दो मंज़िल नीचे रहता है। प्रश्न: P किस मंज़िल पर रहता है?","optionsHi":["2","3","4","5"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 6 से 1 तक: R (आगरा), U (जयपुर), P (चेन्नई), T (दिल्ली), Q (इंदौर), S (भोपाल)। P मंज़िल 4 पर रहता है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-133","question":"Study the information and answer the question. Seven persons Aman, Bela, Chirag, Divya, Esha, Farhan and Gauri sit around a circular table, equally spaced and facing the centre. Farhan sits to the immediate left of Chirag. Divya sits third to the left of Chirag. Chirag sits to the immediate left of Esha. Bela sits second to the left of Aman. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["Aman – Chirag","Divya – Farhan","Chirag – Gauri","Esha – Aman"],"answer":3,"explanation":"Final arrangement: Going clockwise from Aman: Aman, Divya, Bela, Gauri, Esha, Chirag, Farhan. In Divya – Farhan, Aman – Chirag, Chirag – Gauri, the second person sits second to the right of the first; Esha – Aman does not follow this pattern.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति अमन, बेला, चिराग, दिव्या, ईशा, फ़रहान और गौरी केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। फ़रहान चिराग के ठीक बाएँ बैठा है। दिव्या चिराग के बाएँ से तीसरे स्थान पर बैठी है। चिराग ईशा के ठीक बाएँ बैठा है। बेला अमन के बाएँ से दूसरे स्थान पर बैठी है। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["अमन – चिराग","दिव्या – फ़रहान","चिराग – गौरी","ईशा – अमन"],"explanationHi":"अंतिम व्यवस्था: अमन से दक्षिणावर्त चलने पर: अमन, दिव्या, बेला, गौरी, ईशा, चिराग, फ़रहान। दिव्या – फ़रहान, अमन – चिराग, चिराग – गौरी में दूसरा व्यक्ति पहले के दाएँ से दूसरे स्थान पर बैठा है; ईशा – अमन इस पैटर्न का पालन नहीं करता।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-134","question":"Study the information and answer the question. Seven persons Aman, Bela, Chirag, Divya, Esha, Farhan and Gauri sit around a circular table, equally spaced and facing the centre. Farhan sits to the immediate left of Chirag. Divya sits third to the left of Chirag. Chirag sits to the immediate left of Esha. Bela sits second to the left of Aman. Question: How many persons sit between Esha and Divya, counted along the shorter side of the table?","options":["2","3","4","5"],"answer":0,"explanation":"Final arrangement: Going clockwise from Aman: Aman, Divya, Bela, Gauri, Esha, Chirag, Farhan. Between Esha and Divya are Gauri, Bela, i.e. 2.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति अमन, बेला, चिराग, दिव्या, ईशा, फ़रहान और गौरी केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। फ़रहान चिराग के ठीक बाएँ बैठा है। दिव्या चिराग के बाएँ से तीसरे स्थान पर बैठी है। चिराग ईशा के ठीक बाएँ बैठा है। बेला अमन के बाएँ से दूसरे स्थान पर बैठी है। प्रश्न: मेज़ की छोटी ओर से गिनने पर ईशा और दिव्या के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["2","3","4","5"],"explanationHi":"अंतिम व्यवस्था: अमन से दक्षिणावर्त चलने पर: अमन, दिव्या, बेला, गौरी, ईशा, चिराग, फ़रहान। ईशा और दिव्या के बीच गौरी, बेला हैं, यानी 2।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-135","question":"Study the information and answer the question. Six boxes A, B, C, D, E and F are kept one above another in a single stack; position 1 is at the bottom and position 6 at the top; each of a different colour (red, blue, green, white, black and yellow). The yellow box is kept at an odd-numbered position. B is yellow. The yellow box is kept immediately below the green box. Exactly one box is kept between the black box and the green box. F is kept five positions below the red box. The blue box is kept three positions below A. D is kept four positions below E. Question: Which box is kept two positions below C?","options":["A","B","D","E"],"answer":1,"explanation":"Final arrangement: From position 6 down to 1: E (red), C (white), A (green), B (yellow), D (black), F (blue). B is kept two positions below C.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह डिब्बे A, B, C, D, E और F एक ही ढेर में एक के ऊपर एक रखे गए हैं; स्थिति 1 सबसे नीचे और स्थिति 6 सबसे ऊपर है; प्रत्येक अलग रंग का है (लाल, नीला, हरा, सफेद, काला और पीला)। पीला डिब्बा विषम संख्या वाली स्थिति पर रखा है। B पीला है। पीला डिब्बा हरे डिब्बे के ठीक नीचे रखा है। काले डिब्बे और हरे डिब्बे के बीच ठीक एक डिब्बा रखा है। F लाल डिब्बे से पाँच स्थिति नीचे रखा है। नीला डिब्बा A से तीन स्थिति नीचे रखा है। D, E से चार स्थिति नीचे रखा है। प्रश्न: C से दो स्थिति नीचे कौन-सा डिब्बा रखा है?","optionsHi":["A","B","D","E"],"explanationHi":"अंतिम व्यवस्था: स्थिति 6 से 1 तक: E (लाल), C (सफेद), A (हरा), B (पीला), D (काला), F (नीला)। B, C से दो स्थिति नीचे रखा है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-136","question":"Study the information and answer the question. Six boxes A, B, C, D, E and F are kept one above another in a single stack; position 1 is at the bottom and position 6 at the top; each of a different colour (red, blue, green, white, black and yellow). The yellow box is kept at an odd-numbered position. B is yellow. The yellow box is kept immediately below the green box. Exactly one box is kept between the black box and the green box. F is kept five positions below the red box. The blue box is kept three positions below A. D is kept four positions below E. Question: Which box is black?","options":["A","C","D","B"],"answer":2,"explanation":"Final arrangement: From position 6 down to 1: E (red), C (white), A (green), B (yellow), D (black), F (blue). D is black.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह डिब्बे A, B, C, D, E और F एक ही ढेर में एक के ऊपर एक रखे गए हैं; स्थिति 1 सबसे नीचे और स्थिति 6 सबसे ऊपर है; प्रत्येक अलग रंग का है (लाल, नीला, हरा, सफेद, काला और पीला)। पीला डिब्बा विषम संख्या वाली स्थिति पर रखा है। B पीला है। पीला डिब्बा हरे डिब्बे के ठीक नीचे रखा है। काले डिब्बे और हरे डिब्बे के बीच ठीक एक डिब्बा रखा है। F लाल डिब्बे से पाँच स्थिति नीचे रखा है। नीला डिब्बा A से तीन स्थिति नीचे रखा है। D, E से चार स्थिति नीचे रखा है। प्रश्न: कौन-सा डिब्बा काला है?","optionsHi":["A","C","D","B"],"explanationHi":"अंतिम व्यवस्था: स्थिति 6 से 1 तक: E (लाल), C (सफेद), A (हरा), B (पीला), D (काला), F (नीला)। D काला है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-137","question":"Study the information and answer the question. Six boxes A, B, C, D, E and F are kept one above another in a single stack; position 1 is at the bottom and position 6 at the top; each of a different colour (red, blue, green, white, black and yellow). The yellow box is kept at an odd-numbered position. B is yellow. The yellow box is kept immediately below the green box. Exactly one box is kept between the black box and the green box. F is kept five positions below the red box. The blue box is kept three positions below A. D is kept four positions below E. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["D – B","F – D","B – A","A – E"],"answer":3,"explanation":"Final arrangement: From position 6 down to 1: E (red), C (white), A (green), B (yellow), D (black), F (blue). In F – D, D – B, B – A, the second box is kept immediately above the first; A – E does not follow this pattern.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह डिब्बे A, B, C, D, E और F एक ही ढेर में एक के ऊपर एक रखे गए हैं; स्थिति 1 सबसे नीचे और स्थिति 6 सबसे ऊपर है; प्रत्येक अलग रंग का है (लाल, नीला, हरा, सफेद, काला और पीला)। पीला डिब्बा विषम संख्या वाली स्थिति पर रखा है। B पीला है। पीला डिब्बा हरे डिब्बे के ठीक नीचे रखा है। काले डिब्बे और हरे डिब्बे के बीच ठीक एक डिब्बा रखा है। F लाल डिब्बे से पाँच स्थिति नीचे रखा है। नीला डिब्बा A से तीन स्थिति नीचे रखा है। D, E से चार स्थिति नीचे रखा है। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["D – B","F – D","B – A","A – E"],"explanationHi":"अंतिम व्यवस्था: स्थिति 6 से 1 तक: E (लाल), C (सफेद), A (हरा), B (पीला), D (काला), F (नीला)। F – D, D – B, B – A में दूसरा डिब्बा पहले के ठीक ऊपर रखा है; A – E इस पैटर्न का पालन नहीं करता।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-138","question":"Study the information and answer the question. Six persons Kiran, Lalit, Meena, Naveen, Ojas and Pooja visit a trade fair in 6 different months of the same year (July, August, September, October, November, December), one person per month, in that order of months; each plays a different game (Cricket, Hockey, Tennis, Chess, Kabaddi and Football). Pooja goes in a month that has 30 days. Meena goes in September. The person who plays Cricket goes in some month after the person who plays Hockey. Exactly one person goes between the person who plays Hockey and Kiran. Kiran goes exactly four months before the person who plays Kabaddi. Exactly two persons go between the person who plays Hockey and the person who plays Chess. Kiran goes in the month immediately before the person who plays Tennis. Naveen goes neither first nor last. Exactly three persons go between Naveen and Ojas. Question: How many persons visit the fair between Lalit and Kiran?","options":["1","2","3","4"],"answer":1,"explanation":"Final arrangement: July: Kiran (Football), August: Naveen (Tennis), September: Meena (Hockey), October: Lalit (Cricket), November: Pooja (Kabaddi), December: Ojas (Chess). Between Lalit and Kiran are Naveen, Meena, i.e. 2.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति किरण, ललित, मीना, नवीन, ओजस और पूजा एक ही वर्ष के 6 अलग-अलग महीनों (जुलाई, अगस्त, सितंबर, अक्टूबर, नवंबर, दिसंबर) में एक व्यापार मेले में जाते हैं, प्रत्येक महीने में एक व्यक्ति, महीनों के इसी क्रम में; प्रत्येक अलग खेल खेलता है (क्रिकेट, हॉकी, टेनिस, शतरंज, कबड्डी और फुटबॉल)। पूजा उस महीने में जाती है जिसमें 30 दिन होते हैं। मीना सितंबर में जाती है। क्रिकेट खेलने वाला हॉकी खेलने वाले के बाद किसी महीने में जाता है। हॉकी खेलने वाले और किरण के बीच ठीक एक व्यक्ति जाता है। किरण कबड्डी खेलने वाले से ठीक चार महीने पहले जाता है। हॉकी खेलने वाले और शतरंज खेलने वाले के बीच ठीक दो व्यक्ति जाते हैं। किरण टेनिस खेलने वाले के ठीक पहले वाले महीने में जाता है। नवीन न पहले जाता है न अंत में। नवीन और ओजस के बीच ठीक तीन व्यक्ति जाते हैं। प्रश्न: ललित और किरण के बीच कितने व्यक्ति मेले में जाते हैं?","optionsHi":["1","2","3","4"],"explanationHi":"अंतिम व्यवस्था: जुलाई: किरण (फुटबॉल), अगस्त: नवीन (टेनिस), सितंबर: मीना (हॉकी), अक्टूबर: ललित (क्रिकेट), नवंबर: पूजा (कबड्डी), दिसंबर: ओजस (शतरंज)। ललित और किरण के बीच नवीन, मीना हैं, यानी 2।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-139","question":"Study the information and answer the question. Six persons Kiran, Lalit, Meena, Naveen, Ojas and Pooja visit a trade fair in 6 different months of the same year (July, August, September, October, November, December), one person per month, in that order of months; each plays a different game (Cricket, Hockey, Tennis, Chess, Kabaddi and Football). Pooja goes in a month that has 30 days. Meena goes in September. The person who plays Cricket goes in some month after the person who plays Hockey. Exactly one person goes between the person who plays Hockey and Kiran. Kiran goes exactly four months before the person who plays Kabaddi. Exactly two persons go between the person who plays Hockey and the person who plays Chess. Kiran goes in the month immediately before the person who plays Tennis. Naveen goes neither first nor last. Exactly three persons go between Naveen and Ojas. Question: Who goes two months after Naveen?","options":["Lalit","Ojas","Meena","Pooja"],"answer":0,"explanation":"Final arrangement: July: Kiran (Football), August: Naveen (Tennis), September: Meena (Hockey), October: Lalit (Cricket), November: Pooja (Kabaddi), December: Ojas (Chess). Lalit goes two months after Naveen.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति किरण, ललित, मीना, नवीन, ओजस और पूजा एक ही वर्ष के 6 अलग-अलग महीनों (जुलाई, अगस्त, सितंबर, अक्टूबर, नवंबर, दिसंबर) में एक व्यापार मेले में जाते हैं, प्रत्येक महीने में एक व्यक्ति, महीनों के इसी क्रम में; प्रत्येक अलग खेल खेलता है (क्रिकेट, हॉकी, टेनिस, शतरंज, कबड्डी और फुटबॉल)। पूजा उस महीने में जाती है जिसमें 30 दिन होते हैं। मीना सितंबर में जाती है। क्रिकेट खेलने वाला हॉकी खेलने वाले के बाद किसी महीने में जाता है। हॉकी खेलने वाले और किरण के बीच ठीक एक व्यक्ति जाता है। किरण कबड्डी खेलने वाले से ठीक चार महीने पहले जाता है। हॉकी खेलने वाले और शतरंज खेलने वाले के बीच ठीक दो व्यक्ति जाते हैं। किरण टेनिस खेलने वाले के ठीक पहले वाले महीने में जाता है। नवीन न पहले जाता है न अंत में। नवीन और ओजस के बीच ठीक तीन व्यक्ति जाते हैं। प्रश्न: नवीन से दो महीने बाद कौन जाता है?","optionsHi":["ललित","ओजस","मीना","पूजा"],"explanationHi":"अंतिम व्यवस्था: जुलाई: किरण (फुटबॉल), अगस्त: नवीन (टेनिस), सितंबर: मीना (हॉकी), अक्टूबर: ललित (क्रिकेट), नवंबर: पूजा (कबड्डी), दिसंबर: ओजस (शतरंज)। ललित नवीन से दो महीने बाद जाता है।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-140","question":"Study the information and answer the question. Six persons J, K, L, M, N and O sit around a circular table, equally spaced and facing the centre; each has a different profession (doctor, engineer, lawyer, pilot, teacher and banker). J sits to the immediate left of the doctor. The banker is not an immediate neighbour of the engineer. The engineer sits to the immediate right of the lawyer. The engineer sits second to the left of M. The banker sits to the immediate right of O. M is a teacher. K sits second to the left of L. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["O – K","L – O","K – J","J – M"],"answer":2,"explanation":"Final arrangement: Going clockwise from J: J (engineer), K (lawyer), N (banker), O (pilot), M (teacher), L (doctor). In O – K, J – M, L – O, the second person sits second to the right of the first; K – J does not follow this pattern.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति J, K, L, M, N और O केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; प्रत्येक का पेशा अलग है (डॉक्टर, इंजीनियर, वकील, पायलट, शिक्षक और बैंकर)। J डॉक्टर के ठीक बाएँ बैठा है। बैंकर इंजीनियर का निकटतम पड़ोसी नहीं है। इंजीनियर वकील के ठीक दाएँ बैठा है। इंजीनियर M के बाएँ से दूसरे स्थान पर बैठा है। बैंकर O के ठीक दाएँ बैठा है। M शिक्षक है। K, L के बाएँ से दूसरे स्थान पर बैठा है। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["O – K","L – O","K – J","J – M"],"explanationHi":"अंतिम व्यवस्था: J से दक्षिणावर्त चलने पर: J (इंजीनियर), K (वकील), N (बैंकर), O (पायलट), M (शिक्षक), L (डॉक्टर)। O – K, J – M, L – O में दूसरा व्यक्ति पहले के दाएँ से दूसरे स्थान पर बैठा है; K – J इस पैटर्न का पालन नहीं करता।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-141","question":"Study the information and answer the question. Six persons J, K, L, M, N and O sit around a circular table, equally spaced and facing the centre; each has a different profession (doctor, engineer, lawyer, pilot, teacher and banker). J sits to the immediate left of the doctor. The banker is not an immediate neighbour of the engineer. The engineer sits to the immediate right of the lawyer. The engineer sits second to the left of M. The banker sits to the immediate right of O. M is a teacher. K sits second to the left of L. Question: How many persons sit between J and O, counted along the shorter side of the table?","options":["1","2","3","4"],"answer":1,"explanation":"Final arrangement: Going clockwise from J: J (engineer), K (lawyer), N (banker), O (pilot), M (teacher), L (doctor). Between J and O are K, N, i.e. 2.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति J, K, L, M, N और O केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; प्रत्येक का पेशा अलग है (डॉक्टर, इंजीनियर, वकील, पायलट, शिक्षक और बैंकर)। J डॉक्टर के ठीक बाएँ बैठा है। बैंकर इंजीनियर का निकटतम पड़ोसी नहीं है। इंजीनियर वकील के ठीक दाएँ बैठा है। इंजीनियर M के बाएँ से दूसरे स्थान पर बैठा है। बैंकर O के ठीक दाएँ बैठा है। M शिक्षक है। K, L के बाएँ से दूसरे स्थान पर बैठा है। प्रश्न: मेज़ की छोटी ओर से गिनने पर J और O के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["1","2","3","4"],"explanationHi":"अंतिम व्यवस्था: J से दक्षिणावर्त चलने पर: J (इंजीनियर), K (वकील), N (बैंकर), O (पायलट), M (शिक्षक), L (डॉक्टर)। J और O के बीच K, N हैं, यानी 2।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-142","question":"Study the information and answer the question. Six persons J, K, L, M, N and O sit around a circular table, equally spaced and facing the centre; each has a different profession (doctor, engineer, lawyer, pilot, teacher and banker). J sits to the immediate left of the doctor. The banker is not an immediate neighbour of the engineer. The engineer sits to the immediate right of the lawyer. The engineer sits second to the left of M. The banker sits to the immediate right of O. M is a teacher. K sits second to the left of L. Question: Who sits third to the left of O?","options":["L","K","M","J"],"answer":3,"explanation":"Final arrangement: Going clockwise from J: J (engineer), K (lawyer), N (banker), O (pilot), M (teacher), L (doctor). J sits third to the left of O.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति J, K, L, M, N और O केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; प्रत्येक का पेशा अलग है (डॉक्टर, इंजीनियर, वकील, पायलट, शिक्षक और बैंकर)। J डॉक्टर के ठीक बाएँ बैठा है। बैंकर इंजीनियर का निकटतम पड़ोसी नहीं है। इंजीनियर वकील के ठीक दाएँ बैठा है। इंजीनियर M के बाएँ से दूसरे स्थान पर बैठा है। बैंकर O के ठीक दाएँ बैठा है। M शिक्षक है। K, L के बाएँ से दूसरे स्थान पर बैठा है। प्रश्न: O के बाएँ से तीसरे स्थान पर कौन बैठा है?","optionsHi":["L","K","M","J"],"explanationHi":"अंतिम व्यवस्था: J से दक्षिणावर्त चलने पर: J (इंजीनियर), K (वकील), N (बैंकर), O (पायलट), M (शिक्षक), L (डॉक्टर)। J, O के बाएँ से तीसरे स्थान पर बैठा है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-143","question":"Study the information and answer the question. Six persons A, B, C, D, E and F sit in a row of 6 seats numbered 1 to 6 from west to east; some of them face north and the others face south. A faces south. Exactly one person sits between B and A. B and D face the same direction. A sits to the immediate right of E. E sits to the immediate left of A. A sits to the immediate right of F. E sits fourth to the right of D. B sits second to the right of C. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["E – C","A – B","C – B","D – F"],"answer":0,"explanation":"Final arrangement: Seats 1 to 6 (west to east): C [N], D [N], B [N], F [N], A [S], E [S] (N = faces north, S = faces south). In C – B, D – F, A – B, the second person sits second to the right of the first; E – C does not follow this pattern.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति A, B, C, D, E और F 6 सीटों की एक पंक्ति में बैठे हैं, जो पश्चिम से पूर्व की ओर 1 से 6 तक क्रमांकित हैं; उनमें से कुछ का मुख उत्तर की ओर और बाकी का दक्षिण की ओर है। A का मुख दक्षिण की ओर है। B और A के बीच ठीक एक व्यक्ति बैठा है। B और D का मुख एक ही दिशा में है। A, E के ठीक दाएँ बैठा है। E, A के ठीक बाएँ बैठा है। A, F के ठीक दाएँ बैठा है। E, D के दाएँ से चौथे स्थान पर बैठा है। B, C के दाएँ से दूसरे स्थान पर बैठा है। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["E – C","A – B","C – B","D – F"],"explanationHi":"अंतिम व्यवस्था: सीट 1 से 6 (पश्चिम से पूर्व): C [N], D [N], B [N], F [N], A [S], E [S] (N = उत्तर की ओर मुख, S = दक्षिण की ओर मुख)। C – B, D – F, A – B में दूसरा व्यक्ति पहले के दाएँ से दूसरे स्थान पर बैठा है; E – C इस पैटर्न का पालन नहीं करता।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-144","question":"Study the information and answer the question. Six persons A, B, C, D, E and F sit in a row of 6 seats numbered 1 to 6 from west to east; some of them face north and the others face south. A faces south. Exactly one person sits between B and A. B and D face the same direction. A sits to the immediate right of E. E sits to the immediate left of A. A sits to the immediate right of F. E sits fourth to the right of D. B sits second to the right of C. Question: How many persons sit between D and F?","options":["1","2","3","4"],"answer":0,"explanation":"Final arrangement: Seats 1 to 6 (west to east): C [N], D [N], B [N], F [N], A [S], E [S]. D is in seat 2 and F in seat 4, so only B sits between them, i.e. 1.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति A, B, C, D, E और F 6 सीटों की एक पंक्ति में बैठे हैं, जो पश्चिम से पूर्व की ओर 1 से 6 तक क्रमांकित हैं; उनमें से कुछ का मुख उत्तर की ओर और बाकी का दक्षिण की ओर है। A का मुख दक्षिण की ओर है। B और A के बीच ठीक एक व्यक्ति बैठा है। B और D का मुख एक ही दिशा में है। A, E के ठीक दाएँ बैठा है। E, A के ठीक बाएँ बैठा है। A, F के ठीक दाएँ बैठा है। E, D के दाएँ से चौथे स्थान पर बैठा है। B, C के दाएँ से दूसरे स्थान पर बैठा है। प्रश्न: D और F के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["1","2","3","4"],"explanationHi":"अंतिम व्यवस्था: सीट 1 से 6 (पश्चिम से पूर्व): C [N], D [N], B [N], F [N], A [S], E [S]। D सीट 2 पर और F सीट 4 पर है, इसलिए उनके बीच केवल B बैठा है, यानी 1।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-145","question":"Study the information and answer the question. Six persons A, B, C, D, E and F sit in a row of 6 seats numbered 1 to 6 from west to east; some of them face north and the others face south. A faces south. Exactly one person sits between B and A. B and D face the same direction. A sits to the immediate right of E. E sits to the immediate left of A. A sits to the immediate right of F. E sits fourth to the right of D. B sits second to the right of C. Question: Who sits third to the right of B?","options":["A","D","C","E"],"answer":3,"explanation":"Final arrangement: Seats 1 to 6 (west to east): C [N], D [N], B [N], F [N], A [S], E [S] (N = faces north, S = faces south). E sits third to the right of B (B faces north).","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति A, B, C, D, E और F 6 सीटों की एक पंक्ति में बैठे हैं, जो पश्चिम से पूर्व की ओर 1 से 6 तक क्रमांकित हैं; उनमें से कुछ का मुख उत्तर की ओर और बाकी का दक्षिण की ओर है। A का मुख दक्षिण की ओर है। B और A के बीच ठीक एक व्यक्ति बैठा है। B और D का मुख एक ही दिशा में है। A, E के ठीक दाएँ बैठा है। E, A के ठीक बाएँ बैठा है। A, F के ठीक दाएँ बैठा है। E, D के दाएँ से चौथे स्थान पर बैठा है। B, C के दाएँ से दूसरे स्थान पर बैठा है। प्रश्न: B के दाएँ से तीसरे स्थान पर कौन बैठा है?","optionsHi":["A","D","C","E"],"explanationHi":"अंतिम व्यवस्था: सीट 1 से 6 (पश्चिम से पूर्व): C [N], D [N], B [N], F [N], A [S], E [S] (N = उत्तर की ओर मुख, S = दक्षिण की ओर मुख)। E, B के दाएँ से तीसरे स्थान पर बैठा है (B का मुख उत्तर की ओर है)।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-146","question":"Study the information and answer the question. Eight persons P, Q, R, S, T, U, V and W sit around a circular table, equally spaced; some face the centre and the others face outside. Both the immediate neighbours of T face outside. T faces the centre. T sits to the immediate right of V. V sits second to the left of R. W sits second to the right of V. P is not an immediate neighbour of W. P sits second to the right of U. W sits second to the right of S. Both the immediate neighbours of S face the centre. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["T – V","R – S","Q – T","U – P"],"answer":0,"explanation":"Final arrangement: Going clockwise from P: P [in], R [in], U [in], V [out], T [in], W [out], Q [in], S [in] (in = faces the centre, out = faces outside). In Q – T, R – S, U – P, the second person sits second to the right of the first; T – V does not follow this pattern.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति P, Q, R, S, T, U, V और W एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; कुछ का मुख केंद्र की ओर और बाकी का बाहर की ओर है। T के दोनों निकटतम पड़ोसियों का मुख बाहर की ओर है। T का मुख केंद्र की ओर है। T, V के ठीक दाएँ बैठा है। V, R के बाएँ से दूसरे स्थान पर बैठा है। W, V के दाएँ से दूसरे स्थान पर बैठा है। P, W का निकटतम पड़ोसी नहीं है। P, U के दाएँ से दूसरे स्थान पर बैठा है। W, S के दाएँ से दूसरे स्थान पर बैठा है। S के दोनों निकटतम पड़ोसियों का मुख केंद्र की ओर है। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["T – V","R – S","Q – T","U – P"],"explanationHi":"अंतिम व्यवस्था: P से दक्षिणावर्त चलने पर: P [अंदर], R [अंदर], U [अंदर], V [बाहर], T [अंदर], W [बाहर], Q [अंदर], S [अंदर] (अंदर = केंद्र की ओर मुख, बाहर = बाहर की ओर मुख)। Q – T, R – S, U – P में दूसरा व्यक्ति पहले के दाएँ से दूसरे स्थान पर बैठा है; T – V इस पैटर्न का पालन नहीं करता।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-147","question":"Study the information and answer the question. Eight persons P, Q, R, S, T, U, V and W sit around a circular table, equally spaced; some face the centre and the others face outside. Both the immediate neighbours of T face outside. T faces the centre. T sits to the immediate right of V. V sits second to the left of R. W sits second to the right of V. P is not an immediate neighbour of W. P sits second to the right of U. W sits second to the right of S. Both the immediate neighbours of S face the centre. Question: How many persons sit between P and T, counted along the shorter side of the table?","options":["2","3","4","5"],"answer":1,"explanation":"Final arrangement: Going clockwise from P: P [in], R [in], U [in], V [out], T [in], W [out], Q [in], S [in] (in = faces the centre, out = faces outside). Between P and T are R, U, V, i.e. 3.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति P, Q, R, S, T, U, V और W एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; कुछ का मुख केंद्र की ओर और बाकी का बाहर की ओर है। T के दोनों निकटतम पड़ोसियों का मुख बाहर की ओर है। T का मुख केंद्र की ओर है। T, V के ठीक दाएँ बैठा है। V, R के बाएँ से दूसरे स्थान पर बैठा है। W, V के दाएँ से दूसरे स्थान पर बैठा है। P, W का निकटतम पड़ोसी नहीं है। P, U के दाएँ से दूसरे स्थान पर बैठा है। W, S के दाएँ से दूसरे स्थान पर बैठा है। S के दोनों निकटतम पड़ोसियों का मुख केंद्र की ओर है। प्रश्न: मेज़ की छोटी ओर से गिनने पर P और T के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["2","3","4","5"],"explanationHi":"अंतिम व्यवस्था: P से दक्षिणावर्त चलने पर: P [अंदर], R [अंदर], U [अंदर], V [बाहर], T [अंदर], W [बाहर], Q [अंदर], S [अंदर] (अंदर = केंद्र की ओर मुख, बाहर = बाहर की ओर मुख)। P और T के बीच R, U, V हैं, यानी 3।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-148","question":"Study the information and answer the question. Eight persons P, Q, R, S, T, U, V and W sit around a circular table, equally spaced; some face the centre and the others face outside. Both the immediate neighbours of T face outside. T faces the centre. T sits to the immediate right of V. V sits second to the left of R. W sits second to the right of V. P is not an immediate neighbour of W. P sits second to the right of U. W sits second to the right of S. Both the immediate neighbours of S face the centre. Question: Who sits opposite V?","options":["U","W","S","T"],"answer":2,"explanation":"Final arrangement: Going clockwise from P: P [in], R [in], U [in], V [out], T [in], W [out], Q [in], S [in] (in = faces the centre, out = faces outside). S is directly opposite V.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति P, Q, R, S, T, U, V और W एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; कुछ का मुख केंद्र की ओर और बाकी का बाहर की ओर है। T के दोनों निकटतम पड़ोसियों का मुख बाहर की ओर है। T का मुख केंद्र की ओर है। T, V के ठीक दाएँ बैठा है। V, R के बाएँ से दूसरे स्थान पर बैठा है। W, V के दाएँ से दूसरे स्थान पर बैठा है। P, W का निकटतम पड़ोसी नहीं है। P, U के दाएँ से दूसरे स्थान पर बैठा है। W, S के दाएँ से दूसरे स्थान पर बैठा है। S के दोनों निकटतम पड़ोसियों का मुख केंद्र की ओर है। प्रश्न: V के सामने कौन बैठा है?","optionsHi":["U","W","S","T"],"explanationHi":"अंतिम व्यवस्था: P से दक्षिणावर्त चलने पर: P [अंदर], R [अंदर], U [अंदर], V [बाहर], T [अंदर], W [बाहर], Q [अंदर], S [अंदर] (अंदर = केंद्र की ओर मुख, बाहर = बाहर की ओर मुख)। S ठीक V के सामने है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-149","question":"Study the information and answer the question. Six persons Aman, Bela, Chirag, Divya, Esha and Farhan sit in a straight row facing north; each likes a different colour (Red, Blue, Green, White, Black and Yellow). The person who likes Yellow sits at an extreme end of the row. Only two persons sit between the person who likes Yellow and the person who likes Red. The person who likes Yellow is not an immediate neighbour of Esha. Farhan likes Yellow. Farhan sits to the immediate left of the person who likes Green. The person who likes Green sits third to the left of the person who likes Black. Divya sits at an extreme end of the row. Divya sits to the immediate right of Aman. Only one person sits between the person who likes White and Bela. Question: The person who likes Red is:","options":["Chirag","Divya","Aman","Bela"],"answer":3,"explanation":"Final arrangement: From left to right: Farhan (Yellow), Chirag (Green), Esha (Blue), Bela (Red), Aman (Black), Divya (White). Bela likes Red.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति अमन, बेला, चिराग, दिव्या, ईशा और फ़रहान उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं; प्रत्येक को अलग रंग पसंद है (लाल, नीला, हरा, सफेद, काला और पीला)। पीला रंग पसंद करने वाला पंक्ति के एक छोर पर बैठा है। पीला रंग पसंद करने वाले और लाल रंग पसंद करने वाले के बीच केवल दो व्यक्ति बैठे हैं। पीला रंग पसंद करने वाला ईशा का निकटतम पड़ोसी नहीं है। फ़रहान को पीला रंग पसंद है। फ़रहान हरा रंग पसंद करने वाले के ठीक बाएँ बैठा है। हरा रंग पसंद करने वाला काला रंग पसंद करने वाले के बाएँ से तीसरे स्थान पर बैठा है। दिव्या पंक्ति के एक छोर पर बैठी है। दिव्या अमन के ठीक दाएँ बैठी है। सफेद रंग पसंद करने वाले और बेला के बीच केवल एक व्यक्ति बैठा है। प्रश्न: लाल रंग किसे पसंद है?","optionsHi":["चिराग","दिव्या","अमन","बेला"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: फ़रहान (पीला), चिराग (हरा), ईशा (नीला), बेला (लाल), अमन (काला), दिव्या (सफेद)। बेला को लाल रंग पसंद है।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-150","question":"Study the information and answer the question. Six persons Aman, Bela, Chirag, Divya, Esha and Farhan sit in a straight row facing north; each likes a different colour (Red, Blue, Green, White, Black and Yellow). The person who likes Yellow sits at an extreme end of the row. Only two persons sit between the person who likes Yellow and the person who likes Red. The person who likes Yellow is not an immediate neighbour of Esha. Farhan likes Yellow. Farhan sits to the immediate left of the person who likes Green. The person who likes Green sits third to the left of the person who likes Black. Divya sits at an extreme end of the row. Divya sits to the immediate right of Aman. Only one person sits between the person who likes White and Bela. Question: Who sits to the immediate left of Aman?","options":["Bela","Divya","Chirag","Esha"],"answer":0,"explanation":"Final arrangement: From left to right: Farhan (Yellow), Chirag (Green), Esha (Blue), Bela (Red), Aman (Black), Divya (White). Bela sits to the immediate left of Aman.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति अमन, बेला, चिराग, दिव्या, ईशा और फ़रहान उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं; प्रत्येक को अलग रंग पसंद है (लाल, नीला, हरा, सफेद, काला और पीला)। पीला रंग पसंद करने वाला पंक्ति के एक छोर पर बैठा है। पीला रंग पसंद करने वाले और लाल रंग पसंद करने वाले के बीच केवल दो व्यक्ति बैठे हैं। पीला रंग पसंद करने वाला ईशा का निकटतम पड़ोसी नहीं है। फ़रहान को पीला रंग पसंद है। फ़रहान हरा रंग पसंद करने वाले के ठीक बाएँ बैठा है। हरा रंग पसंद करने वाला काला रंग पसंद करने वाले के बाएँ से तीसरे स्थान पर बैठा है। दिव्या पंक्ति के एक छोर पर बैठी है। दिव्या अमन के ठीक दाएँ बैठी है। सफेद रंग पसंद करने वाले और बेला के बीच केवल एक व्यक्ति बैठा है। प्रश्न: अमन के ठीक बाएँ कौन बैठा है?","optionsHi":["बेला","दिव्या","चिराग","ईशा"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: फ़रहान (पीला), चिराग (हरा), ईशा (नीला), बेला (लाल), अमन (काला), दिव्या (सफेद)। बेला अमन के ठीक बाएँ बैठी है।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-151","question":"Study the information and answer the question. Six persons Aman, Bela, Chirag, Divya, Esha and Farhan sit in a straight row facing north; each likes a different colour (Red, Blue, Green, White, Black and Yellow). The person who likes Yellow sits at an extreme end of the row. Only two persons sit between the person who likes Yellow and the person who likes Red. The person who likes Yellow is not an immediate neighbour of Esha. Farhan likes Yellow. Farhan sits to the immediate left of the person who likes Green. The person who likes Green sits third to the left of the person who likes Black. Divya sits at an extreme end of the row. Divya sits to the immediate right of Aman. Only one person sits between the person who likes White and Bela. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["Bela – Divya","Aman – Chirag","Chirag – Bela","Esha – Aman"],"answer":1,"explanation":"Final arrangement: From left to right: Farhan (Yellow), Chirag (Green), Esha (Blue), Bela (Red), Aman (Black), Divya (White). In Chirag – Bela, Esha – Aman, Bela – Divya, the second person sits second to the right of the first; Aman – Chirag does not follow this pattern.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति अमन, बेला, चिराग, दिव्या, ईशा और फ़रहान उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं; प्रत्येक को अलग रंग पसंद है (लाल, नीला, हरा, सफेद, काला और पीला)। पीला रंग पसंद करने वाला पंक्ति के एक छोर पर बैठा है। पीला रंग पसंद करने वाले और लाल रंग पसंद करने वाले के बीच केवल दो व्यक्ति बैठे हैं। पीला रंग पसंद करने वाला ईशा का निकटतम पड़ोसी नहीं है। फ़रहान को पीला रंग पसंद है। फ़रहान हरा रंग पसंद करने वाले के ठीक बाएँ बैठा है। हरा रंग पसंद करने वाला काला रंग पसंद करने वाले के बाएँ से तीसरे स्थान पर बैठा है। दिव्या पंक्ति के एक छोर पर बैठी है। दिव्या अमन के ठीक दाएँ बैठी है। सफेद रंग पसंद करने वाले और बेला के बीच केवल एक व्यक्ति बैठा है। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["बेला – दिव्या","अमन – चिराग","चिराग – बेला","ईशा – अमन"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: फ़रहान (पीला), चिराग (हरा), ईशा (नीला), बेला (लाल), अमन (काला), दिव्या (सफेद)। चिराग – बेला, ईशा – अमन, बेला – दिव्या में दूसरा व्यक्ति पहले के दाएँ से दूसरे स्थान पर बैठा है; अमन – चिराग इस पैटर्न का पालन नहीं करता।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-152","question":"Study the information and answer the question. Six persons Kiran, Lalit, Meena, Naveen, Ojas and Pooja live on the 6 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 6; each likes a different fruit (Apple, Banana, Guava, Mango, Orange and Papaya). The person who likes Apple lives somewhere above the person who likes Guava. Pooja lives four floors below the person who likes Guava. Naveen lives three floors above the person who likes Banana. Only four persons live between the person who likes Papaya and Meena. Ojas lives two floors above the person who likes Papaya. As many persons live above Lalit as below the person who likes Mango. Question: How many persons live between Lalit and Kiran?","options":["1","2","3","4"],"answer":0,"explanation":"Final arrangement: From floor 6 down to 1: Meena (Apple), Naveen (Guava), Lalit (Orange), Ojas (Mango), Kiran (Banana), Pooja (Papaya). Between Lalit and Kiran is Ojas, i.e. 1.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति किरण, ललित, मीना, नवीन, ओजस और पूजा एक इमारत की 6 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 6 है; प्रत्येक को अलग फल पसंद है (सेब, केला, अमरूद, आम, संतरा और पपीता)। सेब पसंद करने वाला अमरूद पसंद करने वाले से कहीं ऊपर रहता है। पूजा अमरूद पसंद करने वाले से चार मंज़िल नीचे रहती है। नवीन केला पसंद करने वाले से तीन मंज़िल ऊपर रहता है। पपीता पसंद करने वाले और मीना के बीच केवल चार व्यक्ति रहते हैं। ओजस पपीता पसंद करने वाले से दो मंज़िल ऊपर रहता है। ललित के ऊपर उतने ही व्यक्ति रहते हैं जितने आम पसंद करने वाले के नीचे रहते हैं। प्रश्न: ललित और किरण के बीच कितने व्यक्ति रहते हैं?","optionsHi":["1","2","3","4"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 6 से 1 तक: मीना (सेब), नवीन (अमरूद), ललित (संतरा), ओजस (आम), किरण (केला), पूजा (पपीता)। ललित और किरण के बीच ओजस है, यानी 1।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-153","question":"Study the information and answer the question. Six persons Kiran, Lalit, Meena, Naveen, Ojas and Pooja live on the 6 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 6; each likes a different fruit (Apple, Banana, Guava, Mango, Orange and Papaya). The person who likes Apple lives somewhere above the person who likes Guava. Pooja lives four floors below the person who likes Guava. Naveen lives three floors above the person who likes Banana. Only four persons live between the person who likes Papaya and Meena. Ojas lives two floors above the person who likes Papaya. As many persons live above Lalit as below the person who likes Mango. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["Pooja – Kiran","Lalit – Naveen","Meena – Pooja","Naveen – Meena"],"answer":2,"explanation":"Final arrangement: From floor 6 down to 1: Meena (Apple), Naveen (Guava), Lalit (Orange), Ojas (Mango), Kiran (Banana), Pooja (Papaya). In Pooja – Kiran, Lalit – Naveen, Naveen – Meena, the second person lives immediately above the first; Meena – Pooja does not follow this pattern.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति किरण, ललित, मीना, नवीन, ओजस और पूजा एक इमारत की 6 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 6 है; प्रत्येक को अलग फल पसंद है (सेब, केला, अमरूद, आम, संतरा और पपीता)। सेब पसंद करने वाला अमरूद पसंद करने वाले से कहीं ऊपर रहता है। पूजा अमरूद पसंद करने वाले से चार मंज़िल नीचे रहती है। नवीन केला पसंद करने वाले से तीन मंज़िल ऊपर रहता है। पपीता पसंद करने वाले और मीना के बीच केवल चार व्यक्ति रहते हैं। ओजस पपीता पसंद करने वाले से दो मंज़िल ऊपर रहता है। ललित के ऊपर उतने ही व्यक्ति रहते हैं जितने आम पसंद करने वाले के नीचे रहते हैं। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["पूजा – किरण","ललित – नवीन","मीना – पूजा","नवीन – मीना"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 6 से 1 तक: मीना (सेब), नवीन (अमरूद), ललित (संतरा), ओजस (आम), किरण (केला), पूजा (पपीता)। पूजा – किरण, ललित – नवीन, नवीन – मीना में दूसरा व्यक्ति पहले के ठीक ऊपर रहता है; मीना – पूजा इस पैटर्न का पालन नहीं करता।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-154","question":"Study the information and answer the question. Six persons Kiran, Lalit, Meena, Naveen, Ojas and Pooja live on the 6 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 6; each likes a different fruit (Apple, Banana, Guava, Mango, Orange and Papaya). The person who likes Apple lives somewhere above the person who likes Guava. Pooja lives four floors below the person who likes Guava. Naveen lives three floors above the person who likes Banana. Only four persons live between the person who likes Papaya and Meena. Ojas lives two floors above the person who likes Papaya. As many persons live above Lalit as below the person who likes Mango. Question: The person who likes Mango is:","options":["Meena","Kiran","Lalit","Ojas"],"answer":3,"explanation":"Final arrangement: From floor 6 down to 1: Meena (Apple), Naveen (Guava), Lalit (Orange), Ojas (Mango), Kiran (Banana), Pooja (Papaya). Ojas likes Mango.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति किरण, ललित, मीना, नवीन, ओजस और पूजा एक इमारत की 6 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 6 है; प्रत्येक को अलग फल पसंद है (सेब, केला, अमरूद, आम, संतरा और पपीता)। सेब पसंद करने वाला अमरूद पसंद करने वाले से कहीं ऊपर रहता है। पूजा अमरूद पसंद करने वाले से चार मंज़िल नीचे रहती है। नवीन केला पसंद करने वाले से तीन मंज़िल ऊपर रहता है। पपीता पसंद करने वाले और मीना के बीच केवल चार व्यक्ति रहते हैं। ओजस पपीता पसंद करने वाले से दो मंज़िल ऊपर रहता है। ललित के ऊपर उतने ही व्यक्ति रहते हैं जितने आम पसंद करने वाले के नीचे रहते हैं। प्रश्न: आम किसे पसंद है?","optionsHi":["मीना","किरण","ललित","ओजस"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 6 से 1 तक: मीना (सेब), नवीन (अमरूद), ललित (संतरा), ओजस (आम), किरण (केला), पूजा (पपीता)। ओजस को आम पसंद है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-155","question":"Study the information and answer the question. Six persons Tanya, Uday, Varun, Wasim, Yamini and Zoya sit around a circular table, equally spaced; some face the centre and the others face outside; each plays a different game (Cricket, Hockey, Tennis, Chess, Kabaddi and Football). The person who plays Tennis faces outside. Varun faces outside. Zoya sits second to the left of Varun. The person who plays Hockey sits to the immediate left of Zoya. Wasim faces the centre. Yamini and Wasim face the same direction. Yamini does not play Cricket. The person who plays Kabaddi sits second to the left of Wasim. Uday sits second to the right of the person who plays Kabaddi. Wasim sits to the immediate left of the person who plays Cricket. The person who plays Cricket sits to the immediate right of the person who plays Football. Question: The person who plays Football is:","options":["Varun","Uday","Tanya","Wasim"],"answer":1,"explanation":"Final arrangement: Going clockwise from Tanya: Tanya (Kabaddi) [out], Yamini (Chess) [in], Uday (Football) [out], Zoya (Cricket) [in], Wasim (Hockey) [in], Varun (Tennis) [out] (in = faces the centre, out = faces outside). Uday plays Football.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति तान्या, उदय, वरुण, वसीम, यामिनी और ज़ोया एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; कुछ का मुख केंद्र की ओर और बाकी का बाहर की ओर है; प्रत्येक अलग खेल खेलता है (क्रिकेट, हॉकी, टेनिस, शतरंज, कबड्डी और फुटबॉल)। टेनिस खेलने वाले का मुख बाहर की ओर है। वरुण का मुख बाहर की ओर है। ज़ोया वरुण के बाएँ से दूसरे स्थान पर बैठी है। हॉकी खेलने वाला ज़ोया के ठीक बाएँ बैठा है। वसीम का मुख केंद्र की ओर है। यामिनी और वसीम का मुख एक ही दिशा में है। यामिनी क्रिकेट नहीं खेलती। कबड्डी खेलने वाला वसीम के बाएँ से दूसरे स्थान पर बैठा है। उदय कबड्डी खेलने वाले के दाएँ से दूसरे स्थान पर बैठा है। वसीम क्रिकेट खेलने वाले के ठीक बाएँ बैठा है। क्रिकेट खेलने वाला फुटबॉल खेलने वाले के ठीक दाएँ बैठा है। प्रश्न: फुटबॉल कौन खेलता है?","optionsHi":["वरुण","उदय","तान्या","वसीम"],"explanationHi":"अंतिम व्यवस्था: तान्या से दक्षिणावर्त चलने पर: तान्या (कबड्डी) [बाहर], यामिनी (शतरंज) [अंदर], उदय (फुटबॉल) [बाहर], ज़ोया (क्रिकेट) [अंदर], वसीम (हॉकी) [अंदर], वरुण (टेनिस) [बाहर] (अंदर = केंद्र की ओर मुख, बाहर = बाहर की ओर मुख)। उदय फुटबॉल खेलता है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-156","question":"Study the information and answer the question. Six persons Tanya, Uday, Varun, Wasim, Yamini and Zoya sit around a circular table, equally spaced; some face the centre and the others face outside; each plays a different game (Cricket, Hockey, Tennis, Chess, Kabaddi and Football). The person who plays Tennis faces outside. Varun faces outside. Zoya sits second to the left of Varun. The person who plays Hockey sits to the immediate left of Zoya. Wasim faces the centre. Yamini and Wasim face the same direction. Yamini does not play Cricket. The person who plays Kabaddi sits second to the left of Wasim. Uday sits second to the right of the person who plays Kabaddi. Wasim sits to the immediate left of the person who plays Cricket. The person who plays Cricket sits to the immediate right of the person who plays Football. Question: How many persons sit between Uday and Wasim, counted along the shorter side of the table?","options":["1","2","3","4"],"answer":0,"explanation":"Final arrangement: Going clockwise from Tanya: Tanya (Kabaddi) [out], Yamini (Chess) [in], Uday (Football) [out], Zoya (Cricket) [in], Wasim (Hockey) [in], Varun (Tennis) [out] (in = faces the centre, out = faces outside). Between Uday and Wasim is Zoya, i.e. 1.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति तान्या, उदय, वरुण, वसीम, यामिनी और ज़ोया एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; कुछ का मुख केंद्र की ओर और बाकी का बाहर की ओर है; प्रत्येक अलग खेल खेलता है (क्रिकेट, हॉकी, टेनिस, शतरंज, कबड्डी और फुटबॉल)। टेनिस खेलने वाले का मुख बाहर की ओर है। वरुण का मुख बाहर की ओर है। ज़ोया वरुण के बाएँ से दूसरे स्थान पर बैठी है। हॉकी खेलने वाला ज़ोया के ठीक बाएँ बैठा है। वसीम का मुख केंद्र की ओर है। यामिनी और वसीम का मुख एक ही दिशा में है। यामिनी क्रिकेट नहीं खेलती। कबड्डी खेलने वाला वसीम के बाएँ से दूसरे स्थान पर बैठा है। उदय कबड्डी खेलने वाले के दाएँ से दूसरे स्थान पर बैठा है। वसीम क्रिकेट खेलने वाले के ठीक बाएँ बैठा है। क्रिकेट खेलने वाला फुटबॉल खेलने वाले के ठीक दाएँ बैठा है। प्रश्न: मेज़ की छोटी ओर से गिनने पर उदय और वसीम के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["1","2","3","4"],"explanationHi":"अंतिम व्यवस्था: तान्या से दक्षिणावर्त चलने पर: तान्या (कबड्डी) [बाहर], यामिनी (शतरंज) [अंदर], उदय (फुटबॉल) [बाहर], ज़ोया (क्रिकेट) [अंदर], वसीम (हॉकी) [अंदर], वरुण (टेनिस) [बाहर] (अंदर = केंद्र की ओर मुख, बाहर = बाहर की ओर मुख)। उदय और वसीम के बीच ज़ोया है, यानी 1।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-157","question":"Study the information and answer the question. Six persons Tanya, Uday, Varun, Wasim, Yamini and Zoya sit around a circular table, equally spaced; some face the centre and the others face outside; each plays a different game (Cricket, Hockey, Tennis, Chess, Kabaddi and Football). The person who plays Tennis faces outside. Varun faces outside. Zoya sits second to the left of Varun. The person who plays Hockey sits to the immediate left of Zoya. Wasim faces the centre. Yamini and Wasim face the same direction. Yamini does not play Cricket. The person who plays Kabaddi sits second to the left of Wasim. Uday sits second to the right of the person who plays Kabaddi. Wasim sits to the immediate left of the person who plays Cricket. The person who plays Cricket sits to the immediate right of the person who plays Football. Question: Who sits second to the right of Wasim?","options":["Varun","Tanya","Uday","Zoya"],"answer":2,"explanation":"Final arrangement: Going clockwise from Tanya: Tanya (Kabaddi) [out], Yamini (Chess) [in], Uday (Football) [out], Zoya (Cricket) [in], Wasim (Hockey) [in], Varun (Tennis) [out] (in = faces the centre, out = faces outside). Uday sits second to the right of Wasim (Wasim faces the centre).","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति तान्या, उदय, वरुण, वसीम, यामिनी और ज़ोया एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; कुछ का मुख केंद्र की ओर और बाकी का बाहर की ओर है; प्रत्येक अलग खेल खेलता है (क्रिकेट, हॉकी, टेनिस, शतरंज, कबड्डी और फुटबॉल)। टेनिस खेलने वाले का मुख बाहर की ओर है। वरुण का मुख बाहर की ओर है। ज़ोया वरुण के बाएँ से दूसरे स्थान पर बैठी है। हॉकी खेलने वाला ज़ोया के ठीक बाएँ बैठा है। वसीम का मुख केंद्र की ओर है। यामिनी और वसीम का मुख एक ही दिशा में है। यामिनी क्रिकेट नहीं खेलती। कबड्डी खेलने वाला वसीम के बाएँ से दूसरे स्थान पर बैठा है। उदय कबड्डी खेलने वाले के दाएँ से दूसरे स्थान पर बैठा है। वसीम क्रिकेट खेलने वाले के ठीक बाएँ बैठा है। क्रिकेट खेलने वाला फुटबॉल खेलने वाले के ठीक दाएँ बैठा है। प्रश्न: वसीम के दाएँ से दूसरे स्थान पर कौन बैठा है?","optionsHi":["वरुण","तान्या","उदय","ज़ोया"],"explanationHi":"अंतिम व्यवस्था: तान्या से दक्षिणावर्त चलने पर: तान्या (कबड्डी) [बाहर], यामिनी (शतरंज) [अंदर], उदय (फुटबॉल) [बाहर], ज़ोया (क्रिकेट) [अंदर], वसीम (हॉकी) [अंदर], वरुण (टेनिस) [बाहर] (अंदर = केंद्र की ओर मुख, बाहर = बाहर की ओर मुख)। उदय वसीम के दाएँ से दूसरे स्थान पर बैठा है (वसीम का मुख केंद्र की ओर है)।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-158","question":"Study the information and answer the question. Six persons J, K, L, M, N and O sit in a row of 6 seats numbered 1 to 6 from west to east; some of them face north and the others face south; each is from a different city (Agra, Bhopal, Chennai, Delhi, Indore and Jaipur). The person from Indore faces north. The person from Indore is an immediate neighbour of the person from Jaipur. The person from Indore sits at the east end. The person from Agra sits to the immediate left of the person from Bhopal. The person from Agra sits fourth to the right of K. K sits to the immediate right of O. K sits second to the left of N. J is an immediate neighbour of the person from Agra. The person from Delhi sits second to the right of L. Question: Who sits to the immediate left of O?","options":["M","J","K","N"],"answer":3,"explanation":"Final arrangement: Seats 1 to 6 (west to east): L (Agra) [N], J (Bhopal) [N], N (Delhi) [S], O (Chennai) [N], K (Jaipur) [S], M (Indore) [N] (N = faces north, S = faces south). N sits to the immediate left of O (O faces north).","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति J, K, L, M, N और O 6 सीटों की एक पंक्ति में बैठे हैं, जो पश्चिम से पूर्व की ओर 1 से 6 तक क्रमांकित हैं; उनमें से कुछ का मुख उत्तर की ओर और बाकी का दक्षिण की ओर है; प्रत्येक अलग शहर का है (आगरा, भोपाल, चेन्नई, दिल्ली, इंदौर और जयपुर)। इंदौर के व्यक्ति का मुख उत्तर की ओर है। इंदौर का व्यक्ति जयपुर के व्यक्ति का निकटतम पड़ोसी है। इंदौर का व्यक्ति पूर्वी छोर पर बैठा है। आगरा का व्यक्ति भोपाल के व्यक्ति के ठीक बाएँ बैठा है। आगरा का व्यक्ति K के दाएँ से चौथे स्थान पर बैठा है। K, O के ठीक दाएँ बैठा है। K, N के बाएँ से दूसरे स्थान पर बैठा है। J आगरा के व्यक्ति का निकटतम पड़ोसी है। दिल्ली का व्यक्ति L के दाएँ से दूसरे स्थान पर बैठा है। प्रश्न: O के ठीक बाएँ कौन बैठा है?","optionsHi":["M","J","K","N"],"explanationHi":"अंतिम व्यवस्था: सीट 1 से 6 (पश्चिम से पूर्व): L (आगरा) [N], J (भोपाल) [N], N (दिल्ली) [S], O (चेन्नई) [N], K (जयपुर) [S], M (इंदौर) [N] (N = उत्तर की ओर मुख, S = दक्षिण की ओर मुख)। N, O के ठीक बाएँ बैठा है (O का मुख उत्तर की ओर है)।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-159","question":"Study the information and answer the question. Six persons J, K, L, M, N and O sit in a row of 6 seats numbered 1 to 6 from west to east; some of them face north and the others face south; each is from a different city (Agra, Bhopal, Chennai, Delhi, Indore and Jaipur). The person from Indore faces north. The person from Indore is an immediate neighbour of the person from Jaipur. The person from Indore sits at the east end. The person from Agra sits to the immediate left of the person from Bhopal. The person from Agra sits fourth to the right of K. K sits to the immediate right of O. K sits second to the left of N. J is an immediate neighbour of the person from Agra. The person from Delhi sits second to the right of L. Question: How many persons sit between L and M?","options":["1","2","3","4"],"answer":3,"explanation":"Final arrangement: Seats 1 to 6 (west to east): L (Agra) [N], J (Bhopal) [N], N (Delhi) [S], O (Chennai) [N], K (Jaipur) [S], M (Indore) [N] (N = faces north, S = faces south). Between L and M are J, N, O, K, i.e. 4.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति J, K, L, M, N और O 6 सीटों की एक पंक्ति में बैठे हैं, जो पश्चिम से पूर्व की ओर 1 से 6 तक क्रमांकित हैं; उनमें से कुछ का मुख उत्तर की ओर और बाकी का दक्षिण की ओर है; प्रत्येक अलग शहर का है (आगरा, भोपाल, चेन्नई, दिल्ली, इंदौर और जयपुर)। इंदौर के व्यक्ति का मुख उत्तर की ओर है। इंदौर का व्यक्ति जयपुर के व्यक्ति का निकटतम पड़ोसी है। इंदौर का व्यक्ति पूर्वी छोर पर बैठा है। आगरा का व्यक्ति भोपाल के व्यक्ति के ठीक बाएँ बैठा है। आगरा का व्यक्ति K के दाएँ से चौथे स्थान पर बैठा है। K, O के ठीक दाएँ बैठा है। K, N के बाएँ से दूसरे स्थान पर बैठा है। J आगरा के व्यक्ति का निकटतम पड़ोसी है। दिल्ली का व्यक्ति L के दाएँ से दूसरे स्थान पर बैठा है। प्रश्न: L और M के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["1","2","3","4"],"explanationHi":"अंतिम व्यवस्था: सीट 1 से 6 (पश्चिम से पूर्व): L (आगरा) [N], J (भोपाल) [N], N (दिल्ली) [S], O (चेन्नई) [N], K (जयपुर) [S], M (इंदौर) [N] (N = उत्तर की ओर मुख, S = दक्षिण की ओर मुख)। L और M के बीच J, N, O, K हैं, यानी 4।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-160","question":"Study the information and answer the question. Six persons J, K, L, M, N and O sit in a row of 6 seats numbered 1 to 6 from west to east; some of them face north and the others face south; each is from a different city (Agra, Bhopal, Chennai, Delhi, Indore and Jaipur). The person from Indore faces north. The person from Indore is an immediate neighbour of the person from Jaipur. The person from Indore sits at the east end. The person from Agra sits to the immediate left of the person from Bhopal. The person from Agra sits fourth to the right of K. K sits to the immediate right of O. K sits second to the left of N. J is an immediate neighbour of the person from Agra. The person from Delhi sits second to the right of L. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["K – N","N – J","J – O","L – N"],"answer":1,"explanation":"Final arrangement: Seats 1 to 6 (west to east): L (Agra) [N], J (Bhopal) [N], N (Delhi) [S], O (Chennai) [N], K (Jaipur) [S], M (Indore) [N] (N = faces north, S = faces south). In L – N, K – N, J – O, the second person sits second to the right of the first; N – J does not follow this pattern.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति J, K, L, M, N और O 6 सीटों की एक पंक्ति में बैठे हैं, जो पश्चिम से पूर्व की ओर 1 से 6 तक क्रमांकित हैं; उनमें से कुछ का मुख उत्तर की ओर और बाकी का दक्षिण की ओर है; प्रत्येक अलग शहर का है (आगरा, भोपाल, चेन्नई, दिल्ली, इंदौर और जयपुर)। इंदौर के व्यक्ति का मुख उत्तर की ओर है। इंदौर का व्यक्ति जयपुर के व्यक्ति का निकटतम पड़ोसी है। इंदौर का व्यक्ति पूर्वी छोर पर बैठा है। आगरा का व्यक्ति भोपाल के व्यक्ति के ठीक बाएँ बैठा है। आगरा का व्यक्ति K के दाएँ से चौथे स्थान पर बैठा है। K, O के ठीक दाएँ बैठा है। K, N के बाएँ से दूसरे स्थान पर बैठा है। J आगरा के व्यक्ति का निकटतम पड़ोसी है। दिल्ली का व्यक्ति L के दाएँ से दूसरे स्थान पर बैठा है। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["K – N","N – J","J – O","L – N"],"explanationHi":"अंतिम व्यवस्था: सीट 1 से 6 (पश्चिम से पूर्व): L (आगरा) [N], J (भोपाल) [N], N (दिल्ली) [S], O (चेन्नई) [N], K (जयपुर) [S], M (इंदौर) [N] (N = उत्तर की ओर मुख, S = दक्षिण की ओर मुख)। L – N, K – N, J – O में दूसरा व्यक्ति पहले के दाएँ से दूसरे स्थान पर बैठा है; N – J इस पैटर्न का पालन नहीं करता।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-161","question":"Study the information and answer the question. Six persons A, B, C, D, E and F visit a trade fair in 6 different months of the same year (April, May, June, July, August, September), one person per month, in that order of months; each has a different profession (doctor, engineer, lawyer, pilot, teacher and banker). The doctor goes in some month before the pilot. The pilot goes in some month after F. B goes exactly three months after the pilot. Only one person goes between the lawyer and F. A goes exactly two months after C. Exactly four persons go between the engineer and D. D goes in the month immediately before the teacher. Question: Which of the following correctly describes B?","options":["is a pilot","is a lawyer","is an engineer","is a doctor"],"answer":2,"explanation":"Final arrangement: April: D (doctor), May: F (teacher), June: C (pilot), July: E (lawyer), August: A (banker), September: B (engineer). B is an engineer.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति A, B, C, D, E और F एक ही वर्ष के 6 अलग-अलग महीनों (अप्रैल, मई, जून, जुलाई, अगस्त, सितंबर) में एक व्यापार मेले में जाते हैं, प्रत्येक महीने में एक व्यक्ति, महीनों के इसी क्रम में; प्रत्येक का पेशा अलग है (डॉक्टर, इंजीनियर, वकील, पायलट, शिक्षक और बैंकर)। डॉक्टर पायलट से पहले किसी महीने में जाता है। पायलट F के बाद किसी महीने में जाता है। B पायलट से ठीक तीन महीने बाद जाता है। वकील और F के बीच केवल एक व्यक्ति जाता है। A, C से ठीक दो महीने बाद जाता है। इंजीनियर और D के बीच ठीक चार व्यक्ति जाते हैं। D शिक्षक के ठीक पहले वाले महीने में जाता है। प्रश्न: निम्नलिखित में से कौन-सा कथन B का सही वर्णन करता है?","optionsHi":["पायलट है","वकील है","इंजीनियर है","डॉक्टर है"],"explanationHi":"अंतिम व्यवस्था: अप्रैल: D (डॉक्टर), मई: F (शिक्षक), जून: C (पायलट), जुलाई: E (वकील), अगस्त: A (बैंकर), सितंबर: B (इंजीनियर)। B इंजीनियर है।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-162","question":"Study the information and answer the question. Six persons A, B, C, D, E and F visit a trade fair in 6 different months of the same year (April, May, June, July, August, September), one person per month, in that order of months; each has a different profession (doctor, engineer, lawyer, pilot, teacher and banker). The doctor goes in some month before the pilot. The pilot goes in some month after F. B goes exactly three months after the pilot. Only one person goes between the lawyer and F. A goes exactly two months after C. Exactly four persons go between the engineer and D. D goes in the month immediately before the teacher. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["B – E","D – F","F – C","A – B"],"answer":0,"explanation":"Final arrangement: April: D (doctor), May: F (teacher), June: C (pilot), July: E (lawyer), August: A (banker), September: B (engineer). In A – B, F – C, D – F, the second person goes in the month immediately after the first; B – E does not follow this pattern.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति A, B, C, D, E और F एक ही वर्ष के 6 अलग-अलग महीनों (अप्रैल, मई, जून, जुलाई, अगस्त, सितंबर) में एक व्यापार मेले में जाते हैं, प्रत्येक महीने में एक व्यक्ति, महीनों के इसी क्रम में; प्रत्येक का पेशा अलग है (डॉक्टर, इंजीनियर, वकील, पायलट, शिक्षक और बैंकर)। डॉक्टर पायलट से पहले किसी महीने में जाता है। पायलट F के बाद किसी महीने में जाता है। B पायलट से ठीक तीन महीने बाद जाता है। वकील और F के बीच केवल एक व्यक्ति जाता है। A, C से ठीक दो महीने बाद जाता है। इंजीनियर और D के बीच ठीक चार व्यक्ति जाते हैं। D शिक्षक के ठीक पहले वाले महीने में जाता है। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["B – E","D – F","F – C","A – B"],"explanationHi":"अंतिम व्यवस्था: अप्रैल: D (डॉक्टर), मई: F (शिक्षक), जून: C (पायलट), जुलाई: E (वकील), अगस्त: A (बैंकर), सितंबर: B (इंजीनियर)। A – B, F – C, D – F में दूसरा व्यक्ति पहले के ठीक अगले महीने में जाता है; B – E इस पैटर्न का पालन नहीं करता।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-163","question":"Study the information and answer the question. Six persons A, B, C, D, E and F visit a trade fair in 6 different months of the same year (April, May, June, July, August, September), one person per month, in that order of months; each has a different profession (doctor, engineer, lawyer, pilot, teacher and banker). The doctor goes in some month before the pilot. The pilot goes in some month after F. B goes exactly three months after the pilot. Only one person goes between the lawyer and F. A goes exactly two months after C. Exactly four persons go between the engineer and D. D goes in the month immediately before the teacher. Question: How many persons visit the fair between D and A?","options":["1","2","3","4"],"answer":2,"explanation":"Final arrangement: April: D (doctor), May: F (teacher), June: C (pilot), July: E (lawyer), August: A (banker), September: B (engineer). Between D and A are F, C, E, i.e. 3.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति A, B, C, D, E और F एक ही वर्ष के 6 अलग-अलग महीनों (अप्रैल, मई, जून, जुलाई, अगस्त, सितंबर) में एक व्यापार मेले में जाते हैं, प्रत्येक महीने में एक व्यक्ति, महीनों के इसी क्रम में; प्रत्येक का पेशा अलग है (डॉक्टर, इंजीनियर, वकील, पायलट, शिक्षक और बैंकर)। डॉक्टर पायलट से पहले किसी महीने में जाता है। पायलट F के बाद किसी महीने में जाता है। B पायलट से ठीक तीन महीने बाद जाता है। वकील और F के बीच केवल एक व्यक्ति जाता है। A, C से ठीक दो महीने बाद जाता है। इंजीनियर और D के बीच ठीक चार व्यक्ति जाते हैं। D शिक्षक के ठीक पहले वाले महीने में जाता है। प्रश्न: D और A के बीच कितने व्यक्ति मेले में जाते हैं?","optionsHi":["1","2","3","4"],"explanationHi":"अंतिम व्यवस्था: अप्रैल: D (डॉक्टर), मई: F (शिक्षक), जून: C (पायलट), जुलाई: E (वकील), अगस्त: A (बैंकर), सितंबर: B (इंजीनियर)। D और A के बीच F, C, E हैं, यानी 3।","subtopic":"scheduling-attributes"},
  {"id":"reason-seating-puzzles-164","question":"Study the information and answer the question. Six persons P, Q, R, S, T and U sit around a circular table, equally spaced and facing away from the centre; each likes a different colour (Red, Blue, Green, White, Black and Yellow). R sits to the immediate left of Q. R sits second to the left of U. Q sits to the immediate left of the person who likes Yellow. Q sits second to the right of S. The person who likes White is an immediate neighbour of P. The person who likes White sits to the immediate right of the person who likes Green. P sits second to the left of the person who likes Black. The person who likes White sits opposite the person who likes Red. Question: Which of the following correctly describes Q?","options":["likes Blue","likes Red","likes White","likes Green"],"answer":1,"explanation":"Final arrangement: Going clockwise from P: P (Green), T (White), S (Black), R (Blue), Q (Red), U (Yellow). Q likes Red.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति P, Q, R, S, T और U केंद्र से बाहर की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; प्रत्येक को अलग रंग पसंद है (लाल, नीला, हरा, सफेद, काला और पीला)। R, Q के ठीक बाएँ बैठा है। R, U के बाएँ से दूसरे स्थान पर बैठा है। Q, पीला रंग पसंद करने वाले के ठीक बाएँ बैठा है। Q, S के दाएँ से दूसरे स्थान पर बैठा है। सफेद रंग पसंद करने वाला P का निकटतम पड़ोसी है। सफेद रंग पसंद करने वाला हरा रंग पसंद करने वाले के ठीक दाएँ बैठा है। P, काला रंग पसंद करने वाले के बाएँ से दूसरे स्थान पर बैठा है। सफेद रंग पसंद करने वाला लाल रंग पसंद करने वाले के सामने बैठा है। प्रश्न: निम्नलिखित में से कौन-सा कथन Q का सही वर्णन करता है?","optionsHi":["को नीला पसंद है","को लाल पसंद है","को सफेद पसंद है","को हरा पसंद है"],"explanationHi":"अंतिम व्यवस्था: P से दक्षिणावर्त चलने पर: P (हरा), T (सफेद), S (काला), R (नीला), Q (लाल), U (पीला)। Q को लाल रंग पसंद है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-165","question":"Study the information and answer the question. Six persons P, Q, R, S, T and U sit around a circular table, equally spaced and facing away from the centre; each likes a different colour (Red, Blue, Green, White, Black and Yellow). R sits to the immediate left of Q. R sits second to the left of U. Q sits to the immediate left of the person who likes Yellow. Q sits second to the right of S. The person who likes White is an immediate neighbour of P. The person who likes White sits to the immediate right of the person who likes Green. P sits second to the left of the person who likes Black. The person who likes White sits opposite the person who likes Red. Question: How many persons sit between R and P, counted along the shorter side of the table?","options":["1","2","3","4"],"answer":1,"explanation":"Final arrangement: Going clockwise from P: P (Green), T (White), S (Black), R (Blue), Q (Red), U (Yellow). Between R and P are Q, U, i.e. 2.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति P, Q, R, S, T और U केंद्र से बाहर की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; प्रत्येक को अलग रंग पसंद है (लाल, नीला, हरा, सफेद, काला और पीला)। R, Q के ठीक बाएँ बैठा है। R, U के बाएँ से दूसरे स्थान पर बैठा है। Q, पीला रंग पसंद करने वाले के ठीक बाएँ बैठा है। Q, S के दाएँ से दूसरे स्थान पर बैठा है। सफेद रंग पसंद करने वाला P का निकटतम पड़ोसी है। सफेद रंग पसंद करने वाला हरा रंग पसंद करने वाले के ठीक दाएँ बैठा है। P, काला रंग पसंद करने वाले के बाएँ से दूसरे स्थान पर बैठा है। सफेद रंग पसंद करने वाला लाल रंग पसंद करने वाले के सामने बैठा है। प्रश्न: मेज़ की छोटी ओर से गिनने पर R और P के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["1","2","3","4"],"explanationHi":"अंतिम व्यवस्था: P से दक्षिणावर्त चलने पर: P (हरा), T (सफेद), S (काला), R (नीला), Q (लाल), U (पीला)। R और P के बीच Q, U हैं, यानी 2।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-166","question":"Study the information and answer the question. Six persons P, Q, R, S, T and U sit around a circular table, equally spaced and facing away from the centre; each likes a different colour (Red, Blue, Green, White, Black and Yellow). R sits to the immediate left of Q. R sits second to the left of U. Q sits to the immediate left of the person who likes Yellow. Q sits second to the right of S. The person who likes White is an immediate neighbour of P. The person who likes White sits to the immediate right of the person who likes Green. P sits second to the left of the person who likes Black. The person who likes White sits opposite the person who likes Red. Question: Who sits third to the right of R?","options":["U","T","S","P"],"answer":3,"explanation":"Final arrangement: Going clockwise from P: P (Green), T (White), S (Black), R (Blue), Q (Red), U (Yellow). P sits third to the right of R.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति P, Q, R, S, T और U केंद्र से बाहर की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; प्रत्येक को अलग रंग पसंद है (लाल, नीला, हरा, सफेद, काला और पीला)। R, Q के ठीक बाएँ बैठा है। R, U के बाएँ से दूसरे स्थान पर बैठा है। Q, पीला रंग पसंद करने वाले के ठीक बाएँ बैठा है। Q, S के दाएँ से दूसरे स्थान पर बैठा है। सफेद रंग पसंद करने वाला P का निकटतम पड़ोसी है। सफेद रंग पसंद करने वाला हरा रंग पसंद करने वाले के ठीक दाएँ बैठा है। P, काला रंग पसंद करने वाले के बाएँ से दूसरे स्थान पर बैठा है। सफेद रंग पसंद करने वाला लाल रंग पसंद करने वाले के सामने बैठा है। प्रश्न: R के दाएँ से तीसरे स्थान पर कौन बैठा है?","optionsHi":["U","T","S","P"],"explanationHi":"अंतिम व्यवस्था: P से दक्षिणावर्त चलने पर: P (हरा), T (सफेद), S (काला), R (नीला), Q (लाल), U (पीला)। P, R के दाएँ से तीसरे स्थान पर बैठा है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-167","question":"Study the information and answer the question. Six boxes K, L, M, N, O and P are kept one above another in a single stack; position 1 is at the bottom and position 6 at the top; each of a different colour (red, blue, green, white, black and yellow). N is kept at an odd-numbered position. The blue box is kept immediately above N. O is kept somewhere below the blue box. Only four boxes are kept between the green box and the white box. The white box is kept immediately below M. P is kept immediately above the red box. Exactly three boxes are kept between L and the black box. Question: At which position is box P kept?","options":["2","3","4","5"],"answer":2,"explanation":"Final arrangement: From position 6 down to 1: L (green), K (yellow), P (blue), N (red), M (black), O (white). P is at position 4.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह डिब्बे K, L, M, N, O और P एक ही ढेर में एक के ऊपर एक रखे गए हैं; स्थिति 1 सबसे नीचे और स्थिति 6 सबसे ऊपर है; प्रत्येक अलग रंग का है (लाल, नीला, हरा, सफेद, काला और पीला)। N विषम संख्या वाली स्थिति पर रखा है। नीला डिब्बा N के ठीक ऊपर रखा है। O नीले डिब्बे से कहीं नीचे रखा है। हरे डिब्बे और सफेद डिब्बे के बीच केवल चार डिब्बे रखे हैं। सफेद डिब्बा M के ठीक नीचे रखा है। P लाल डिब्बे के ठीक ऊपर रखा है। L और काले डिब्बे के बीच ठीक तीन डिब्बे रखे हैं। प्रश्न: डिब्बा P किस स्थिति पर रखा है?","optionsHi":["2","3","4","5"],"explanationHi":"अंतिम व्यवस्था: स्थिति 6 से 1 तक: L (हरा), K (पीला), P (नीला), N (लाल), M (काला), O (सफेद)। P स्थिति 4 पर है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-168","question":"Study the information and answer the question. Six boxes K, L, M, N, O and P are kept one above another in a single stack; position 1 is at the bottom and position 6 at the top; each of a different colour (red, blue, green, white, black and yellow). N is kept at an odd-numbered position. The blue box is kept immediately above N. O is kept somewhere below the blue box. Only four boxes are kept between the green box and the white box. The white box is kept immediately below M. P is kept immediately above the red box. Exactly three boxes are kept between L and the black box. Question: Which box is kept two positions above O?","options":["N","M","K","L"],"answer":0,"explanation":"Final arrangement: From position 6 down to 1: L (green), K (yellow), P (blue), N (red), M (black), O (white). N is kept two positions above O.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह डिब्बे K, L, M, N, O और P एक ही ढेर में एक के ऊपर एक रखे गए हैं; स्थिति 1 सबसे नीचे और स्थिति 6 सबसे ऊपर है; प्रत्येक अलग रंग का है (लाल, नीला, हरा, सफेद, काला और पीला)। N विषम संख्या वाली स्थिति पर रखा है। नीला डिब्बा N के ठीक ऊपर रखा है। O नीले डिब्बे से कहीं नीचे रखा है। हरे डिब्बे और सफेद डिब्बे के बीच केवल चार डिब्बे रखे हैं। सफेद डिब्बा M के ठीक नीचे रखा है। P लाल डिब्बे के ठीक ऊपर रखा है। L और काले डिब्बे के बीच ठीक तीन डिब्बे रखे हैं। प्रश्न: O से दो स्थिति ऊपर कौन-सा डिब्बा रखा है?","optionsHi":["N","M","K","L"],"explanationHi":"अंतिम व्यवस्था: स्थिति 6 से 1 तक: L (हरा), K (पीला), P (नीला), N (लाल), M (काला), O (सफेद)। N, O से दो स्थिति ऊपर रखा है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-169","question":"Study the information and answer the question. Six boxes K, L, M, N, O and P are kept one above another in a single stack; position 1 is at the bottom and position 6 at the top; each of a different colour (red, blue, green, white, black and yellow). N is kept at an odd-numbered position. The blue box is kept immediately above N. O is kept somewhere below the blue box. Only four boxes are kept between the green box and the white box. The white box is kept immediately below M. P is kept immediately above the red box. Exactly three boxes are kept between L and the black box. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["M – N","K – L","O – M","L – O"],"answer":3,"explanation":"Final arrangement: From position 6 down to 1: L (green), K (yellow), P (blue), N (red), M (black), O (white). In K – L, O – M, M – N, the second box is kept immediately above the first; L – O does not follow this pattern.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह डिब्बे K, L, M, N, O और P एक ही ढेर में एक के ऊपर एक रखे गए हैं; स्थिति 1 सबसे नीचे और स्थिति 6 सबसे ऊपर है; प्रत्येक अलग रंग का है (लाल, नीला, हरा, सफेद, काला और पीला)। N विषम संख्या वाली स्थिति पर रखा है। नीला डिब्बा N के ठीक ऊपर रखा है। O नीले डिब्बे से कहीं नीचे रखा है। हरे डिब्बे और सफेद डिब्बे के बीच केवल चार डिब्बे रखे हैं। सफेद डिब्बा M के ठीक नीचे रखा है। P लाल डिब्बे के ठीक ऊपर रखा है। L और काले डिब्बे के बीच ठीक तीन डिब्बे रखे हैं। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["M – N","K – L","O – M","L – O"],"explanationHi":"अंतिम व्यवस्था: स्थिति 6 से 1 तक: L (हरा), K (पीला), P (नीला), N (लाल), M (काला), O (सफेद)। K – L, O – M, M – N में दूसरा डिब्बा पहले के ठीक ऊपर रखा है; L – O इस पैटर्न का पालन नहीं करता।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-170","question":"Study the information and answer the question. Five persons Tanya, Uday, Varun, Wasim and Yamini sit in a straight row facing north. Yamini sits at an extreme end of the row. Tanya sits third to the left of Yamini. Uday sits third to the left of Varun. Question: How many persons sit between Wasim and Yamini?","options":["0","1","2","3"],"answer":1,"explanation":"Final arrangement: From left to right: Uday, Tanya, Wasim, Varun, Yamini. Between Wasim and Yamini is Varun, i.e. 1.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। पाँच व्यक्ति तान्या, उदय, वरुण, वसीम और यामिनी उत्तर की ओर मुख करके एक सीधी पंक्ति में बैठे हैं। यामिनी पंक्ति के एक छोर पर बैठी है। तान्या यामिनी के बाएँ से तीसरे स्थान पर बैठी है। उदय वरुण के बाएँ से तीसरे स्थान पर बैठा है। प्रश्न: वसीम और यामिनी के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["0","1","2","3"],"explanationHi":"अंतिम व्यवस्था: बाएँ से दाएँ: उदय, तान्या, वसीम, वरुण, यामिनी। वसीम और यामिनी के बीच वरुण है, यानी 1।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-171","question":"Study the information and answer the question. Six persons A, B, C, D, E and F sit around a circular table, equally spaced and facing the centre. D is an immediate neighbour of C. B sits to the immediate left of C. F is an immediate neighbour of B. B sits second to the right of A. Question: Who sits third to the right of E?","options":["B","F","D","A"],"answer":0,"explanation":"Final arrangement: Going clockwise from A: A, E, D, C, B, F. B sits third to the right of E.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। छह व्यक्ति A, B, C, D, E और F केंद्र की ओर मुख करके एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं। D, C का निकटतम पड़ोसी है। B, C के ठीक बाएँ बैठा है। F, B का निकटतम पड़ोसी है। B, A के दाएँ से दूसरे स्थान पर बैठा है। प्रश्न: E के दाएँ से तीसरे स्थान पर कौन बैठा है?","optionsHi":["B","F","D","A"],"explanationHi":"अंतिम व्यवस्था: A से दक्षिणावर्त चलने पर: A, E, D, C, B, F। B, E के दाएँ से तीसरे स्थान पर बैठा है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-172","question":"Study the information and answer the question. Seven persons Tanya, Uday, Varun, Wasim, Yamini, Zoya and Arjun live on the 7 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 7. Yamini lives on an even-numbered floor. Wasim lives on floor 4. Wasim lives somewhere above Zoya. Wasim lives immediately above Uday. Varun lives on an even-numbered floor. Varun lives immediately below Arjun. Question: On which floor does Tanya live?","options":["3","4","5","6"],"answer":2,"explanation":"Final arrangement: From floor 7 down to 1: Arjun, Varun, Tanya, Wasim, Uday, Yamini, Zoya. Tanya lives on floor 5.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति तान्या, उदय, वरुण, वसीम, यामिनी, ज़ोया और अर्जुन एक इमारत की 7 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 7 है। यामिनी सम संख्या वाली मंज़िल पर रहती है। वसीम मंज़िल 4 पर रहता है। वसीम ज़ोया से कहीं ऊपर रहता है। वसीम उदय के ठीक ऊपर रहता है। वरुण सम संख्या वाली मंज़िल पर रहता है। वरुण अर्जुन के ठीक नीचे रहता है। प्रश्न: तान्या किस मंज़िल पर रहती है?","optionsHi":["3","4","5","6"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 7 से 1 तक: अर्जुन, वरुण, तान्या, वसीम, उदय, यामिनी, ज़ोया। तान्या मंज़िल 5 पर रहती है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-173","question":"Study the information and answer the question. Seven persons Tanya, Uday, Varun, Wasim, Yamini, Zoya and Arjun live on the 7 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 7. Yamini lives on an even-numbered floor. Wasim lives on floor 4. Wasim lives somewhere above Zoya. Wasim lives immediately above Uday. Varun lives on an even-numbered floor. Varun lives immediately below Arjun. Question: Three of the following four pairs are alike in a certain way based on the arrangement. Which pair does not belong to the group?","options":["Wasim – Tanya","Uday – Wasim","Yamini – Uday","Arjun – Zoya"],"answer":3,"explanation":"Final arrangement: From floor 7 down to 1: Arjun, Varun, Tanya, Wasim, Uday, Yamini, Zoya. In Wasim – Tanya, Uday – Wasim, Yamini – Uday, the second person lives immediately above the first; Arjun – Zoya does not follow this pattern.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति तान्या, उदय, वरुण, वसीम, यामिनी, ज़ोया और अर्जुन एक इमारत की 7 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 7 है। यामिनी सम संख्या वाली मंज़िल पर रहती है। वसीम मंज़िल 4 पर रहता है। वसीम ज़ोया से कहीं ऊपर रहता है। वसीम उदय के ठीक ऊपर रहता है। वरुण सम संख्या वाली मंज़िल पर रहता है। वरुण अर्जुन के ठीक नीचे रहता है। प्रश्न: व्यवस्था के आधार पर निम्नलिखित चार जोड़ों में से तीन किसी निश्चित प्रकार से समान हैं। कौन-सा जोड़ा समूह से संबंधित नहीं है?","optionsHi":["वसीम – तान्या","उदय – वसीम","यामिनी – उदय","अर्जुन – ज़ोया"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 7 से 1 तक: अर्जुन, वरुण, तान्या, वसीम, उदय, यामिनी, ज़ोया। वसीम – तान्या, उदय – वसीम, यामिनी – उदय में दूसरा व्यक्ति पहले के ठीक ऊपर रहता है; अर्जुन – ज़ोया इस पैटर्न का पालन नहीं करता।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-174","question":"Study the information and answer the question. Seven persons A, B, C, D, E, F and G live on the 7 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 7. D lives on floor 6. Exactly two persons live between D and A. C lives on floor 5. C lives somewhere below G. E lives on floor 2. B lives neither at the top nor at the bottom. Question: How many persons live between D and F?","options":["2","3","4","5"],"answer":2,"explanation":"Final arrangement: From floor 7 down to 1: G, D, C, B, A, E, F. Between D and F are E, A, B, C, i.e. 4.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति A, B, C, D, E, F और G एक इमारत की 7 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 7 है। D मंज़िल 6 पर रहता है। D और A के बीच ठीक दो व्यक्ति रहते हैं। C मंज़िल 5 पर रहता है। C, G से कहीं नीचे रहता है। E मंज़िल 2 पर रहता है। B न सबसे ऊपर रहता है न सबसे नीचे। प्रश्न: D और F के बीच कितने व्यक्ति रहते हैं?","optionsHi":["2","3","4","5"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 7 से 1 तक: G, D, C, B, A, E, F। D और F के बीच E, A, B, C हैं, यानी 4।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-175","question":"Study the information and answer the question. Seven persons A, B, C, D, E, F and G live on the 7 floors of a building, one on each floor; the lowest floor is numbered 1 and the top floor 7. D lives on floor 6. Exactly two persons live between D and A. C lives on floor 5. C lives somewhere below G. E lives on floor 2. B lives neither at the top nor at the bottom. Question: On which floor does B live?","options":["4","5","6","7"],"answer":0,"explanation":"Final arrangement: From floor 7 down to 1: G, D, C, B, A, E, F. B lives on floor 4.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति A, B, C, D, E, F और G एक इमारत की 7 मंज़िलों पर रहते हैं, प्रत्येक मंज़िल पर एक; सबसे निचली मंज़िल 1 और सबसे ऊपरी मंज़िल 7 है। D मंज़िल 6 पर रहता है। D और A के बीच ठीक दो व्यक्ति रहते हैं। C मंज़िल 5 पर रहता है। C, G से कहीं नीचे रहता है। E मंज़िल 2 पर रहता है। B न सबसे ऊपर रहता है न सबसे नीचे। प्रश्न: B किस मंज़िल पर रहता है?","optionsHi":["4","5","6","7"],"explanationHi":"अंतिम व्यवस्था: मंज़िल 7 से 1 तक: G, D, C, B, A, E, F। B मंज़िल 4 पर रहता है।","subtopic":"floor-puzzles"},
  {"id":"reason-seating-puzzles-176","question":"Study the information and answer the question. Eight persons A, B, C, D, E, F, G and H sit around a circular table, equally spaced; some face the centre and the others face away from it. A faces the centre. E sits third to the right of A. C sits second to the left of A and faces the centre. H is an immediate neighbour of C and faces the same direction as C. G sits second to the right of B. F and D are both immediate neighbours of A. F faces away from the centre. Exactly three persons face away from the centre. The two immediate neighbours of D face opposite directions. Question: Who sits second to the right of G?","options":["D","B","A","H"],"answer":2,"explanation":"Arrangement (clockwise): A (centre), F (out), C (centre), H (centre), B (out), E (centre), G (out), D (centre). G faces away from the centre, so his right runs clockwise: D, then A. Treating G as centre-facing gives B.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति A, B, C, D, E, F, G और H एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; कुछ का मुख केंद्र की ओर और बाकी का केंद्र से बाहर की ओर है। A का मुख केंद्र की ओर है। E, A के दाएँ से तीसरे स्थान पर बैठा है। C, A के बाएँ से दूसरे स्थान पर बैठा है और उसका मुख केंद्र की ओर है। H, C का निकटतम पड़ोसी है और उसका मुख C की ही दिशा में है। G, B के दाएँ से दूसरे स्थान पर बैठा है। F और D दोनों A के निकटतम पड़ोसी हैं। F का मुख केंद्र से बाहर की ओर है। ठीक तीन व्यक्तियों का मुख केंद्र से बाहर की ओर है। D के दोनों निकटतम पड़ोसियों का मुख विपरीत दिशाओं में है। प्रश्न: G के दाएँ से दूसरे स्थान पर कौन बैठा है?","optionsHi":["D","B","A","H"],"explanationHi":"व्यवस्था (दक्षिणावर्त): A (केंद्र), F (बाहर), C (केंद्र), H (केंद्र), B (बाहर), E (केंद्र), G (बाहर), D (केंद्र)। G का मुख केंद्र से बाहर की ओर है, इसलिए उसका दायाँ दक्षिणावर्त चलता है: D, फिर A। G को केंद्र की ओर मुख वाला मान लेने पर B मिलता है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-177","question":"Study the information and answer the question. Eight persons A, B, C, D, E, F, G and H sit around a circular table, equally spaced; some face the centre and the others face away from it. A faces the centre. E sits third to the right of A. C sits second to the left of A and faces the centre. H is an immediate neighbour of C and faces the same direction as C. G sits second to the right of B. F and D are both immediate neighbours of A. F faces away from the centre. Exactly three persons face away from the centre. The two immediate neighbours of D face opposite directions. Question: How many persons sit between H and D, counting from the left of H?","options":["2","4","3","1"],"answer":2,"explanation":"Arrangement (clockwise): A (centre), F (out), C (centre), H (centre), B (out), E (centre), G (out), D (centre). H faces the centre, so his left runs clockwise: B, E, G, and then D, so 3 persons sit in between. Including D in the count gives the trap answer 4.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति A, B, C, D, E, F, G और H एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; कुछ का मुख केंद्र की ओर और बाकी का केंद्र से बाहर की ओर है। A का मुख केंद्र की ओर है। E, A के दाएँ से तीसरे स्थान पर बैठा है। C, A के बाएँ से दूसरे स्थान पर बैठा है और उसका मुख केंद्र की ओर है। H, C का निकटतम पड़ोसी है और उसका मुख C की ही दिशा में है। G, B के दाएँ से दूसरे स्थान पर बैठा है। F और D दोनों A के निकटतम पड़ोसी हैं। F का मुख केंद्र से बाहर की ओर है। ठीक तीन व्यक्तियों का मुख केंद्र से बाहर की ओर है। D के दोनों निकटतम पड़ोसियों का मुख विपरीत दिशाओं में है। प्रश्न: H के बाएँ से गिनने पर H और D के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["2","4","3","1"],"explanationHi":"व्यवस्था (दक्षिणावर्त): A (केंद्र), F (बाहर), C (केंद्र), H (केंद्र), B (बाहर), E (केंद्र), G (बाहर), D (केंद्र)। H का मुख केंद्र की ओर है, इसलिए उसका बायाँ दक्षिणावर्त चलता है: B, E, G, और फिर D, इसलिए बीच में 3 व्यक्ति बैठे हैं। D को भी गिन लेने पर जाल का उत्तर 4 मिलता है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-178","question":"Study the information and answer the question. Eight persons A, B, C, D, E, F, G and H sit around a circular table, equally spaced; some face the centre and the others face away from it. A faces the centre. E sits third to the right of A. C sits second to the left of A and faces the centre. H is an immediate neighbour of C and faces the same direction as C. G sits second to the right of B. F and D are both immediate neighbours of A. F faces away from the centre. Exactly three persons face away from the centre. The two immediate neighbours of D face opposite directions. Question: Which of the following pairs consists of two persons who both face away from the centre?","options":["B and E","G and D","C and F","F and G"],"answer":3,"explanation":"Arrangement (clockwise): A (centre), F (out), C (centre), H (centre), B (out), E (centre), G (out), D (centre). The three outward-facing persons are F, B and G, so F and G is the only pair here with both facing away.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति A, B, C, D, E, F, G और H एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; कुछ का मुख केंद्र की ओर और बाकी का केंद्र से बाहर की ओर है। A का मुख केंद्र की ओर है। E, A के दाएँ से तीसरे स्थान पर बैठा है। C, A के बाएँ से दूसरे स्थान पर बैठा है और उसका मुख केंद्र की ओर है। H, C का निकटतम पड़ोसी है और उसका मुख C की ही दिशा में है। G, B के दाएँ से दूसरे स्थान पर बैठा है। F और D दोनों A के निकटतम पड़ोसी हैं। F का मुख केंद्र से बाहर की ओर है। ठीक तीन व्यक्तियों का मुख केंद्र से बाहर की ओर है। D के दोनों निकटतम पड़ोसियों का मुख विपरीत दिशाओं में है। प्रश्न: निम्नलिखित में से किस जोड़े के दोनों व्यक्तियों का मुख केंद्र से बाहर की ओर है?","optionsHi":["B और E","G और D","C और F","F और G"],"explanationHi":"व्यवस्था (दक्षिणावर्त): A (केंद्र), F (बाहर), C (केंद्र), H (केंद्र), B (बाहर), E (केंद्र), G (बाहर), D (केंद्र)। बाहर की ओर मुख वाले तीन व्यक्ति F, B और G हैं, इसलिए यहाँ F और G ही ऐसा जोड़ा है जिसके दोनों का मुख बाहर की ओर है।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-179","question":"Study the information and answer the question. Eight persons A, B, C, D, E, F, G and H sit around a circular table, equally spaced; some face the centre and the others face away from it. A faces the centre. E sits third to the right of A. C sits second to the left of A and faces the centre. H is an immediate neighbour of C and faces the same direction as C. G sits second to the right of B. F and D are both immediate neighbours of A. F faces away from the centre. Exactly three persons face away from the centre. The two immediate neighbours of D face opposite directions. Question: What is the position of B with respect to D?","options":["Third to the left","Third to the right","Fifth to the right","Second to the left"],"answer":1,"explanation":"Arrangement (clockwise): A (centre), F (out), C (centre), H (centre), B (out), E (centre), G (out), D (centre). D faces the centre, so D's right runs anticlockwise: G, E, B. B is third to the right of D (and fifth to the left).","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। आठ व्यक्ति A, B, C, D, E, F, G और H एक वृत्ताकार मेज़ के चारों ओर समान दूरी पर बैठे हैं; कुछ का मुख केंद्र की ओर और बाकी का केंद्र से बाहर की ओर है। A का मुख केंद्र की ओर है। E, A के दाएँ से तीसरे स्थान पर बैठा है। C, A के बाएँ से दूसरे स्थान पर बैठा है और उसका मुख केंद्र की ओर है। H, C का निकटतम पड़ोसी है और उसका मुख C की ही दिशा में है। G, B के दाएँ से दूसरे स्थान पर बैठा है। F और D दोनों A के निकटतम पड़ोसी हैं। F का मुख केंद्र से बाहर की ओर है। ठीक तीन व्यक्तियों का मुख केंद्र से बाहर की ओर है। D के दोनों निकटतम पड़ोसियों का मुख विपरीत दिशाओं में है। प्रश्न: D के सापेक्ष B की स्थिति क्या है?","optionsHi":["बाएँ से तीसरा","दाएँ से तीसरा","दाएँ से पाँचवाँ","बाएँ से दूसरा"],"explanationHi":"व्यवस्था (दक्षिणावर्त): A (केंद्र), F (बाहर), C (केंद्र), H (केंद्र), B (बाहर), E (केंद्र), G (बाहर), D (केंद्र)। D का मुख केंद्र की ओर है, इसलिए उसका दायाँ वामावर्त चलता है: G, E, B। B, D के दाएँ से तीसरे स्थान पर है (और बाएँ से पाँचवें)।","subtopic":"circular"},
  {"id":"reason-seating-puzzles-180","question":"Study the information and answer the question. Seven persons J, K, L, M, N, O and P sit in a row of seats numbered 1 to 7 from west to east; some face north and the others face south. J sits on seat 3 and faces north. O sits to the immediate right of J. K sits second to the left of L. K is an immediate neighbour of N and both face the same direction. L and M sit at the two ends of the row and face the same direction. P faces the direction opposite to M. Exactly three persons face south. Question: Who sits to the immediate left of N?","options":["No one","L","K","O"],"answer":1,"explanation":"Arrangement, seats 1 to 7: M (north), P (south), J (north), O (north), K (south), N (south), L (north). N faces south, so N's left is towards the east: seat 7, L. K is N's immediate right.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति J, K, L, M, N, O और P पश्चिम से पूर्व की ओर 1 से 7 तक क्रमांकित सीटों की एक पंक्ति में बैठे हैं; कुछ का मुख उत्तर की ओर और बाकी का दक्षिण की ओर है। J सीट 3 पर बैठा है और उसका मुख उत्तर की ओर है। O, J के ठीक दाएँ बैठा है। K, L के बाएँ से दूसरे स्थान पर बैठा है। K, N का निकटतम पड़ोसी है और दोनों का मुख एक ही दिशा में है। L और M पंक्ति के दोनों छोरों पर बैठे हैं और उनका मुख एक ही दिशा में है। P का मुख M की विपरीत दिशा में है। ठीक तीन व्यक्तियों का मुख दक्षिण की ओर है। प्रश्न: N के ठीक बाएँ कौन बैठा है?","optionsHi":["कोई नहीं","L","K","O"],"explanationHi":"व्यवस्था, सीट 1 से 7: M (उत्तर), P (दक्षिण), J (उत्तर), O (उत्तर), K (दक्षिण), N (दक्षिण), L (उत्तर)। N का मुख दक्षिण की ओर है, इसलिए N का बायाँ पूर्व की ओर है: सीट 7, यानी L। K, N के ठीक दाएँ है।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-181","question":"Study the information and answer the question. Seven persons J, K, L, M, N, O and P sit in a row of seats numbered 1 to 7 from west to east; some face north and the others face south. J sits on seat 3 and faces north. O sits to the immediate right of J. K sits second to the left of L. K is an immediate neighbour of N and both face the same direction. L and M sit at the two ends of the row and face the same direction. P faces the direction opposite to M. Exactly three persons face south. Question: Who sits to the immediate right of P, and which way does that person face?","options":["M, facing north","J, facing south","J, facing north","M, facing south"],"answer":0,"explanation":"Arrangement, seats 1 to 7: M (north), P (south), J (north), O (north), K (south), N (south), L (north). P faces south, so P's right is towards the west: seat 1, M, who faces north (same as L).","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति J, K, L, M, N, O और P पश्चिम से पूर्व की ओर 1 से 7 तक क्रमांकित सीटों की एक पंक्ति में बैठे हैं; कुछ का मुख उत्तर की ओर और बाकी का दक्षिण की ओर है। J सीट 3 पर बैठा है और उसका मुख उत्तर की ओर है। O, J के ठीक दाएँ बैठा है। K, L के बाएँ से दूसरे स्थान पर बैठा है। K, N का निकटतम पड़ोसी है और दोनों का मुख एक ही दिशा में है। L और M पंक्ति के दोनों छोरों पर बैठे हैं और उनका मुख एक ही दिशा में है। P का मुख M की विपरीत दिशा में है। ठीक तीन व्यक्तियों का मुख दक्षिण की ओर है। प्रश्न: P के ठीक दाएँ कौन बैठा है, और उस व्यक्ति का मुख किस ओर है?","optionsHi":["M, उत्तर की ओर मुख","J, दक्षिण की ओर मुख","J, उत्तर की ओर मुख","M, दक्षिण की ओर मुख"],"explanationHi":"व्यवस्था, सीट 1 से 7: M (उत्तर), P (दक्षिण), J (उत्तर), O (उत्तर), K (दक्षिण), N (दक्षिण), L (उत्तर)। P का मुख दक्षिण की ओर है, इसलिए P का दायाँ पश्चिम की ओर है: सीट 1, यानी M, जिसका मुख उत्तर की ओर है (L के समान)।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-182","question":"Study the information and answer the question. Seven persons J, K, L, M, N, O and P sit in a row of seats numbered 1 to 7 from west to east; some face north and the others face south. J sits on seat 3 and faces north. O sits to the immediate right of J. K sits second to the left of L. K is an immediate neighbour of N and both face the same direction. L and M sit at the two ends of the row and face the same direction. P faces the direction opposite to M. Exactly three persons face south. Question: How many persons sit to the left of K?","options":["2","4","5","3"],"answer":0,"explanation":"Arrangement, seats 1 to 7: M (north), P (south), J (north), O (north), K (south), N (south), L (north). K faces south, so K's left is towards the east: N and L, i.e. 2 persons. 4 is the count to the west, which is K's right.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO Mains","questionHi":"जानकारी का अध्ययन कीजिए और प्रश्न का उत्तर दीजिए। सात व्यक्ति J, K, L, M, N, O और P पश्चिम से पूर्व की ओर 1 से 7 तक क्रमांकित सीटों की एक पंक्ति में बैठे हैं; कुछ का मुख उत्तर की ओर और बाकी का दक्षिण की ओर है। J सीट 3 पर बैठा है और उसका मुख उत्तर की ओर है। O, J के ठीक दाएँ बैठा है। K, L के बाएँ से दूसरे स्थान पर बैठा है। K, N का निकटतम पड़ोसी है और दोनों का मुख एक ही दिशा में है। L और M पंक्ति के दोनों छोरों पर बैठे हैं और उनका मुख एक ही दिशा में है। P का मुख M की विपरीत दिशा में है। ठीक तीन व्यक्तियों का मुख दक्षिण की ओर है। प्रश्न: K के बाएँ कितने व्यक्ति बैठे हैं?","optionsHi":["2","4","5","3"],"explanationHi":"व्यवस्था, सीट 1 से 7: M (उत्तर), P (दक्षिण), J (उत्तर), O (उत्तर), K (दक्षिण), N (दक्षिण), L (उत्तर)। K का मुख दक्षिण की ओर है, इसलिए K का बायाँ पूर्व की ओर है: N और L, यानी 2 व्यक्ति। 4 पश्चिम की ओर की गिनती है, जो K का दायाँ है।","subtopic":"linear-row"},
  {"id":"reason-seating-puzzles-183","question":"Six persons K, L, M, N, O and P sit in a straight row, all facing north. Clues: (1) P does not sit at either extreme end. (2) L sits somewhere to the left of P. (3) M sits second to the right of K. (4) M sits next to O. (5) N does not sit at either extreme end. (6) Exactly 1 person sits between P and L. Who sits third to the right of L?","options":["O","K","M","N"],"answer":1,"explanation":"Using the clues one by one (the fixed-gap and end clues first, the negative clues to cut the rest) leaves exactly one arrangement, west to east: L↑, N↑, P↑, K↑, O↑, M↑; ↑ = faces north and ↓ = faces south. The answer is read off this arrangement. Answer: K.","difficulty":"moderate","questionHi":"छह व्यक्ति K, L, M, N, O और P एक सीधी पंक्ति में बैठे हैं और सभी उत्तर की ओर मुख किए हुए हैं। संकेत: (1) P किसी भी छोर पर नहीं बैठा है। (2) L, P के बाईं ओर कहीं बैठा है। (3) M, K के दाईं ओर दूसरे स्थान पर बैठा है। (4) M, O के बगल में बैठा है। (5) N किसी भी छोर पर नहीं बैठा है। (6) P और L के बीच ठीक 1 व्यक्ति बैठे हैं। L के दाईं ओर तीसरे स्थान पर कौन बैठा है?","optionsHi":["O","K","M","N"],"explanationHi":"संकेतों को एक-एक करके लगाने पर (पहले निश्चित दूरी और छोर वाले संकेत, फिर नकारात्मक संकेतों से शेष विकल्प हटाकर) केवल एक ही व्यवस्था बचती है, पश्चिम से पूर्व: L↑, N↑, P↑, K↑, O↑, M↑; ↑ का अर्थ उत्तर की ओर मुख और ↓ का अर्थ दक्षिण की ओर मुख है। उत्तर इसी व्यवस्था से मिलता है। उत्तर: K।","subtopic":"linear-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-184","question":"Seven persons A, B, C, D, E, F and G sit in a straight row. A, B and D face north, while C, E, F and G face south. Left and right are taken from each person's own point of view. Clues: (1) B sits somewhere between G and F. (2) C sits next to A. (3) A sits next to B. (4) Exactly 2 persons sit to the left of G. (5) E does not sit at either extreme end. (6) C sits somewhere to the left of B. How many persons sit between B and C?","options":["0","1","3","5"],"answer":1,"explanation":"Using the clues one by one (the fixed-gap and end clues first, the negative clues to cut the rest) leaves exactly one arrangement, west to east: F↓, C↓, A↑, B↑, G↓, E↓, D↑; ↑ = faces north and ↓ = faces south. The answer is read off this arrangement. Answer: 1.","difficulty":"hard","questionHi":"सात व्यक्ति A, B, C, D, E, F और G एक सीधी पंक्ति में बैठे हैं। A, B और D उत्तर की ओर मुख किए हुए हैं, जबकि C, E, F और G दक्षिण की ओर मुख किए हुए हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) B, G और F के बीच में कहीं बैठा है। (2) C, A के बगल में बैठा है। (3) A, B के बगल में बैठा है। (4) G के बाईं ओर ठीक 2 व्यक्ति बैठे हैं। (5) E किसी भी छोर पर नहीं बैठा है। (6) C, B के बाईं ओर कहीं बैठा है। B और C के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["0","1","3","5"],"explanationHi":"संकेतों को एक-एक करके लगाने पर (पहले निश्चित दूरी और छोर वाले संकेत, फिर नकारात्मक संकेतों से शेष विकल्प हटाकर) केवल एक ही व्यवस्था बचती है, पश्चिम से पूर्व: F↓, C↓, A↑, B↑, G↓, E↓, D↑; ↑ का अर्थ उत्तर की ओर मुख और ↓ का अर्थ दक्षिण की ओर मुख है। उत्तर इसी व्यवस्था से मिलता है। उत्तर: 1।","subtopic":"linear-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-185","question":"Eight persons S, T, U, V, W, X, Y and Z sit in a straight row, all facing north. Clues: (1) V sits next to X. (2) Y sits at one of the two extreme ends of the row. (3) U sits next to Y. (4) T sits somewhere to the left of W. (5) W sits somewhere to the left of S. (6) Z sits somewhere to the left of U. (7) Z sits next to U. (8) Z sits next to V. Who sits second to the right of V?","options":["S","U","Y","Z"],"answer":1,"explanation":"Using the clues one by one (the fixed-gap and end clues first, the negative clues to cut the rest) leaves exactly one arrangement, west to east: T↑, W↑, S↑, X↑, V↑, Z↑, U↑, Y↑; ↑ = faces north and ↓ = faces south. The answer is read off this arrangement. Answer: U.","difficulty":"hard","questionHi":"आठ व्यक्ति S, T, U, V, W, X, Y और Z एक सीधी पंक्ति में बैठे हैं और सभी उत्तर की ओर मुख किए हुए हैं। संकेत: (1) V, X के बगल में बैठा है। (2) Y पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (3) U, Y के बगल में बैठा है। (4) T, W के बाईं ओर कहीं बैठा है। (5) W, S के बाईं ओर कहीं बैठा है। (6) Z, U के बाईं ओर कहीं बैठा है। (7) Z, U के बगल में बैठा है। (8) Z, V के बगल में बैठा है। V के दाईं ओर दूसरे स्थान पर कौन बैठा है?","optionsHi":["S","U","Y","Z"],"explanationHi":"संकेतों को एक-एक करके लगाने पर (पहले निश्चित दूरी और छोर वाले संकेत, फिर नकारात्मक संकेतों से शेष विकल्प हटाकर) केवल एक ही व्यवस्था बचती है, पश्चिम से पूर्व: T↑, W↑, S↑, X↑, V↑, Z↑, U↑, Y↑; ↑ का अर्थ उत्तर की ओर मुख और ↓ का अर्थ दक्षिण की ओर मुख है। उत्तर इसी व्यवस्था से मिलता है। उत्तर: U।","subtopic":"linear-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-186","question":"Eight persons S, T, U, V, W, X, Y and Z sit in a straight row. S, T, X and Z face north, while U, V, W and Y face south. Left and right are taken from each person's own point of view. Clues: (1) U sits third to the left of S. (2) X does not sit at either extreme end. (3) X sits next to Y. (4) V sits to the immediate left of S. (5) T sits next to W. (6) X sits somewhere to the left of W. (7) U sits somewhere to the left of X. (8) T sits at one of the two extreme ends of the row. How many persons sit between S and Z?","options":["1","4","2","6"],"answer":0,"explanation":"Using the clues one by one (the fixed-gap and end clues first, the negative clues to cut the rest) leaves exactly one arrangement, west to east: T↑, W↓, U↓, Z↑, V↓, S↑, X↑, Y↓; ↑ = faces north and ↓ = faces south. The answer is read off this arrangement. Answer: 1.","difficulty":"very-hard","questionHi":"आठ व्यक्ति S, T, U, V, W, X, Y और Z एक सीधी पंक्ति में बैठे हैं। S, T, X और Z उत्तर की ओर मुख किए हुए हैं, जबकि U, V, W और Y दक्षिण की ओर मुख किए हुए हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) U, S के बाईं ओर तीसरे स्थान पर बैठा है। (2) X किसी भी छोर पर नहीं बैठा है। (3) X, Y के बगल में बैठा है। (4) V, S के ठीक बाईं ओर बैठा है। (5) T, W के बगल में बैठा है। (6) X, W के बाईं ओर कहीं बैठा है। (7) U, X के बाईं ओर कहीं बैठा है। (8) T पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। S और Z के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["1","4","2","6"],"explanationHi":"संकेतों को एक-एक करके लगाने पर (पहले निश्चित दूरी और छोर वाले संकेत, फिर नकारात्मक संकेतों से शेष विकल्प हटाकर) केवल एक ही व्यवस्था बचती है, पश्चिम से पूर्व: T↑, W↓, U↓, Z↑, V↓, S↑, X↑, Y↓; ↑ का अर्थ उत्तर की ओर मुख और ↓ का अर्थ दक्षिण की ओर मुख है। उत्तर इसी व्यवस्था से मिलता है। उत्तर: 1।","subtopic":"linear-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-187","question":"Eight persons D, E, F, G, H, I, J and K sit in a straight row. D, E, F and K face north, while G, H, I and J face south. Left and right are taken from each person's own point of view. Clues: (1) H sits next to G. (2) E sits to the immediate left of F. (3) D sits next to I. (4) J does not sit at either extreme end. (5) I does not sit at either extreme end. (6) K sits somewhere to the left of G. (7) K sits next to G. (8) F sits somewhere to the left of K. (9) F sits somewhere to the left of J. Which of the following persons sits at an extreme end of the row?","options":["D","H","J","E"],"answer":0,"explanation":"Using the clues one by one (the fixed-gap and end clues first, the negative clues to cut the rest) leaves exactly one arrangement, west to east: D↑, I↓, J↓, E↑, F↑, H↓, G↓, K↑; ↑ = faces north and ↓ = faces south. The answer is read off this arrangement. Answer: D.","difficulty":"very-hard","questionHi":"आठ व्यक्ति D, E, F, G, H, I, J और K एक सीधी पंक्ति में बैठे हैं। D, E, F और K उत्तर की ओर मुख किए हुए हैं, जबकि G, H, I और J दक्षिण की ओर मुख किए हुए हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) H, G के बगल में बैठा है। (2) E, F के ठीक बाईं ओर बैठा है। (3) D, I के बगल में बैठा है। (4) J किसी भी छोर पर नहीं बैठा है। (5) I किसी भी छोर पर नहीं बैठा है। (6) K, G के बाईं ओर कहीं बैठा है। (7) K, G के बगल में बैठा है। (8) F, K के बाईं ओर कहीं बैठा है। (9) F, J के बाईं ओर कहीं बैठा है। निम्नलिखित में से कौन पंक्ति के एक छोर पर बैठा है?","optionsHi":["D","H","J","E"],"explanationHi":"संकेतों को एक-एक करके लगाने पर (पहले निश्चित दूरी और छोर वाले संकेत, फिर नकारात्मक संकेतों से शेष विकल्प हटाकर) केवल एक ही व्यवस्था बचती है, पश्चिम से पूर्व: D↑, I↓, J↓, E↑, F↑, H↓, G↓, K↑; ↑ का अर्थ उत्तर की ओर मुख और ↓ का अर्थ दक्षिण की ओर मुख है। उत्तर इसी व्यवस्था से मिलता है। उत्तर: D।","subtopic":"linear-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-188","question":"Six persons K, L, M, N, O and P sit around a circular table, all facing the centre. Clues: (1) O and N are not immediate neighbours. (2) N and P are not immediate neighbours. (3) M sits second to the right of P. (4) P and K are not immediate neighbours. (5) K and M are immediate neighbours. Who sits exactly opposite K?","options":["O","P","M","N"],"answer":1,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (in = faces centre, out = faces outside; fixed up to a rotation of the table): K(in), M(in), O(in), P(in), L(in), N(in). The answer is read from it. Answer: P.","difficulty":"moderate","questionHi":"छह व्यक्ति K, L, M, N, O और P एक वृत्ताकार मेज़ के चारों ओर बैठे हैं और सभी केंद्र की ओर मुख किए हुए हैं। संकेत: (1) O और N एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (2) N और P एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (3) M, P के दाईं ओर दूसरे स्थान पर बैठा है। (4) P और K एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (5) K और M एक-दूसरे के ठीक बगल में बैठे हैं। K के ठीक सामने कौन बैठा है?","optionsHi":["O","P","M","N"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (in = केंद्र की ओर, out = बाहर की ओर; व्यवस्था मेज़ को घुमाने तक निश्चित है): K(in), M(in), O(in), P(in), L(in), N(in)। उत्तर इसी से मिलता है। उत्तर: P।","subtopic":"circular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-189","question":"Eight persons S, T, U, V, W, X, Y and Z sit around a circular table. T, V, W and Y face the centre, while S, U, X and Z face outside. Left and right are taken from each person's own point of view. Clues: (1) Exactly 2 persons sit between Z and U, counted along the shorter way round. (2) T and Y are not immediate neighbours. (3) Y and V are not immediate neighbours. (4) Exactly 1 person sits between X and Y, counted along the shorter way round. (5) X sits second to the left of W. (6) S does not sit opposite V. (7) Exactly 1 person sits between Z and Y, counted along the shorter way round. Who are the two immediate neighbours of W?","options":["T and V","S and Z","U and Z","S and Y"],"answer":0,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (in = faces centre, out = faces outside; fixed up to a rotation of the table): S(out), Z(out), V(in), W(in), T(in), X(out), U(out), Y(in). The answer is read from it. Answer: T and V.","difficulty":"hard","questionHi":"आठ व्यक्ति S, T, U, V, W, X, Y और Z एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। T, V, W और Y केंद्र की ओर मुख किए हुए हैं, जबकि S, U, X और Z बाहर की ओर मुख किए हुए हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) Z और U के बीच छोटे रास्ते से गिनने पर ठीक 2 व्यक्ति बैठे हैं। (2) T और Y एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (3) Y और V एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (4) X और Y के बीच छोटे रास्ते से गिनने पर ठीक 1 व्यक्ति बैठे हैं। (5) X, W के बाईं ओर दूसरे स्थान पर बैठा है। (6) S, V के ठीक सामने नहीं बैठा है। (7) Z और Y के बीच छोटे रास्ते से गिनने पर ठीक 1 व्यक्ति बैठे हैं। W के दोनों ओर के ठीक पड़ोसी कौन हैं?","optionsHi":["T और V","S और Z","U और Z","S और Y"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (in = केंद्र की ओर, out = बाहर की ओर; व्यवस्था मेज़ को घुमाने तक निश्चित है): S(out), Z(out), V(in), W(in), T(in), X(out), U(out), Y(in)। उत्तर इसी से मिलता है। उत्तर: T और V।","subtopic":"circular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-190","question":"Eight persons K, L, M, N, O, P, Q and R sit around a circular table. M, O, Q and R face the centre, while K, L, N and P face outside. Left and right are taken from each person's own point of view. Clues: (1) L does not sit opposite P. (2) Exactly 2 persons sit between N and M, counted along the shorter way round. (3) K sits second to the left of N. (4) O sits exactly opposite K. (5) R and K are not immediate neighbours. (6) L and K are not immediate neighbours. (7) M sits exactly opposite R. (8) L and P are not immediate neighbours. Who sits exactly opposite the person who sits second to the left of O?","options":["N","Q","M","R"],"answer":0,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (in = faces centre, out = faces outside; fixed up to a rotation of the table): K(out), P(out), N(out), R(in), O(in), Q(in), L(out), M(in). The answer is read from it. Answer: N.","difficulty":"hard","questionHi":"आठ व्यक्ति K, L, M, N, O, P, Q और R एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। M, O, Q और R केंद्र की ओर मुख किए हुए हैं, जबकि K, L, N और P बाहर की ओर मुख किए हुए हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) L, P के ठीक सामने नहीं बैठा है। (2) N और M के बीच छोटे रास्ते से गिनने पर ठीक 2 व्यक्ति बैठे हैं। (3) K, N के बाईं ओर दूसरे स्थान पर बैठा है। (4) O, K के ठीक सामने बैठा है। (5) R और K एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (6) L और K एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (7) M, R के ठीक सामने बैठा है। (8) L और P एक-दूसरे के ठीक बगल में नहीं बैठे हैं। O के बाईं ओर दूसरे स्थान पर बैठे व्यक्ति के ठीक सामने कौन बैठा है?","optionsHi":["N","Q","M","R"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (in = केंद्र की ओर, out = बाहर की ओर; व्यवस्था मेज़ को घुमाने तक निश्चित है): K(out), P(out), N(out), R(in), O(in), Q(in), L(out), M(in)। उत्तर इसी से मिलता है। उत्तर: N।","subtopic":"circular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-191","question":"Eight persons A, B, C, D, E, F, G and H sit around a circular table. B, C, D and F face the centre, while A, E, G and H face outside. Left and right are taken from each person's own point of view. Clues: (1) H and B are not immediate neighbours. (2) A sits third to the left of F. (3) B sits exactly opposite A. (4) F and D are not immediate neighbours. (5) F does not sit opposite C. (6) G does not sit opposite F. (7) B and C are not immediate neighbours. (8) Exactly 1 person sits between H and F, counted along the shorter way round. (9) A and D are not immediate neighbours. (10) B and D are not immediate neighbours. Who sits to the immediate right of C?","options":["G","B","E","F"],"answer":3,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (in = faces centre, out = faces outside; fixed up to a rotation of the table): A(out), E(out), D(in), G(out), B(in), F(in), C(in), H(out). The answer is read from it. Answer: F.","difficulty":"very-hard","questionHi":"आठ व्यक्ति A, B, C, D, E, F, G और H एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। B, C, D और F केंद्र की ओर मुख किए हुए हैं, जबकि A, E, G और H बाहर की ओर मुख किए हुए हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) H और B एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (2) A, F के बाईं ओर तीसरे स्थान पर बैठा है। (3) B, A के ठीक सामने बैठा है। (4) F और D एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (5) F, C के ठीक सामने नहीं बैठा है। (6) G, F के ठीक सामने नहीं बैठा है। (7) B और C एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (8) H और F के बीच छोटे रास्ते से गिनने पर ठीक 1 व्यक्ति बैठे हैं। (9) A और D एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (10) B और D एक-दूसरे के ठीक बगल में नहीं बैठे हैं। C के ठीक दाईं ओर कौन बैठा है?","optionsHi":["G","B","E","F"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (in = केंद्र की ओर, out = बाहर की ओर; व्यवस्था मेज़ को घुमाने तक निश्चित है): A(out), E(out), D(in), G(out), B(in), F(in), C(in), H(out)। उत्तर इसी से मिलता है। उत्तर: F।","subtopic":"circular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-192","question":"Eight persons P, Q, R, S, T, U, V and W sit around a circular table. Q, T, V and W face the centre, while P, R, S and U face outside. Left and right are taken from each person's own point of view. Clues: (1) R does not sit opposite T. (2) Q and V are not immediate neighbours. (3) Exactly 2 persons sit between S and Q, counted along the shorter way round. (4) S and P are immediate neighbours. (5) P and R are not immediate neighbours. (6) Q does not sit opposite R. (7) Q sits second to the left of P. (8) W sits exactly opposite S. (9) T and S are not immediate neighbours. (10) W and R are not immediate neighbours. How many persons sit between U and V, counted along the shorter way round?","options":["3","2","0","1"],"answer":1,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (in = faces centre, out = faces outside; fixed up to a rotation of the table): P(out), S(out), V(in), R(out), T(in), W(in), Q(in), U(out). The answer is read from it. Answer: 2.","difficulty":"very-hard","questionHi":"आठ व्यक्ति P, Q, R, S, T, U, V और W एक वृत्ताकार मेज़ के चारों ओर बैठे हैं। Q, T, V और W केंद्र की ओर मुख किए हुए हैं, जबकि P, R, S और U बाहर की ओर मुख किए हुए हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) R, T के ठीक सामने नहीं बैठा है। (2) Q और V एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (3) S और Q के बीच छोटे रास्ते से गिनने पर ठीक 2 व्यक्ति बैठे हैं। (4) S और P एक-दूसरे के ठीक बगल में बैठे हैं। (5) P और R एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (6) Q, R के ठीक सामने नहीं बैठा है। (7) Q, P के बाईं ओर दूसरे स्थान पर बैठा है। (8) W, S के ठीक सामने बैठा है। (9) T और S एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (10) W और R एक-दूसरे के ठीक बगल में नहीं बैठे हैं। U और V के बीच छोटे रास्ते से गिनने पर कितने व्यक्ति बैठे हैं?","optionsHi":["3","2","0","1"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (in = केंद्र की ओर, out = बाहर की ओर; व्यवस्था मेज़ को घुमाने तक निश्चित है): P(out), S(out), V(in), R(out), T(in), W(in), Q(in), U(out)। उत्तर इसी से मिलता है। उत्तर: 2।","subtopic":"circular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-193","question":"Eight persons A, B, C, D, E, F, G and H sit around a square table; four sit at the corners and four sit in the middle of the sides. Those at the corners face outside, while those in the middle of the sides face the centre. Left and right are taken from each person's own point of view. Clues: (1) C sits second to the left of D. (2) F sits exactly opposite D. (3) G sits third to the left of E. (4) A sits in the middle of a side of the table. (5) G and C are not immediate neighbours. (6) A and C are not immediate neighbours. (7) H and D are immediate neighbours. Who sits exactly opposite the person who sits to the immediate left of D?","options":["G","B","A","F"],"answer":2,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (the arrangement is fixed up to a rotation of the table): A, F, B, C, E, D, H, G. The answer is read from it. Answer: A.","difficulty":"hard","questionHi":"आठ व्यक्ति A, B, C, D, E, F, G और H एक वर्गाकार मेज़ के चारों ओर बैठे हैं; चार कोनों पर और चार भुजाओं के मध्य में बैठे हैं। कोनों पर बैठे व्यक्ति बाहर की ओर मुख किए हुए हैं, जबकि भुजाओं के मध्य में बैठे व्यक्ति केंद्र की ओर मुख किए हुए हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) C, D के बाईं ओर दूसरे स्थान पर बैठा है। (2) F, D के ठीक सामने बैठा है। (3) G, E के बाईं ओर तीसरे स्थान पर बैठा है। (4) A मेज़ की एक भुजा के मध्य में बैठा है। (5) G और C एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (6) A और C एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (7) H और D एक-दूसरे के ठीक बगल में बैठे हैं। D के ठीक बाईं ओर बैठे व्यक्ति के ठीक सामने कौन बैठा है?","optionsHi":["G","B","A","F"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (व्यवस्था मेज़ को घुमाने तक निश्चित है): A, F, B, C, E, D, H, G। उत्तर इसी से मिलता है। उत्तर: A।","subtopic":"square-rectangular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-194","question":"Eight persons A, B, C, D, E, F, G and H sit around a square table; four sit at the corners and four sit in the middle of the sides. Those at the corners face the centre, while those in the middle of the sides face outside. Left and right are taken from each person's own point of view. Clues: (1) A sits second to the right of F. (2) G sits third to the left of D. (3) B sits second to the left of E. (4) Exactly 2 persons sit between B and H, counted along the shorter way round. (5) G sits at a corner of the table. (6) E sits at a corner of the table. (7) C sits exactly opposite E. Who sits second to the left of B?","options":["A","D","C","H"],"answer":2,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (the arrangement is fixed up to a rotation of the table): A, G, H, E, D, B, F, C. The answer is read from it. Answer: C.","difficulty":"hard","questionHi":"आठ व्यक्ति A, B, C, D, E, F, G और H एक वर्गाकार मेज़ के चारों ओर बैठे हैं; चार कोनों पर और चार भुजाओं के मध्य में बैठे हैं। कोनों पर बैठे व्यक्ति केंद्र की ओर मुख किए हुए हैं, जबकि भुजाओं के मध्य में बैठे व्यक्ति बाहर की ओर मुख किए हुए हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) A, F के दाईं ओर दूसरे स्थान पर बैठा है। (2) G, D के बाईं ओर तीसरे स्थान पर बैठा है। (3) B, E के बाईं ओर दूसरे स्थान पर बैठा है। (4) B और H के बीच छोटे रास्ते से गिनने पर ठीक 2 व्यक्ति बैठे हैं। (5) G मेज़ के एक कोने पर बैठा है। (6) E मेज़ के एक कोने पर बैठा है। (7) C, E के ठीक सामने बैठा है। B के बाईं ओर दूसरे स्थान पर कौन बैठा है?","optionsHi":["A","D","C","H"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (व्यवस्था मेज़ को घुमाने तक निश्चित है): A, G, H, E, D, B, F, C। उत्तर इसी से मिलता है। उत्तर: C।","subtopic":"square-rectangular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-195","question":"Eight persons A, B, C, D, E, F, G and H sit around a square table; four sit at the corners and four sit in the middle of the sides. Those at the corners face outside, while those in the middle of the sides face the centre. Left and right are taken from each person's own point of view. Clues: (1) B sits in the middle of a side of the table. (2) E and B are the two immediate neighbours of F. (3) G sits at a corner of the table. (4) H sits exactly opposite F. (5) H sits to the immediate left of A. (6) D and B are not immediate neighbours. (7) D sits second to the left of F. Who are the two immediate neighbours of D?","options":["C and E","A and H","G and H","A and E"],"answer":0,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (the arrangement is fixed up to a rotation of the table): A, H, C, D, E, F, B, G. The answer is read from it. Answer: C and E.","difficulty":"hard","questionHi":"आठ व्यक्ति A, B, C, D, E, F, G और H एक वर्गाकार मेज़ के चारों ओर बैठे हैं; चार कोनों पर और चार भुजाओं के मध्य में बैठे हैं। कोनों पर बैठे व्यक्ति बाहर की ओर मुख किए हुए हैं, जबकि भुजाओं के मध्य में बैठे व्यक्ति केंद्र की ओर मुख किए हुए हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) B मेज़ की एक भुजा के मध्य में बैठा है। (2) E और B, F के दोनों ओर के ठीक पड़ोसी हैं। (3) G मेज़ के एक कोने पर बैठा है। (4) H, F के ठीक सामने बैठा है। (5) H, A के ठीक बाईं ओर बैठा है। (6) D और B एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (7) D, F के बाईं ओर दूसरे स्थान पर बैठा है। D के दोनों ओर के ठीक पड़ोसी कौन हैं?","optionsHi":["C और E","A और H","G और H","A और E"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (व्यवस्था मेज़ को घुमाने तक निश्चित है): A, H, C, D, E, F, B, G। उत्तर इसी से मिलता है। उत्तर: C और E।","subtopic":"square-rectangular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-196","question":"Eight persons S, T, U, V, W, X, Y and Z sit around a square table; four sit at the corners and four sit in the middle of the sides. Those at the corners face outside, while those in the middle of the sides face the centre. Left and right are taken from each person's own point of view. Clues: (1) S sits third to the right of U. (2) V and X are not immediate neighbours. (3) Y does not sit opposite W. (4) V sits in the middle of a side of the table. (5) Z and W are not immediate neighbours. (6) Exactly 2 persons sit between Z and V, counted along the shorter way round. (7) W and Y are not immediate neighbours. (8) W sits in the middle of a side of the table. (9) S sits to the immediate right of Z. Who sits exactly opposite the person who sits to the immediate right of Y?","options":["X","V","U","S"],"answer":0,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (the arrangement is fixed up to a rotation of the table): S, Y, V, T, W, U, X, Z. The answer is read from it. Answer: X.","difficulty":"very-hard","questionHi":"आठ व्यक्ति S, T, U, V, W, X, Y और Z एक वर्गाकार मेज़ के चारों ओर बैठे हैं; चार कोनों पर और चार भुजाओं के मध्य में बैठे हैं। कोनों पर बैठे व्यक्ति बाहर की ओर मुख किए हुए हैं, जबकि भुजाओं के मध्य में बैठे व्यक्ति केंद्र की ओर मुख किए हुए हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) S, U के दाईं ओर तीसरे स्थान पर बैठा है। (2) V और X एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (3) Y, W के ठीक सामने नहीं बैठा है। (4) V मेज़ की एक भुजा के मध्य में बैठा है। (5) Z और W एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (6) Z और V के बीच छोटे रास्ते से गिनने पर ठीक 2 व्यक्ति बैठे हैं। (7) W और Y एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (8) W मेज़ की एक भुजा के मध्य में बैठा है। (9) S, Z के ठीक दाईं ओर बैठा है। Y के ठीक दाईं ओर बैठे व्यक्ति के ठीक सामने कौन बैठा है?","optionsHi":["X","V","U","S"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (व्यवस्था मेज़ को घुमाने तक निश्चित है): S, Y, V, T, W, U, X, Z। उत्तर इसी से मिलता है। उत्तर: X।","subtopic":"square-rectangular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-197","question":"Eight persons J, K, L, M, N, O, P and Q sit around a square table; four sit at the corners and four sit in the middle of the sides. Those at the corners face the centre, while those in the middle of the sides face outside. Left and right are taken from each person's own point of view. Clues: (1) O sits in the middle of a side of the table. (2) N and K are the two immediate neighbours of L. (3) L sits to the immediate right of K. (4) N does not sit opposite O. (5) M does not sit opposite Q. (6) M sits at a corner of the table. (7) Exactly 2 persons sit between K and M, counted along the shorter way round. (8) Exactly 2 persons sit between O and Q, counted along the shorter way round. (9) J sits in the middle of a side of the table. Who sits exactly opposite the person who sits to the immediate right of J?","options":["L","N","K","P"],"answer":3,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (the arrangement is fixed up to a rotation of the table): J, Q, K, L, N, P, O, M. The answer is read from it. Answer: P.","difficulty":"very-hard","questionHi":"आठ व्यक्ति J, K, L, M, N, O, P और Q एक वर्गाकार मेज़ के चारों ओर बैठे हैं; चार कोनों पर और चार भुजाओं के मध्य में बैठे हैं। कोनों पर बैठे व्यक्ति केंद्र की ओर मुख किए हुए हैं, जबकि भुजाओं के मध्य में बैठे व्यक्ति बाहर की ओर मुख किए हुए हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) O मेज़ की एक भुजा के मध्य में बैठा है। (2) N और K, L के दोनों ओर के ठीक पड़ोसी हैं। (3) L, K के ठीक दाईं ओर बैठा है। (4) N, O के ठीक सामने नहीं बैठा है। (5) M, Q के ठीक सामने नहीं बैठा है। (6) M मेज़ के एक कोने पर बैठा है। (7) K और M के बीच छोटे रास्ते से गिनने पर ठीक 2 व्यक्ति बैठे हैं। (8) O और Q के बीच छोटे रास्ते से गिनने पर ठीक 2 व्यक्ति बैठे हैं। (9) J मेज़ की एक भुजा के मध्य में बैठा है। J के ठीक दाईं ओर बैठे व्यक्ति के ठीक सामने कौन बैठा है?","optionsHi":["L","N","K","P"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (व्यवस्था मेज़ को घुमाने तक निश्चित है): J, Q, K, L, N, P, O, M। उत्तर इसी से मिलता है। उत्तर: P।","subtopic":"square-rectangular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-198","question":"Eight persons P, Q, R, S, T, U, V and W sit around a square table; four sit at the corners and four sit in the middle of the sides. Those at the corners face outside, while those in the middle of the sides face the centre. Left and right are taken from each person's own point of view. Clues: (1) T does not sit opposite P. (2) W sits second to the left of V. (3) W and R are not immediate neighbours. (4) P and Q are immediate neighbours. (5) S and U are not immediate neighbours. (6) P does not sit opposite R. (7) Q sits at a corner of the table. (8) T and R are not immediate neighbours. (9) S does not sit opposite P. (10) W sits to the immediate left of P. Who sits to the immediate right of T?","options":["S","P","W","R"],"answer":2,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (the arrangement is fixed up to a rotation of the table): P, W, T, V, U, R, S, Q. The answer is read from it. Answer: W.","difficulty":"very-hard","questionHi":"आठ व्यक्ति P, Q, R, S, T, U, V और W एक वर्गाकार मेज़ के चारों ओर बैठे हैं; चार कोनों पर और चार भुजाओं के मध्य में बैठे हैं। कोनों पर बैठे व्यक्ति बाहर की ओर मुख किए हुए हैं, जबकि भुजाओं के मध्य में बैठे व्यक्ति केंद्र की ओर मुख किए हुए हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) T, P के ठीक सामने नहीं बैठा है। (2) W, V के बाईं ओर दूसरे स्थान पर बैठा है। (3) W और R एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (4) P और Q एक-दूसरे के ठीक बगल में बैठे हैं। (5) S और U एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (6) P, R के ठीक सामने नहीं बैठा है। (7) Q मेज़ के एक कोने पर बैठा है। (8) T और R एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (9) S, P के ठीक सामने नहीं बैठा है। (10) W, P के ठीक बाईं ओर बैठा है। T के ठीक दाईं ओर कौन बैठा है?","optionsHi":["S","P","W","R"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (व्यवस्था मेज़ को घुमाने तक निश्चित है): P, W, T, V, U, R, S, Q। उत्तर इसी से मिलता है। उत्तर: W।","subtopic":"square-rectangular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-199","question":"Eight persons K, L, M, N, O, P, Q and R sit around a rectangular table, all facing the centre: three persons on each of the two longer sides and one person on each of the two shorter sides. Clues: (1) P sits to the immediate right of N. (2) O sits third to the right of M. (3) O and Q are immediate neighbours. (4) M sits to the immediate right of L. (5) R sits exactly opposite M. (6) M sits second to the left of P. How many persons sit between R and N, counted along the shorter way round?","options":["1","0","3","2"],"answer":3,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (the arrangement is fixed up to a rotation of the table): K, Q, O, P, N, M, L, R. The answer is read from it. Answer: 2.","difficulty":"moderate","questionHi":"आठ व्यक्ति K, L, M, N, O, P, Q और R एक आयताकार मेज़ के चारों ओर बैठे हैं और सभी केंद्र की ओर मुख किए हुए हैं: दोनों लंबी भुजाओं में से प्रत्येक पर तीन व्यक्ति और दोनों छोटी भुजाओं में से प्रत्येक पर एक व्यक्ति। संकेत: (1) P, N के ठीक दाईं ओर बैठा है। (2) O, M के दाईं ओर तीसरे स्थान पर बैठा है। (3) O और Q एक-दूसरे के ठीक बगल में बैठे हैं। (4) M, L के ठीक दाईं ओर बैठा है। (5) R, M के ठीक सामने बैठा है। (6) M, P के बाईं ओर दूसरे स्थान पर बैठा है। R और N के बीच छोटे रास्ते से गिनने पर कितने व्यक्ति बैठे हैं?","optionsHi":["1","0","3","2"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (व्यवस्था मेज़ को घुमाने तक निश्चित है): K, Q, O, P, N, M, L, R। उत्तर इसी से मिलता है। उत्तर: 2।","subtopic":"square-rectangular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-200","question":"Eight persons K, L, M, N, O, P, Q and R sit around a rectangular table, all facing the centre: three persons on each of the two longer sides and one person on each of the two shorter sides. Clues: (1) Exactly 1 person sits between Q and M, counted along the shorter way round. (2) N sits on one of the two shorter sides of the table. (3) Q sits second to the left of K. (4) P sits exactly opposite L. (5) N and M are not immediate neighbours. (6) M sits third to the right of O. (7) Exactly 2 persons sit between M and L, counted along the shorter way round. Who sits exactly opposite the person who sits second to the left of P?","options":["L","Q","M","O"],"answer":3,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (the arrangement is fixed up to a rotation of the table): K, L, Q, P, M, R, N, O. The answer is read from it. Answer: O.","difficulty":"hard","questionHi":"आठ व्यक्ति K, L, M, N, O, P, Q और R एक आयताकार मेज़ के चारों ओर बैठे हैं और सभी केंद्र की ओर मुख किए हुए हैं: दोनों लंबी भुजाओं में से प्रत्येक पर तीन व्यक्ति और दोनों छोटी भुजाओं में से प्रत्येक पर एक व्यक्ति। संकेत: (1) Q और M के बीच छोटे रास्ते से गिनने पर ठीक 1 व्यक्ति बैठे हैं। (2) N मेज़ की दोनों छोटी भुजाओं में से किसी एक पर बैठा है। (3) Q, K के बाईं ओर दूसरे स्थान पर बैठा है। (4) P, L के ठीक सामने बैठा है। (5) N और M एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (6) M, O के दाईं ओर तीसरे स्थान पर बैठा है। (7) M और L के बीच छोटे रास्ते से गिनने पर ठीक 2 व्यक्ति बैठे हैं। P के बाईं ओर दूसरे स्थान पर बैठे व्यक्ति के ठीक सामने कौन बैठा है?","optionsHi":["L","Q","M","O"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (व्यवस्था मेज़ को घुमाने तक निश्चित है): K, L, Q, P, M, R, N, O। उत्तर इसी से मिलता है। उत्तर: O।","subtopic":"square-rectangular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-201","question":"Eight persons P, Q, R, S, T, U, V and W sit around a rectangular table, all facing the centre: three persons on each of the two longer sides and one person on each of the two shorter sides. Clues: (1) Exactly 2 persons sit between R and P, counted along the shorter way round. (2) Q sits on one of the two shorter sides of the table. (3) U and S are immediate neighbours. (4) T does not sit opposite V. (5) Exactly 1 person sits between V and T, counted along the shorter way round. (6) S sits to the immediate left of T. (7) P and V are immediate neighbours. Who sits exactly opposite the person who sits second to the right of S?","options":["U","R","V","W"],"answer":3,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (the arrangement is fixed up to a rotation of the table): P, T, S, U, W, R, Q, V. The answer is read from it. Answer: W.","difficulty":"hard","questionHi":"आठ व्यक्ति P, Q, R, S, T, U, V और W एक आयताकार मेज़ के चारों ओर बैठे हैं और सभी केंद्र की ओर मुख किए हुए हैं: दोनों लंबी भुजाओं में से प्रत्येक पर तीन व्यक्ति और दोनों छोटी भुजाओं में से प्रत्येक पर एक व्यक्ति। संकेत: (1) R और P के बीच छोटे रास्ते से गिनने पर ठीक 2 व्यक्ति बैठे हैं। (2) Q मेज़ की दोनों छोटी भुजाओं में से किसी एक पर बैठा है। (3) U और S एक-दूसरे के ठीक बगल में बैठे हैं। (4) T, V के ठीक सामने नहीं बैठा है। (5) V और T के बीच छोटे रास्ते से गिनने पर ठीक 1 व्यक्ति बैठे हैं। (6) S, T के ठीक बाईं ओर बैठा है। (7) P और V एक-दूसरे के ठीक बगल में बैठे हैं। S के दाईं ओर दूसरे स्थान पर बैठे व्यक्ति के ठीक सामने कौन बैठा है?","optionsHi":["U","R","V","W"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (व्यवस्था मेज़ को घुमाने तक निश्चित है): P, T, S, U, W, R, Q, V। उत्तर इसी से मिलता है। उत्तर: W।","subtopic":"square-rectangular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-202","question":"Eight persons P, Q, R, S, T, U, V and W sit around a rectangular table, all facing the centre: three persons on each of the two longer sides and one person on each of the two shorter sides. Clues: (1) R sits second to the right of W. (2) T does not sit opposite S. (3) V sits on one of the two shorter sides of the table. (4) P does not sit opposite W. (5) U and Q are not immediate neighbours. (6) R and U are not immediate neighbours. (7) S and Q are not immediate neighbours. (8) Exactly 2 persons sit between V and R, counted along the shorter way round. (9) Q and P are not immediate neighbours. (10) U sits second to the left of P. Who sits third to the left of Q?","options":["R","U","P","T"],"answer":2,"explanation":"Fix the opposite-pair and gap clues first, then use the left/right clues with each person's facing and the negative clues to remove the rest; exactly one seating survives, clockwise starting from the first person (the arrangement is fixed up to a rotation of the table): P, W, U, S, V, Q, T, R. The answer is read from it. Answer: P.","difficulty":"very-hard","questionHi":"आठ व्यक्ति P, Q, R, S, T, U, V और W एक आयताकार मेज़ के चारों ओर बैठे हैं और सभी केंद्र की ओर मुख किए हुए हैं: दोनों लंबी भुजाओं में से प्रत्येक पर तीन व्यक्ति और दोनों छोटी भुजाओं में से प्रत्येक पर एक व्यक्ति। संकेत: (1) R, W के दाईं ओर दूसरे स्थान पर बैठा है। (2) T, S के ठीक सामने नहीं बैठा है। (3) V मेज़ की दोनों छोटी भुजाओं में से किसी एक पर बैठा है। (4) P, W के ठीक सामने नहीं बैठा है। (5) U और Q एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (6) R और U एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (7) S और Q एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (8) V और R के बीच छोटे रास्ते से गिनने पर ठीक 2 व्यक्ति बैठे हैं। (9) Q और P एक-दूसरे के ठीक बगल में नहीं बैठे हैं। (10) U, P के बाईं ओर दूसरे स्थान पर बैठा है। Q के बाईं ओर तीसरे स्थान पर कौन बैठा है?","optionsHi":["R","U","P","T"],"explanationHi":"पहले सामने वाले और बीच की दूरी वाले संकेत लगाइए, फिर प्रत्येक व्यक्ति के मुख के अनुसार बाएँ-दाएँ वाले और नकारात्मक संकेतों से शेष विकल्प हटाइए; केवल एक ही बैठक बचती है, पहले व्यक्ति से शुरू करके दक्षिणावर्त (व्यवस्था मेज़ को घुमाने तक निश्चित है): P, W, U, S, V, Q, T, R। उत्तर इसी से मिलता है। उत्तर: P।","subtopic":"square-rectangular","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-203","question":"Eight persons sit in two parallel rows of four each, with equal spacing, so that each person in one row faces exactly one person of the other row. A, B, C and D sit in row 1 facing south, and E, F, G and H sit in row 2 facing north. Left and right are taken from each person's own point of view. Clues: (1) C sits exactly opposite the person who sits to the immediate left of F. (2) A sits diagonally opposite E (in the other row, one seat to the side). (3) B does not sit at either end of a row. (4) F sits next to H. (5) Exactly 2 persons sit between F and G. Who sits exactly opposite G?","options":["D","A","B","C"],"answer":1,"explanation":"Placing the opposite-pair clues and the end clues first and then applying the left/right clues with each row's facing leaves exactly one seating, west to east: row 1 = A, B, C, D; row 2 = G, E, H, F. The answer follows from it. Answer: A.","difficulty":"moderate","questionHi":"आठ व्यक्ति दो समानांतर पंक्तियों में, प्रत्येक में चार, समान दूरी पर बैठे हैं, ताकि एक पंक्ति का प्रत्येक व्यक्ति दूसरी पंक्ति के ठीक एक व्यक्ति के सामने हो। A, B, C और D पंक्ति 1 में दक्षिण की ओर मुख किए बैठे हैं, और E, F, G और H पंक्ति 2 में उत्तर की ओर मुख किए बैठे हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) C, F के ठीक बाईं ओर बैठे व्यक्ति के ठीक सामने बैठा है। (2) A, E के विकर्णतः सामने बैठा है (दूसरी पंक्ति में, बगल की ओर एक सीट पर)। (3) B पंक्ति के किसी भी छोर पर नहीं बैठा है। (4) F, H के बगल में बैठा है। (5) F और G के बीच ठीक 2 व्यक्ति बैठे हैं। G के ठीक सामने कौन बैठा है?","optionsHi":["D","A","B","C"],"explanationHi":"पहले सामने वाले और छोर वाले संकेत लगाकर फिर प्रत्येक पंक्ति के मुख के अनुसार बाएँ-दाएँ वाले संकेत लगाने पर केवल एक ही बैठक बचती है, पश्चिम से पूर्व: पंक्ति 1 = A, B, C, D; पंक्ति 2 = G, E, H, F। उत्तर इसी से निकलता है। उत्तर: A।","subtopic":"double-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-204","question":"Eight persons sit in two parallel rows of four each, with equal spacing, so that each person in one row faces exactly one person of the other row. C, D, E and F sit in row 1 facing south, and G, H, I and J sit in row 2 facing north. Left and right are taken from each person's own point of view. Clues: (1) C sits exactly opposite G. (2) E sits to the immediate left of F. (3) D sits exactly opposite the person who sits to the immediate left of J. (4) H does not sit at either end of a row. (5) D sits exactly opposite H. Which of the following pairs of persons sit at the two ends of row 2?","options":["H and J","I and J","G and I","G and H"],"answer":2,"explanation":"Placing the opposite-pair clues and the end clues first and then applying the left/right clues with each row's facing leaves exactly one seating, west to east: row 1 = C, D, F, E; row 2 = G, H, J, I. The answer follows from it. Answer: G and I.","difficulty":"moderate","questionHi":"आठ व्यक्ति दो समानांतर पंक्तियों में, प्रत्येक में चार, समान दूरी पर बैठे हैं, ताकि एक पंक्ति का प्रत्येक व्यक्ति दूसरी पंक्ति के ठीक एक व्यक्ति के सामने हो। C, D, E और F पंक्ति 1 में दक्षिण की ओर मुख किए बैठे हैं, और G, H, I और J पंक्ति 2 में उत्तर की ओर मुख किए बैठे हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) C, G के ठीक सामने बैठा है। (2) E, F के ठीक बाईं ओर बैठा है। (3) D, J के ठीक बाईं ओर बैठे व्यक्ति के ठीक सामने बैठा है। (4) H पंक्ति के किसी भी छोर पर नहीं बैठा है। (5) D, H के ठीक सामने बैठा है। निम्नलिखित में से कौन-सा युग्म पंक्ति 2 के दोनों छोरों पर बैठा है?","optionsHi":["H और J","I और J","G और I","G और H"],"explanationHi":"पहले सामने वाले और छोर वाले संकेत लगाकर फिर प्रत्येक पंक्ति के मुख के अनुसार बाएँ-दाएँ वाले संकेत लगाने पर केवल एक ही बैठक बचती है, पश्चिम से पूर्व: पंक्ति 1 = C, D, F, E; पंक्ति 2 = G, H, J, I। उत्तर इसी से निकलता है। उत्तर: G और I।","subtopic":"double-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-205","question":"Eight persons sit in two parallel rows of four each, with equal spacing, so that each person in one row faces exactly one person of the other row. A, B, C and D sit in row 1 facing south, and E, F, G and H sit in row 2 facing north. Left and right are taken from each person's own point of view. Clues: (1) F sits next to E. (2) C does not sit opposite H. (3) D sits second to the right of B. (4) F sits at one of the two ends of a row. (5) A sits at one of the two ends of a row. (6) H does not sit opposite B. (7) E sits diagonally opposite A (in the other row, one seat to the side). How many persons sit between D and C?","options":["0","1","3","2"],"answer":0,"explanation":"Placing the opposite-pair clues and the end clues first and then applying the left/right clues with each row's facing leaves exactly one seating, west to east: row 1 = D, C, B, A; row 2 = H, G, E, F. The answer follows from it. Answer: 0.","difficulty":"hard","questionHi":"आठ व्यक्ति दो समानांतर पंक्तियों में, प्रत्येक में चार, समान दूरी पर बैठे हैं, ताकि एक पंक्ति का प्रत्येक व्यक्ति दूसरी पंक्ति के ठीक एक व्यक्ति के सामने हो। A, B, C और D पंक्ति 1 में दक्षिण की ओर मुख किए बैठे हैं, और E, F, G और H पंक्ति 2 में उत्तर की ओर मुख किए बैठे हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) F, E के बगल में बैठा है। (2) C, H के ठीक सामने नहीं बैठा है। (3) D, B के दाईं ओर दूसरे स्थान पर बैठा है। (4) F पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (5) A पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (6) H, B के ठीक सामने नहीं बैठा है। (7) E, A के विकर्णतः सामने बैठा है (दूसरी पंक्ति में, बगल की ओर एक सीट पर)। D और C के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["0","1","3","2"],"explanationHi":"पहले सामने वाले और छोर वाले संकेत लगाकर फिर प्रत्येक पंक्ति के मुख के अनुसार बाएँ-दाएँ वाले संकेत लगाने पर केवल एक ही बैठक बचती है, पश्चिम से पूर्व: पंक्ति 1 = D, C, B, A; पंक्ति 2 = H, G, E, F। उत्तर इसी से निकलता है। उत्तर: 0।","subtopic":"double-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-206","question":"Eight persons sit in two parallel rows of four each, with equal spacing, so that each person in one row faces exactly one person of the other row. C, D, E and F sit in row 1 facing south, and G, H, I and J sit in row 2 facing north. Left and right are taken from each person's own point of view. Clues: (1) G does not sit opposite D. (2) Exactly 1 person sits between G and I. (3) J sits exactly opposite the person who sits to the immediate left of C. (4) F sits at one of the two ends of a row. (5) G sits next to H. (6) D and C do not sit next to each other. (7) H sits at one of the two ends of a row. Who sits exactly opposite the person who sits to the immediate right of G?","options":["H","J","E","F"],"answer":2,"explanation":"Placing the opposite-pair clues and the end clues first and then applying the left/right clues with each row's facing leaves exactly one seating, west to east: row 1 = F, C, E, D; row 2 = H, G, J, I. The answer follows from it. Answer: E.","difficulty":"hard","questionHi":"आठ व्यक्ति दो समानांतर पंक्तियों में, प्रत्येक में चार, समान दूरी पर बैठे हैं, ताकि एक पंक्ति का प्रत्येक व्यक्ति दूसरी पंक्ति के ठीक एक व्यक्ति के सामने हो। C, D, E और F पंक्ति 1 में दक्षिण की ओर मुख किए बैठे हैं, और G, H, I और J पंक्ति 2 में उत्तर की ओर मुख किए बैठे हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) G, D के ठीक सामने नहीं बैठा है। (2) G और I के बीच ठीक 1 व्यक्ति बैठे हैं। (3) J, C के ठीक बाईं ओर बैठे व्यक्ति के ठीक सामने बैठा है। (4) F पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (5) G, H के बगल में बैठा है। (6) D और C एक-दूसरे के बगल में नहीं बैठे हैं। (7) H पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। G के ठीक दाईं ओर बैठे व्यक्ति के ठीक सामने कौन बैठा है?","optionsHi":["H","J","E","F"],"explanationHi":"पहले सामने वाले और छोर वाले संकेत लगाकर फिर प्रत्येक पंक्ति के मुख के अनुसार बाएँ-दाएँ वाले संकेत लगाने पर केवल एक ही बैठक बचती है, पश्चिम से पूर्व: पंक्ति 1 = F, C, E, D; पंक्ति 2 = H, G, J, I। उत्तर इसी से निकलता है। उत्तर: E।","subtopic":"double-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-207","question":"Eight persons sit in two parallel rows of four each, with equal spacing, so that each person in one row faces exactly one person of the other row. A, B, C and D sit in row 1 facing south, and E, F, G and H sit in row 2 facing north. Left and right are taken from each person's own point of view. Clues: (1) H sits somewhere between G and F. (2) B and A do not sit next to each other. (3) F sits at one of the two ends of a row. (4) H does not sit opposite C. (5) E sits next to F. (6) A sits exactly opposite the person who sits to the immediate left of H. (7) C does not sit at either end of a row. Who sits exactly opposite H?","options":["B","A","C","D"],"answer":3,"explanation":"Placing the opposite-pair clues and the end clues first and then applying the left/right clues with each row's facing leaves exactly one seating, west to east: row 1 = A, D, C, B; row 2 = G, H, E, F. The answer follows from it. Answer: D.","difficulty":"hard","questionHi":"आठ व्यक्ति दो समानांतर पंक्तियों में, प्रत्येक में चार, समान दूरी पर बैठे हैं, ताकि एक पंक्ति का प्रत्येक व्यक्ति दूसरी पंक्ति के ठीक एक व्यक्ति के सामने हो। A, B, C और D पंक्ति 1 में दक्षिण की ओर मुख किए बैठे हैं, और E, F, G और H पंक्ति 2 में उत्तर की ओर मुख किए बैठे हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) H, G और F के बीच में कहीं बैठा है। (2) B और A एक-दूसरे के बगल में नहीं बैठे हैं। (3) F पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (4) H, C के ठीक सामने नहीं बैठा है। (5) E, F के बगल में बैठा है। (6) A, H के ठीक बाईं ओर बैठे व्यक्ति के ठीक सामने बैठा है। (7) C पंक्ति के किसी भी छोर पर नहीं बैठा है। H के ठीक सामने कौन बैठा है?","optionsHi":["B","A","C","D"],"explanationHi":"पहले सामने वाले और छोर वाले संकेत लगाकर फिर प्रत्येक पंक्ति के मुख के अनुसार बाएँ-दाएँ वाले संकेत लगाने पर केवल एक ही बैठक बचती है, पश्चिम से पूर्व: पंक्ति 1 = A, D, C, B; पंक्ति 2 = G, H, E, F। उत्तर इसी से निकलता है। उत्तर: D।","subtopic":"double-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-208","question":"Eight persons sit in two parallel rows of four each, with equal spacing, so that each person in one row faces exactly one person of the other row. P, Q, R and S sit in row 1 facing south, and T, U, V and W sit in row 2 facing north. Left and right are taken from each person's own point of view. Clues: (1) Q does not sit opposite T. (2) V sits at one of the two ends of a row. (3) P and S do not sit next to each other. (4) W does not sit at either end of a row. (5) S does not sit opposite T. (6) R sits to the immediate left of P. (7) V sits exactly opposite R. Who sits exactly opposite the person who sits to the immediate left of T?","options":["W","R","Q","U"],"answer":2,"explanation":"Placing the opposite-pair clues and the end clues first and then applying the left/right clues with each row's facing leaves exactly one seating, west to east: row 1 = S, Q, P, R; row 2 = U, W, T, V. The answer follows from it. Answer: Q.","difficulty":"hard","questionHi":"आठ व्यक्ति दो समानांतर पंक्तियों में, प्रत्येक में चार, समान दूरी पर बैठे हैं, ताकि एक पंक्ति का प्रत्येक व्यक्ति दूसरी पंक्ति के ठीक एक व्यक्ति के सामने हो। P, Q, R और S पंक्ति 1 में दक्षिण की ओर मुख किए बैठे हैं, और T, U, V और W पंक्ति 2 में उत्तर की ओर मुख किए बैठे हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) Q, T के ठीक सामने नहीं बैठा है। (2) V पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (3) P और S एक-दूसरे के बगल में नहीं बैठे हैं। (4) W पंक्ति के किसी भी छोर पर नहीं बैठा है। (5) S, T के ठीक सामने नहीं बैठा है। (6) R, P के ठीक बाईं ओर बैठा है। (7) V, R के ठीक सामने बैठा है। T के ठीक बाईं ओर बैठे व्यक्ति के ठीक सामने कौन बैठा है?","optionsHi":["W","R","Q","U"],"explanationHi":"पहले सामने वाले और छोर वाले संकेत लगाकर फिर प्रत्येक पंक्ति के मुख के अनुसार बाएँ-दाएँ वाले संकेत लगाने पर केवल एक ही बैठक बचती है, पश्चिम से पूर्व: पंक्ति 1 = S, Q, P, R; पंक्ति 2 = U, W, T, V। उत्तर इसी से निकलता है। उत्तर: Q।","subtopic":"double-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-209","question":"Eight persons sit in two parallel rows of four each, with equal spacing, so that each person in one row faces exactly one person of the other row. P, Q, R and S sit in row 1 facing south, and T, U, V and W sit in row 2 facing north. Left and right are taken from each person's own point of view. Clues: (1) W does not sit at either end of a row. (2) R and Q do not sit next to each other. (3) Q does not sit opposite V. (4) U sits to the immediate right of T. (5) T sits diagonally opposite P (in the other row, one seat to the side). (6) Q sits at one of the two ends of a row. (7) Q does not sit opposite T. Who sits exactly opposite S?","options":["U","W","T","V"],"answer":2,"explanation":"Placing the opposite-pair clues and the end clues first and then applying the left/right clues with each row's facing leaves exactly one seating, west to east: row 1 = R, P, S, Q; row 2 = V, W, T, U. The answer follows from it. Answer: T.","difficulty":"hard","questionHi":"आठ व्यक्ति दो समानांतर पंक्तियों में, प्रत्येक में चार, समान दूरी पर बैठे हैं, ताकि एक पंक्ति का प्रत्येक व्यक्ति दूसरी पंक्ति के ठीक एक व्यक्ति के सामने हो। P, Q, R और S पंक्ति 1 में दक्षिण की ओर मुख किए बैठे हैं, और T, U, V और W पंक्ति 2 में उत्तर की ओर मुख किए बैठे हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) W पंक्ति के किसी भी छोर पर नहीं बैठा है। (2) R और Q एक-दूसरे के बगल में नहीं बैठे हैं। (3) Q, V के ठीक सामने नहीं बैठा है। (4) U, T के ठीक दाईं ओर बैठा है। (5) T, P के विकर्णतः सामने बैठा है (दूसरी पंक्ति में, बगल की ओर एक सीट पर)। (6) Q पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (7) Q, T के ठीक सामने नहीं बैठा है। S के ठीक सामने कौन बैठा है?","optionsHi":["U","W","T","V"],"explanationHi":"पहले सामने वाले और छोर वाले संकेत लगाकर फिर प्रत्येक पंक्ति के मुख के अनुसार बाएँ-दाएँ वाले संकेत लगाने पर केवल एक ही बैठक बचती है, पश्चिम से पूर्व: पंक्ति 1 = R, P, S, Q; पंक्ति 2 = V, W, T, U। उत्तर इसी से निकलता है। उत्तर: T।","subtopic":"double-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-210","question":"Eight persons sit in two parallel rows of four each, with equal spacing, so that each person in one row faces exactly one person of the other row. A, B, C and D sit in row 1 facing south, and E, F, G and H sit in row 2 facing north. Left and right are taken from each person's own point of view. Clues: (1) F sits at one of the two ends of a row. (2) G does not sit at either end of a row. (3) E sits exactly opposite the person who sits to the immediate left of A. (4) A sits next to B. (5) B sits at one of the two ends of a row. (6) D sits at one of the two ends of a row. (7) Exactly 1 person sits between G and E. Who sits exactly opposite F?","options":["D","C","B","A"],"answer":0,"explanation":"Placing the opposite-pair clues and the end clues first and then applying the left/right clues with each row's facing leaves exactly one seating, west to east: row 1 = D, C, A, B; row 2 = F, G, H, E. The answer follows from it. Answer: D.","difficulty":"hard","questionHi":"आठ व्यक्ति दो समानांतर पंक्तियों में, प्रत्येक में चार, समान दूरी पर बैठे हैं, ताकि एक पंक्ति का प्रत्येक व्यक्ति दूसरी पंक्ति के ठीक एक व्यक्ति के सामने हो। A, B, C और D पंक्ति 1 में दक्षिण की ओर मुख किए बैठे हैं, और E, F, G और H पंक्ति 2 में उत्तर की ओर मुख किए बैठे हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) F पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (2) G पंक्ति के किसी भी छोर पर नहीं बैठा है। (3) E, A के ठीक बाईं ओर बैठे व्यक्ति के ठीक सामने बैठा है। (4) A, B के बगल में बैठा है। (5) B पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (6) D पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (7) G और E के बीच ठीक 1 व्यक्ति बैठे हैं। F के ठीक सामने कौन बैठा है?","optionsHi":["D","C","B","A"],"explanationHi":"पहले सामने वाले और छोर वाले संकेत लगाकर फिर प्रत्येक पंक्ति के मुख के अनुसार बाएँ-दाएँ वाले संकेत लगाने पर केवल एक ही बैठक बचती है, पश्चिम से पूर्व: पंक्ति 1 = D, C, A, B; पंक्ति 2 = F, G, H, E। उत्तर इसी से निकलता है। उत्तर: D।","subtopic":"double-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-211","question":"Eight persons sit in two parallel rows of four each, with equal spacing, so that each person in one row faces exactly one person of the other row. A, B, C and D sit in row 1 facing south, and E, F, G and H sit in row 2 facing north. Left and right are taken from each person's own point of view. Clues: (1) D sits at one of the two ends of a row. (2) D does not sit opposite G. (3) F does not sit at either end of a row. (4) F sits diagonally opposite C (in the other row, one seat to the side). (5) A does not sit opposite G. (6) H does not sit opposite A. (7) G and E do not sit next to each other. (8) A sits at one of the two ends of a row. (9) F sits to the immediate right of G. Who sits exactly opposite A?","options":["H","E","F","G"],"answer":1,"explanation":"Placing the opposite-pair clues and the end clues first and then applying the left/right clues with each row's facing leaves exactly one seating, west to east: row 1 = D, C, B, A; row 2 = H, G, F, E. The answer follows from it. Answer: E.","difficulty":"very-hard","questionHi":"आठ व्यक्ति दो समानांतर पंक्तियों में, प्रत्येक में चार, समान दूरी पर बैठे हैं, ताकि एक पंक्ति का प्रत्येक व्यक्ति दूसरी पंक्ति के ठीक एक व्यक्ति के सामने हो। A, B, C और D पंक्ति 1 में दक्षिण की ओर मुख किए बैठे हैं, और E, F, G और H पंक्ति 2 में उत्तर की ओर मुख किए बैठे हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) D पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (2) D, G के ठीक सामने नहीं बैठा है। (3) F पंक्ति के किसी भी छोर पर नहीं बैठा है। (4) F, C के विकर्णतः सामने बैठा है (दूसरी पंक्ति में, बगल की ओर एक सीट पर)। (5) A, G के ठीक सामने नहीं बैठा है। (6) H, A के ठीक सामने नहीं बैठा है। (7) G और E एक-दूसरे के बगल में नहीं बैठे हैं। (8) A पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (9) F, G के ठीक दाईं ओर बैठा है। A के ठीक सामने कौन बैठा है?","optionsHi":["H","E","F","G"],"explanationHi":"पहले सामने वाले और छोर वाले संकेत लगाकर फिर प्रत्येक पंक्ति के मुख के अनुसार बाएँ-दाएँ वाले संकेत लगाने पर केवल एक ही बैठक बचती है, पश्चिम से पूर्व: पंक्ति 1 = D, C, B, A; पंक्ति 2 = H, G, F, E। उत्तर इसी से निकलता है। उत्तर: E।","subtopic":"double-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-212","question":"Eight persons sit in two parallel rows of four each, with equal spacing, so that each person in one row faces exactly one person of the other row. P, Q, R and S sit in row 1 facing south, and T, U, V and W sit in row 2 facing north. Left and right are taken from each person's own point of view. Clues: (1) R sits next to S. (2) S sits diagonally opposite U (in the other row, one seat to the side). (3) Q sits to the immediate left of P. (4) Q sits diagonally opposite V (in the other row, one seat to the side). (5) R sits at one of the two ends of a row. (6) V and W do not sit next to each other. (7) P does not sit opposite W. (8) T does not sit opposite S. (9) U does not sit at either end of a row. How many persons sit between S and Q?","options":["2","3","0","1"],"answer":2,"explanation":"Placing the opposite-pair clues and the end clues first and then applying the left/right clues with each row's facing leaves exactly one seating, west to east: row 1 = P, Q, S, R; row 2 = V, U, W, T. The answer follows from it. Answer: 0.","difficulty":"very-hard","questionHi":"आठ व्यक्ति दो समानांतर पंक्तियों में, प्रत्येक में चार, समान दूरी पर बैठे हैं, ताकि एक पंक्ति का प्रत्येक व्यक्ति दूसरी पंक्ति के ठीक एक व्यक्ति के सामने हो। P, Q, R और S पंक्ति 1 में दक्षिण की ओर मुख किए बैठे हैं, और T, U, V और W पंक्ति 2 में उत्तर की ओर मुख किए बैठे हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) R, S के बगल में बैठा है। (2) S, U के विकर्णतः सामने बैठा है (दूसरी पंक्ति में, बगल की ओर एक सीट पर)। (3) Q, P के ठीक बाईं ओर बैठा है। (4) Q, V के विकर्णतः सामने बैठा है (दूसरी पंक्ति में, बगल की ओर एक सीट पर)। (5) R पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (6) V और W एक-दूसरे के बगल में नहीं बैठे हैं। (7) P, W के ठीक सामने नहीं बैठा है। (8) T, S के ठीक सामने नहीं बैठा है। (9) U पंक्ति के किसी भी छोर पर नहीं बैठा है। S और Q के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["2","3","0","1"],"explanationHi":"पहले सामने वाले और छोर वाले संकेत लगाकर फिर प्रत्येक पंक्ति के मुख के अनुसार बाएँ-दाएँ वाले संकेत लगाने पर केवल एक ही बैठक बचती है, पश्चिम से पूर्व: पंक्ति 1 = P, Q, S, R; पंक्ति 2 = V, U, W, T। उत्तर इसी से निकलता है। उत्तर: 0।","subtopic":"double-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-213","question":"Ten persons sit in two parallel rows of five each, with equal spacing, so that each person in one row faces exactly one person of the other row. C, D, E, F and G sit in row 1 facing south, and H, I, J, K and L sit in row 2 facing north. Left and right are taken from each person's own point of view. Clues: (1) L and H do not sit next to each other. (2) J and L do not sit next to each other. (3) C sits third to the right of E. (4) E sits next to F. (5) F sits at one of the two ends of a row. (6) D sits next to E. (7) C does not sit opposite L. (8) H does not sit opposite C. (9) E sits exactly opposite the person who sits to the immediate right of J. (10) C does not sit opposite I. How many persons sit between F and E?","options":["3","0","1","4"],"answer":1,"explanation":"Placing the opposite-pair clues and the end clues first and then applying the left/right clues with each row's facing leaves exactly one seating, west to east: row 1 = C, G, D, E, F; row 2 = K, H, J, I, L. The answer follows from it. Answer: 0.","difficulty":"very-hard","questionHi":"दस व्यक्ति दो समानांतर पंक्तियों में, प्रत्येक में पाँच, समान दूरी पर बैठे हैं, ताकि एक पंक्ति का प्रत्येक व्यक्ति दूसरी पंक्ति के ठीक एक व्यक्ति के सामने हो। C, D, E, F और G पंक्ति 1 में दक्षिण की ओर मुख किए बैठे हैं, और H, I, J, K और L पंक्ति 2 में उत्तर की ओर मुख किए बैठे हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) L और H एक-दूसरे के बगल में नहीं बैठे हैं। (2) J और L एक-दूसरे के बगल में नहीं बैठे हैं। (3) C, E के दाईं ओर तीसरे स्थान पर बैठा है। (4) E, F के बगल में बैठा है। (5) F पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (6) D, E के बगल में बैठा है। (7) C, L के ठीक सामने नहीं बैठा है। (8) H, C के ठीक सामने नहीं बैठा है। (9) E, J के ठीक दाईं ओर बैठे व्यक्ति के ठीक सामने बैठा है। (10) C, I के ठीक सामने नहीं बैठा है। F और E के बीच कितने व्यक्ति बैठे हैं?","optionsHi":["3","0","1","4"],"explanationHi":"पहले सामने वाले और छोर वाले संकेत लगाकर फिर प्रत्येक पंक्ति के मुख के अनुसार बाएँ-दाएँ वाले संकेत लगाने पर केवल एक ही बैठक बचती है, पश्चिम से पूर्व: पंक्ति 1 = C, G, D, E, F; पंक्ति 2 = K, H, J, I, L। उत्तर इसी से निकलता है। उत्तर: 0।","subtopic":"double-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-214","question":"Ten persons sit in two parallel rows of five each, with equal spacing, so that each person in one row faces exactly one person of the other row. A, B, C, D and E sit in row 1 facing south, and F, G, H, I and J sit in row 2 facing north. Left and right are taken from each person's own point of view. Clues: (1) A does not sit at either end of a row. (2) G sits exactly opposite the person who sits to the immediate right of A. (3) E and D do not sit next to each other. (4) Exactly 1 person sits between E and B. (5) H sits at one of the two ends of a row. (6) C and D do not sit next to each other. (7) E does not sit opposite H. (8) B sits exactly opposite the person who sits to the immediate right of J. (9) F sits at one of the two ends of a row. (10) E sits at one of the two ends of a row. Who sits exactly opposite H?","options":["E","A","D","C"],"answer":2,"explanation":"Placing the opposite-pair clues and the end clues first and then applying the left/right clues with each row's facing leaves exactly one seating, west to east: row 1 = E, C, B, A, D; row 2 = F, J, G, I, H. The answer follows from it. Answer: D.","difficulty":"very-hard","questionHi":"दस व्यक्ति दो समानांतर पंक्तियों में, प्रत्येक में पाँच, समान दूरी पर बैठे हैं, ताकि एक पंक्ति का प्रत्येक व्यक्ति दूसरी पंक्ति के ठीक एक व्यक्ति के सामने हो। A, B, C, D और E पंक्ति 1 में दक्षिण की ओर मुख किए बैठे हैं, और F, G, H, I और J पंक्ति 2 में उत्तर की ओर मुख किए बैठे हैं। बाएँ और दाएँ प्रत्येक व्यक्ति की अपनी दिशा से लिए गए हैं। संकेत: (1) A पंक्ति के किसी भी छोर पर नहीं बैठा है। (2) G, A के ठीक दाईं ओर बैठे व्यक्ति के ठीक सामने बैठा है। (3) E और D एक-दूसरे के बगल में नहीं बैठे हैं। (4) E और B के बीच ठीक 1 व्यक्ति बैठे हैं। (5) H पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (6) C और D एक-दूसरे के बगल में नहीं बैठे हैं। (7) E, H के ठीक सामने नहीं बैठा है। (8) B, J के ठीक दाईं ओर बैठे व्यक्ति के ठीक सामने बैठा है। (9) F पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। (10) E पंक्ति के दोनों छोरों में से किसी एक छोर पर बैठा है। H के ठीक सामने कौन बैठा है?","optionsHi":["E","A","D","C"],"explanationHi":"पहले सामने वाले और छोर वाले संकेत लगाकर फिर प्रत्येक पंक्ति के मुख के अनुसार बाएँ-दाएँ वाले संकेत लगाने पर केवल एक ही बैठक बचती है, पश्चिम से पूर्व: पंक्ति 1 = E, C, B, A, D; पंक्ति 2 = F, J, G, I, H। उत्तर इसी से निकलता है। उत्तर: D।","subtopic":"double-row","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-215","question":"Five persons K, L, M, N and O live on five different floors of a building numbered 1 (lowest) to 5 (topmost), one person per floor. Each of them likes a different colour: Pink, White, Black, Green, Orange. Clues: (1) The one who likes Orange lives on the floor immediately above K. (2) L lives on the topmost floor. (3) K likes White. (4) N lives on the floor immediately above M. (5) The one who likes Pink lives on floor 5. (6) The one who likes Orange lives on a floor higher than that of the one who likes Green. (7) N lives on the floor immediately above the one who likes Green. Which colour does M like?","options":["Pink","Orange","White","Green"],"answer":3,"explanation":"Placing the position clues first and then the relative and negative clues leaves one consistent table (floor: person-colour): 1: M-Green; 2: N-Black; 3: K-White; 4: O-Orange; 5: L-Pink. The answer is read from this table. Answer: Green.","difficulty":"moderate","questionHi":"पाँच व्यक्ति K, L, M, N और O एक इमारत की पाँच अलग-अलग मंज़िलों पर रहते हैं, जिनकी संख्या 1 (सबसे नीचे) से 5 (सबसे ऊपर) तक है, प्रति मंज़िल एक व्यक्ति। उनमें से प्रत्येक को एक अलग रंग पसंद है: गुलाबी, सफ़ेद, काला, हरा, नारंगी। संकेत: (1) नारंगी रंग पसंद करने वाला, K के ठीक ऊपर वाली मंज़िल पर रहता है। (2) L सबसे ऊपरी मंज़िल पर रहता है। (3) K को सफ़ेद रंग पसंद है। (4) N, M के ठीक ऊपर वाली मंज़िल पर रहता है। (5) गुलाबी रंग पसंद करने वाला मंज़िल 5 पर रहता है। (6) नारंगी रंग पसंद करने वाला, हरा रंग पसंद करने वाले से ऊपर की किसी मंज़िल पर रहता है। (7) N, हरा रंग पसंद करने वाले के ठीक ऊपर वाली मंज़िल पर रहता है। M को कौन-सा रंग पसंद है?","optionsHi":["गुलाबी","नारंगी","सफ़ेद","हरा"],"explanationHi":"पहले स्थिति वाले संकेत और फिर सापेक्ष तथा नकारात्मक संकेत लगाने पर एक ही संगत तालिका बनती है (मंज़िल: व्यक्ति-रंग): 1: M-हरा; 2: N-काला; 3: K-सफ़ेद; 4: O-नारंगी; 5: L-गुलाबी। उत्तर इसी तालिका से मिलता है। उत्तर: हरा।","subtopic":"floor-puzzles","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-216","question":"Six persons P, Q, R, S, T and U live on six different floors of a building numbered 1 (lowest) to 6 (topmost), one person per floor. Each of them likes a different colour: Pink, Red, Yellow, Orange, White, Black. Clues: (1) Exactly 3 floors lie between the floors of R and T. (2) S lives on floor 1, the lowest floor. (3) P lives on the floor immediately above the one who likes Pink. (4) P likes White. (5) P lives on a floor higher than that of R. (6) Exactly 1 floor lies between the floors of the one who likes Red and the one who likes Orange. (7) U lives on a floor between those of the one who likes Yellow and the one who likes Red. (8) U lives on the floor immediately above P. On which floor does U live?","options":["2","5","6","4"],"answer":3,"explanation":"Placing the position clues first and then the relative and negative clues leaves one consistent table (floor: person-colour): 1: S-Yellow; 2: R-Pink; 3: P-White; 4: U-Orange; 5: Q-Black; 6: T-Red. The answer is read from this table. Answer: 4.","difficulty":"hard","questionHi":"छह व्यक्ति P, Q, R, S, T और U एक इमारत की छह अलग-अलग मंज़िलों पर रहते हैं, जिनकी संख्या 1 (सबसे नीचे) से 6 (सबसे ऊपर) तक है, प्रति मंज़िल एक व्यक्ति। उनमें से प्रत्येक को एक अलग रंग पसंद है: गुलाबी, लाल, पीला, नारंगी, सफ़ेद, काला। संकेत: (1) R और T की मंज़िलों के बीच ठीक 3 मंज़िलें हैं। (2) S मंज़िल 1, यानी सबसे नीचे वाली मंज़िल पर रहता है। (3) P, गुलाबी रंग पसंद करने वाले के ठीक ऊपर वाली मंज़िल पर रहता है। (4) P को सफ़ेद रंग पसंद है। (5) P, R से ऊपर की किसी मंज़िल पर रहता है। (6) लाल रंग पसंद करने वाला और नारंगी रंग पसंद करने वाले की मंज़िलों के बीच ठीक 1 मंज़िल हैं। (7) U की मंज़िल पीला रंग पसंद करने वाले और लाल रंग पसंद करने वाले की मंज़िलों के बीच में है। (8) U, P के ठीक ऊपर वाली मंज़िल पर रहता है। U किस मंज़िल पर रहता है?","optionsHi":["2","5","6","4"],"explanationHi":"पहले स्थिति वाले संकेत और फिर सापेक्ष तथा नकारात्मक संकेत लगाने पर एक ही संगत तालिका बनती है (मंज़िल: व्यक्ति-रंग): 1: S-पीला; 2: R-गुलाबी; 3: P-सफ़ेद; 4: U-नारंगी; 5: Q-काला; 6: T-लाल। उत्तर इसी तालिका से मिलता है। उत्तर: 4।","subtopic":"floor-puzzles","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-217","question":"Six persons K, L, M, N, O and P live on six different floors of a building numbered 1 (lowest) to 6 (topmost), one person per floor. Each of them likes a different colour: Black, Green, Red, Blue, White, Yellow. Clues: (1) Exactly 2 floors lie between the floors of the one who likes Green and the one who likes White. (2) The one who likes Blue lives on a floor higher than that of L. (3) O lives on the floor immediately above K. (4) The one who likes Red lives on the floor immediately above the one who likes Blue. (5) M and the one who likes Black do not live on consecutive floors. (6) The one who likes Green lives on a floor between those of the one who likes Red and M. (7) N does not like Black. (8) M does not like Black. (9) The one who likes Black lives on a floor between those of P and the one who likes Yellow. (10) O likes Red. Who lives on floor 4?","options":["O","N","M","P"],"answer":3,"explanation":"Placing the position clues first and then the relative and negative clues leaves one consistent table (floor: person-colour): 1: M-White; 2: N-Yellow; 3: L-Black; 4: P-Green; 5: K-Blue; 6: O-Red. The answer is read from this table. Answer: P.","difficulty":"hard","questionHi":"छह व्यक्ति K, L, M, N, O और P एक इमारत की छह अलग-अलग मंज़िलों पर रहते हैं, जिनकी संख्या 1 (सबसे नीचे) से 6 (सबसे ऊपर) तक है, प्रति मंज़िल एक व्यक्ति। उनमें से प्रत्येक को एक अलग रंग पसंद है: काला, हरा, लाल, नीला, सफ़ेद, पीला। संकेत: (1) हरा रंग पसंद करने वाला और सफ़ेद रंग पसंद करने वाले की मंज़िलों के बीच ठीक 2 मंज़िलें हैं। (2) नीला रंग पसंद करने वाला, L से ऊपर की किसी मंज़िल पर रहता है। (3) O, K के ठीक ऊपर वाली मंज़िल पर रहता है। (4) लाल रंग पसंद करने वाला, नीला रंग पसंद करने वाले के ठीक ऊपर वाली मंज़िल पर रहता है। (5) M और काला रंग पसंद करने वाले लगातार मंज़िलों पर नहीं रहते हैं। (6) हरा रंग पसंद करने वाला की मंज़िल लाल रंग पसंद करने वाले और M की मंज़िलों के बीच में है। (7) N को काला रंग पसंद नहीं है। (8) M को काला रंग पसंद नहीं है। (9) काला रंग पसंद करने वाला की मंज़िल P और पीला रंग पसंद करने वाले की मंज़िलों के बीच में है। (10) O को लाल रंग पसंद है। मंज़िल 4 पर कौन रहता है?","optionsHi":["O","N","M","P"],"explanationHi":"पहले स्थिति वाले संकेत और फिर सापेक्ष तथा नकारात्मक संकेत लगाने पर एक ही संगत तालिका बनती है (मंज़िल: व्यक्ति-रंग): 1: M-सफ़ेद; 2: N-पीला; 3: L-काला; 4: P-हरा; 5: K-नीला; 6: O-लाल। उत्तर इसी तालिका से मिलता है। उत्तर: P।","subtopic":"floor-puzzles","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-218","question":"Six persons U, V, W, X, Y and Z live on six different floors of a building numbered 1 (lowest) to 6 (topmost), one person per floor. Each of them likes a different colour: Orange, Black, Yellow, Blue, Pink, Red. Clues: (1) Z does not like Yellow. (2) V lives on a floor higher than that of the one who likes Yellow. (3) Exactly 1 floor lies between the floors of the one who likes Orange and the one who likes Yellow. (4) Z lives on a floor higher than that of the one who likes Pink. (5) The one who likes Black lives on the floor immediately above the one who likes Blue. (6) The one who likes Yellow and Z do not live on consecutive floors. (7) W likes Pink. (8) Exactly 3 floors lie between the floors of U and the one who likes Orange. (9) Exactly 3 floors lie between the floors of the one who likes Blue and X. On which floor does X live?","options":["5","4","1","2"],"answer":2,"explanation":"Placing the position clues first and then the relative and negative clues leaves one consistent table (floor: person-colour): 1: X-Orange; 2: W-Pink; 3: Y-Yellow; 4: V-Red; 5: U-Blue; 6: Z-Black. The answer is read from this table. Answer: 1.","difficulty":"hard","questionHi":"छह व्यक्ति U, V, W, X, Y और Z एक इमारत की छह अलग-अलग मंज़िलों पर रहते हैं, जिनकी संख्या 1 (सबसे नीचे) से 6 (सबसे ऊपर) तक है, प्रति मंज़िल एक व्यक्ति। उनमें से प्रत्येक को एक अलग रंग पसंद है: नारंगी, काला, पीला, नीला, गुलाबी, लाल। संकेत: (1) Z को पीला रंग पसंद नहीं है। (2) V, पीला रंग पसंद करने वाले से ऊपर की किसी मंज़िल पर रहता है। (3) नारंगी रंग पसंद करने वाला और पीला रंग पसंद करने वाले की मंज़िलों के बीच ठीक 1 मंज़िल हैं। (4) Z, गुलाबी रंग पसंद करने वाले से ऊपर की किसी मंज़िल पर रहता है। (5) काला रंग पसंद करने वाला, नीला रंग पसंद करने वाले के ठीक ऊपर वाली मंज़िल पर रहता है। (6) पीला रंग पसंद करने वाला और Z लगातार मंज़िलों पर नहीं रहते हैं। (7) W को गुलाबी रंग पसंद है। (8) U और नारंगी रंग पसंद करने वाले की मंज़िलों के बीच ठीक 3 मंज़िलें हैं। (9) नीला रंग पसंद करने वाला और X की मंज़िलों के बीच ठीक 3 मंज़िलें हैं। X किस मंज़िल पर रहता है?","optionsHi":["5","4","1","2"],"explanationHi":"पहले स्थिति वाले संकेत और फिर सापेक्ष तथा नकारात्मक संकेत लगाने पर एक ही संगत तालिका बनती है (मंज़िल: व्यक्ति-रंग): 1: X-नारंगी; 2: W-गुलाबी; 3: Y-पीला; 4: V-लाल; 5: U-नीला; 6: Z-काला। उत्तर इसी तालिका से मिलता है। उत्तर: 1।","subtopic":"floor-puzzles","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-219","question":"Six persons K, L, M, N, O and P live on six different floors of a building numbered 1 (lowest) to 6 (topmost), one person per floor. Each of them likes a different colour: Red, Pink, Black, Yellow, Blue, Orange. Clues: (1) M likes Blue. (2) The one who likes Blue lives on a floor between those of K and N. (3) Exactly 1 floor lies between the floors of the one who likes Red and the one who likes Pink. (4) The one who likes Pink lives on the floor immediately above P. (5) K does not like Yellow. (6) The one who likes Orange lives on the floor immediately above O. (7) K lives on a floor higher than that of L. (8) The one who likes Yellow lives on a floor higher than that of O. (9) The one who likes Red lives on a floor higher than that of O. (10) The one who likes Yellow and the one who likes Pink do not live on consecutive floors. Which colour does P like?","options":["Black","Orange","Red","Pink"],"answer":0,"explanation":"Placing the position clues first and then the relative and negative clues leaves one consistent table (floor: person-colour): 1: P-Black; 2: O-Pink; 3: L-Orange; 4: K-Red; 5: M-Blue; 6: N-Yellow. The answer is read from this table. Answer: Black.","difficulty":"very-hard","questionHi":"छह व्यक्ति K, L, M, N, O और P एक इमारत की छह अलग-अलग मंज़िलों पर रहते हैं, जिनकी संख्या 1 (सबसे नीचे) से 6 (सबसे ऊपर) तक है, प्रति मंज़िल एक व्यक्ति। उनमें से प्रत्येक को एक अलग रंग पसंद है: लाल, गुलाबी, काला, पीला, नीला, नारंगी। संकेत: (1) M को नीला रंग पसंद है। (2) नीला रंग पसंद करने वाला की मंज़िल K और N की मंज़िलों के बीच में है। (3) लाल रंग पसंद करने वाला और गुलाबी रंग पसंद करने वाले की मंज़िलों के बीच ठीक 1 मंज़िल हैं। (4) गुलाबी रंग पसंद करने वाला, P के ठीक ऊपर वाली मंज़िल पर रहता है। (5) K को पीला रंग पसंद नहीं है। (6) नारंगी रंग पसंद करने वाला, O के ठीक ऊपर वाली मंज़िल पर रहता है। (7) K, L से ऊपर की किसी मंज़िल पर रहता है। (8) पीला रंग पसंद करने वाला, O से ऊपर की किसी मंज़िल पर रहता है। (9) लाल रंग पसंद करने वाला, O से ऊपर की किसी मंज़िल पर रहता है। (10) पीला रंग पसंद करने वाला और गुलाबी रंग पसंद करने वाले लगातार मंज़िलों पर नहीं रहते हैं। P को कौन-सा रंग पसंद है?","optionsHi":["काला","नारंगी","लाल","गुलाबी"],"explanationHi":"पहले स्थिति वाले संकेत और फिर सापेक्ष तथा नकारात्मक संकेत लगाने पर एक ही संगत तालिका बनती है (मंज़िल: व्यक्ति-रंग): 1: P-काला; 2: O-गुलाबी; 3: L-नारंगी; 4: K-लाल; 5: M-नीला; 6: N-पीला। उत्तर इसी तालिका से मिलता है। उत्तर: काला।","subtopic":"floor-puzzles","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-220","question":"Five students U, V, W, X and Y each present a project on a different day, from Monday to Friday (one student per day, no break). Each of them chose a different subject: History, Geography, Maths, Physics, Biology. Clues: (1) Exactly 2 days lie between the presentation days of the one who chose Geography and the one who chose Biology. (2) X presents on a later day than Y. (3) W did not choose Biology. (4) X presents on Wednesday. (5) The one who chose History presents on Thursday. (6) U chose History. (7) V chose Maths. Who presents on the day immediately before the day of the student who chose History?","options":["U","W","V","X"],"answer":3,"explanation":"Placing the position clues first and then the relative and negative clues leaves one consistent table (day: person-subject): Monday: V-Maths; Tuesday: Y-Biology; Wednesday: X-Physics; Thursday: U-History; Friday: W-Geography. The answer is read from this table. Answer: X.","difficulty":"moderate","questionHi":"पाँच विद्यार्थी U, V, W, X और Y प्रत्येक एक अलग दिन परियोजना प्रस्तुत करते हैं, सोमवार से शुक्रवार तक (प्रतिदिन एक विद्यार्थी, बीच में अवकाश नहीं)। उनमें से प्रत्येक ने एक अलग विषय चुना है: इतिहास, भूगोल, गणित, भौतिकी, जीव विज्ञान। संकेत: (1) भूगोल विषय चुनने वाला और जीव विज्ञान विषय चुनने वाले के प्रस्तुति-दिनों के बीच ठीक 2 दिन हैं। (2) X, Y के बाद के किसी दिन प्रस्तुति देता है। (3) W ने जीव विज्ञान विषय नहीं चुना है। (4) X बुधवार को प्रस्तुति देता है। (5) इतिहास विषय चुनने वाला गुरुवार को प्रस्तुति देता है। (6) U ने इतिहास विषय चुना है। (7) V ने गणित विषय चुना है। इतिहास विषय चुनने वाले विद्यार्थी के ठीक पिछले दिन कौन प्रस्तुति देता है?","optionsHi":["U","W","V","X"],"explanationHi":"पहले स्थिति वाले संकेत और फिर सापेक्ष तथा नकारात्मक संकेत लगाने पर एक ही संगत तालिका बनती है (दिन: व्यक्ति-विषय): सोमवार: V-गणित; मंगलवार: Y-जीव विज्ञान; बुधवार: X-भौतिकी; गुरुवार: U-इतिहास; शुक्रवार: W-भूगोल। उत्तर इसी तालिका से मिलता है। उत्तर: X।","subtopic":"scheduling-attributes","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-221","question":"Six students A, B, C, D, E and F each present a project on a different day, from Monday to Saturday (one student per day, no break). Each of them chose a different subject: Chemistry, Maths, Biology, Geography, Economics, Physics. Clues: (1) Exactly 1 day lies between the presentation days of the one who chose Economics and D. (2) The one who chose Geography presents on the last day of the schedule. (3) The one who chose Geography presents on the day immediately after the day of F. (4) The one who chose Physics presents on a later day than the one who chose Biology. (5) The one who chose Geography and the one who chose Physics do not present on consecutive days. (6) The one who chose Economics and B do not present on consecutive days. (7) Exactly 1 day lies between the presentation days of the one who chose Maths and E. (8) A chose Geography. (9) E chose Chemistry. (10) The one who chose Biology presents on a later day than the one who chose Chemistry. How many days lie between the presentation days of F and C?","options":["3","4","1","0"],"answer":3,"explanation":"Placing the position clues first and then the relative and negative clues leaves one consistent table (day: person-subject): Monday: E-Chemistry; Tuesday: B-Biology; Wednesday: D-Maths; Thursday: C-Physics; Friday: F-Economics; Saturday: A-Geography. The answer is read from this table. Answer: 0.","difficulty":"hard","questionHi":"छह विद्यार्थी A, B, C, D, E और F प्रत्येक एक अलग दिन परियोजना प्रस्तुत करते हैं, सोमवार से शनिवार तक (प्रतिदिन एक विद्यार्थी, बीच में अवकाश नहीं)। उनमें से प्रत्येक ने एक अलग विषय चुना है: रसायन विज्ञान, गणित, जीव विज्ञान, भूगोल, अर्थशास्त्र, भौतिकी। संकेत: (1) अर्थशास्त्र विषय चुनने वाला और D के प्रस्तुति-दिनों के बीच ठीक 1 दिन हैं। (2) भूगोल विषय चुनने वाला कार्यक्रम के अंतिम दिन प्रस्तुति देता है। (3) भूगोल विषय चुनने वाला, F के ठीक अगले दिन प्रस्तुति देता है। (4) भौतिकी विषय चुनने वाला, जीव विज्ञान विषय चुनने वाले के बाद के किसी दिन प्रस्तुति देता है। (5) भूगोल विषय चुनने वाला और भौतिकी विषय चुनने वाले लगातार दिनों में प्रस्तुति नहीं देते हैं। (6) अर्थशास्त्र विषय चुनने वाला और B लगातार दिनों में प्रस्तुति नहीं देते हैं। (7) गणित विषय चुनने वाला और E के प्रस्तुति-दिनों के बीच ठीक 1 दिन हैं। (8) A ने भूगोल विषय चुना है। (9) E ने रसायन विज्ञान विषय चुना है। (10) जीव विज्ञान विषय चुनने वाला, रसायन विज्ञान विषय चुनने वाले के बाद के किसी दिन प्रस्तुति देता है। F और C के प्रस्तुति-दिनों के बीच कितने दिन हैं?","optionsHi":["3","4","1","0"],"explanationHi":"पहले स्थिति वाले संकेत और फिर सापेक्ष तथा नकारात्मक संकेत लगाने पर एक ही संगत तालिका बनती है (दिन: व्यक्ति-विषय): सोमवार: E-रसायन विज्ञान; मंगलवार: B-जीव विज्ञान; बुधवार: D-गणित; गुरुवार: C-भौतिकी; शुक्रवार: F-अर्थशास्त्र; शनिवार: A-भूगोल। उत्तर इसी तालिका से मिलता है। उत्तर: 0।","subtopic":"scheduling-attributes","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-222","question":"Six students P, Q, R, S, T and U each present a project on a different day, from Monday to Saturday (one student per day, no break). Each of them chose a different subject: History, Maths, Civics, Chemistry, Biology, Geography. Clues: (1) Q and the one who chose Chemistry do not present on consecutive days. (2) Q chose Civics. (3) The one who chose Geography and S do not present on consecutive days. (4) Exactly 2 days lie between the presentation days of S and the one who chose Biology. (5) S did not choose Geography. (6) The one who chose Chemistry presents on the last day of the schedule. (7) Exactly 3 days lie between the presentation days of the one who chose Civics and R. (8) U chose Chemistry. (9) P chose Maths. Who presents on the day immediately after the day of the student who chose Biology?","options":["U","S","P","Q"],"answer":0,"explanation":"Placing the position clues first and then the relative and negative clues leaves one consistent table (day: person-subject): Monday: Q-Civics; Tuesday: S-History; Wednesday: P-Maths; Thursday: T-Geography; Friday: R-Biology; Saturday: U-Chemistry. The answer is read from this table. Answer: U.","difficulty":"hard","questionHi":"छह विद्यार्थी P, Q, R, S, T और U प्रत्येक एक अलग दिन परियोजना प्रस्तुत करते हैं, सोमवार से शनिवार तक (प्रतिदिन एक विद्यार्थी, बीच में अवकाश नहीं)। उनमें से प्रत्येक ने एक अलग विषय चुना है: इतिहास, गणित, नागरिक शास्त्र, रसायन विज्ञान, जीव विज्ञान, भूगोल। संकेत: (1) Q और रसायन विज्ञान विषय चुनने वाले लगातार दिनों में प्रस्तुति नहीं देते हैं। (2) Q ने नागरिक शास्त्र विषय चुना है। (3) भूगोल विषय चुनने वाला और S लगातार दिनों में प्रस्तुति नहीं देते हैं। (4) S और जीव विज्ञान विषय चुनने वाले के प्रस्तुति-दिनों के बीच ठीक 2 दिन हैं। (5) S ने भूगोल विषय नहीं चुना है। (6) रसायन विज्ञान विषय चुनने वाला कार्यक्रम के अंतिम दिन प्रस्तुति देता है। (7) नागरिक शास्त्र विषय चुनने वाला और R के प्रस्तुति-दिनों के बीच ठीक 3 दिन हैं। (8) U ने रसायन विज्ञान विषय चुना है। (9) P ने गणित विषय चुना है। जीव विज्ञान विषय चुनने वाले विद्यार्थी के ठीक अगले दिन कौन प्रस्तुति देता है?","optionsHi":["U","S","P","Q"],"explanationHi":"पहले स्थिति वाले संकेत और फिर सापेक्ष तथा नकारात्मक संकेत लगाने पर एक ही संगत तालिका बनती है (दिन: व्यक्ति-विषय): सोमवार: Q-नागरिक शास्त्र; मंगलवार: S-इतिहास; बुधवार: P-गणित; गुरुवार: T-भूगोल; शुक्रवार: R-जीव विज्ञान; शनिवार: U-रसायन विज्ञान। उत्तर इसी तालिका से मिलता है। उत्तर: U।","subtopic":"scheduling-attributes","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-223","question":"Six students U, V, W, X, Y and Z each present a project on a different day, from Monday to Saturday (one student per day, no break). Each of them chose a different subject: Maths, Biology, History, Economics, Chemistry, Geography. Clues: (1) U presents on a day between those of the one who chose History and the one who chose Biology. (2) W chose Geography. (3) Y chose Maths. (4) Exactly 1 day lies between the presentation days of the one who chose Chemistry and the one who chose Economics. (5) The one who chose Biology and Y do not present on consecutive days. (6) The one who chose Chemistry presents on the day immediately after the day of V. (7) Y presents on the first day of the schedule. (8) Z chose Chemistry. (9) The one who chose Economics presents on a later day than the one who chose Biology. Who presents on Thursday?","options":["Y","U","V","X"],"answer":1,"explanation":"Placing the position clues first and then the relative and negative clues leaves one consistent table (day: person-subject): Monday: Y-Maths; Tuesday: W-Geography; Wednesday: X-Biology; Thursday: U-Economics; Friday: V-History; Saturday: Z-Chemistry. The answer is read from this table. Answer: U.","difficulty":"hard","questionHi":"छह विद्यार्थी U, V, W, X, Y और Z प्रत्येक एक अलग दिन परियोजना प्रस्तुत करते हैं, सोमवार से शनिवार तक (प्रतिदिन एक विद्यार्थी, बीच में अवकाश नहीं)। उनमें से प्रत्येक ने एक अलग विषय चुना है: गणित, जीव विज्ञान, इतिहास, अर्थशास्त्र, रसायन विज्ञान, भूगोल। संकेत: (1) U का दिन इतिहास विषय चुनने वाले और जीव विज्ञान विषय चुनने वाले के दिनों के बीच में है। (2) W ने भूगोल विषय चुना है। (3) Y ने गणित विषय चुना है। (4) रसायन विज्ञान विषय चुनने वाला और अर्थशास्त्र विषय चुनने वाले के प्रस्तुति-दिनों के बीच ठीक 1 दिन हैं। (5) जीव विज्ञान विषय चुनने वाला और Y लगातार दिनों में प्रस्तुति नहीं देते हैं। (6) रसायन विज्ञान विषय चुनने वाला, V के ठीक अगले दिन प्रस्तुति देता है। (7) Y कार्यक्रम के पहले दिन प्रस्तुति देता है। (8) Z ने रसायन विज्ञान विषय चुना है। (9) अर्थशास्त्र विषय चुनने वाला, जीव विज्ञान विषय चुनने वाले के बाद के किसी दिन प्रस्तुति देता है। गुरुवार को कौन प्रस्तुति देता है?","optionsHi":["Y","U","V","X"],"explanationHi":"पहले स्थिति वाले संकेत और फिर सापेक्ष तथा नकारात्मक संकेत लगाने पर एक ही संगत तालिका बनती है (दिन: व्यक्ति-विषय): सोमवार: Y-गणित; मंगलवार: W-भूगोल; बुधवार: X-जीव विज्ञान; गुरुवार: U-अर्थशास्त्र; शुक्रवार: V-इतिहास; शनिवार: Z-रसायन विज्ञान। उत्तर इसी तालिका से मिलता है। उत्तर: U।","subtopic":"scheduling-attributes","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-224","question":"Six students U, V, W, X, Y and Z each present a project on a different day, from Monday to Saturday (one student per day, no break). Each of them chose a different subject: Chemistry, Maths, Geography, Biology, Physics, Economics. Clues: (1) The one who chose Chemistry and Y do not present on consecutive days. (2) V and X do not present on consecutive days. (3) Z chose Physics. (4) W did not choose Chemistry. (5) Exactly 1 day lies between the presentation days of V and the one who chose Maths. (6) Y chose Maths. (7) The one who chose Biology presents on the last day of the schedule. (8) X presents on a later day than the one who chose Physics. (9) Exactly 1 day lies between the presentation days of the one who chose Chemistry and the one who chose Economics. (10) V presents on a later day than X. Who presents on Tuesday?","options":["Z","W","V","U"],"answer":0,"explanation":"Placing the position clues first and then the relative and negative clues leaves one consistent table (day: person-subject): Monday: U-Chemistry; Tuesday: Z-Physics; Wednesday: X-Economics; Thursday: Y-Maths; Friday: W-Geography; Saturday: V-Biology. The answer is read from this table. Answer: Z.","difficulty":"hard","questionHi":"छह विद्यार्थी U, V, W, X, Y और Z प्रत्येक एक अलग दिन परियोजना प्रस्तुत करते हैं, सोमवार से शनिवार तक (प्रतिदिन एक विद्यार्थी, बीच में अवकाश नहीं)। उनमें से प्रत्येक ने एक अलग विषय चुना है: रसायन विज्ञान, गणित, भूगोल, जीव विज्ञान, भौतिकी, अर्थशास्त्र। संकेत: (1) रसायन विज्ञान विषय चुनने वाला और Y लगातार दिनों में प्रस्तुति नहीं देते हैं। (2) V और X लगातार दिनों में प्रस्तुति नहीं देते हैं। (3) Z ने भौतिकी विषय चुना है। (4) W ने रसायन विज्ञान विषय नहीं चुना है। (5) V और गणित विषय चुनने वाले के प्रस्तुति-दिनों के बीच ठीक 1 दिन हैं। (6) Y ने गणित विषय चुना है। (7) जीव विज्ञान विषय चुनने वाला कार्यक्रम के अंतिम दिन प्रस्तुति देता है। (8) X, भौतिकी विषय चुनने वाले के बाद के किसी दिन प्रस्तुति देता है। (9) रसायन विज्ञान विषय चुनने वाला और अर्थशास्त्र विषय चुनने वाले के प्रस्तुति-दिनों के बीच ठीक 1 दिन हैं। (10) V, X के बाद के किसी दिन प्रस्तुति देता है। मंगलवार को कौन प्रस्तुति देता है?","optionsHi":["Z","W","V","U"],"explanationHi":"पहले स्थिति वाले संकेत और फिर सापेक्ष तथा नकारात्मक संकेत लगाने पर एक ही संगत तालिका बनती है (दिन: व्यक्ति-विषय): सोमवार: U-रसायन विज्ञान; मंगलवार: Z-भौतिकी; बुधवार: X-अर्थशास्त्र; गुरुवार: Y-गणित; शुक्रवार: W-भूगोल; शनिवार: V-जीव विज्ञान। उत्तर इसी तालिका से मिलता है। उत्तर: Z।","subtopic":"scheduling-attributes","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-225","question":"Six students U, V, W, X, Y and Z each present a project on a different day, from Monday to Saturday (one student per day, no break). Each of them chose a different subject: Biology, Geography, Economics, Civics, Physics, History. Clues: (1) The one who chose Civics and U do not present on consecutive days. (2) The one who chose Biology presents on a day between those of W and Y. (3) The one who chose Economics and X do not present on consecutive days. (4) The one who chose Biology presents on a later day than V. (5) V did not choose History. (6) Exactly 1 day lies between the presentation days of the one who chose Physics and W. (7) The one who chose Geography presents on the day immediately after the day of the one who chose History. (8) W chose Economics. (9) Exactly 1 day lies between the presentation days of the one who chose Biology and X. (10) X chose Geography. (11) Y and X do not present on consecutive days. Which subject did the student presenting on Tuesday choose?","options":["Physics","History","Biology","Economics"],"answer":1,"explanation":"Placing the position clues first and then the relative and negative clues leaves one consistent table (day: person-subject): Monday: Y-Civics; Tuesday: Z-History; Wednesday: X-Geography; Thursday: V-Physics; Friday: U-Biology; Saturday: W-Economics. The answer is read from this table. Answer: History.","difficulty":"very-hard","questionHi":"छह विद्यार्थी U, V, W, X, Y और Z प्रत्येक एक अलग दिन परियोजना प्रस्तुत करते हैं, सोमवार से शनिवार तक (प्रतिदिन एक विद्यार्थी, बीच में अवकाश नहीं)। उनमें से प्रत्येक ने एक अलग विषय चुना है: जीव विज्ञान, भूगोल, अर्थशास्त्र, नागरिक शास्त्र, भौतिकी, इतिहास। संकेत: (1) नागरिक शास्त्र विषय चुनने वाला और U लगातार दिनों में प्रस्तुति नहीं देते हैं। (2) जीव विज्ञान विषय चुनने वाला का दिन W और Y के दिनों के बीच में है। (3) अर्थशास्त्र विषय चुनने वाला और X लगातार दिनों में प्रस्तुति नहीं देते हैं। (4) जीव विज्ञान विषय चुनने वाला, V के बाद के किसी दिन प्रस्तुति देता है। (5) V ने इतिहास विषय नहीं चुना है। (6) भौतिकी विषय चुनने वाला और W के प्रस्तुति-दिनों के बीच ठीक 1 दिन हैं। (7) भूगोल विषय चुनने वाला, इतिहास विषय चुनने वाले के ठीक अगले दिन प्रस्तुति देता है। (8) W ने अर्थशास्त्र विषय चुना है। (9) जीव विज्ञान विषय चुनने वाला और X के प्रस्तुति-दिनों के बीच ठीक 1 दिन हैं। (10) X ने भूगोल विषय चुना है। (11) Y और X लगातार दिनों में प्रस्तुति नहीं देते हैं। मंगलवार को प्रस्तुति देने वाले विद्यार्थी ने कौन-सा विषय चुना?","optionsHi":["भौतिकी","इतिहास","जीव विज्ञान","अर्थशास्त्र"],"explanationHi":"पहले स्थिति वाले संकेत और फिर सापेक्ष तथा नकारात्मक संकेत लगाने पर एक ही संगत तालिका बनती है (दिन: व्यक्ति-विषय): सोमवार: Y-नागरिक शास्त्र; मंगलवार: Z-इतिहास; बुधवार: X-भूगोल; गुरुवार: V-भौतिकी; शुक्रवार: U-जीव विज्ञान; शनिवार: W-अर्थशास्त्र। उत्तर इसी तालिका से मिलता है। उत्तर: इतिहास।","subtopic":"scheduling-attributes","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-226","question":"Six students P, Q, R, S, T and U each present a project on a different day, from Monday to Saturday (one student per day, no break). Each of them chose a different subject: History, Maths, Physics, Chemistry, Geography, Biology. Clues: (1) The one who chose Geography and T do not present on consecutive days. (2) P did not choose Chemistry. (3) P presents on a later day than S. (4) Exactly 2 days lie between the presentation days of U and the one who chose History. (5) Exactly 2 days lie between the presentation days of Q and the one who chose Geography. (6) P and Q do not present on consecutive days. (7) S chose History. (8) U chose Maths. (9) The one who chose Physics presents on Wednesday. (10) The one who chose Physics and the one who chose Chemistry do not present on consecutive days. (11) T did not choose Physics. (12) The one who chose Maths presents on the first day of the schedule. Who presents on Thursday?","options":["S","R","P","U"],"answer":0,"explanation":"Placing the position clues first and then the relative and negative clues leaves one consistent table (day: person-subject): Monday: U-Maths; Tuesday: T-Biology; Wednesday: Q-Physics; Thursday: S-History; Friday: R-Chemistry; Saturday: P-Geography. The answer is read from this table. Answer: S.","difficulty":"very-hard","questionHi":"छह विद्यार्थी P, Q, R, S, T और U प्रत्येक एक अलग दिन परियोजना प्रस्तुत करते हैं, सोमवार से शनिवार तक (प्रतिदिन एक विद्यार्थी, बीच में अवकाश नहीं)। उनमें से प्रत्येक ने एक अलग विषय चुना है: इतिहास, गणित, भौतिकी, रसायन विज्ञान, भूगोल, जीव विज्ञान। संकेत: (1) भूगोल विषय चुनने वाला और T लगातार दिनों में प्रस्तुति नहीं देते हैं। (2) P ने रसायन विज्ञान विषय नहीं चुना है। (3) P, S के बाद के किसी दिन प्रस्तुति देता है। (4) U और इतिहास विषय चुनने वाले के प्रस्तुति-दिनों के बीच ठीक 2 दिन हैं। (5) Q और भूगोल विषय चुनने वाले के प्रस्तुति-दिनों के बीच ठीक 2 दिन हैं। (6) P और Q लगातार दिनों में प्रस्तुति नहीं देते हैं। (7) S ने इतिहास विषय चुना है। (8) U ने गणित विषय चुना है। (9) भौतिकी विषय चुनने वाला बुधवार को प्रस्तुति देता है। (10) भौतिकी विषय चुनने वाला और रसायन विज्ञान विषय चुनने वाले लगातार दिनों में प्रस्तुति नहीं देते हैं। (11) T ने भौतिकी विषय नहीं चुना है। (12) गणित विषय चुनने वाला कार्यक्रम के पहले दिन प्रस्तुति देता है। गुरुवार को कौन प्रस्तुति देता है?","optionsHi":["S","R","P","U"],"explanationHi":"पहले स्थिति वाले संकेत और फिर सापेक्ष तथा नकारात्मक संकेत लगाने पर एक ही संगत तालिका बनती है (दिन: व्यक्ति-विषय): सोमवार: U-गणित; मंगलवार: T-जीव विज्ञान; बुधवार: Q-भौतिकी; गुरुवार: S-इतिहास; शुक्रवार: R-रसायन विज्ञान; शनिवार: P-भूगोल। उत्तर इसी तालिका से मिलता है। उत्तर: S।","subtopic":"scheduling-attributes","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
  {"id":"reason-seating-puzzles-227","question":"Six students A, B, C, D, E and F each present a project on a different day, from Monday to Saturday (one student per day, no break). Each of them chose a different subject: Chemistry, Maths, Biology, Civics, Economics, Physics. Clues: (1) Exactly 2 days lie between the presentation days of D and the one who chose Biology. (2) E did not choose Biology. (3) The one who chose Civics presents on the day immediately after the day of the one who chose Biology. (4) The one who chose Chemistry presents on the day immediately after the day of the one who chose Civics. (5) A chose Physics. (6) E did not choose Chemistry. (7) The one who chose Economics presents on a later day than the one who chose Maths. (8) Exactly 1 day lies between the presentation days of B and the one who chose Maths. (9) The one who chose Physics and F do not present on consecutive days. (10) Exactly 1 day lies between the presentation days of C and E. Which subject did the student presenting on Thursday choose?","options":["Physics","Maths","Biology","Civics"],"answer":1,"explanation":"Placing the position clues first and then the relative and negative clues leaves one consistent table (day: person-subject): Monday: F-Biology; Tuesday: B-Civics; Wednesday: C-Chemistry; Thursday: D-Maths; Friday: E-Economics; Saturday: A-Physics. The answer is read from this table. Answer: Maths.","difficulty":"very-hard","questionHi":"छह विद्यार्थी A, B, C, D, E और F प्रत्येक एक अलग दिन परियोजना प्रस्तुत करते हैं, सोमवार से शनिवार तक (प्रतिदिन एक विद्यार्थी, बीच में अवकाश नहीं)। उनमें से प्रत्येक ने एक अलग विषय चुना है: रसायन विज्ञान, गणित, जीव विज्ञान, नागरिक शास्त्र, अर्थशास्त्र, भौतिकी। संकेत: (1) D और जीव विज्ञान विषय चुनने वाले के प्रस्तुति-दिनों के बीच ठीक 2 दिन हैं। (2) E ने जीव विज्ञान विषय नहीं चुना है। (3) नागरिक शास्त्र विषय चुनने वाला, जीव विज्ञान विषय चुनने वाले के ठीक अगले दिन प्रस्तुति देता है। (4) रसायन विज्ञान विषय चुनने वाला, नागरिक शास्त्र विषय चुनने वाले के ठीक अगले दिन प्रस्तुति देता है। (5) A ने भौतिकी विषय चुना है। (6) E ने रसायन विज्ञान विषय नहीं चुना है। (7) अर्थशास्त्र विषय चुनने वाला, गणित विषय चुनने वाले के बाद के किसी दिन प्रस्तुति देता है। (8) B और गणित विषय चुनने वाले के प्रस्तुति-दिनों के बीच ठीक 1 दिन हैं। (9) भौतिकी विषय चुनने वाला और F लगातार दिनों में प्रस्तुति नहीं देते हैं। (10) C और E के प्रस्तुति-दिनों के बीच ठीक 1 दिन हैं। गुरुवार को प्रस्तुति देने वाले विद्यार्थी ने कौन-सा विषय चुना?","optionsHi":["भौतिकी","गणित","जीव विज्ञान","नागरिक शास्त्र"],"explanationHi":"पहले स्थिति वाले संकेत और फिर सापेक्ष तथा नकारात्मक संकेत लगाने पर एक ही संगत तालिका बनती है (दिन: व्यक्ति-विषय): सोमवार: F-जीव विज्ञान; मंगलवार: B-नागरिक शास्त्र; बुधवार: C-रसायन विज्ञान; गुरुवार: D-गणित; शुक्रवार: E-अर्थशास्त्र; शनिवार: A-भौतिकी। उत्तर इसी तालिका से मिलता है। उत्तर: गणित।","subtopic":"scheduling-attributes","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2"},
];

